def _v26_atomic_ready_marker(payload):
    """اكتب readiness عبر fsync+replace، وأظهر أي فشل بدل إخفائه."""
    target='/tmp/desktop_core_ready.json';tmp=''
    try:
        fd,tmp=tempfile.mkstemp(prefix='.desktop-core-ready-',dir='/tmp')
        with os.fdopen(fd,'w',encoding='utf-8') as f:
            json.dump(payload,f,ensure_ascii=False,separators=(',',':'))
            f.flush();os.fsync(f.fileno())
        os.chmod(tmp,0o600);os.replace(tmp,target)
        # readback إلزامي: العلامة ليست ناجحة إن لم يمكن قراءتها ومطابقة schema.
        check=json.loads(Path(target).read_text(encoding='utf-8'))
        if check.get('schema')!=27:raise RuntimeError('ready marker readback mismatch')
        return True
    except Exception as exc:
        try:
            if tmp and os.path.exists(tmp):os.unlink(tmp)
        except Exception:pass
        print('[!] تعذر كتابة علامة FastBoot V27: %s: %s'%(type(exc).__name__,exc),flush=True)
        try:_diag_event('v26_ready_marker',exc,'error')
        except Exception:pass
        return False

