_DIAG_RING = collections.deque(maxlen=200)
_DIAG_LOCK = threading.Lock()
_DIAG_LAST = {}
_DIAG_REPEAT_SECONDS = 60
def _diag_event(component, exc=None, level="warning"):
    """Metadata-only diagnostic event: no command output, user text, cookies or secrets."""
    item={"ts":int(time.time()),"component":str(component)[:64],"level":level,
          "error":type(exc).__name__ if exc is not None else ""}
    key=(item["component"],item["level"],item["error"])
    now_mono=time.monotonic()
    with _DIAG_LOCK:
        _DIAG_RING.append(item)
        previous=_DIAG_LAST.get(key,0.0)
        _DIAG_LAST[key]=now_mono
    # منع فيضان السجل من فحص دوري يفشل بالطريقة نفسها كل ثوانٍ.
    if now_mono-previous < _DIAG_REPEAT_SECONDS:
        return item
    try:
        os.makedirs("/root/workspace", exist_ok=True)
        _elf = "/root/workspace/error-log.txt"
        with open(_elf, "a", encoding="utf-8") as _ef:
            _ef.write(json.dumps(item, ensure_ascii=False) + chr(10))
        if os.path.getsize(_elf) > 512000:
            _lines = open(_elf, encoding="utf-8").readlines()[-2000:]
            with open(_elf, "w", encoding="utf-8") as _ef:
                _ef.writelines(_lines)
    except Exception:
        pass
    if level=="error": logging.error("[%s] %s",item["component"],item["error"])
    return item

def run(cmd, timeout=None):
    """Bounded command runner. Strings use explicit bash argv without implicit shell mode."""
    p=None
    try:
        argv=cmd if isinstance(cmd,(list,tuple)) else ["/bin/bash","-o","pipefail","-c",str(cmd)]
        p=subprocess.Popen(list(argv),shell=False,stdout=subprocess.PIPE,stderr=subprocess.PIPE,
                           text=True,encoding="utf-8",errors="replace",start_new_session=True)
        out,err=p.communicate(timeout=timeout)
        class R: pass
        r=R();r.returncode=p.returncode;r.stdout=out;r.stderr=err
        if (p.returncode and os.environ.get("DIAG_COMMAND_EXITS", "0").strip().lower()
                in ("1", "true", "yes", "on")):
            _diag_event("command_exit_%d" % p.returncode)
        return r
    except subprocess.TimeoutExpired as exc:
        try:
            if p is not None: os.killpg(os.getpgid(p.pid),9);p.communicate(timeout=5)
        except Exception as cleanup_exc: _diag_event("command_timeout_cleanup",cleanup_exc)
        _diag_event("command_timeout",exc,"error")
        class R:
            returncode = 124
            stdout = ""
            stderr = "timeout"
        return R()
    except (OSError,ValueError) as exc:
        _diag_event("command_start",exc,"error")
        class R: pass
        r=R();r.returncode=127;r.stdout="";r.stderr=type(exc).__name__;return r

def find_free_port(start):
    port = start
    while port < start + 200:
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
            if s.connect_ex(("127.0.0.1", port)) != 0:
                return port
        port += 1
    return start

def port_listening(port):
    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
        s.settimeout(1)
        return s.connect_ex(("127.0.0.1", port)) == 0

def proc_running(pattern):
    """يفحص العمليات دون تمرير النمط إلى shell."""
    try:
        r = subprocess.run(["pgrep", "-f", str(pattern)],
                           stdout=subprocess.PIPE, stderr=subprocess.DEVNULL,
                           text=True, timeout=10)
        return r.returncode == 0 and bool(r.stdout.strip())
    except Exception:
        return False

