def _env_int_bounded(name, default, minimum, maximum):
    """اقرأ عددًا صحيحًا من البيئة بلا إسقاط الإقلاع عند قيمة تالفة."""
    try:
        value = int(str(os.environ.get(name, default)).strip())
    except (TypeError, ValueError):
        value = int(default)
    return max(int(minimum), min(value, int(maximum)))


