# ============================================================
# >>> أقصى سرعة إنترنت وتحميل (على مستوى واة النظام):
#     • BBR: خوارزمية تحكّم ازدحام تملأ عرض النطاق المتاح بالكامل بدل
#       cubic الافتراضية (فرق كبير على المسافات الطويلة Colab↔Cloudflare).
#     • نوافذ TCP حتى 16 ميجابايت: دفعات ضخمة بلا انتظار ACK.
#     • tcp_fastopen + مخازن UDP كبيرة (لبروتوكول QUIC في النفق).
#     كل أمر داخل «|| true» — لو Colab منع sysctl معيّن نُكمل بلا خطأ. <<<
# ============================================================
for _sc in [
    "net.core.default_qdisc=fq",
    "net.ipv4.tcp_congestion_control=bbr",
    "net.core.rmem_max=16777216",
    "net.core.wmem_max=16777216",
    "net.ipv4.tcp_rmem=4096 1048576 16777216",
    "net.ipv4.tcp_wmem=4096 1048576 16777216",
    "net.ipv4.tcp_fastopen=3",
    "net.ipv4.tcp_slow_start_after_idle=0",
    "net.core.rmem_default=1048576",
    "net.core.wmem_default=1048576",
    # >>> دفعة تسريع إضافية (تنزيل/رفع >100MB/s حيث تسمح شبكة Colab):
    #     نوافذ حتى 32MB (مسار Colab↔الخوادم عالي الـ BDP)، MTU probing
    #     (يمنع تعليق الاتصالات خلف الأنفاق)، طوابير أكبر، إعادة استخدام
    #     TIME_WAIT (مئات الاتصالات المتوازية للتنزيل المجزّأ). <<<
    "net.core.rmem_max=33554432",
    "net.core.wmem_max=33554432",
    "net.ipv4.tcp_rmem=4096 1048576 33554432",
    "net.ipv4.tcp_wmem=4096 1048576 33554432",
    "net.ipv4.tcp_mtu_probing=1",
    "net.ipv4.tcp_window_scaling=1",
    "net.ipv4.tcp_sack=1",
    "net.ipv4.tcp_timestamps=1",
    "net.core.netdev_max_backlog=16384",
    "net.core.somaxconn=8192",
    "net.ipv4.tcp_max_syn_backlog=8192",
    "net.ipv4.tcp_tw_reuse=1",
    "net.ipv4.ip_local_port_range=1024 65535",
    "net.ipv4.udp_rmem_min=16384",
    "net.ipv4.udp_wmem_min=16384",
    "fs.file-max=1048576",
]:
    run("sysctl -w '%s' >/dev/null 2>&1 || true" % _sc)
_cc = run("sysctl -n net.ipv4.tcp_congestion_control 2>/dev/null").stdout.strip()
print("[i] تسريع الشبكة: تحكّم الازدحام = %s | نوافذ TCP حتى 32MB ✅"
      % (_cc or "cubic"))

# ============================================================
# >>> DNS فائق السرعة — أسرع فتح واستجابة للمواقع في المتصفّح:
#     زمن الاستعلام DNS يدخل في *كل* فتح صفحة. نضيف Cloudflare 1.1.1.1
#     وGoogle 8.8.8.8 (الأسرع عالميًّا) مع options timeout/attempts صارمة
#     فلا ينتظر المتصفّح ثواني على مُحلّل بطيء. لا نحذف مُحلّل Colab
#     الأصلي (يبقى احتياطيًّا في الائمة). <<<
# ============================================================
try:
    _resolv = open("/etc/resolv.conf").read() if \
        os.path.exists("/etc/resolv.conf") else ""
    if "1.1.1.1" not in _resolv:
        _keep = [ln for ln in _resolv.splitlines()
                 if ln.strip() and not ln.startswith("options")]
        with open("/etc/resolv.conf", "w") as f:
            f.write("nameserver 1.1.1.1\nnameserver 8.8.8.8\n"
                    + "\n".join(_keep)
                    + "\noptions timeout:1 attempts:2 rotate\n")
    print("[i] DNS سريع: 1.1.1.1 + 8.8.8.8 (timeout=1s) ✅")
except Exception:
    pass

# ============================================================
# >>> تنزيلات النظام فائقة السرعة (>100MB/s حيث تسمح شبكة Colab):
#     • apt: 8 اتصالات متوازية لكل مضيف + طابور مضيف كامل — تنزيل الحزم
#       الكبيرة أسرع بمرّات.
#     • aria2c: أداة التنزيل المجزّأ (16 اتصالًا للملف الواحد) — تُثبَّت
#       في خيط خلفي ويُوفَّر أمر «fast-dl رابط» يستخدمها تلقائيًّا،
#       و wget/curl يبقيان كما هما (لا نغيّر سلوكًا قائمًا). <<<
# ============================================================
with open("/etc/apt/apt.conf.d/99parallel-dl", "w") as f:
    f.write('Acquire::Queue-Mode "access";\n'
            'Acquire::http::Pipeline-Depth "8";\n'
            'Acquire::Retries "3";\n')
_fastdl_sh = r"""#!/bin/bash
# fast-dl : تنزيل مجزّأ فائق السرعة (aria2c: 16 اتصالًا متوازيًا للملف)
# الاستخدام: fast-dl <رابط> [مجلد-الحفظ]
URL="$1"; DIR="${2:-$PWD}"
[ -z "$URL" ] && { echo "الاستخدام: fast-dl <رابط> [مجلد]"; exit 1; }
if command -v aria2c >/dev/null 2>&1; then
  exec aria2c -x16 -s16 -k1M --file-allocation=none --summary-interval=1 \
    --auto-file-renaming=true -d "$DIR" "$URL"
else
  echo "ℹ️ aria2 لم يكتمل تثبيته بعد — تنزيل عبر wget..."
  exec wget -P "$DIR" "$URL"
fi
"""
with open("/usr/local/bin/fast-dl", "w") as f:
    f.write(_fastdl_sh)
run("chmod +x /usr/local/bin/fast-dl")
def _install_aria2():
    # v46: تحصين جسم الخيط — aria2 تحسين سرعة اختياري تمامًا؛
    # لا يجوز أن يطبع تتبّع خطأ في الخلية أو يُقلق المستخدم.
    try:
        if not os.path.exists("/usr/bin/aria2c"):
            run("sudo DEBIAN_FRONTEND=noninteractive apt-get install -y -qq "
                "aria2 > /dev/null 2>&1", timeout=300)
    except Exception as _exc:
        _diag_event("install_aria2", _exc)
threading.Thread(target=_install_aria2, name="aria2_bg",
                 daemon=True).start()
print("[i] تنزيلات سريعة: apt متوازي ×8 + أمر fast-dl (aria2 ×16) ✅")

# ============================================================
# 0.5) zram (ذاكرة إ��افة مضغوطة) — حلّ ض��ف الرام
# ============================================================
# zram ينئ «رام افتراضية» مضغوطة في الذارة نفسها (أسرع 100× من swap على القرص).
# نجعل حجمها = ضِعف الرام الفعلية تقريبًا (بحدّ أقصى 8 جيجا) لتخفيف الضغط بقوة.
try:
    _zram_gb = 2 if RAM_GB >= 8.0 else int(min(4, max(2, RAM_GB)))
    run("sudo swapoff /dev/zram0 2>/dev/null")
    run("sudo modprobe zram num_devices=1")
    # lz4 is chosen for low CPU latency; compression ratio is secondary here.
    run("echo lz4 | sudo tee /sys/block/zram0/comp_algorithm")
    run("echo %dG | sudo tee /sys/block/zram0/disksize" % _zram_gb)
    run("sudo mkswap /dev/zram0")
    run("sudo swapon --priority 100 /dev/zram0")
    # swappiness أعلى للرام المنخفضة كي يُستخدم zram السريع باكرًا (لا تجمّد)
    run("echo %d | sudo tee /proc/sys/vm/swappiness"
        % (60 if RAM_GB < 6.0 else 10))
    # تقليل التخزين المؤقت للقرص (cache pressure) لإبقاء رام أكثر للتطبيقات
    run("echo 50 | sudo tee /proc/sys/vm/vfs_cache_pressure")
    print("[OK] zram يعمل (%d جيجا ذاكرة مضغوطة إضافية)." % _zram_gb)
except Exception as e:
    print("[!] تخطّي zram (%s)." % e)

# Disk swap can freeze an interactive remote desktop. Enable it only below 6GB.
try:
    if RAM_GB < 6.0:
        if not os.path.exists("/swapfile_colab"):
            run("sudo fallocate -l 2G /swapfile_colab || "
                "sudo dd if=/dev/zero of=/swapfile_colab bs=1M count=2048", timeout=90)
            run("sudo chmod 600 /swapfile_colab && sudo mkswap /swapfile_colab", timeout=30)
        run("sudo swapon --priority 20 /swapfile_colab 2>/dev/null", timeout=30)
        print("[OK] swap احتياطي 2GB مفعّل للرام المنخفضة.")
    else:
        run("sudo swapoff /swapfile_colab 2>/dev/null || true")
        print("[i] swap القرص معطّل لتفادي تجميد الواجهة (الرام كافية).")
except Exception as e:
    print("[!] تخطّي swap الاحتياطي (%s)." % e)

# ============================================================
# Round 11: ربط Google Drive مبكرًا (قبل الحزم) — لتخزين حزم النظام مؤقتً
# ============================================================
# طلب المستخدم: "احفظ في درايف ... حزم لنظام التي يحتاجها السكربت للإقلاع
# لتسريع عملية الإقلاع". على Colab يُعاد تعيين الـ runtime بالكامل عند كل
# جلسة جديد فتُقد كل الحزم المثبّتة (XFCE/Chrome/KasmVNC) ويُعاد تنزيلها
# وتثبيتها (2-3 دقائق + تنزيل ثقيل). الحل: نحفظ ملفّات .deb المثبّتة في Drive
# مرّة واحدة، ثم في كل إقلاع نستعيدها من Drive ونثبّتها محليًّا (dpkg -i)
# بلا أي تنزيل من الإنترنت → إقلاع أسرع بكثير حتى مع runtime جديد.
# نربط Drive هنا مبكرًا (قبل الحزم) كي يتوفّر مخزن الحزم عند الحاجة.
DRIVE_OK = False
PERSIST_DIR = "/content/persist"
# ربط Drive يحتاج سياق kernel تفاعليًّا. الخطأ 'NoneType has no attribute
# kernel' يحدث لو نُفّذت الكتلة قبل جهوزية الـ kernel أو من سياق غير تفاعلي.
# الحل: إن كان Drive مربوطًا مسبقًا نستخدمه فورًا (لا نعيد الربط)، وإلا نحاول
# الربط مع إعادة محاولة بسيطة، وإن فشل نكمل بأمان (تخزين مؤقت + تنبيه واضح).
if os.path.ismount("/content/drive") or os.path.isdir(
        "/content/drive/MyDrive"):
    # Drive مربوط بالفعل (جلسة م��تأنفة) — استخدمه مباشرة بلا إعادة ربط
    PERSIST_DIR = "/content/drive/MyDrive/colab_desktop_v43"
    DRIVE_OK = True
    print("[OK] Drive مربوط مسبقًا — تخزين حزم النظام مُفعّل ✅")
else:
    for _try in range(2):
        try:
            from google.colab import drive
            drive.mount('/content/drive', force_remount=True)
            PERSIST_DIR = "/content/drive/MyDrive/colab_desktop_v43"
            DRIVE_OK = True
            print("[OK] تم ربط Drive مبكرًا — تخزين حزم النظام مُفعّل ✅")
            break
        except Exception as e:
            if _try == 0:
                time.sleep(3)   # امنح الـ kernel لحظة ليجهز ثم أعد المحاولة
                continue
            print("[!] تعذّر ربط Drive (%s) — تخزين مؤقت فقط." % e)
            print("    ملاحظة: لربط Drive شغّل الخلية يدويًّا في Colab "
                  "(وامنح الإذن) — أو تجاهلها؛ سيعمل السكربت دون حفظ دائم.")
os.makedirs(PERSIST_DIR, exist_ok=True)

# مخزن حزم دائم ومُعرَّف ببيئة النظام. لا نستخدم مخزنًا عامًا بين إصدارات
# Ubuntu المختلفة، لأن خلط .deb من توزيعات مختلفة هو سبب شائع لكسر dpkg.
# (platform و shlex مستوردان مع بقية المكتبات في أعلى الملف — v46.)
_APT_ARCH = run("dpkg --print-architecture", timeout=15).stdout.strip() or platform.machine()
_APT_SUITE = (DISTRIB_CODENAME or "unknown").strip()
PKG_CACHE = os.path.join(PERSIST_DIR, "package_store", "%s-%s" % (_APT_SUITE, _APT_ARCH))
PKG_MANIFEST = os.path.join(PKG_CACHE, "manifest.tsv")
try:
    os.makedirs(PKG_CACHE, exist_ok=True)
except Exception:
    PKG_CACHE = "/tmp/pkg_cache"
    PKG_MANIFEST = os.path.join(PKG_CACHE, "manifest.tsv")
    os.makedirs(PKG_CACHE, exist_ok=True)

# v41 clean layout: system cache is isolated from Chrome generations and user workspace.
try:
    _layout_dirs = {
        "runtime_cache": os.path.join(PERSIST_DIR, "package_store"),
        "chrome_profiles": os.path.join(PERSIST_DIR, "chrome-profiles"),
        "workspace": os.path.join(PERSIST_DIR, "workspace"),
        "logs": os.path.join(PERSIST_DIR, "logs"),
    }
    for _p in _layout_dirs.values(): os.makedirs(_p, exist_ok=True)
    _layout_meta = {"schema": 42, "root": os.path.basename(PERSIST_DIR),
                    "policy": "smart-fastboot-pending-critical-generations",
                    "created_or_checked": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())}
    _layout_tmp = os.path.join(PERSIST_DIR, ".layout-v43.json.tmp")
    with open(_layout_tmp, "w", encoding="utf-8") as _f:
        json.dump(_layout_meta, _f, ensure_ascii=False, separators=(",", ":")); _f.flush(); os.fsync(_f.fileno())
    os.replace(_layout_tmp, os.path.join(PERSIST_DIR, ".layout-v43.json"))
except Exception as _e:
    print("[!] تعذر كتابة بيان تنظيم Drive: %s" % _e)

# صور Colab مبنية على Docker وقد تحتوي إعدادًا يمسح /var/cache/apt/archives
# تلقائيًا بعد كل apt install. نعطله قبل أول تثبيت، وإلا لن يبقى أي .deb لنقله.
def _preserve_apt_archives():
    cmd = ("printf '%s\\n' "
           "'APT::Keep-Downloaded-Packages \"true\";' "
           "'APT::Get::Keep-Downloaded-Packages \"true\";' "
           "'Binary::apt::APT::Keep-Downloaded-Packages \"true\";' "
           "'Binary::apt-get::APT::Keep-Downloaded-Packages \"true\";' "
           "> /etc/apt/apt.conf.d/99-colab-persistent-archives")
    r = run(["sudo", "/bin/sh", "-c", cmd], timeout=30)
    if getattr(r, "returncode", 1) != 0:
        _diag_event("preserve_apt_archives_config", RuntimeError("write failed"), "warning")
    # docker-clean لا يؤثر في سلامة apt، لكنه يحذف الأرشيف المطلوب للحفظ الدائم.
    run("sudo mv /etc/apt/apt.conf.d/docker-clean "
        "/etc/apt/apt.conf.d/docker-clean.disabled 2>/dev/null || true", timeout=30)

_preserve_apt_archives()


# ============================================================
# >>> ن��م اللقطة الدائمة (SYSTEM SNAPSHOT) — إقلاع اوخي با تكرار تنزيل <<<
# ============================================================
# الفكرة (بديل دقيق وسريع جدًّا عن dpkg -i على مئات الحزم في كل إقلاع):
#   • أول تشغيل فقط: بعد اكتمال تثبيت كل شيء (XFCE + Chrome + KasmVNC + الأدوات)
#     نأخذ «لقطة» = أرشيف tar واحد مضغوط لكل ملفّات النظام المُثبَّتة فعليًّا
#     (الثنائيات + المكتبا + الإعدادات + قاعدة بيانات dpkg) ونرفعه إلى Drive
#     مرّة واحدة، مع ملف علامة (marker) يحوي رقم الإصدار + الحجم + الاختبار
#     الجمعي (sha256) لضمان السلامة ومنع أي تكرار.
#   • كل تشغيل لاحق: نتحقّق من العلامة، ثم نفكّ ضغط الأرشيف الواحد مباشرة على
#     الجذر «/» (بلا تنزيل من الإنترنت، بلا dpkg، بلا أي عملية متكرّرة).
#     فكّ ضغط أرشيف واحد أسرع بمرّات من تثبيت مئات الحزم = إقلاع خلال ثوانٍ.
#   • منع التكرار نهائيًّا: لا نُنشئ اللقطة ولا نرفعها إلا مرّة واحدة (إن لم
#     تكن العلامة موجودة وسليمة). ولا نستعيدها إن كان النظام جاهزًا أصلًا.
#
# رقم إصدار اللقطة: أي تغيير في قائمة الحزم أو طريقة البناء = ارفع الرقم.
# v2-delta: لقطة «الدلتا» — نلتقط فقط الملفات الت ثبّتها/عدّلها السكربت
# (ctime أحدث من علامة الإقلاع BOOT_MARKER) بدل أرشفة /usr كاملًا من صورة
# Colab (التي تحوي CUDA وPython بعشرات الجيجا!). النتيجة: لقطة أصغر 10-20،
# بناء واستعادة أسرع بمرّات، ومساحة Drive أقل بكثير — بلا أي تكرار.
# v46: تغيّرت بنية العلامة (أُضيف tier وتقلّصت required_paths إلى طبقة CORE)،
# فنرفع الإصدار والمخطّط كي تُهمَل اللقطات القديمة بنظافة وتُبنى الجديدة مرّة.
SNAPSHOT_VERSION = "v46-two-tier-fastboot-2026"
SNAPSHOT_SCHEMA = 29
SNAPSHOT_MIN_BYTES = 5_000_000
# جذر المشكلة المثبت من السجل: boot-core بحجم 1180MB كان يُفك فوق /usr و/lib
# في صورة Colab جديدة، فيخلط مكتبات/ثنائيات جلسة قديمة مع الحالية. نحافظ على
# كل ملفات Drive كما هي، لكن نستعيد الحزم عبر .deb والتطبيقات عبر مخازنها فقط.
SAFE_PACKAGE_RESTORE = (os.environ.get("SAFE_PACKAGE_RESTORE", "1").strip().lower()
                        not in ("0", "false", "no", "off"))
_UNSAFE_OVERLAY_NOTICE = False

def _safe_restore_notice():
    global _UNSAFE_OVERLAY_NOTICE
    if not _UNSAFE_OVERLAY_NOTICE:
        _UNSAFE_OVERLAY_NOTICE=True
        print("[🛡️ استعادة آمنة] تجاهلنا لقطة rootfs القديمة دون حذفها؛ "
              "سنستخدم حزم Drive المنفصلة لمنع تشوّه سطح المكتب ✅")
# ملفّات اللقطة داخل مخزن الحزم الخاص بنفس (الإصدار + المعمارية) — لا نخلط
# لقطة أوبونتو 22 مع 20 (سبب شائع لكسر النظام).
SNAPSHOT_DIR = os.path.join(PKG_CACHE, "system_snapshot")
SNAPSHOT_TAR = os.path.join(SNAPSHOT_DIR, "rootfs-%s.tar.zst" % SNAPSHOT_VERSION)
SNAPSHOT_MARK = os.path.join(SNAPSHOT_DIR, "rootfs-%s.done" % SNAPSHOT_VERSION)
SNAPSHOT_ZSTD_DECODER = os.path.join(SNAPSHOT_DIR, "zstd-decoder-%s" % SNAPSHOT_VERSION)
try:
    os.makedirs(SNAPSHOT_DIR, exist_ok=True)
except Exception:
    pass

# المسارات التي نضمّها في اللقطة (كل ما يُثبّته apt للحزم أعلاه). نحفظ الملفّات
# النظامية فقط — لا نحفظ /root (بيانات المستخدم لها نظام حفظ منفصل) ولا الكاش.
_SNAP_PATHS = [
    "usr", "etc", "opt", "var/lib/dpkg", "var/lib/apt/extended_states",
    "lib", "lib64", "bin", "sbin",
]
# نستثني الكاش والملفّات المؤقتة الضخمة (تُنتفخ الأرشيف بلا فائدة)، إضافةً
# إلى ملفّات النظام الخاصّة بجلسة Colab الحالية (شبكة/هوية/تحميل) التي تختلف
# كلّ جلسة — استعادتها من لقطة قديمة قد تكسر الشبكة/DNS في الجلسة الجديدة.
_SNAP_EXCLUDES = [
    "usr/share/doc", "usr/share/man", "usr/share/locale",
    "var/cache", "var/log", "var/tmp",
    "usr/share/icons/*/*/apps",  # أيقونات ضخمة تُعاد توليدها
    # ملفّات خاصّة بالجلسة الحالية — لا تُلتقط ولا تُستعاد (تُبقي شبكة الجلسة سليمة)
    "etc/resolv.conf", "etc/hosts", "etc/hostname", "etc/mtab",
    "etc/machine-id", "etc/fstab", "etc/nsswitch.conf",
    "etc/apt/apt.conf.d/99-colab-persistent-archives",
    "opt/google-antigravity-previous",
    "opt/google-antigravity-ide-previous",
    "opt/android-studio-previous", "opt/cursor-previous",
]

# لا نعتمد لقطة «سريعة» ما لم تكن التطبيقات المطلوبة موجودة فعلًا داخلها.
# هذه المسارات تُفحص قبل البناء وبعد الاستعادة، فلا تظهر أيقونات معطلة.
# v46 (إصلاح جذري لبطء الإقلاع): كانت اللقطة تشترط وجود *كل* التطبيقات الثقيلة
# الأربعة (Android Studio + Cursor + Antigravity Hub + IDE). أي تطبيق واحد يفشل
# تنزيله (وهو شائع: حزم بحجم غيغابايت من شبكة Colab) = لا تُبنى لقطة أبدًا =
# كل إقلاع بارد يعيد تثبيت XFCE/Chrome/KasmVNC من الصفر (2-3 دقائق+).
# الحل: طقتن مستقلتان.
#   • CORE: سط�� المكتب + Chrome + KasmVNC — هذه وحدها تكفي لإقلاع فوي.
#   • OPTIONAL: بيئات التطوير الثقيلة — ُضاف إلى اللقطة عندما تجهز، ولا
#     يمنع غيابها بناء لقطة CORE سريعة.
# النتيجة: أول إقلاع يبني لقطة CORE بسرعة، وكل إقلاع لاحق فوري، ثم تُرفَّع
# اللقطة إلى «كاملة» تلقائيًا مرة واحدة بعد جهوز التطبيقات.
_SNAP_CORE_PATHS = [
    "/usr/bin/xfce4-session", "/usr/bin/Xvfb", "/usr/bin/pulseaudio",
    "/usr/bin/xdotool", "/opt/google/chrome/google-chrome",
]
_SNAP_OPTIONAL_PATHS = [
    "/usr/local/bin/android-studio-colab", "/usr/local/bin/cursor-colab",
    "/usr/local/bin/antigravity-ide-colab", "/usr/local/bin/antigravity-hub-colab",
    "/opt/android-studio/bin/studio", "/opt/cursor/AppRun",
    "/opt/google-antigravity/current-bin", "/opt/google-antigravity-ide/current-bin",
]
# يُحفظ في العلامة للتوافق التشخيصي فقط؛ الفحص الفعلي صار على CORE.
_SNAP_REQUIRED_PATHS = list(_SNAP_CORE_PATHS)


def _snapshot_pointer_ok(pointer):
    """مؤشّر current-bin سليم فقط إن ��ان موجودًا ويشي�� إلى ملف تنفيذي فعلي."""
    try:
        if not os.path.isfile(pointer):return False
        target=Path(pointer).read_text(encoding="utf-8").strip()
        return bool(target and os.path.isfile(target) and os.access(target,os.X_OK))
    except Exception:return False


def _snapshot_core_ready():
    """شرط الحد الأدنى للقطة مفيدة: سطح مكتب قابل للتشغيل + متصفح."""
    try:
        return all(os.path.exists(p) for p in _SNAP_CORE_PATHS)
    except Exception:return False


def _snapshot_optional_apps_ready():
    """هل كل بيئات التطوير الثقيلة جاهزة فعلًا (لترقية اللقطة إلى كاملة)؟"""
    try:
        if not all(os.path.exists(p) for p in _SNAP_OPTIONAL_PATHS):return False
        return all(_snapshot_pointer_ok(p) for p in
                   ("/opt/google-antigravity/current-bin",
                    "/opt/google-antigravity-ide/current-bin"))
    except Exception:return False


def _snapshot_required_paths_ready():
    """بوابة بناء/قبول اللقطة = طبقة CORE فقط (لا تنتظر التطبيقات الثقيلة)."""
    return _snapshot_core_ready()


# v46: طبقات اللقطة. "core" = سطح مكتب + متصفح (تكفي لإ��لا فوري)،
# "full" = core + كل بيئات التطوير الثقية. تُبنى core أولًا ثم تُرقّى تلقائيًا.
SNAPSHOT_TIER_CORE = "core"
# مهلة سماح قصيرة قبل بناء لقطة CORE (لعلّ التطبيقات تجهز فتُدرَج معها)،
# ومهلة طويلة للترقية اللاحقة core→full. غياب التطبيقات لا يمنع CORE.
_SNAP_CORE_GRACE_SECONDS = 240
_SNAP_UPGRADE_WAIT_SECONDS = 2700
SNAPSHOT_TIER_FULL = "full"
# قفل من��ي: أثناء بناء/تقية اللطة يُمنع الحذف الذاتي (_discard_bad_snapshot)
# لأن الأرشيف على Drive يكون مؤقتًا غير متوافق مع العلامة القديمة لثوانٍ.
_SNAPSHOT_BUILD_IN_PROGRESS = threading.Event()


def _snapshot_target_tier():
    """الطبقة الت�� يمكن بنا����ا الآن بحسب ما جهز فعليًا على القرص."""
    return SNAPSHOT_TIER_FULL if _snapshot_optional_apps_ready() else SNAPSHOT_TIER_CORE


def _snapshot_tier_on_drive():
    """طبقة اللقطة الموجودة على Drive، أو None إن لم توجد لقطة صالحة."""
    try:
        _fp, _meta = _snapshot_file_from_mark()
        if not _fp or not _meta:
            return None
        tier = str(_meta.get("tier") or "").strip().lower()
        return tier if tier in (SNAPSHOT_TIER_CORE, SNAPSHOT_TIER_FULL) else SNAPSHOT_TIER_CORE
    except Exception:
        return None


def _have_zstd():
    return os.path.exists("/usr/bin/zstd") or os.path.exists("/bin/zstd")



def _snapshot_file_from_mark():
    """يعيد لقطة موثوقة بنيويًا فقط؛ يمنع traversal/symlink وخلط الإصدارات."""
    if not (DRIVE_OK and os.path.isfile(SNAPSHOT_MARK)):
        return None, None
    try:
        if os.path.islink(SNAPSHOT_MARK):
            raise ValueError("marker symlink")
        meta = json.loads(Path(SNAPSHOT_MARK).read_text(encoding="utf-8"))
        if not isinstance(meta, dict):
            raise ValueError("marker is not an object")
        if int(meta.get("schema", -1)) != SNAPSHOT_SCHEMA:
            raise ValueError("schema mismatch")
        if meta.get("version") != SNAPSHOT_VERSION:
            raise ValueError("version mismatch")
        if meta.get("required_paths") != _SNAP_REQUIRED_PATHS:
            raise ValueError("required application set mismatch")
        import platform
        osrel = {}
        try:
            for _line in Path("/etc/os-release").read_text(encoding="utf-8", errors="ignore").splitlines():
                if "=" in _line:
                    _k,_v=_line.split("=",1); osrel[_k]=_v.strip().strip('"')
        except Exception:
            pass
        if meta.get("machine") != platform.machine():
            raise ValueError("architecture mismatch")
        if meta.get("os_id") != osrel.get("ID") or meta.get("os_version") != osrel.get("VERSION_ID"):
            raise ValueError("operating-system mismatch")
        fname = str(meta.get("file") or "")
        if not fname or fname != os.path.basename(fname):
            raise ValueError("unsafe archive name")
        if not (fname.endswith(".tar.zst") or fname.endswith(".tar.gz")):
            raise ValueError("unsupported archive extension")
        fpath = os.path.join(SNAPSHOT_DIR, fname)
        if os.path.islink(fpath) or not _inside_safe_roots(fpath):
            raise ValueError("unsafe archive path")
        if not os.path.isfile(fpath):
            raise FileNotFoundError(fname)
        if bool(meta.get("zstd",fname.endswith(".zst"))):
            dec=meta.get("decoder") or {};dname=str(dec.get("file") or "")
            if dname!=os.path.basename(SNAPSHOT_ZSTD_DECODER) or dname!=os.path.basename(dname):
                raise ValueError("unsafe zstd decoder name")
            dpath=os.path.join(SNAPSHOT_DIR,dname)
            if os.path.islink(dpath) or not _inside_safe_roots(dpath) or not os.path.isfile(dpath):
                raise ValueError("missing zstd decoder")
            if os.path.getsize(dpath)!=int(dec.get("size",-1)) or not re.fullmatch(r"[0-9a-f]{64}",str(dec.get("sha256") or "")):
                raise ValueError("invalid zstd decoder metadata")
        return fpath, meta
    except Exception as _e:
        print("[!] علامة مخبأ الإقلاع غير صالحة: %s" % _e)
        return None, None


def _snapshot_ready_on_drive():
    """تحقق بنيوي سريع؛ أي حزمة ناقصة/غير منطقية تُحذف فورًا من Drive."""
    marker_exists = os.path.lexists(SNAPSHOT_MARK)
    fpath, meta = _snapshot_file_from_mark()
    if not fpath or not meta:
        if marker_exists:
            _discard_bad_snapshot("علامة مفقودة/غير صالحة")
        return False
    try:
        actual = os.path.getsize(fpath)
        expected = int(meta.get("size", -1))
        sha = str(meta.get("sha256") or "").lower()
        if expected != actual or actual < SNAPSHOT_MIN_BYTES:
            _discard_bad_snapshot("حجم الأرشيف لا يطابق العلامة")
            return False
        if not __import__('re').fullmatch(r'[0-9a-f]{64}', sha):
            _discard_bad_snapshot("بصمة SHA-256 غير صالحة")
            return False
        return True
    except Exception as _e:
        _discard_bad_snapshot("تعذر فحص الأرشيف: %s" % _e)
        return False


def _purge_old_snapshots():
    """يبقي الأرشيف الحالي السليم فقط ويحذف القديم/اليتيم/الجزئي فورًا."""
    try:
        if not os.path.isdir(SNAPSHOT_DIR):
            return
        keep = set()
        fpath, _meta = _snapshot_file_from_mark()
        if fpath:
            keep.update((os.path.realpath(fpath), os.path.realpath(SNAPSHOT_MARK)))
            if os.path.isfile(SNAPSHOT_ZSTD_DECODER):
                keep.add(os.path.realpath(SNAPSHOT_ZSTD_DECODER))
        removed = 0; freed = 0; entries = []
        for fn in list(os.listdir(SNAPSHOT_DIR)):
            p = os.path.join(SNAPSHOT_DIR, fn)
            if os.path.islink(p) or not os.path.isfile(p):
                continue
            if os.path.realpath(p) in keep:
                continue
            if fn.startswith("rootfs-") or fn.startswith("zstd-decoder-") or fn.endswith(".partial"):
                got = _safe_unlink(p)
                if got is not None:
                    removed += 1; freed += got
                    entries.append(("fastboot-قديم/يتيم", os.path.basename(p), got))
        _append_cleanup_log(entries)
        if removed:
            print("[🧹 FastBoot] حُذف %d ملف قديم/يتيم (%.0fMB) من Drive ✅"
                  % (removed, freed / 1048576.0))
    except Exception as _e:
        print("[!] تعذر تنظيف مخبأ FastBoot: %s" % _e)

def _purge_deb_cache_on_drive():
    """بعد نجاح اللقطة الدائمة، أرشيف الـ .deb على Drive يصبح تكرارًا محضًا
    (نفس الملفات داخل اللقطة!) وقد يتجاوز 1.5GB. نحذفه بالكامل لتحرير
    مساحة Drive — اللقطة الواحدة هي مصدر الاستعادة الوحيد الأسرع."""
    try:
        debs = [f for f in os.listdir(PKG_CACHE) if f.endswith(".deb")
                and f != "kasmvncserver.deb"]  # نُبقي KasmVNC (خطة طوارئ خفيفة)
    except Exception:
        return
    if not debs:
        return
    freed = 0
    for f in debs:
        # حذف فردي بعد تحقق realpath داخل PKG_CACHE فقط (يرفض symlinks)
        got = _safe_unlink(os.path.join(PKG_CACHE, f))
        if got is not None:
            freed += got
    try:
        if os.path.exists(PKG_MANIFEST):
            os.remove(PKG_MANIFEST)
    except Exception:
        pass
    if freed:
        print("[🧹 تنظيف] حُذف أرشيف .deb المكرّر من Drive (%.0fMB مُحرَّرة) — "
              "اللقطة الواحدة تكفي ✅" % (freed / 1048576))


# ============================================================
# >>> إدارة آمنة جدًّا لمساحة Drive الخاصة بالمشروع <<<
# حدّ المشروع 6.5GB مع احتياطي طوارئ دائم 1.5GB. قرار التنظيف/الحفظ يعتمد
# حصراً عل حجم عناصر السكربت داخل PKG_CACHE وSNAPSHOT_DIR (لا statvfs وحده،
# وحجم PERSIST_DIR يُحسب للعرض فقط). ممنوع فحص/حذف أي شيء خارج هذين
# الملدين  لا workspace ولا home_root ولا chrome-profiles ولا أي ملفات
# مستخدم مهما كان امتدادها/عرها. الاستثناء الوحيد: ملف cleanup-log داخل
# PERSIST_DIR (تدوير فقط). الحذف فردي (os.unlink) بعد تحقق realpath —
# لا find -delete ولا rm -rf لمسار ديناميكي. لتشغيل مرتين آمن.
DRIVE_PROJECT_LIMIT_GB = 6.5
DRIVE_EMERGENCY_FREE_GB = 1.5
DRIVE_PROJECT_LIMIT_BYTES = int(DRIVE_PROJECT_LIMIT_GB * 1024 ** 3)
DRIVE_EMERGENCY_FREE_BYTES = int(DRIVE_EMERGENCY_FREE_GB * 1024 ** 3)
_CLEANUP_LOG = os.path.join(PERSIST_DIR, "cleanup-log.tsv")
_SAFE_CLEAN_LOCK = threading.Lock()
# يُرفع أثناء نسخ/استعادة/تثبيت الحزم لمنع حذف ملفات قيد الاستخدام
_SAFE_CLEAN_BUSY = {"copy": False}


def _safe_roots():
    """الجذور الوحيدة المسموح بالتنظيف داخلها (realpath) — لا شيء غيرها."""
    roots = []
    for r in (PKG_CACHE, SNAPSHOT_DIR):
        try:
            if os.path.isdir(r):
                roots.append(os.path.realpath(r))
        except Exception:
            pass
    return roots


def _inside_safe_roots(p):
    """المسار الفعلي داخل realpath(PKG_CACHE) أو realpath(SNAPSHOT_DIR)؟
    يرفض ��ي symlink (قد يشير ��لخ��رج) وأي مسار خ��رجي — شرط إلزامي قبل الح���ف."""
    try:
        if os.path.islink(p):
            return False
        rp = os.path.realpath(p)
        for root in _safe_roots():
            if rp != root and rp.startswith(root + os.sep):
                return True
    except Exception:
        pass
    return False


def _safe_unlink(p):
    """حذف فردي متحقَّق منه (os.unlink) — يعيد الحجم المحذوف أو None عند
    الفشل/��لرفض. فشل ملف واحد لا يوقف العملية."""
    if not _inside_safe_roots(p):
        return None
    try:
        sz = os.path.getsize(p)
    except Exception:
        sz = 0
    try:
        os.unlink(p)
        return sz
    except Exception:
        return None


def _iter_safe_files():
    """ملفات الجذور الآمنة فقط (بلا تكرار للجذور المتداخلة، بلا اتباع symlinks)."""
    roots = _safe_roots()
    tops = [r for r in roots
            if not any(r != o and r.startswith(o + os.sep) for o in roots)]
    for root in tops:
        for dp, dns, fns in os.walk(root):
            dns[:] = [d for d in dns
                      if not os.path.islink(os.path.join(dp, d))]
            for fn in fns:
                yield os.path.join(dp, fn)


def _managed_bytes():
    """حجم عناصر السكربت (PKG_CACHE + SNAPSHOT_DIR) بالبايت — أساس القرار."""
    total = 0
    for fp in _iter_safe_files():
        try:
            if not os.path.islink(fp):
                total += os.path.getsize(fp)
        except Exception:
            pass
    return total


def _cleanup_candidates():
    """مرشّحات التنظيف الآمنة حصراً، بترتيب الحذف المسموح:
      1) .partial بعمر ≥24 ساعة (بلا قفل نشط)   2) لقطات تالفة
      3) لقطات قديمة بشرط بقاء الأحدث السليمة    4) .deb يتيمة
      5) .deb مكررة (تبقى نسخة سليمة واحدة)
    لا يُرشَّح أبدًا: أحدث snapshot سليم، manifest صالح، قائمة الحزم،
    kasmvncserver.deb، أو أي .deb مسجّل — ولا أي ملف خارج الجذور الآمنة."""
    cands = []
    seen = set()
    now = time.time()
    lock_active = False
    try:
        _lk = os.path.join(PKG_CACHE, ".cache.lock")
        if os.path.exists(_lk):
            r = run("fuser %s 2>/dev/null" % shlex.quote(_lk), timeout=10)
            lock_active = bool((getattr(r, "stdout", "") or "").strip())
    except Exception:
        lock_active = False
    busy = lock_active or _SAFE_CLEAN_BUSY.get("copy")

    def _add(cat, p):
        try:
            rp = os.path.realpath(p)
        except Exception:
            return
        if rp in seen or not _inside_safe_roots(p):
            return
        seen.add(rp)
        try:
            sz = os.path.getsize(p)
        except Exception:
            sz = 0
        cands.append((cat, p, sz))

    # اللقطة السليمة الأحدث + علامتها = محمية دائمًا
    keep = set()
    snap_valid = False
    try:
        if _snapshot_ready_on_drive():
            fpath, _m = _snapshot_file_from_mark()
            if fpath:
                keep.add(os.path.realpath(fpath))
                keep.add(os.path.realpath(SNAPSHOT_MARK))
                snap_valid = True
    except Exception:
        pass
    files = list(_iter_safe_files())
    # (1) ملفات .partial بعمر ≥ 24 ساعة — فقط إن لم يكن هناك نسخ جارٍ
    if not busy:
        for p in files:
            if p.endswith(".partial"):
                try:
                    if now - os.path.getmtime(p) >= 86400:
                        _add("partial-قديم", p)
                except Exception:
                    pass
    # (2)+(3) لقطات تالفة/قديمة — فقط مع بقاء الأحدث السليمة المتحقَّق منها
    if snap_valid:
        _snap_root = os.path.realpath(SNAPSHOT_DIR)
        for p in files:
            fn = os.path.basename(p)
            try:
                if os.path.dirname(os.path.realpath(p)) != _snap_root:
                    continue
            except Exception:
                continue
            if p.endswith(".partial") or os.path.realpath(p) in keep:
                continue
            if fn.startswith("rootfs-") and (".tar" in fn
                                             or fn.endswith(".done")):
                _add("snapshot-قديم/تالف", p)
    # (4)+(5) .deb يتيمة/مكررة في المستوى الأعلى من PKG_CACHE فقط
    if not busy:
        try:
            registered = set()
            if os.path.isfile(PKG_MANIFEST):
                for ln in open(PKG_MANIFEST, encoding="utf-8",
                               errors="ignore"):
                    nm = ln.split("\t")[0].strip()
                    if nm:
                        registered.add(nm)
            have_manifest = bool(registered)
            by_pkg = {}
            for fn in sorted(os.listdir(PKG_CACHE)):
                if not fn.endswith(".deb"):
                    continue
                p = os.path.join(PKG_CACHE, fn)
                if os.path.islink(p) or not os.path.isfile(p):
                    continue
                if fn == "kasmvncserver.deb":
                    continue  # خطة الطوارئ الخفيفة — لا تُحذف
                by_pkg.setdefault(fn.split("_", 1)[0], []).append(fn)
                # يتيم = غير مسجّل في manifest صالح (لا حذف لمجرد القِدم)
                if have_manifest and fn not in registered:
                    _add("deb-يتيم", p)
            for _base, fns in by_pkg.items():
                if len(fns) < 2:
                    continue
                keep_fn = next((f for f in fns if f in registered), None)
                if keep_fn is None:
                    keep_fn = max(fns, key=lambda f: os.path.getmtime(
                        os.path.join(PKG_CACHE, f)))
                for fn in fns:
                    if fn != keep_fn:
                        _add("deb-مك��ر", os.path.join(PKG_CACHE, fn))
        except Exception:
            pass
    return cands


def _append_cleanup_log(entries):
    """سجلّ التنظيف داخل PERSIST_DIR: وقت + فئة + حجم + مسار نسبي فقط."""
    if not entries:
        return
    try:
        with open(_CLEANUP_LOG, "a", encoding="utf-8") as f:
            ts = time.strftime("%Y-%m-%d %H:%M:%S")
            for cat, rel, sz in entries:
                f.write("%s\t%s\t%d\t%s\n" % (ts, cat, sz, rel))
    except Exception:
        pass


def _run_safe_cleanup(auto=False):
    """ينفّذ التنظيف الآمن (المرشّحات أعلاه فقط) — حذف فردي متحقَّق منه.
    يعيد (البايتات المحرَّرة، عدد العناصر). التشغيل مرتين آمن."""
    freed = 0
    n = 0
    entries = []
    if not _SAFE_CLEAN_LOCK.acquire(blocking=False):
        return 0, 0  # تنظيف آخر جارٍ — لا تعارض
    try:
        base = os.path.realpath(PKG_CACHE)
        for cat, p, _sz in _cleanup_candidates():
            try:
                rel = os.path.relpath(os.path.realpath(p), base)
            except Exception:
                rel = os.path.basename(p)
            got = _safe_unlink(p)
            if got is None:
                continue  # فشل/رُفض ملف واحد — نتابع بحذر
            freed += got
            n += 1
            entries.append((cat, rel, got))
        # (6) تدوير سجل تنظيف قديم يخص السكربت فقط (لا حذف ملفات أخرى)
        try:
            if os.path.isfile(_CLEANUP_LOG) \
                    and os.path.getsize(_CLEANUP_LOG) > 5 * 1024 * 1024:
                _lines = open(_CLEANUP_LOG, encoding="utf-8",
                              errors="ignore").readlines()[-200:]
                with open(_CLEANUP_LOG, "w", encoding="utf-8") as f:
                    f.writelines(_lines)
        except Exception:
            pass
    finally:
        _SAFE_CLEAN_LOCK.release()
    _append_cleanup_log(entries)
    return freed, n


def _notify_desktop_ar(title, text):
    """إش��ار عربي داخل سطح المكتب (best-effort) — لا نافذة حوارية."""
    try:
        _disp = globals().get("DISPLAY_NUM", ":1")
        run("DISPLAY=%s notify-send %s %s 2>/dev/null" %
            (_disp, shlex.quote(title), shlex.quote(text)), timeout=10)
    except Exception:
        pass


def _drive_budget_ok(extra_bytes, what=""):
    """حارس الميزانية قبل أي حفظ إلى Drive: هل تبقى عناصر السكربت ضمن حدّ
    6.5GB (يحمي احتياطي 1.5GB) بعد إضافة extra_bytes؟ عند التجاوز: تنظيف
    طوارئ محدود جدًّا (القائمة الآمنة فقط، بلا نافذة). إن لم تكفِ المساحة:
    False + إشعار عربي بأن الحفظ تم تجاوزه — لا يُحذف شيء آخر أبدًا."""
    try:
        used = _managed_bytes()
        if used + extra_bytes <= DRIVE_PROJECT_LIMIT_BYTES:
            return True
        freed, n = _run_safe_cleanup(auto=True)
        if n:
            msg = ("تنظيف طوارئ آمن قبل الحفظ: %d عنصرًا (%.0fMB محرَّرة)"
                   % (n, freed / 1048576.0))
            print("[🧹 طوارئ] %s ✅" % msg)
            _notify_desktop_ar("تنظيف مساحة Colab الآمن", msg)
        used = _managed_bytes()
        if used + extra_bytes <= DRIVE_PROJECT_LIMIT_BYTES:
            return True
        msg = ("تم تجاوز حفظ %s لحماية الاحتياطي (%.1fGB): عناصر السكربت "
               "%.0fMB + المطلوب %.0fMB يتجاوزان حدّ %.1fGB."
               % (what or "العنصر الجديد", DRIVE_EMERGENCY_FREE_GB,
                  used / 1048576.0, extra_bytes / 1048576.0,
                  DRIVE_PROJECT_LIMIT_GB))
        print("[⛔ مساحة] %s" % msg)
        _notify_desktop_ar("حماية مساحة Drive", msg)
        return False
    except Exception:
        return True  # الحارس best-effort — لا يُفشل الحفظ لعطل في الحساب


def _create_system_snapshot(force=False, tier=None):
    """يُنشئ «لقطة الدلتا» — أرشيف واحد صغير يضمّ فقط الملفات التي ثبّتها
    السكربت (ctime أحدث من علامة الإقلاع) + قاعدة بيانات dpkg كاملة.

    v46: صار للّقطة «طبقة» (tier):
      • core = سطح المكتب + Chrome + KasmVNC → تكفي لإقلاع فوري وتُبنى بسرعة.
      • full = core + بيئات التطوير الثقيلة → تُرقّى تلقائيًا عند جهوزها.
    force=True: أعد البناء رغم وجود لقطة سليمة (للترقية core→full فقط)."""
    if SAFE_PACKAGE_RESTORE:
        _safe_restore_notice(); return False
    if not DRIVE_OK:
        print("[!] Drive غير متاح — تخطّينا إنشاء اللقطة الدائمة.")
        return False
    tier = tier or _snapshot_target_tier()
    if not force and _snapshot_ready_on_drive():
        print("[📸 لقطة] اللقطة الدائمة موجودة وسليمة على Drive — لن نُعيد إنشاءها ✅")
        return True
    if not _snapshot_required_paths_ready():
        print("[i] لن تُبنى لقطة FastBoot ناقصة؛ سطح المكتب أو المتصفح لم يجهز بعد.")
        return False
    _SNAPSHOT_BUILD_IN_PROGRESS.set()
    try:
        return _create_system_snapshot_locked(tier)
    finally:
        _SNAPSHOT_BUILD_IN_PROGRESS.clear()


def _create_system_snapshot_locked(tier):
    """جسم بناء اللقطة (يُنادى دائمًا داخل قفل البناء المنطقي)."""
    print("[📸 لقطة] الطبقة المستهدفة: %s" % tier)
    # نضمن وجود zstd (ضغط فائق السرعة/النسبة)؛ إن غاب نستخدم gzip كبديل.
    if not _have_zstd():
        run("sudo DEBIAN_FRONTEND=noninteractive apt-get install -y -qq zstd "
            "> /dev/null 2>&1", timeout=180)
    _use_zstd = _have_zstd()
    tar_local = "/tmp/rootfs-snapshot.tar.zst" if _use_zstd \
        else "/tmp/rootfs-snapshot.tar.gz"
    comp = ("zstd -T0 -3" if _use_zstd else "gzip -3")
    excl = " ".join("--exclude='%s'" % e for e in _SNAP_EXCLUDES)
    print("[📸 لقطة] بناء «لقطة الدلتا» لأول مرّة (ملفاتنا فقط — أصغر 10-20×)...")
    # (1) قائمة الملفات المتغيّرة بعد علامة الإقلاع (= ما ثبّتناه نحن فقط).
    #     -cnewer يقارن ctime (يلتقط ملفّات dpkg المنسوخة بطوابع زمنية قديمة).
    listfile = "/tmp/.snap_delta_list"
    paths = " ".join("/" + p for p in _SNAP_PATHS if os.path.exists("/" + p))
    _delta_ok = False
    if os.path.exists(BOOT_MARKER):
        r = run("sudo find %s -xdev \\( -type f -o -type l \\) "
                "-cnewer %s -print0 2>/dev/null | tr '\\0' '\\n' "
                "| sed 's|^/||' > %s" % (paths, BOOT_MARKER, listfile),
                timeout=600)
        try:
            _nlines = sum(1 for _ in open(listfile, encoding="utf-8",
                                          errors="ignore"))
        except Exception:
            _nlines = 0
        # عاقل (آلاف ا��لفات لا صفر ولا ملايين) — وإا نرجع للقطة الكاملة
        _delta_ok = (getattr(r, "returncode", 1) == 0
                     and 200 < _nlines < 2_000_000)
        if _delta_ok:
            # قاعدة بيانات dpkg كاملة إلزامية (حالة الحزم متّسقة عند الاستعادة)
            run("sudo find /var/lib/dpkg -xdev \\( -type f -o -type l \\) "
                "-print0 2>/dev/null | tr '\\0' '\\n' | sed 's|^/||' >> %s"
                % listfile, timeout=120)
            run("sort -u -o %s %s" % (listfile, listfile), timeout=120)
            print("[📸 لقطة] الدلتا: %d ملفًّا (بدل ملايين ملفّات صورة Colab) ⚡"
                  % _nlines)
    if _delta_ok:
        r = run("cd / && sudo tar -I '%s' %s --no-recursion "
                "--files-from=%s -cf %s 2>/dev/null"
                % (comp, excl, listfile, tar_local), timeout=1800)
    else:
        # احتياط: اللقطة الكاملة القديمة (نادرًا — لو غابت علامة الإقلاع)
        print("[i] علامة الإقلاع غير متاحة — لقطة كاملة احتياطية.")
        r = run("cd / && sudo tar -I '%s' %s -cf %s %s 2>/dev/null"
                % (comp, excl, tar_local,
                   " ".join(p for p in _SNAP_PATHS if os.path.exists("/" + p))),
                timeout=1800)
    run("rm -f %s" % listfile)
    if getattr(r, "returncode", 1) != 0 or not os.path.exists(tar_local) \
            or os.path.getsize(tar_local) < 5_000_000:
        print("[✗] فشل بناء اللقطة — نُكمل بالطريقة العادية (لا ضرر).")
        run("rm -f %s" % tar_local)
        return False
    size = os.path.getsize(tar_local)
    # >>> ارس مساحة المشروع (6.5GB/احتياطي 1.5GB): افحص الحجم المتوقع قبل
    # الحفظ؛ تنظيف طوارئ آمن محدود عند الحاة، وإلا نتجاوز الحفظ بأمان. <<<
    if not _drive_budget_ok(size, "اللقطة الجديدة"):
        run("rm -f %s" % tar_local)
        return False
    print("[📸 لقطة] الأرشيف جاهز (%.1fMB) — نحسب البصمة ونرفعه إلى Drive..."
          % (size / 1048576))
    sha = run("sha256sum %s | awk '{print $1}'" % tar_local,
              timeout=300).stdout.strip()
    # الرفع الذرّي: ننسخ إلى ملف مؤقّت ثم نعيد التسمية (لا تظهر لقطة نصفية)
    dst = SNAPSHOT_TAR if _use_zstd else SNAPSHOT_TAR.replace(".zst", ".gz")
    try:
        tmp = dst + ".partial"
        shutil.copy2(tar_local, tmp)
        if os.path.getsize(tmp) != size:
            raise IOError("نسخة اللقطة إلى Drive غير مكتملة")
        # تحقق قراءةٍ راجعة من نسخة Drive قبل نشرها؛ الحجم وحده لا يكشف التلف.
        drive_sha = run("sha256sum '%s' | awk '{print $1}'" % tmp,
                        timeout=600).stdout.strip()
        if drive_sha != sha:
            _safe_unlink(tmp)
            raise IOError("بصمة نسخة Drive لا تطابق المصدر المحلي")
        os.replace(tmp, dst)
        # تحقق ثان مؤجل: يلتقط تأخر/تلف Google Drive FUSE قبل اعتماد اللقطة.
        time.sleep(8 if str(SNAPSHOT_DIR).startswith("/content/drive/") else 1)
        delayed_sha = run("sha256sum '%s' | awk '{print $1}'" % dst, timeout=600).stdout.strip()
        if delayed_sha != sha or os.path.getsize(dst) != size:
            _safe_unlink(dst)
            raise IOError("فشل التحقق المؤجل من لقطة النظام")
        decoder_meta = None
        if _use_zstd:
            decoder_src = shutil.which("zstd")
            if not decoder_src or not os.path.isfile(decoder_src):
                raise IOError("مفكك zstd غير متاح لحزمة FastBoot")
            decoder_tmp = SNAPSHOT_ZSTD_DECODER + ".partial"
            shutil.copy2(decoder_src, decoder_tmp)
            decoder_size = os.path.getsize(decoder_tmp)
            decoder_sha = run("sha256sum '%s' | awk '{print $1}'" % decoder_tmp,
                              timeout=120).stdout.strip()
            if decoder_size < 50_000 or not re.fullmatch(r"[0-9a-f]{64}",decoder_sha):
                _safe_unlink(decoder_tmp);raise IOError("مفكك zstd غير صالح")
            os.replace(decoder_tmp,SNAPSHOT_ZSTD_DECODER)
            decoder_meta={"file":os.path.basename(SNAPSHOT_ZSTD_DECODER),
                          "size":decoder_size,"sha256":decoder_sha}
        # نشر العلامة ذريًا بعد اكتمال الأرشيف والتحقق منه فقط.
        import platform
        _osrel = {}
        try:
            for _line in Path("/etc/os-release").read_text(encoding="utf-8", errors="ignore").splitlines():
                if "=" in _line:
                    _k,_v=_line.split("=",1); _osrel[_k]=_v.strip().strip('"')
        except Exception:
            pass
        meta = {"schema": SNAPSHOT_SCHEMA, "version": SNAPSHOT_VERSION,
                "size": size, "sha256": sha, "file": os.path.basename(dst),
                "zstd": _use_zstd, "delta": _delta_ok,
                "decoder": decoder_meta,
                "machine": platform.machine(), "os_id": _osrel.get("ID"),
                "os_version": _osrel.get("VERSION_ID"),
                "required_paths": _SNAP_REQUIRED_PATHS,
                # v46: قائمة CORE فقط هي شرط القبول. التطبيقات الثقيلة تُسجَّل
                # للمعلومة (optional_apps) ولا تُطل لقطة سليمة بغيابها.
                "required_binaries": ["xfce4-session","Xvfb","pulseaudio","xdotool","google-chrome"],
                "tier": tier,
                "optional_apps": _snapshot_optional_apps_ready(),
                "created": time.strftime("%Y-%m-%d %H:%M:%S")}
        mark_tmp = SNAPSHOT_MARK + ".partial"
        with open(mark_tmp, "w", encoding="utf-8") as _mf:
            _mf.write(json.dumps(meta, ensure_ascii=False, separators=(",", ":")))
            _mf.flush(); os.fsync(_mf.fileno())
        os.replace(mark_tmp, SNAPSHOT_MARK)
        print("[💾 لقطة] رُفِعت اللقطة الدائمة إلى Drive وتم التحقّق ✅ "
              "(الإقلاعات القادمة ستكون فورية)")
        run("rm -f %s" % tar_local)
        # >>> إزالة التكرار من Drive: لقطة واحدة فقط + حذف أرشيف .deb الضخم <<<
        _purge_old_snapshots()
        _purge_deb_cache_on_drive()
        return True
    except Exception as _e:
        print("[✗] فشل رفع اللقطة إلى Drive: %s" % _e)
        run("rm -f %s '%s.partial'" % (tar_local, dst))
        return False



def _discard_bad_snapshot(reason):
    """يحذف كل مك��نات FastBoot الت��لفة/الجزئية فورًا ولا يلمس بيانات Chrome."""
    # v46: أثناء بناء/ترقية اللقطة تكون ملفات Drive بحالة انتقالية لثوانٍ
    # (partial + علامة قديمة). حذفها هنا كان يُفسد اللقطة التي نبنيها للتو
    # ويؤدي إلى حلقة «تُبنى ثم تُحذف» = لا لقطة أبدًا = بطء إقلاع دائم.
    if _SNAPSHOT_BUILD_IN_PROGRESS.is_set():
        print("[i] FastBoot: تجاهل الحذف الذاتي (%s) — بناء اللقطة جارٍ الآن." % reason)
        return
    print("[🧹 FastBoot] حذف الحزمة التالفة من Drive (%s) — ستُبنى سليمة تلقائيًا."
          % reason)
    freed = 0; n = 0; entries = []
    try:
        names = list(os.listdir(SNAPSHOT_DIR)) if os.path.isdir(SNAPSHOT_DIR) else []
    except Exception:
        names = []
    candidates = [SNAPSHOT_MARK]
    candidates += [os.path.join(SNAPSHOT_DIR, fn) for fn in names
                   if fn.startswith("rootfs-") or fn.startswith("zstd-decoder-") or fn.endswith(".partial")]
    seen = set()
    for p in candidates:
        rp = os.path.realpath(p)
        if rp in seen: continue
        seen.add(rp)
        if os.path.islink(p):
            continue
        got = _safe_unlink(p) if os.path.exists(p) else None
        if got is not None:
            freed += got; n += 1
            entries.append(("fastboot-تالف", os.path.basename(p), got))
    _append_cleanup_log(entries)
    if n:
        print("[✅ FastBoot] حُذف %d ملف تالف وتحررت %.0fMB من Drive."
              % (n, freed / 1048576.0))

# ============================================================
# v80) طبقة الإقلاع السريع (boot-core)
# ------------------------------------------------------------
# المشكلة: اللقطة الكاملة ضخمة (~2.4GB) فيتأخر ظهور الرابط الأزرق بعد أن
# يحذف Colab بيانات الجلسة. الحل: أرشيف صغير جدًا يحتوي فقط ما يلزم لظهور
# سطح المكتب (XFCE + KasmVNC + الأدوات + مشغّلاتنا)، يُبنى مرة واحدة في
# الخلفية بعد أن يعمل النظام، ويُستعاد أولًا إن لم توجد لقطة كاملة صالحة.
# قواعد الأمان: لا يُبنى إلا بعد ظهور الرابط، ولا يُستعاد فوق ملفات أحدث،
# ولا يمنع أي مسار قديم من العمل (فشلُه صامت تمامًا).
# ============================================================
_BOOT_CORE_DIR = os.path.join(PERSIST_DIR, "boot-core")
_BOOT_CORE_FILE = os.path.join(_BOOT_CORE_DIR, "boot-core.tar.zst")
_BOOT_CORE_META = os.path.join(_BOOT_CORE_DIR, "boot-core.json")
_BOOT_CORE_SCHEMA = 3  # v3 preserves Xvnc + vncpasswd/vncconfig runtime aliases
_BOOT_CORE_PATHS = [
    "usr/bin/xfce4-session", "usr/bin/xfwm4", "usr/bin/xfdesktop",
    "usr/bin/xfce4-panel", "usr/bin/xfsettingsd", "usr/bin/xfconf-query",
    "usr/bin/Xvfb", "usr/bin/xdotool", "usr/bin/wmctrl", "usr/bin/xsel",
    "usr/bin/zenity", "usr/bin/thunar", "usr/bin/xfce4-terminal",
    "usr/bin/dbus-launch", "usr/bin/dbus-daemon", "usr/bin/zstd",
    "usr/bin/kasmvncserver", "usr/bin/vncserver",
    "usr/bin/Xkasmvnc", "usr/bin/Xvnc",
    "usr/bin/kasmvncpasswd", "usr/bin/vncpasswd",
    "usr/bin/kasmvncconfig", "usr/bin/vncconfig",
    "usr/share/kasmvnc", "usr/lib/kasmvncserver", "etc/kasmvnc",
    "usr/share/xfce4", "etc/xdg/xfce4",
    "usr/local/bin", "usr/share/applications",
    # v86: طبقة مكتفية ذاتيًّا — كل ما يلزم لاجتياز فحص الجاهزية ولعمل
    # سطح المكتب كاملًا (Chrome + الصوت + المكتبات المشتركة + الخطوط +
    # الأيقونات والسمات)، فتنطلق الواجهة خلال ثوانٍ من هذه الطبقة بينما
    # تُستكمل اللقطة الكاملة في الخلفية بأولوية منخفضة.
    "usr/bin", "usr/sbin",
    "usr/lib/x86_64-linux-gnu", "usr/lib/gtk-3.0", "usr/lib/gtk-2.0",
    "usr/lib/xfce4", "usr/lib/pulseaudio", "usr/lib/dbus-1.0",
    "usr/lib/gvfs", "usr/lib/glib-networking", "usr/lib/xorg",
    "usr/share/fonts", "usr/share/icons", "usr/share/themes",
    "usr/share/glib-2.0", "usr/share/mime", "usr/share/X11",
    "usr/share/perl5",  # KasmVNC wrapper needs Switch.pm (libswitch-perl)
    "usr/share/desktop-directories", "etc/xdg/menus",
    "opt/google/chrome",
]


def _boot_core_fresh(max_age_hours=48):
    try:
        if not os.path.exists(_BOOT_CORE_FILE):
            return False
        meta={}
        try:
            with open(_BOOT_CORE_META,encoding="utf-8") as f:meta=json.load(f)
        except Exception:
            meta={}
        # لا نعيد استخدام طبقة قديمة تعدّ الحزمة مثبتة بينما تفقد Xvnc.
        if int(meta.get("schema",0) or 0) < _BOOT_CORE_SCHEMA:
            return False
        age = (time.time() - os.path.getmtime(_BOOT_CORE_FILE)) / 3600.0
        return age <= max_age_hours and os.path.getsize(_BOOT_CORE_FILE) > 4_000_000
    except Exception:
        return False


def _create_boot_core_archive():
    """يبني طبقة الإقلاع السريع (صغيرة) بهدوء تام وبأولوية منخفضة."""
    if SAFE_PACKAGE_RESTORE:
        return False
    if _boot_core_fresh():
        return True
    if not os.path.isdir(PERSIST_DIR):
        return False
    if not _have_zstd():
        return False
    try:
        os.makedirs(_BOOT_CORE_DIR, exist_ok=True)
    except Exception:
        return False
    paths = [p for p in _BOOT_CORE_PATHS if os.path.exists("/" + p)]
    if len(paths) < 6:
        return False
    tmp = "/tmp/boot-core.tar.zst"
    # لا تقبل ملفًا مؤقتًا قديمًا إن فشل أمر الإنشاء الحالي.
    try:
        os.unlink(tmp)
    except FileNotFoundError:
        pass
    except OSError:
        return False
    cmd = ("cd / && nice -n 19 ionice -c3 tar -I 'zstd -T0 -3 --long=27' "
           "--warning=no-file-changed --ignore-failed-read -cf %s %s 2>/dev/null"
           % (tmp, " ".join("'%s'" % p for p in paths)))
    r = run(cmd, timeout=1200)
    if (r.returncode != 0 or not os.path.isfile(tmp)
            or os.path.getsize(tmp) < 2_000_000):
        run("rm -f %s" % tmp)
        return False
    size = os.path.getsize(tmp)
    sha = ""
    try:
        sha = run("sha256sum '%s' | awk '{print $1}'" % tmp, timeout=300).stdout.strip()
    except Exception:
        sha = ""
    part = _BOOT_CORE_FILE + ".part"
    try:
        shutil.copyfile(tmp, part)
        os.replace(part, _BOOT_CORE_FILE)
        with open(_BOOT_CORE_META, "w") as f:
            json.dump({"schema": _BOOT_CORE_SCHEMA, "size": size, "sha256": sha,
                       "paths": len(paths), "built": time.time()}, f)
        print("[⚡ إقلاع سريع] جهّزنا طبقة الإقلاع الصغيرة (%.0fMB) في Drive."
              % (size / 1048576.0))
        return True
    except Exception as exc:
        try:
            os.unlink(part)
        except Exception:
            pass
        _diag_event("boot_core_upload", exc, "warning")
        return False
    finally:
        run("rm -f %s" % tmp)


def _restore_boot_core():
    """يستعيد طبقة الإقلاع السريع فقط (بلا لقطة كاملة). صامت عند الغياب."""
    if SAFE_PACKAGE_RESTORE:
        _safe_restore_notice(); return False
    try:
        if not os.path.exists(_BOOT_CORE_FILE):
            return False
        meta = {}
        try:
            with open(_BOOT_CORE_META) as f:
                meta = json.load(f)
        except Exception:
            meta = {}
        local = "/tmp/boot-core-restore.tar.zst"
        cp = run("cp -f '%s' '%s'" % (_BOOT_CORE_FILE, local), timeout=600)
        if getattr(cp, "returncode", 1) != 0 or not os.path.exists(local):
            return False
        want = int(meta.get("size", 0) or 0)
        if (int(meta.get("schema", 0) or 0) < _BOOT_CORE_SCHEMA or not want
                or os.path.getsize(local) != want):
            run("rm -f %s" % local)
            print("[!] طبقة الإقلاع السريع ناقصة/قديمة — سنُكمل بالمسار العادي.")
            return False
        want_sha = str(meta.get("sha256") or "").lower()
        got_sha = run("sha256sum '%s' | awk '{print $1}'" % local, timeout=600).stdout.strip()
        if (not re.fullmatch(r"[0-9a-f]{64}", want_sha)
                or not hmac.compare_digest(got_sha, want_sha)):
            run("rm -f %s" % local)
            print("[!] بصمة طبقة الإقلاع السريع غير مطابقة — رُفضت قبل الفك.")
            return False
        if not _have_zstd():
            run("sudo DEBIAN_FRONTEND=noninteractive apt-get install -y -qq zstd "
                "> /dev/null 2>&1", timeout=120)
        if not _have_zstd():
            run("rm -f %s" % local)
            return False
        print("[⚡ إقلاع سريع] استعادة طبقة الإقلاع الصغيرة (%.0fMB)..."
              % (os.path.getsize(local) / 1048576.0))
        t0 = time.time()
        r = run("cd / && sudo tar -I 'zstd -d -T0' --keep-directory-symlink "
                "-xf %s 2>/dev/null" % local, timeout=900)
        run("rm -f %s" % local)
        okc = (getattr(r, "returncode", 1) == 0
               and os.path.exists("/usr/bin/xfce4-session"))
        if okc:
            print("    ✅ سطح المكتب صار جاهزًا للانطلاق في %.0f ثانية."
                  % (time.time() - t0))
            run("ldconfig > /dev/null 2>&1 || true", timeout=120)
        return bool(okc)
    except Exception as exc:
        _diag_event("boot_core_restore", exc, "warning")
        return False


# ------------------------------------------------------------
# v86) استعادة اللقطة الكاملة في الخلفية (بعد ظهور الرابط)
# ------------------------------------------------------------
# الواجهة تنطلق من طبقة boot-core الخفيفة خلال ثوانٍ، ثم يكمل هذا الخيط
# بقية ملفات النظام محليًّا بأولوية منخفضة: نسخ Drive يبدأ فورًا بالتوازي
# مع الإقلاع، والفكّ فوق الجذر لا يبدأ إلا بعد أن يصبح سطح المكتب والرابط
# أمام المستخدم، فلا يشعر بأي بطء ولا يتسابق أحد على الكتابة في /opt.
# ------------------------------------------------------------
_DEFERRED_FULL_RESTORE = False          # يُضبط True عند الإقلاع من boot-core
_DEF_FULL_LOCK = threading.Lock()       # بوابة /opt: المثبِّت ينتظر الفكّ الخلفي
_DEF_FULL_DONE = threading.Event()      # يُضبط عند اكتمال/تخطّي الاستعادة الخلفية


def _wait_desktop_link_ready(max_seconds):
    """ينتظر ظهور رابط سطح المكتب (بولينغ كسول — لا افتراض مبكر للأسماء)."""
    t_end = time.time() + max_seconds
    while time.time() < t_end:
        try:
            ev = globals().get("_LINK_READY_EVENT")
            if ev is not None and ev.is_set():
                return True
        except Exception:
            pass
        try:
            if os.path.exists("/tmp/desktop_link.txt"):
                return True
        except Exception:
            pass
        time.sleep(3)
    return False


def _background_full_snapshot_restore():
    """يكمل اللقطة الكاملة في الخلفية بعد إقلاع boot-core. فشله صامت وآمن."""
    if SAFE_PACKAGE_RESTORE:
        _DEF_FULL_DONE.set(); return
    try:
        if not _snapshot_ready_on_drive():
            return
        src, meta = _snapshot_file_from_mark()
        if not src or not meta:
            return
        is_zstd = bool(meta.get("zstd", src.endswith(".zst")))
        if is_zstd and not _have_zstd():
            return
        local = "/tmp/rootfs-bg-restore" + (".tar.zst" if is_zstd else ".tar.gz")
        expected = int(meta.get("size", -1))
        # (1) النسخ من Drive يبدأ فورًا — يعمل بالتوازي مع إقلاع الواجهة كله.
        t0 = time.time()
        cp = run("cp -f '%s' '%s'" % (src, local), timeout=1200)
        if getattr(cp, "returncode", 1) != 0 or not os.path.exists(local) \
                or (expected > 0 and os.path.getsize(local) != expected):
            run("rm -f '%s'" % local)
            return
        print("[⚡ خلفية] نُسخت اللقطة الكاملة محليًّا في %.0f ثانية — "
              "ستُستكمل تلقائيًّا بعد ظهور الرابط." % (time.time() - t0), flush=True)
        # (2) البصمة تُحسب بالتوازي مع الانتظار (قراءة من كاش القرص المحلي).
        want_sha = (meta.get("sha256") or "").strip()
        sha_box = {"got": ""}

        def _sha_worker():
            try:
                sha_box["got"] = run(
                    "sha256sum '%s' | awk '{print $1}'" % local,
                    timeout=900).stdout.strip()
            except Exception:
                sha_box["got"] = ""

        sha_thread = None
        if want_sha:
            sha_thread = threading.Thread(target=_sha_worker, daemon=True)
            sha_thread.start()
        # (3) انتظر الرابط بالتوازي مع حساب البصمة، ثم ارفض أي اختلاف قبل الفك.
        _link_ready = _wait_desktop_link_ready(600)
        if sha_thread is not None:
            sha_thread.join(timeout=900)
        got_sha = sha_box.get("got") or ""
        if (not want_sha or not got_sha
                or not hmac.compare_digest(got_sha, want_sha)):
            _discard_bad_snapshot("بصمة sha256 غير مطابقة قبل الفك (خلفية)")
            return
        if not _link_ready:
            print("[i] تأجل فكّ اللقطة الخلفي: تأخر ظهور الرابط — سيبقى النظام"
                  " يعمل من طبقة الإقلاع السريع بكفاءة كاملة.", flush=True)
        else:
            # نمنح الواجهة لحظات استقرار إضافية بعد نشر الرابط.
            time.sleep(10)
            # (4) بوابة /opt: لو كان مثبّت التطبيقات يكتب الآن ننتظر دورنا،
            #     ولو بدأنا أولًا فهو من ينتظر — لا سباق ملفات إطلاقًا.
            with _DEF_FULL_LOCK:
                decomp = "zstd -d -T0" if is_zstd else "gzip -d"
                print("[⚡ خلفية] فكّ اللقطة الكاملة بدأ (أولوية منخفضة — "
                      "لن يؤثر في استخدامك)...", flush=True)
                t1 = time.time()
                r = run("sudo nice -n 19 ionice -c 3 "
                        "tar -I '%s' --unlink-first --keep-directory-symlink "
                        "--no-same-owner -xf '%s' -C / 2>/dev/null"
                        % (decomp, local), timeout=1800)
                if getattr(r, "returncode", 1) == 0:
                    print("[✅ خلفية] اكتملت اللقطة الكاملة في %.0f ثانية — "
                          "كل التطبيقات الثقيلة صارت ج��هزة بلا إعادة تشغيل ⚡"
                          % (time.time() - t1), flush=True)
                    run("sudo ldconfig >/dev/null 2>&1 || true", timeout=120)
                    run("sudo systemctl daemon-reload >/dev/null 2>&1 || true",
                        timeout=30)
                else:
                    _diag_event("bg_full_restore_extract",
                                RuntimeError("extract failed"), "warning")
        # (5) تم التحقق من البصمة قبل أي فكّ فوق الجذر.
    except Exception as _exc:
        _diag_event("bg_full_restore", _exc, "warning")
    finally:
        run("rm -f /tmp/rootfs-bg-restore.tar.zst /tmp/rootfs-bg-restore.tar.gz")
        _DEF_FULL_DONE.set()


def _boot_core_stage_loop():
    """يبني طبقة الإقلاع السريع بعد أن يعمل كل شيء (لا يعطّل الإقلاع أبدًا)."""
    if SAFE_PACKAGE_RESTORE:
        return
    waited = 0
    while waited < 900:
        if os.path.exists("/tmp/desktop_link.txt"):
            break
        time.sleep(15)
        waited += 15
    time.sleep(90)
    while True:
        try:
            _create_boot_core_archive()
        except Exception as exc:
            try:
                _diag_event("boot_core_stage", exc, "warning")
            except Exception:
                pass
        time.sleep(3600)


def _restore_system_snapshot():
    """يستعيد النظام من لقطة Drive الواحدة — بالترتيب الصحيح السريع:
      1) نسخ الأرشيف من Drive إلى القرص المحلي أولًا (قراءة تسلسلية واحدة
         من FUSE = أسرع 5-10× من الفكّ المباش�� عبر FUSE الذي كان يفشل).
      2) فحص الحجم + sha256 قبل الفكّ (لا نفكّ أرشيفًا تالفًا أبدًا).
      3) فكّ محلي خاطف بكل الأنوية.
      4) لو تبي��ن تلف اللقطة: تُحذف ��لقائيًّا كي تُبنى من جديد (إصلاح ذاتي
         — لا فشل متكرّر في كل إقلاع كما كان يحدث سابقًا).
    يعيد True عند النجاح؛ False إن لم توجد لقطة أو فشل الفكّ."""
    if SAFE_PACKAGE_RESTORE:
        _safe_restore_notice(); return False
    if not _snapshot_ready_on_drive():
        # v80: لا لقطة كاملة صالحة — نجرّب طبقة الإقلاع السريع الصغيرة أولًا.
        return _restore_boot_core()
    src, meta = _snapshot_file_from_mark()
    if not src or not meta:
        return False
    is_zstd = bool(meta.get("zstd", src.endswith(".zst")))
    bootstrap_zstd = None
    if is_zstd and not _have_zstd():
        # لا ننتظر apt في الإقلاع الدافئ: انسخ مفكك zstd الموثق الصغير من
        # Drive، وافحص بصمته، ثم استخدمه من /tmp.
        try:
            dec=meta.get("decoder") or {};dsrc=os.path.join(SNAPSHOT_DIR,dec["file"])
            bootstrap_zstd="/tmp/zstd-fastboot"
            shutil.copy2(dsrc,bootstrap_zstd);os.chmod(bootstrap_zstd,0o755)
            if os.path.getsize(bootstrap_zstd)!=int(dec.get("size",-1)):
                raise IOError("decoder size")
            got=run("sha256sum '%s' | awk '{print $1}'"%bootstrap_zstd,timeout=60).stdout.strip()
            if got!=dec.get("sha256"):
                raise IOError("decoder sha256")
            if run([bootstrap_zstd,"--version"],timeout=15).returncode!=0:
                raise IOError("decoder runtime")
        except Exception:
            bootstrap_zstd=None
        # خطة أخيرة فقط إذا تعذّر المفكك المحمول.
        if not bootstrap_zstd:
            run("sudo DEBIAN_FRONTEND=noninteractive apt-get install -y -qq zstd "
                "> /dev/null 2>&1", timeout=90)
        if not _have_zstd():
            if not bootstrap_zstd:
                print("[!] تعذّر توفير zstd الآن — سنُكمل بالتثبيت العادي.")
                return False
    # v86: --long=31 يسمح بفكّ أرشيفات مبنية بنافذة ضغط كبيرة (أسرع فكّا
    #     وأعلى ضغطا)، وهو متوافق رجعيًّا مع الأرشيفات العادية أيضًا.
    decomp = (("'%s' -d -T0 --long=31"%bootstrap_zstd) if (is_zstd and bootstrap_zstd)
              else ("zstd -d -T0 --long=31" if is_zstd else "gzip -d"))
    size_mb = os.path.getsize(src) / 1048576.0
    print("[⚡ لقطة] استعادة ��لنظام من لقطة Drive الواحدة (%.0fMB)..." % size_mb)
    # (1) النسخ المحلي أولًا — دائمًا (وليس كخطة بديلة بعد فشل مضمون).
    local = "/tmp/rootfs-restore" + (".tar.zst" if is_zstd else ".tar.gz")
    t0 = time.time()
    cp = run("cp -f '%s' '%s'" % (src, local), timeout=900)
    if getattr(cp, "returncode", 1) != 0 or not os.path.exists(local) \
            or os.path.getsize(local) != int(meta.get("size", -1)):
        run("rm -f '%s'" % local)
        print("[!] تعذّر نسخ اللقطة من Drive كاملةً — سنُكمل بالتثبيت العادي.")
        return False
    print("    نُسخت محليًّا في %.0f ثانية — فكّ + فحص سلامة متزامنان (مرور واحد)..."
          % (time.time() - t0))
    # >>> v64 — سرعة الإقلاع بعد حذف كولاب لبيانات الجلسة:
    #     كان السكربت يقرأ اللقطة كاملة مرتين (2.4GB للبصمة ثم 2.4GB للفكّ)
    #     ومن دون أي مخرج أثناء العملية، فيبدو واقفًا. الآن:
    #     (أ) البصمة تُحسب في خيط موازٍ للفكّ (قراءة واحدة من الكاش) لا قبله.
    #     (ب) مؤشر تقدّم حيّ كل 6 ثوانٍ فلا تبدو الخلية متوقفة.
    #     (ج) أولوية قرص ومعالج أعلى للفكّ + تعطيل fsync المكلف.
    #     (د) لو اختلفت البصمة تُحذف اللقطة ويُستكمل التثبيت العادي (كما كان). <<<
    want_sha = (meta.get("sha256") or "").strip()
    sha_box = {"got": ""}

    def _sha_worker():
        try:
            sha_box["got"] = run("sha256sum '%s' | awk '{print $1}'" % local,
                                 timeout=900).stdout.strip()
        except Exception:
            sha_box["got"] = ""

    sha_thread = None
    if want_sha:
        sha_thread = threading.Thread(target=_sha_worker, daemon=True)
        sha_thread.start()
    # (2) تحقق كامل قبل أي فكّ بصلاحيات root؛ الفحص بعد الفك لا يحمي النظام.
    if sha_thread is not None:
        sha_thread.join(timeout=900)
    got_sha = sha_box.get("got") or ""
    if (not want_sha or not got_sha
            or not hmac.compare_digest(got_sha, want_sha)):
        run("rm -f '%s'" % local)
        _discard_bad_snapshot("بصمة sha256 غير مطابقة قبل الفك")
        print("[✗] بصمة اللقطة غير مطابقة — رُفضت قبل تعديل النظام.")
        return False
    # (3) فكّ محلي خاطف. --keep-directory-symlink يمنع كسر روابط النظام.
    t1 = time.time()
    _tick_stop = threading.Event()

    def _tick_worker():
        waited = 0
        while not _tick_stop.wait(6):
            waited += 6
            try:
                used = os.statvfs("/")
                free_gb = (used.f_bavail * used.f_frsize) / 1073741824.0
                print("    … فكّ اللقطة جارٍ (%d ثانية) — متبقٍ على القرص %.1fGB"
                      % (waited, free_gb))
            except Exception:
                print("    … فكّ اللقطة جارٍ (%d ثانية)" % waited)

    _tick = threading.Thread(target=_tick_worker, daemon=True)
    _tick.start()
    try:
        r = run("sudo nice -n -5 ionice -c 2 -n 0 "
                "tar -I '%s' --keep-directory-symlink --no-same-owner "
                "-xf '%s' -C / 2>/dev/null" % (decomp, local), timeout=1200)
    finally:
        _tick_stop.set()
    run("rm -f '%s'" % local)
    if getattr(r, "returncode", 1) != 0:
        # الفكّ فشل = أرشيف تالف/مبني خطأ → إصلاح ذاتي بإعادة البناء
        _discard_bad_snapshot("فشل فكّ الأرشيف")
        print("[✗] فشل استعادة اللقطة — سنُكمل بالتثبيت العادي.")
        return False
    print("    فُكّت اللقطة في %.0f ثانية ⚡" % (time.time() - t1))
    # تحديث الروابط/الكاش الخفيف بعد الاستعادة (لا يُنزّل شيئًا)
    run("sudo ldconfig >/dev/null 2>&1 || true", timeout=120)
    run("sudo systemctl daemon-reload >/dev/null 2>&1 || true", timeout=30)
    if not _snapshot_required_paths_ready():
        _discard_bad_snapshot("اللقطة لا تحتوي طبقة CORE (سطح المكتب/المتصفح)")
        print("[✗] لقطة FastBoot ناقصة؛ سيُستكمل التثبيت العادي وتُبنى لقطة سليمة.")
        return False
    print("[✅ لقطة] استُعيد النظام من اللقطة الواحدة — إقلاع فوري ⚡⚡")
    # v46: إن كانت اللقطة من طبقة core فقط، فسطح المكتب جاهز فورًا والتطبيقات
    # الثقيلة ستُثبَّت/تُستكمل في الخلفية ثم تُرقّى اللقطة إلى full تلقائيًا.
    if _snapshot_tier_on_drive() == SNAPSHOT_TIER_CORE:
        print("[i] طبقة اللقطة = core: سطح المكتب فوري ✅ "
              "وبيئات التطوير تُستكمل في الخلفية ثم تُرقّى اللقطة تلقائيًا.")
    return True


def _with_pkg_cache_lock(command, timeout=600):
    """قفل واحد يمنع نسخ Drive ال��تزامن أو تكرار تنزيل الحزمة نفسها."""
    lock = os.path.join(PKG_CACHE, ".cache.lock")
    return run("flock -w 300 '%s' bash -lc %s" %
               (lock, shlex.quote(command)), timeout=timeout)


def _save_apt_cache_to_drive():
    """يحفظ أرشيفات apt في خيط خلفي — لا يعلِّق الإقلاع إطلاقًا.
    (كان النسخ المتزامن لمئات الملفات إلى FUSE يجمّد الخلية دقائق.)
    منع التكرار: يت��طّى تمامًا إن كانت اللقطة الدائمة موجودة (هي المصدر)."""
    if not (DRIVE_OK and os.path.isdir(PKG_CACHE)):
        return False
    # >>> منع التكرار: إن كانت «اللقطة الدائمة» موجودة وسليمة فهي الطريق
    #     الأساسي للإقلاع؛ لا حاجة لنسخ أي .deb إلى Drive مجدّدًا. <<<
    try:
        if _snapshot_ready_on_drive() and not SAFE_PACKAGE_RESTORE:
            return True
    except Exception:
        pass
    _preserve_apt_archives()

    def _worker():
        archives = []
        try:
            archives = [x for x in Path('/var/cache/apt/archives').glob('*.deb')
                        if x.is_file() and x.stat().st_size > 0]
        except Exception:
            pass
        if not archives:
            return
        copied = 0
        # >>> حارس مساحة المشروع: افحص الحجم المتوقع للملفات الجديدة قبل
        # النسخ�� عند تجاوز 6.5GB يجري تنظيف طوارئ آمن، وإلا يُتجاوز الحفظ. <<<
        try:
            _new_bytes = 0
            for _a in archives:
                _d = os.path.join(PKG_CACHE, _a.name)
                if not (os.path.exists(_d)
                        and os.path.getsize(_d) == _a.stat().st_size):
                    _new_bytes += _a.stat().st_size
            if _new_bytes and not _drive_budget_ok(_new_bytes, "أرشيف الحزم"):
                return
        except Exception:
            pass
        _SAFE_CLEAN_BUSY["copy"] = True
        try:
            with open(os.path.join(PKG_CACHE, '.cache.lock'), 'a'):
                for src in archives:
                    # لو اكتملت اللقطة أثناء النسخ نتوقّف فورًا (لا تكرار)
                    if _snapshot_ready_on_drive() and not SAFE_PACKAGE_RESTORE:
                        return
                    dst = os.path.join(PKG_CACHE, src.name)
                    if os.path.exists(dst) and os.path.getsize(dst) == src.stat().st_size:
                        continue
                    # النقل عبر shutil إلى FUSE أكثر موثوقية من wildcard.
                    tmp = dst + '.partial'
                    shutil.copy2(str(src), tmp)
                    if os.path.getsize(tmp) != src.stat().st_size:
                        raise IOError("نسخة غير مكتملة: %s" % src.name)
                    os.replace(tmp, dst)
                    copied += 1
            saved = [x for x in Path(PKG_CACHE).glob('*.deb') if x.is_file()]
            total = sum(x.stat().st_size for x in saved)
            Path(PKG_MANIFEST).write_text(
                '\n'.join('%s\t%d' % (x.name, x.stat().st_size)
                          for x in sorted(saved)) + '\n')
            print("[💾 حزم] Drive مؤكد: %d ملفًا، %.1fMB؛ جديد هذه المرة: %d."
                  % (len(saved), total / 1048576, copied))
        except Exception as _e:
            print("[!] فشل حفظ أرشيف الحزم في Drive: %s" % _e)
        finally:
            _SAFE_CLEAN_BUSY["copy"] = False

    threading.Thread(target=_worker, name="save_debs_bg", daemon=True).start()
    return True


_V15_CORE_PKGS = (
    "ca-certificates curl wget jq tar gzip xz-utils "
    "xvfb x11-utils x11-xserver-utils xdotool wmctrl xsel xauth "
    "dbus-x11 at-spi2-core desktop-file-utils zenity net-tools "
    "imagemagick x11-apps libxfont2 libxtst6 libxext6 libxdamage1 "
    "libxfixes3 pulseaudio pulseaudio-utils alsa-utils "
    "locales language-pack-ar language-pack-gnome-ar ibus ibus-table "
    "ibus-m17n xfce4 xfce4-session xfwm4 xfdesktop4 xfce4-panel "
    "xfce4-settings xfce4-terminal thunar xfce4-taskmanager exo-utils "
    "xfce4-power-manager xfce4-notifyd thunar-archive-plugin "
    "file-roller fonts-noto-core fonts-noto-ui-core fonts-kacst-one "
    "fonts-hosny-amiri fonts-dejavu fonts-liberation")
import re as _re_v15


def _v15_match_names(names):
    out = []
    for p in _V15_CORE_PKGS.split():
        rx = _re_v15.compile(
            '^' + _re_v15.escape(p).replace(r'\+', r'\+') + r'_.*\.deb$')
        hits = sorted(n for n in names if rx.match(n))
        if hits:
            out.append(hits[-1])
    return out


def _core_ready():
    need = ("/usr/bin/xfce4-session", "/usr/bin/xfwm4",
            "/usr/bin/xfdesktop", "/usr/bin/xfce4-panel",
            "/usr/bin/Xvfb", "/usr/bin/pulseaudio",
            "/usr/bin/xdotool", "/opt/google/chrome/google-chrome")
    return all(os.path.isfile(p) and os.access(p, os.X_OK) for p in need)


def _v15_install_rest_bg(names):
    """يثبّت بقية حزم .deb في خيط خلفي منخفض الأولوية؛ لا يحجب الإقلاع."""
    try:
        if not names:
            return
        import subprocess as _sp
        import shlex as _sh
        base = "/var/cache/apt/archives"
        files = " ".join(_sh.quote(os.path.join(base, n)) for n in names)
        script = (
            "sudo DEBIAN_FRONTEND=noninteractive "
            "dpkg --force-confdef --force-confold --force-unsafe-io "
            "-i --no-triggers " + files + " </dev/null >/dev/null 2>&1 || true; "
            "sudo DEBIAN_FRONTEND=noninteractive dpkg --configure -a "
            "</dev/null >/dev/null 2>&1 || true; "
            "sudo DEBIAN_FRONTEND=noninteractive dpkg --triggers-only -a "
            "</dev/null >/dev/null 2>&1 || true; "
            "sudo DEBIAN_FRONTEND=noninteractive apt-get install -y -qq -f "
            "--no-download </dev/null >/dev/null 2>&1 || true; "
            "echo done >/tmp/.v15-rest-debs-done 2>/dev/null || true")
        _sp.Popen(["nice", "-n", "19", "ionice", "-c", "3",
                   "bash", "-c", script],
                  stdin=_sp.DEVNULL, stdout=_sp.DEVNULL, stderr=_sp.DEVNULL)
        print("[⚡ V15] تثبيت %d حزمة إضافية في الخلفية (لا يحجب الإقلاع)"
              % len(names), flush=True)
    except Exception:
        pass


def _restore_apt_cache_from_drive(install=True):
    """خطة بديلة (فقط إن غابت اللقطة): نسخ .deb من Drive دفعة واحدة عبر
    أنبوب tar (قراءة تسلسلية = أسرع بمرّات من cp مل����ًّا-ملفًّا الذي كان
    يستغرق 10-20 دق��قة على مئات الملفات ويوقف الخلية) — وبميزانية زمنية
    ��ارمة: إن تجاوز النسخ 4 دقائق نُ��غيه ونرجع False فيتولى apt التنزيل من
    الشبكة (شبكة Colab أسرع من Drive-FUSE حينها!). لا تعليق بعد اليوم."""
    if not (DRIVE_OK and os.path.isdir(PKG_CACHE)):
        return False
    try:
        debs = [f for f in os.listdir(PKG_CACHE)
                if f.endswith('.deb') and os.path.getsize(os.path.join(PKG_CACHE, f)) > 0]
    except Exception:
        debs = []
    if not debs:
        return False
    _v15_cached = sorted(debs)
    print("[⚡ تسريع] استعادة %d ملف .deb من Drive دفعةً واحدة (أنبوب tar)..."
          % len(debs))
    t0 = time.time()
    run("sudo mkdir -p /var/cache/apt/archives", timeout=30)
    # أنبوب tar واحد: يرأ كل الملفات تسلسليًّا من FUSE ويكتبها محليًّا —
    # عملية واحدة بلا فتح/إغلاق لكل ملف. مهلة صارمة 240 ثانية (لا تعليق).
    r = _with_pkg_cache_lock(
        "cd %s && tar -cf - *.deb | sudo tar -xf - -C /var/cache/apt/archives"
        % shlex.quote(PKG_CACHE), timeout=240)
    if getattr(r, "returncode", 1) != 0:
        print("[!] نسخ Drive أبطأ من الشبكة (%.0f ثانية) — سنُنزّل من "
              "الإنترنت مباشرة (أسرع) ⚡" % (time.time() - t0))
        return False
    print("    نُسخت الحزم في %.0f ثانية — تثبيت محلي بلا تنزيل..."
          % (time.time() - t0))
    # dpkg محلي بالكامل — «غير تفاعلي» إجباريًّا: بدونه كان dpkg يسأل عن
    # ملفات الإعداد (conffile prompt) وينتظر إدخالًا لا يأتي أبدًا = تعليق
    # الخلية إلى الأبد. نغلق stdin ونفرض الإجابة التلقائية + مهلات صارمة.
    if not install:
        return True  # v114: نسخ الأرشيفات فقط بلا تثبيت (مسار إصلاح النواة)
    _NI = ("sudo DEBIAN_FRONTEND=noninteractive "
           "dpkg --force-confdef --force-confold ")
    # V15: --force-unsafe-io يقصّر fsync لكل ملف = أسرع بمرّات مع بقاء
    # الأمان (الخيط الخلفي يكمل الإعداد لاحقًا؛ الفشل يسقط للمسار القديم).
    _NIF = ("sudo DEBIAN_FRONTEND=noninteractive "
            "dpkg --force-confdef --force-confold --force-unsafe-io ")
    # V15: إقلاع مرحلي — الأساسيات متزامنة، الباقي خيط خلفي بلا حجب.
    _v15_core = _v15_match_names(_v15_cached)
    _v15_rest = [n for n in _v15_cached if n not in _v15_core]
    if _v15_core:
        _files = " ".join("/var/cache/apt/archives/" + n for n in _v15_core)
        run(_NIF + "-i --no-triggers " + _files +
            " </dev/null >/dev/null 2>&1 || true", timeout=300)
        run(_NI + "--configure -a </dev/null >/dev/null 2>&1 || true",
            timeout=120)
        if _core_ready():
            print("    [⚡ V15] الأساسيات جاهزة في %.0f ثانية — الرابط يقلع "
                  "فورًا والباقي في الخلفية" % (time.time() - t0),
                  flush=True)
            _v15_install_rest_bg(_v15_rest)
            return True
        print("[!] V15: الأساسيات غير جاهزة — سقوط آمن للمسار القديم الكامل",
              flush=True)
    r = run(_NI + "-i --no-triggers /var/cache/apt/archives/*.deb "
            "</dev/null >/dev/null 2>&1 || true", timeout=600)
    if getattr(r, "returncode", 1) == 124:
        print("[!] dpkg تجاوز المهلة (%.0f ثانية) — إ��لاح وإكمال من الشبكة ⚙️"
              % (time.time() - t0))
    run(_NI + "--configure -a </dev/null >/dev/null 2>&1 || true", timeout=300)
    # v114: الـ triggers تُعالَج مرة واحدة هنا بدل تكرارها مع كل حزمة —
    #     man-db/fc-cache/icon-cache كانت تتكرر مئات المرات = دقائق طويلة.
    run(_NI + "--triggers-only -a </dev/null >/dev/null 2>&1 || true", timeout=600)
    run("sudo DEBIAN_FRONTEND=noninteractive apt-get install -y -qq -f "
        "--no-download </dev/null >/dev/null 2>&1 || true", timeout=300)
    print("    اكتمل التثبيت المحلي في %.0f ثانية ✅" % (time.time() - t0))
    return _core_ready()


# ============================================================
# v135) «إقلاع توربو» — أرشيف مقصود وآمن يقلع في أقل من دقيقة
# ------------------------------------------------------------
# بديل سريع عن مسار dpkg -i لمئات الحزم: أرشيف tar واحد صغير يضمّ فقط
# ملفّات الحزم التي يحتاجها سطح المكتب + الأدوات (dpkg -L = دقيق 100%)،
# يُفكّ فوق الجذر خلال ثوانٍ. الفشل في أي نقطة = رجوع تلقائي للمسار الآمن
# القديم (لا شيء يتعطّل أبدًا)، وفحص بصمة خلفي يحذف الأرشيف إن تلف.
# ============================================================
TURBO_BOOT = os.environ.get("TURBO_BOOT", "1").strip().lower() not in ("0", "false", "no", "off")
_TURBO_SCHEMA = 1
_TURBO_DIR = os.path.join(PKG_CACHE, "boot-turbo")
_TURBO_FILE = os.path.join(_TURBO_DIR, "boot-turbo.tar.zst")
_TURBO_META = os.path.join(_TURBO_DIR, "boot-turbo.json")
_TURBO_PKGS = (
    "xfce4 xfce4-session xfwm4 xfdesktop4 xfce4-panel xfce4-settings "
    "xfce4-terminal thunar exo-utils libexo-2-0 libxfce4ui-2-0 libxfce4panel-2.0-4 "
    "libxfconf-0-3 xfconf xvfb x11-xserver-utils x11-utils xdotool wmctrl xsel "
    "dbus-x11 libgtk-3-0 libgtk-3-bin libglib2.0-0 shared-mime-info "
    "desktop-file-utils zenity pulseaudio pulseaudio-utils alsa-utils at-spi2-core "
    "fonts-noto-core fonts-noto-ui-core fonts-dejavu fonts-liberation "
    "imagemagick x11-apps zstd tar gzip xz-utils")
_TURBO_EXTRA_PATHS = [
    "opt/google/chrome",
    "usr/local/bin",
    "usr/share/applications",
    "usr/share/kasmvnc",
    "usr/lib/kasmvncserver",
    "etc/kasmvnc",
]


def _turbo_os_release():
    d = {}
    try:
        for ln in open("/etc/os-release", encoding="utf-8", errors="ignore"):
            if "=" in ln:
                k, v = ln.split("=", 1)
                d[k] = v.strip().strip('"')
    except Exception:
        pass
    return d


def _turbo_meta_ok():
    """قبول بنيوي صارم للأرشيف: مخطّط + معمارية + نظام + حجم مطابق تمامًا."""
    try:
        if not (os.path.isfile(_TURBO_FILE) and os.path.isfile(_TURBO_META)):
            return None, None
        if os.path.islink(_TURBO_FILE) or os.path.islink(_TURBO_META):
            return None, None
        meta = json.loads(open(_TURBO_META, encoding="utf-8").read())
        if int(meta.get("schema", -1)) != _TURBO_SCHEMA:
            return None, None
        rel = _turbo_os_release()
        if meta.get("machine") != platform.machine():
            return None, None
        if meta.get("os_id") != rel.get("ID") or meta.get("os_version") != rel.get("VERSION_ID"):
            return None, None
        if meta.get("file") != os.path.basename(_TURBO_FILE):
            return None, None
        if os.path.getsize(_TURBO_FILE) != int(meta.get("size", -1)):
            return None, None
        if os.path.getsize(_TURBO_FILE) < 20_000_000:
            return None, None
        return _TURBO_FILE, meta
    except Exception:
        return None, None


def _turbo_collect_paths(listfile):
    """يجمع ملفات الحزم المطلوبة بدقة dpkg + الأشجار الإضافية (Chrome/KasmVNC)."""
    run("rm -f %s" % listfile)
    run("for p in %s; do dpkg -L \"$p\" 2>/dev/null; done "
        "| sed 's|^/||' | sort -u > %s" % (_TURBO_PKGS, listfile), timeout=180)
    extra = " ".join(p for p in _TURBO_EXTRA_PATHS if os.path.exists("/" + p))
    if extra:
        run("sudo find %s -xdev \\( -type f -o -type l \\) -print0 2>/dev/null "
            "| tr '\\0' '\\n' | sed 's|^/||' >> %s" % (extra, listfile), timeout=180)
    run("sort -u -o %s %s" % (listfile, listfile), timeout=60)
    try:
        return sum(1 for _ in open(listfile, encoding="utf-8", errors="ignore"))
    except Exception:
        return 0


def _turbo_verify_bg(local, meta):
    """فحص بصمة خلفي: إن تلف الأرشيف يُحذف ويُبنى من جديد — الجلسة الحالية سليمة."""
    try:
        got = run("sha256sum '%s' | awk '{print $1}'" % local, timeout=600).stdout.strip()
        want = str(meta.get("sha256") or "").strip()
        if want and got != want:
            print("[!] بصمة أرشيف توربو غير مطابقة — حُذف وسيُبنى من جديد؛ "
                  "جلسة العمل الحالية سليمة تمامًا.")
            _safe_unlink(_TURBO_FILE)
            _safe_unlink(_TURBO_META)
    except Exception as exc:
        _diag_event("turbo_verify", exc, "warning")
    finally:
        run("rm -f %s" % local)


def _turbo_restore():
    """يستعيد من أرشيف توربو خلال ثوانٍ؛ أي فشل = رجوع للمسار الآمن القديم."""
    if not TURBO_BOOT:
        return False
    fpath, meta = _turbo_meta_ok()
    if not fpath or not meta:
        return False
    if not _have_zstd():
        return False
    local = "/tmp/boot-turbo-restore.tar.zst"
    t0 = time.time()
    print("[🚀 إقلاع توربو] استعادة سطح المكتب من الأرشيف المقصود (%.0fMB)..."
          % (int(meta.get("size", 0)) / 1048576.0))
    cp = run("cp -f '%s' '%s'" % (fpath, local), timeout=300)
    if getattr(cp, "returncode", 1) != 0 or not os.path.exists(local) \
            or os.path.getsize(local) != int(meta.get("size", -1)):
        run("rm -f %s" % local)
        return False
    r = run("cd / && sudo tar -I 'zstd -d -T0' --keep-directory-symlink "
            "--no-same-owner -xf %s 2>/dev/null" % local, timeout=600)
    if getattr(r, "returncode", 1) != 0:
        run("rm -f %s" % local)
        print("[!] فشل فكّ أرشيف توربو — نُكمل بالمسار الآمن العادي.")
        return False
    run("sudo ldconfig >/dev/null 2>&1 || true", timeout=120)
    run("sudo update-mime-database /usr/share/mime >/dev/null 2>&1 || true", timeout=120)
    if not _pkgs_ready():
        run("rm -f %s" % local)
        print("[!] أرشيف توربو لم يجتز فحص الجاهزية — نُكمل بالمسار الآمن العادي.")
        return False
    print("[✅ إقلاع توربو] سطح المكتب جاهز في %.0f ثانية ⚡🚀" % (time.time() - t0))
    threading.Thread(target=_turbo_verify_bg, args=(local, meta),
                     name="turbo-sha-verify", daemon=True).start()
    return True


def _turbo_build_once():
    """يبني الأرشيف المقصود في الخلفية (أولوية منخفضة) — مرّة واحدة فقط."""
    if not os.path.isdir(PKG_CACHE):
        return False
    listfile = "/tmp/.turbo_paths.list"
    n = _turbo_collect_paths(listfile)
    if n < 500:
        run("rm -f %s" % listfile)
        return False
    try:
        os.makedirs(_TURBO_DIR, exist_ok=True)
    except Exception:
        run("rm -f %s" % listfile)
        return False
    tmp = "/tmp/boot-turbo.tar.zst"
    r = run("cd / && sudo nice -n 19 ionice -c3 tar -I 'zstd -T0 -3' "
            "--no-recursion --ignore-failed-read --warning=no-file-changed "
            "--files-from=%s -cf %s 2>/dev/null" % (listfile, tmp), timeout=1200)
    run("rm -f %s" % listfile)
    if getattr(r, "returncode", 1) != 0 or not os.path.exists(tmp) \
            or os.path.getsize(tmp) < 20_000_000:
        run("rm -f %s" % tmp)
        return False
    size = os.path.getsize(tmp)
    if not _drive_budget_ok(size, "أرشيف إقلاع توربو"):
        run("rm -f %s" % tmp)
        return False
    sha = run("sha256sum %s | awk '{print $1}'" % tmp, timeout=300).stdout.strip()
    part = _TURBO_FILE + ".partial"
    try:
        shutil.copy2(tmp, part)
        if os.path.getsize(part) != size:
            raise IOError("partial turbo copy")
        os.replace(part, _TURBO_FILE)
        rel = _turbo_os_release()
        meta = {"schema": _TURBO_SCHEMA, "size": size, "sha256": sha,
                "file": os.path.basename(_TURBO_FILE),
                "machine": platform.machine(),
                "os_id": rel.get("ID"), "os_version": rel.get("VERSION_ID"),
                "paths": n, "built": time.time()}
        mtmp = _TURBO_META + ".partial"
        with open(mtmp, "w", encoding="utf-8") as f:
            json.dump(meta, f, ensure_ascii=False, separators=(",", ":"))
            f.flush()
            os.fsync(f.fileno())
        os.replace(mtmp, _TURBO_META)
        print("[🚀 إقلاع توربو] جُهّز أرشيف الإقلاع السريع (%.0fMB / %d ملفًّا) — "
              "الإقلاعات القادمة أقل من دقيقة ⚡" % (size / 1048576.0, n))
        return True
    except Exception as exc:
        _diag_event("turbo_build_upload", exc, "warning")
        try:
            os.unlink(part)
        except Exception:
            pass
        return False
    finally:
        run("rm -f %s" % tmp)


def _turbo_build_loop():
    """يبني/يجدّد الأرشيف في الخلفية بعد ظهور سطح المكتب — لا يعطّل شيئًا."""
    if not TURBO_BOOT:
        return
    waited = 0
    while waited < 900:
        if os.path.exists("/tmp/desktop_link.txt"):
            break
        time.sleep(15)
        waited += 15
    time.sleep(_INTERACTIVE_MAINTENANCE_GRACE_SECONDS if INTERACTIVE_DESKTOP_PROFILE else 45)
    while True:
        try:
            if _core_ready() and _have_zstd() and not _turbo_meta_ok()[0]:
                _turbo_build_once()
        except Exception as exc:
            try:
                _diag_event("turbo_build", exc, "warning")
            except Exception:
                pass
        time.sleep(3600)


def _apt_heal():
    """إصلاح شامل لنظام الحزم ��� يُستد��ى قبل أي تثبيت. يمنع الأعطال الشائعة:
    الأقفال العالقة، dpkg المقطوع، الاعتماديات المكسورة، والمستودعات
    الخارجية المعطوبة في Colab (cuda/cran/ppa) التي تُفشل apt-get update."""
    # 1) إزالة أقفال apt/dpkg العالقة من جلسة منقطعة
    run("sudo rm -f /var/lib/dpkg/lock /var/lib/dpkg/lock-frontend "
        "/var/lib/apt/lists/lock /var/cache/apt/archives/lock 2>/dev/null")
    # 2) إتمام أي تهيئة dpkg مقطوعة (أشهر خطأ: dpkg was interrupted)
    run("sudo dpkg --configure -a > /dev/null 2>&1", timeout=300)
    # 3) إصلاح الاعتماديات المكسورة (unmet dependencies / held broken)
    run("sudo DEBIAN_FRONTEND=noninteractive apt-get install -y -qq -f "
        "> /dev/null 2>&1", timeout=300)
    # 4) تعطيل مستودعات Colab الخارجية المعطوبة (مفاتيح GPG منتهية/فاشلة
    #    تكسر update) — لا يحتاجها سطح المكتب إطلاقًا. نُبقي مستودع كروم.
    run('sudo mkdir -p /etc/apt/sources.list.d.disabled 2>/dev/null; '
        'for f in /etc/apt/sources.list.d/*.list '
        '/etc/apt/sources.list.d/*.sources; do '
        '[ -e "$f" ] || continue; case "$f" in '
        '*cuda*|*nvidia*|*cran*|*r2u*|*graphics-drivers*|*deadsnakes*) '
        'sudo mv -f "$f" /etc/apt/sources.list.d.disabled/ 2>/dev/null;; '
        'esac; done', timeout=60)


def _apt_update():
    """apt-get update متسامح: ��تقبّل تغيّر Release ويعيد المحاولة."""
    r = run("sudo apt-get update -qq --allow-releaseinfo-change "
            "2>/dev/null", timeout=300)
    if getattr(r, "returncode", 1) != 0:
        run("sudo apt-get update -qq 2>/dev/null || true", timeout=300)



# ============================================================
# 1) الحزم (XFCE + صوت + أدوات)
# ============================================================
# تسريع الإقلاع: إن كانت الحزم الأساسية مثبّتة مسبقًا (جلسة مستأنفة على نفس
# الـ runtime) نتخطّى apt كاملًا (يوفّر 2-3 دقائق على كل إعادة تشغيل).
def _pkgs_ready():
    needed = ["/usr/bin/xfce4-session", "/usr/bin/xfwm4", "/usr/bin/xfdesktop",
              "/usr/bin/xfce4-panel", "/usr/bin/Xvfb", "/usr/bin/pulseaudio",
              "/usr/bin/xdotool", "/opt/google/chrome/google-chrome"]
    if not all(os.path.isfile(p) and os.access(p,os.X_OK) for p in needed):
        return False
    # كشف خلط المكتبات: أي dependency مفقود يعني أن النسخة المستعادة ليست سليمة.
    probes=("/usr/bin/xfce4-panel","/usr/bin/xfwm4","/opt/google/chrome/google-chrome")
    for binary in probes:
        out=(run("ldd '%s' 2>/dev/null | grep -F 'not found' | head -1"%binary,timeout=20).stdout or '').strip()
        if out:return False
    return True

def _v15_schedule_apps_bg(delay=150):
    """حذف الجذر: STABILITY_FIRST كان يمنع تثبيت Android Studio نهائيًّا.
    نعيد تشغيل مثبّت التطبيقات بعد تأخير وبأولوية دنيا فلا ينافس سطح
    المكتب، ولا يُلغى أبدًا."""
    def _w():
        try:
            time.sleep(max(0, int(delay)))
            _install_optional_apps_background()
        except Exception:
            pass
    threading.Thread(target=_w, name="v15-delayed-apps", daemon=True).start()


def _repair_previously_overlaid_desktop_once():
    """أصلح نفس runtime إذا كانت خلية قديمة قد فكّت rootfs عليه بالفعل."""
    marker="/tmp/.safe-desktop-core-repaired-v1"
    if not SAFE_PACKAGE_RESTORE or os.path.exists(marker) or not _pkgs_ready():
        return True
    print("[🛠️ إصلاح] فحص وإعادة تثبيت نواة XFCE من حزم Drive دون حذفها...")
    # انسخ أرشيفات Drive محليًا أولًا؛ هذه العملية لا تعدّل الملفات المحفوظة.
    # v114: الإصلاح يحتاج نواة XFCE فقط — نسخ الأرشيفات بلا تثبيت الكل
    #     (كان dpkg -i لـ452 حزمة بtriggers متكررة = دقائق عند كل إقلاع).
    try:_restore_apt_cache_from_drive(install=False)
    except Exception as exc:_diag_event("safe_deb_restore",exc,"warning")
    core=("xfce4-session xfwm4 xfdesktop4 xfce4-panel xfce4-settings "
          "libgtk-3-0 dbus-x11 desktop-file-utils shared-mime-info")
    cmd=("sudo DEBIAN_FRONTEND=noninteractive apt-get install -y -qq --reinstall "
         "-o DPkg::Lock::Timeout=600 -o Dpkg::Options::=--no-triggers "
         "--no-download %s >/tmp/safe-desktop-repair.log 2>&1"%core)
    r=run(cmd,timeout=900)
    if getattr(r,"returncode",1)!=0:
        # fallback مح��ود لهذه الحزم فقط؛ لا يعيد تنزيل Android/Cursor أو بقية النظام.
        _apt_heal();_apt_update()
        r=run("sudo DEBIAN_FRONTEND=noninteractive apt-get install -y -qq --reinstall %s "
              ">>/tmp/safe-desktop-repair.log 2>&1"%core,timeout=900)
    run("sudo dpkg --triggers-only -a </dev/null >/dev/null 2>&1 || true", timeout=300)
    run("sudo ldconfig >/dev/null 2>&1 || true; "
        "sudo update-mime-database /usr/share/mime >/dev/null 2>&1 || true; "
        "sudo gtk-update-icon-cache -f -t /usr/share/icons/hicolor >/dev/null 2>&1 || true",
        timeout=300)
    ok=(getattr(r,"returncode",1)==0 and _pkgs_ready())
    if ok:
        Path(marker).write_text("ok\n",encoding="utf-8")
        print("[OK] أُصلحت نواة سطح المكتب من الحزم المحفوظة دون لمس Drive ✅")
    else:
        print("[!] الإصلاح المستهدف لم يكتمل؛ سيواصل مسار التثبيت العادي تلقائيًا.")
    return ok


# هل نبني اللقة الدائمة عد التثبيت؟ (نبنيها مرّة واحدة فق عند أول تبيت
# كامل من الإنترنت  لا نبيها إن اسعدنا من لقطة موجودة أصلً��).
_SNAPSHOT_NEEDS_BUILD = False
_WARM_BOOT_FROM_SNAPSHOT = False

if SAFE_PACKAGE_RESTORE and _pkgs_ready():
    # v114: الإصلاح صيانة (مزامنة حالة dpkg) وليس شرطًا للإقلاع — الحزم
    #     جاهزة أصلًا (_pkgs_ready). نؤجّله لخيط خلفي يبدأ بعد اكتمال تجهيز
    #     النظام فينطلق سطح المكتب والرابط فورًا (<دقيقة) بلا أي تضارب أقفال.
    def _deferred_desktop_core_repair():
        try:
            _SYSTEM_CONFIGURATION_DONE.wait(timeout=900)
        except Exception:
            pass
        time.sleep(10)
        try:
            _repair_previously_overlaid_desktop_once()
        except Exception as _rep_exc:
            try:
                _diag_event("deferred_desktop_repair", _rep_exc, "warning")
            except Exception:
                pass
    threading.Thread(target=_deferred_desktop_core_repair,
                     name="deferred-desktop-repair", daemon=True).start()

if not _pkgs_ready() and DRIVE_OK and os.path.exists(_BOOT_CORE_FILE):
    # v86 — المسار الخاطف: طبقة الإقلاع الصغيرة (مكتفية ذاتيًّا الآن) تُستعاد
    # خلال ثوانٍ وتجتاز فحص الجاهزية، فتنطلق الواجهة والرابط فورًا، بينما
    # تُستكمل اللقطة الكاملة محليًّا في خيط خلفي بأولوية منخفضة بعد ظهور
    # الرابط. الفشل صامت تمامًا ويُسقط إلى المسارات الأصلية أدناه كما كانت.
    if not SAFE_PACKAGE_RESTORE: _purge_old_snapshots()
    if _restore_boot_core() and _pkgs_ready():
        _WARM_BOOT_FROM_SNAPSHOT = True
        _DEFERRED_FULL_RESTORE = True
        print("[1] استُعيد الن��ام من طبقة الإقلاع السريع — انطلاق فوري ⚡⚡⚡")
        if _snapshot_ready_on_drive():
            threading.Thread(target=_background_full_snapshot_restore,
                             name="bg-full-snapshot-restore", daemon=True).start()

if _pkgs_ready():
    print("[1] الحزم مثبّتة مسبقًا — تخطّينا التثبيت ⚡")
    # v46: قد تكون الحزم جاهزة (نفس الجلسة/إعادة تشغيل خلية) بلا لقطة على
    # Drive إطلاقًا. سابقًا كان هذا السار يترك _SNAPSHOT_NEEDS_BUILD=False
    # فلا تُبنى لقطة أبدًا = كل جلسة جديدة إقلاع بارد. الآن نبنيها إن غابت.
    if DRIVE_OK and not _snapshot_ready_on_drive():
        _SNAPSHOT_NEEDS_BUILD = True
        print("[i] لا لقطة على Drive — ستُبنى في الخلفية لتسريع الجلسات القادمة ⚡")
else:
    # (0) الأسرع على الإطلاق: استعادة النظام كاملًا من «اللقطة الواحدة» على
    #     Drive (فكّ ضغط أرشيف واحد — بلا تنزيل من الإنترنت وبلا dpkg متكرّر).
    if not SAFE_PACKAGE_RESTORE: _purge_old_snapshots()
    _restored_snap = False
    if TURBO_BOOT:
        _restored_snap = _turbo_restore()
    if not _restored_snap:
        _restored_snap = _restore_system_snapshot()
    if _restored_snap and _pkgs_ready():
        _WARM_BOOT_FROM_SNAPSHOT = True
        print("[1] استُعيد النظام من اللقطة الدائمة — إقلاع فوري ⚡⚡⚡")
        # v46: إن كانت اللقطة من طبقة core فقط، نُفعّل مسار الترقية إلى full
        # كي تُدرَ بيئات التطوير في اللقطة بع جهوزها (مرّة واحدة فقط).
        if _snapshot_tier_on_drive() == SNAPSHOT_TIER_CORE:
            _SNAPSHOT_NEEDS_BUILD = True
    # (1) بديل: الطريقة القديمة (استعادة ملفّات .deb ثم dpkg -i) — إن لم توجد ��قطة
    elif _restore_apt_cache_from_drive() and _core_ready():
        print("[1] استُعيدت حزم النظام من كاش .deb في Drive ⚡⚡")
        # عندنا الحزم لكن لا لقطة بعد → نبنيها الآن لتسريع الإقلاعات القادمة
        _SNAPSHOT_NEEDS_BUILD = True
    else:
        # لا ��قطة ولا كاش كافٍ → تثبيت كامل من الإنترنت (مرّة واحدة في العمر)
        _SNAPSHOT_NEEDS_BUILD = True
        print("[1] تثبيت الحزم (قد يستغرق 2-3 دقائق)...")
        # >>> إصلاح نظام الحزم قبل أي تثبيت (أقفال/dpkg مقطوع/مستودعات
        #     معطوبة) — كان غيابه أكبر سبب لفشل التثبيت الصامت. <<<
        _apt_heal()
        _apt_update()
        # مجموعات الحزم: نثبّت كل مجموعة مع التحقق وإعاد�� المحاولة بعد
        # إصلاح ذاتي — بدل الفشل الصامت السابق (> /dev/null بلا فحص).
        _pkg_groups = [
            ("الأساسيات + X11 + الصوت",
             "ca-certificates curl wget jq tar gzip xz-utils "
             "xvfb x11-utils x11-xserver-utils xdotool wmctrl xsel xauth "
             "dbus-x11 at-spi2-core desktop-file-utils zenity net-tools "
             # >>> v47: imagemagick (import/convert) + x11-apps (xwd) كانا
             #     مفقودين، فكان /_ai_screenshot يرجع خطأ 500 والأهم أن
             #     حارس «الشاشة السوداء» (_screen_luma_probe) يعمل بصمت
             #     بحالة available=False فلا يُصلح شيئًا أبدًا. <<<
             "imagemagick x11-apps "
             "libxfont2 libxtst6 libxext6 libxdamage1 libxfixes3 "
             "pulseaudio pulseaudio-utils alsa-utils locales language-pack-ar language-pack-gnome-ar ibus ibus-table ibus-m17n"),
            ("سطح مكتب XFCE",
             "xfce4 xfce4-session xfwm4 xfdesktop4 xfce4-panel "
             "xfce4-settings xfce4-terminal thunar xfce4-taskmanager "
             "exo-utils xfce4-power-manager xfce4-notifyd thunar-archive-plugin file-roller"),
            ("الخطوط العربية",
             "fonts-noto-core fonts-noto-ui-core fonts-kacst-one "
             "fonts-hosny-amiri fonts-dejavu fonts-liberation"),
        ]
        for _gname, _gpkgs in _pkg_groups:
            _r = run("sudo DEBIAN_FRONTEND=noninteractive apt-get install "
                     "-y -qq %s > /dev/null 2>&1" % _gpkgs, timeout=600)
            if getattr(_r, "returncode", 1) != 0:
                print("[!] فشل تثبيت مجموعة «%s» — إصلاح وإعادة محاولة..."
                      % _gname)
                _apt_heal()
                _apt_update()
                _r = run("sudo DEBIAN_FRONTEND=noninteractive apt-get "
                         "install -y -qq %s" % _gpkgs, timeout=600)
                if getattr(_r, "returncode", 1) != 0:
                    print("[✗] مجموعة «%s» لم تكتمل — راجع الخطأ أعلاه."
                          % _gname)
