# Antigravity 2.0 (Hub/Agent Manager) and Antigravity IDE are separate products.
# The Hub has a known blank-window regression in remote X11 sessions, so it is
# isolated as an optional secondary app. The stable IDE is installed separately
# from Google's official current Linux bundle and becomes the default launcher.
ANTIGRAVITY_IDE_VERSION="2.1.1-6123990880747520"
_AG_IDE_ROOT="/opt/google-antigravity-ide"
_AG_IDE_BIN_FILE=os.path.join(_AG_IDE_ROOT,"current-bin")
_AG_IDE_READY=False

def _antigravity_ide_find_binary(root):
    preferred=[];fallback=[]
    for base,dirs,files in os.walk(root):
        dirs[:]=[d for d in dirs if d not in ("node_modules",)]
        for name in files:
            p=os.path.join(base,name);low=name.lower().replace(" ","-")
            if low in ("antigravity-ide","antigravityide"):preferred.append(p)
            elif "antigravity" in low and not low.endswith((".so",".pak",".json",".png",".svg",".desktop")):fallback.append(p)
    for p in preferred+fallback:
        try:
            os.chmod(p,os.stat(p).st_mode|0o755)
            if os.path.isfile(p) and os.access(p,os.X_OK):return p
        except Exception:pass
    return ""

def _install_antigravity_ide_official():
    global _AG_IDE_READY
    _defer_full_gate()
    try:
        if os.path.isfile(_AG_IDE_BIN_FILE):
            p=Path(_AG_IDE_BIN_FILE).read_text(encoding="utf-8").strip()
            if p.startswith(_AG_IDE_ROOT+os.sep) and os.path.isfile(p):
                os.chmod(p,os.stat(p).st_mode|0o755)
                env=dict(os.environ,HOME='/root',DISPLAY=os.environ.get('DISPLAY',':1'),XDG_RUNTIME_DIR='/tmp/antigravity-ide-runtime')
                os.makedirs(env['XDG_RUNTIME_DIR'],exist_ok=True);os.chmod(env['XDG_RUNTIME_DIR'],0o700)
                if _electron_structural_check(p,_AG_IDE_ROOT):
                    _cached=_runtime_proof_ok(_AG_IDE_ROOT,p,ANTIGRAVITY_IDE_VERSION)
                    if _cached or _electron_install_canary(p,env):
                        if not _cached:_runtime_proof_write(_AG_IDE_ROOT,p,ANTIGRAVITY_IDE_VERSION)
                        _AG_IDE_READY=True;return True
                print('[i] تثبيت Antigravity IDE المحفوظ غير صالح؛ ستتم إعادة بنائه ذريًا...')
    except Exception:pass
    import platform,tarfile,tempfile,hashlib
    arch=platform.machine().lower()
    flavor="linux-x64" if arch in ("x86_64","amd64") else ("linux-arm" if arch in ("aarch64","arm64") else "")
    if not flavor:
        print("[!] Antigravity IDE: المعمارية غير مدعومة: %s"%arch);return False
    url=("https://edgedl.me.gvt1.com/edgedl/release2/j0qc3/antigravity/stable/"+ANTIGRAVITY_IDE_VERSION+"/"+flavor+"/Antigravity%20IDE.tar.gz")
    pkg="/tmp/Antigravity-IDE-%s.tar.gz"%ANTIGRAVITY_IDE_VERSION
    stage=tempfile.mkdtemp(prefix="antigravity-ide-install-",dir="/tmp")
    try:
        r=run("curl --proto '=https' --proto-redir '=https' --tlsv1.2 -fL --retry 4 --retry-all-errors --connect-timeout 25 --max-time 1200 -o '%s.part' '%s'"%(pkg,url),timeout=1250)
        if getattr(r,"returncode",1)!=0:raise RuntimeError("official IDE download failed")
        os.replace(pkg+".part",pkg);size=os.path.getsize(pkg)
        if size<20*1024*1024 or size>2*1024*1024*1024:raise RuntimeError("unexpected IDE package size")
        with tarfile.open(pkg,"r:gz") as tf:
            members=_antigravity_safe_members(tf)
            try:tf.extractall(stage,members=members,filter="fully_trusted")
            except TypeError:tf.extractall(stage,members=members)
        binary=_antigravity_ide_find_binary(stage)
        if not binary:raise RuntimeError("Antigravity IDE executable not found")
        rel=os.path.relpath(binary,stage)
        old=_AG_IDE_ROOT+".old";shutil.rmtree(old,ignore_errors=True)
        if os.path.isdir(_AG_IDE_ROOT):os.replace(_AG_IDE_ROOT,old)
        os.replace(stage,_AG_IDE_ROOT);stage=""
        final=os.path.join(_AG_IDE_ROOT,rel)
        Path(_AG_IDE_BIN_FILE).write_text(final,encoding="utf-8")
        hh=hashlib.sha256()
        with open(pkg,"rb") as f:
            for chunk in iter(lambda:f.read(1024*1024),b""):hh.update(chunk)
        Path(os.path.join(_AG_IDE_ROOT,"install.json")).write_text(json.dumps({"version":ANTIGRAVITY_IDE_VERSION,"url":url,"sha256":hh.hexdigest(),"size":size},separators=(",",":")),encoding="utf-8")
        env=dict(os.environ,HOME="/root",DISPLAY=os.environ.get("DISPLAY",":1"),XDG_RUNTIME_DIR="/tmp/antigravity-ide-runtime")
        os.makedirs(env["XDG_RUNTIME_DIR"],exist_ok=True);os.chmod(env["XDG_RUNTIME_DIR"],0o700)
        if not (_electron_structural_check(final,_AG_IDE_ROOT) and _electron_install_canary(final,env)):
            shutil.rmtree(_AG_IDE_ROOT,ignore_errors=True)
            if os.path.isdir(old):os.replace(old,_AG_IDE_ROOT)
            restored=False
            try:
                rp=Path(_AG_IDE_BIN_FILE).read_text(encoding='utf-8').strip()
                restored=_electron_structural_check(rp,_AG_IDE_ROOT) and _electron_install_canary(rp,env)
            except Exception:restored=False
            _AG_IDE_READY=restored
            raise RuntimeError('IDE startup canary failed; '+('verified previous version restored' if restored else 'no valid previous version'))
        # v46: نفس مبدأ Hub — الإثبات تسريع لا شرط صحة، فلا يهدم تثبيتًا اجتاز
        # ��لفحص البنيوي و canary فعليًا.
        if not _runtime_proof_write(_AG_IDE_ROOT,final,ANTIGRAVITY_IDE_VERSION):
            _diag_event("ide_runtime_proof_write_failed")
            print("[i] Antigravity IDE: تعذّر كتابة إثبات التشغيل (تسريع فقط)؛ التثبيت سليم ويُعتمد ✅")
        previous=_AG_IDE_ROOT+"-previous";shutil.rmtree(previous,ignore_errors=True)
        if os.path.isdir(old):os.replace(old,previous)
        _AG_IDE_READY=True
        print("[OK] ثُبّت Google Antigravity IDE الرسمي واجتاز فحص التشغيل ✅")
        return True
    except Exception as e:
        print("[!] تعذر تثبيت Antigravity IDE الآن دون التأثير في سطح المكتب: %s"%e);return False
    finally:
        if stage:shutil.rmtree(stage,ignore_errors=True)
        for p in (pkg,pkg+".part"):
            try:os.unlink(p)
            except Exception:pass

