# Official VS Code Marketplace Arabic localization extension. Antigravity IDE
# is VS Code-compatible, so we install the pack into an isolated system
# extensions directory and force locale=ar on every normal/OAuth launch.
_AG_IDE_EXTENSIONS_DIR="/opt/google-antigravity-ide-extensions"
_AG_ARABIC_MARK=os.path.join(_AG_IDE_EXTENSIONS_DIR,"arabic-ready.json")
_ANTIGRAVITY_ARABIC_READY=False
_ARABIC_PACK_DONE=threading.Event()

def _antigravity_arabic_pack_ok():
    try:
        m=json.load(open(_AG_ARABIC_MARK,encoding="utf-8"));folder=m.get("folder","")
        package=os.path.join(_AG_IDE_EXTENSIONS_DIR,folder,"package.json")
        p=json.load(open(package,encoding="utf-8"))
        loc=((p.get("contributes") or {}).get("localizations") or [])
        return bool(p.get("publisher")=="Arabic-language" and p.get("name")=="vscode-ar" and
                    any(str(x.get("languageId","")).lower()=="ar" for x in loc))
    except Exception:return False

def _install_antigravity_arabic_pack():
    global _ANTIGRAVITY_ARABIC_READY
    if _antigravity_arabic_pack_ok():_ANTIGRAVITY_ARABIC_READY=True;return True
    import zipfile,hashlib,tempfile,stat
    url="https://github.com/almhajer/Arabic-for-visual-studio-code/releases/download/v1.125.2/vscode-ar-1.125.2.vsix"
    expected_sha="b3e3e0ea8b788dfcb150773cc467870ea5060b29763dce3ca72be4381aa4b41e"
    pkg="/tmp/antigravity-arabic-language-pack.vsix";stage=tempfile.mkdtemp(prefix="ag-arabic-",dir="/tmp")
    try:
        r=run("curl --proto '=https' --proto-redir '=https' --tlsv1.2 -fL --compressed -H 'Accept: application/octet-stream' -H 'User-Agent: ColabArabicUI-v45.14' --retry 5 --retry-all-errors --connect-timeout 25 --max-time 600 -o '%s.part' '%s'"%(pkg,url),timeout=650)
        if getattr(r,"returncode",1)!=0:raise RuntimeError("Arabic language pack download failed")
        os.replace(pkg+".part",pkg);size=os.path.getsize(pkg)
        if size<100*1024 or size>100*1024*1024:raise RuntimeError("unexpected Arabic VSIX size")
        actual_sha=hashlib.sha256(Path(pkg).read_bytes()).hexdigest()
        if actual_sha!=expected_sha:raise RuntimeError("Arabic VSIX SHA-256 mismatch")
        if not zipfile.is_zipfile(pkg):raise RuntimeError("Arabic download is not a real VSIX/ZIP")
        with zipfile.ZipFile(pkg) as z:
            infos=z.infolist();total=0
            if len(infos)>100000:raise RuntimeError("Arabic VSIX has too many entries")
            for i in infos:
                n=i.filename.replace("\\","/");parts=[x for x in n.split("/") if x not in ("",".")]
                if n.startswith("/") or ".." in parts or ((i.external_attr>>16)&0o170000)==stat.S_IFLNK:raise RuntimeError("unsafe Arabic VSIX entry")
                total+=i.file_size
                if total>500*1024*1024:raise RuntimeError("Arabic VSIX expanded size too large")
            if z.testzip():raise RuntimeError("Arabic VSIX CRC failure")
            raw=z.read("extension/package.json");meta=json.loads(raw.decode("utf-8"))
            loc=((meta.get("contributes") or {}).get("localizations") or [])
            if meta.get("publisher")!="Arabic-language" or meta.get("name")!="vscode-ar" or not any(str(x.get("languageId","")).lower()=="ar" for x in loc):
                raise RuntimeError("downloaded VSIX is not the Arabic UI pack")
            version=str(meta.get("version","")).strip()
            if not re.fullmatch(r"[0-9A-Za-z._-]{1,64}",version):raise RuntimeError("invalid Arabic pack version")
            dest=os.path.join(stage,"arabic-language.vscode-ar-"+version);os.makedirs(dest)
            for i in infos:
                n=i.filename.replace("\\","/")
                if not n.startswith("extension/") or n.endswith("/"):continue
                rel=n[len("extension/"):]
                outp=os.path.join(dest,*rel.split("/"));os.makedirs(os.path.dirname(outp),exist_ok=True)
                with z.open(i) as src,open(outp,"wb") as dst:shutil.copyfileobj(src,dst)
        os.makedirs(_AG_IDE_EXTENSIONS_DIR,exist_ok=True)
        final=os.path.join(_AG_IDE_EXTENSIONS_DIR,os.path.basename(dest));old=final+".old";shutil.rmtree(old,ignore_errors=True)
        if os.path.isdir(final):os.replace(final,old)
        os.replace(dest,final);shutil.rmtree(old,ignore_errors=True)
        # Remove only older copies of this same language pack after the new one is complete.
        for name in os.listdir(_AG_IDE_EXTENSIONS_DIR):
            q=os.path.join(_AG_IDE_EXTENSIONS_DIR,name)
            if name.startswith("arabic-language.vscode-ar-") and q!=final:shutil.rmtree(q,ignore_errors=True)
        h=hashlib.sha256()
        with open(pkg,"rb") as f:
            for b in iter(lambda:f.read(1024*1024),b""):h.update(b)
        fd,tmp=tempfile.mkstemp(prefix=".arabic-ready-",dir=_AG_IDE_EXTENSIONS_DIR)
        with os.fdopen(fd,"w",encoding="utf-8") as f:
            json.dump({"schema":1,"folder":os.path.basename(final),"version":version,"sha256":h.hexdigest(),"source":url},f,separators=(",",":"));f.flush();os.fsync(f.fileno())
        os.replace(tmp,_AG_ARABIC_MARK);os.chmod(_AG_ARABIC_MARK,0o644)
        _ANTIGRAVITY_ARABIC_READY=_antigravity_arabic_pack_ok()
        if not _ANTIGRAVITY_ARABIC_READY:raise RuntimeError("Arabic language pack verification failed")
        print("[OK] ثُبّتت حزمة تعريب واجهة Antigravity وCursor وفُحصت بالكامل ✅")
        return True
    except Exception as exc:
        print("[!] تعذر تجهيز تعريب Antigravity وCursor بأمان: %s"%exc);return False
    finally:
        shutil.rmtree(stage,ignore_errors=True)
        for q in (pkg,pkg+".part"):
            try:os.unlink(q)
            except OSError:pass

# v45.29: Arabic pack runs after the parallel app-install barrier.

_CURSOR_ARABIC_READY=False

def _activate_vscode_arabic(user_data_root):
    """Generate VS Code's required languagepacks.json registry atomically.

    --locale alone falls back to English when the pack is merely unpacked.
    Build the same registry produced by Configure Display Language, validate
    every referenced translation, and also write argv/legacy locale files.
    """
    import hashlib,tempfile
    try:
        mark=json.load(open(_AG_ARABIC_MARK,encoding='utf-8'));folder=mark.get('folder','')
        ext=os.path.realpath(os.path.join(_AG_IDE_EXTENSIONS_DIR,folder));base=os.path.realpath(_AG_IDE_EXTENSIONS_DIR)+os.sep
        if not ext.startswith(base) or not os.path.isdir(ext):raise RuntimeError('unsafe Arabic extension path')
        meta=json.load(open(os.path.join(ext,'package.json'),encoding='utf-8'))
        if meta.get('publisher')!='Arabic-language' or meta.get('name')!='vscode-ar':raise RuntimeError('Arabic extension identity mismatch')
        locs=((meta.get('contributes') or {}).get('localizations') or [])
        ar=next((x for x in locs if str(x.get('languageId','')).lower()=='ar'),None)
        if not ar:raise RuntimeError('Arabic localization contribution missing')
        translations={}
        for item in ar.get('translations') or []:
            tid=str(item.get('id','')).strip();rel=str(item.get('path','')).strip().replace('\\','/')
            if not tid or not rel or rel.startswith('/') or '..' in [x for x in rel.split('/') if x]:raise RuntimeError('unsafe translation entry')
            full=os.path.realpath(os.path.join(ext,rel));
            if not full.startswith(ext+os.sep) or not os.path.isfile(full):raise RuntimeError('missing translation: '+tid)
            json.load(open(full,encoding='utf-8'));translations[tid]=full
        if 'vscode' not in translations or len(translations)<10:raise RuntimeError('Arabic translation set incomplete')
        version=str(meta.get('version',''));digest=hashlib.md5((ext+'|'+version+'|'+str(len(translations))).encode()).hexdigest()
        registry={'ar':{'hash':digest,'extensions':[{'extensionIdentifier':{'id':'arabic-language.vscode-ar'},'version':version}],
                        'translations':translations,'label':'العربية'}}
        os.makedirs(user_data_root,exist_ok=True);os.makedirs(os.path.join(user_data_root,'User'),exist_ok=True)
        for name,data in (('languagepacks.json',registry),('argv.json',{'locale':'ar'})):
            dst=os.path.join(user_data_root,name);fd,tmp=tempfile.mkstemp(prefix='.'+name+'-',dir=user_data_root)
            with os.fdopen(fd,'w',encoding='utf-8') as f:json.dump(data,f,ensure_ascii=False,separators=(',',':'));f.flush();os.fsync(f.fileno())
            os.replace(tmp,dst);os.chmod(dst,0o644)
        Path(os.path.join(user_data_root,'User','locale.json')).write_text('{"locale":"ar"}\n',encoding='utf-8')
        # Read back all critical files; no success based only on writes.
        chk=json.load(open(os.path.join(user_data_root,'languagepacks.json'),encoding='utf-8'))
        return bool(chk.get('ar',{}).get('translations',{}).get('vscode')==translations['vscode'] and
                    json.load(open(os.path.join(user_data_root,'argv.json'),encoding='utf-8')).get('locale')=='ar')
    except Exception as exc:
        print('[!] فشل تسجيل حزمة العربية داخل التطبيق: %s'%exc);return False

