(_cr/'manifest.json').write_text('{\n  "manifest_version": 3,\n  "name": "Local Renderer Recovery",\n  "version": "2.1.0",\n  "permissions": [\n    "tabs",\n    "processes",\n    "alarms"\n  ],\n  "background": {\n    "service_worker": "worker.js"\n  },\n  "content_scripts": [\n    {\n      "matches": [\n        "https://*.genspark.ai/*",\n        "https://genspark.ai/*"\n      ],\n      "css": [\n        "stability.css"\n      ],\n      "js": [\n        "media.js"\n      ],\n      "run_at": "document_start"\n    },\n    {\n      "matches": [\n        "https://*.genspark.ai/*",\n        "https://genspark.ai/*"\n      ],\n      "js": [\n        "main.js"\n      ],\n      "run_at": "document_start",\n      "world": "MAIN"\n    }\n  ]\n}',encoding='utf-8')
(_cr/'worker.js').write_text("const P=new Map(),C=new Map();let timer=0;\nfunction g(u){try{return /(^|\\.)genspark\\.ai$/i.test(new URL(u).hostname)}catch(e){return false}}\nasync function scan(){timer=0;try{for(const t of await chrome.tabs.query({})){if(!t.id||!g(t.url||''))continue;chrome.processes.getProcessIdForTab(t.id,p=>{if(!chrome.runtime.lastError&&p)P.set(p,{id:t.id,at:Date.now()})})}for(const [p,v] of P)if(v.at<Date.now()-180000)P.delete(p)}catch(e){}}\nfunction schedule(){clearTimeout(timer);timer=setTimeout(scan,750)}\nchrome.processes.onExited.addListener((p,t)=>{const v=P.get(p);P.delete(p);if(!v||!['crashed','abnormal','killed'].includes(String(t))||Date.now()-(C.get(v.id)||0)<45000)return;C.set(v.id,Date.now());setTimeout(()=>chrome.tabs.get(v.id,x=>{if(!chrome.runtime.lastError&&x&&g(x.url||''))chrome.tabs.reload(v.id,{bypassCache:false})}),700)});\nchrome.tabs.onUpdated.addListener(schedule);chrome.tabs.onActivated.addListener(schedule);chrome.alarms.create('s',{periodInMinutes:.5});chrome.alarms.onAlarm.addListener(schedule);schedule();\n",encoding='utf-8')
(_cr/'stability.css').write_text('html{scroll-behavior:auto!important}*:not(video):not(canvas){animation:none!important;animation-play-state:paused!important;transition:none!important;scroll-behavior:auto!important}video,canvas{animation-duration:initial!important;transition-duration:initial!important}*{caret-animation:none!important}',encoding='utf-8')
(_cr/'main.js').write_text('(()=>{if(window.__motionShieldInstalled)return;window.__motionShieldInstalled=1;try{const a=Element.prototype.animate;Element.prototype.animate=function(...x){const z=a.apply(this,x);queueMicrotask(()=>{try{z.finish()}catch(e){try{z.pause()}catch(_){}}});return z}}catch(e){}})();',encoding='utf-8')
