# Explicit private-window and normal-compatibility launchers. They do not
# alter page challenges, CAPTCHA behavior, browser fingerprints, or network
# routing. The compatibility profile merely avoids optional local extensions.
_chrome_private_sh = r'''#!/bin/bash
exec /usr/local/bin/chrome-root --incognito --new-window "$@"
'''
_chrome_web_compat_sh = r'''#!/bin/bash
set -eu
PROFILE=/root/.chrome-web-compat
mkdir -p "$PROFILE"
rm -f "$PROFILE"/SingletonLock "$PROFILE"/SingletonSocket "$PROFILE"/SingletonCookie 2>/dev/null || true
exec /opt/google/chrome/google-chrome --no-sandbox --disable-dev-shm-usage \
  --user-data-dir="$PROFILE" --new-window --start-maximized --lang=ar \
  --no-first-run --no-default-browser-check --password-store=basic "$@"
'''
_colab_session_recover_sh = r'''#!/bin/bash
# Diagnostic and supported recovery helper. It never creates artificial input
# or refresh loops. Re-run the notebook cell after a Colab reconnect; the
# script's Drive vault restores saved state during normal startup.
set -u
echo "=== Colab desktop recovery check ==="
if [ -f /tmp/desktop_link.txt ]; then echo "Desktop link is present."; else echo "No active local desktop link: reconnect to Colab and run the same notebook cell again."; fi
if command -v desktop-health >/dev/null 2>&1; then desktop-health || true; fi
if command -v colab-status >/dev/null 2>&1; then colab-status || true; fi
echo "This helper preserves normal platform behavior; it does not bypass idle limits or website challenges."
'''
for _path, _body in (("/usr/local/bin/chrome-private", _chrome_private_sh),
                     ("/usr/local/bin/chrome-web-compat", _chrome_web_compat_sh),
                     ("/usr/local/bin/colab-session-recover", _colab_session_recover_sh)):
    try:
        Path(_path).write_text(_body, encoding="utf-8")
        os.chmod(_path, 0o755)
    except Exception as _launcher_exc:
        _diag_event("compat_launcher", _launcher_exc)
try:
    os.makedirs("/root/Desktop", exist_ok=True)
    _entries = {
        "Chrome خاص.desktop": ("Chrome خاص", "/usr/local/bin/chrome-private", "google-chrome"),
        "Chrome توافق مواقع.desktop": ("Chrome توافق مواقع", "/usr/local/bin/chrome-web-compat", "google-chrome"),
        "فحص تعافي كولاب.desktop": ("فحص تعافي كولاب", "xfce4-terminal --hold -e /usr/local/bin/colab-session-recover", "dialog-information"),
    }
    for _fn, (_name, _cmd, _icon) in _entries.items():
        _p = Path("/root/Desktop") / _fn
        _p.write_text("[Desktop Entry]\nType=Application\nName=%s\nExec=%s\nIcon=%s\nTerminal=false\n" % (_name, _cmd, _icon), encoding="utf-8")
        os.chmod(_p, 0o755)
except Exception as _desktop_entry_exc:
    _diag_event("compat_desktop_entries", _desktop_entry_exc)

