def _chat_id_file():
    return os.path.join(CHATS_DIR, "current")


def _chat_new_id():
    return time.strftime("%Y%m%d-%H%M%S") + "-" + secrets.token_hex(3)


def _set_current_chat_id(cid):
    try:
        os.makedirs(CHATS_DIR, exist_ok=True)
        with open(_chat_id_file(), "w", encoding="utf-8") as f:
            f.write(cid)
    except Exception:
        pass


def _current_chat_id(create=True):
    cid = ""
    try:
        cid = open(_chat_id_file(), encoding="utf-8").read().strip()
    except Exception:
        pass
    if not cid and create:
        cid = _chat_new_id()
        _set_current_chat_id(cid)
    return cid


def _chat_path(cid):
    cid = re.sub(r"[^0-9A-Za-z_-]", "", str(cid or ""))
    return os.path.join(CHATS_DIR, cid + ".json") if cid else ""


def _chat_title():
    with _LOCK:
        for e in _EVENTS:
            if e.get("kind") == "user" and str(e.get("text") or "").strip():
                return str(e["text"]).strip().replace("\n", " ")[:60]
    return "محادثة جديدة"


def _chat_events_for_save():
    with _LOCK:
        evs = list(_EVENTS)
    terms = sum(1 for e in evs if e.get("kind") == "term")
    if terms > CHAT_KEEP_TERM:
        drop = terms - CHAT_KEEP_TERM
        out = []
        for e in evs:
            if drop and e.get("kind") == "term":
                drop -= 1
                continue
            out.append(e)
        evs = out
    return evs


def _chat_save_now():
    cid = _current_chat_id()
    if not cid:
        return
    created = time.time()
    try:
        old = json.load(open(_chat_path(cid), encoding="utf-8"))
        created = float(old.get("created") or created)
    except Exception:
        pass
    data = {"id": cid, "title": _chat_title(), "created": created,
            "updated": time.time(), "events": _chat_events_for_save(),
            "last_task": dict(_LAST_TASK) if _LAST_TASK.get("reason") == "time" else None}
    try:
        os.makedirs(CHATS_DIR, exist_ok=True)
        tmp = _chat_path(cid) + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False, separators=(",", ":"))
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp, _chat_path(cid))
    except Exception:
        pass


def _chat_load_into_state(cid):
    p = _chat_path(cid)
    if not p or not os.path.exists(p):
        return False
    try:
        data = json.load(open(p, encoding="utf-8"))
        with _LOCK:
            _EVENTS[:] = data.get("events") or []
        lt = data.get("last_task")
        if isinstance(lt, dict) and lt.get("reason") == "time" and lt.get("messages"):
            _LAST_TASK.update(lt)
        return True
    except Exception:
        return False


def _chat_flush_loop():
    while True:
        time.sleep(2)
        if _CHAT_DIRTY["v"]:
            _CHAT_DIRTY["v"] = False
            _chat_save_now()


def _emit(kind, **kw):
    with _LOCK:
        item = {"id": len(_EVENTS), "kind": kind, "ts": time.time()}
        item.update(kw)
        _EVENTS.append(item)
    _CHAT_DIRTY["v"] = True
    if kind == "done":
        _chat_save_now()


def _events_since(n):
    with _LOCK:
        return list(_EVENTS[n:]), len(_EVENTS)


