gs_qwen_sh = r'''#!/bin/bash
# gs-qwen — وكيل ترمنل كوين من سطر الأوامر (طبقة فوق gs-do بنقطة كوين).
#   gs-qwen --endpoint <رابط>  : يضبط نقطة كوين بشكل دائم
#   gs-qwen --key <مفتاح>      : يضبط مفتاح API بشكل دائم (محفوظ بأمان)
#   gs-qwen --model <اسم>      : يضبط اسم النموذج بشكل دائم
#   gs-qwen --official <مفتاح> : ربط رسمي بحساب Qwen API (DashScope) خطوة واحدة
case "$1" in
  --endpoint)
    [ -n "$2" ] || { echo "الاستخدام: gs-qwen --endpoint <رابط>"; exit 1; }
    mkdir -p /root/.config
    printf "%s" "$2" > /root/.config/gs-qwen-endpoint
    echo "✅ ضُبطت نقطة كوين: $2"
    exit 0;;
  --key)
    [ -n "$2" ] || { echo "الاستخدام: gs-qwen --key <مفتاح>"; exit 1; }
    mkdir -p /root/.config
    printf "%s" "$2" > /root/.config/gs-qwen-key
    chmod 600 /root/.config/gs-qwen-key
    echo "✅ ضُبط مفتاح كوين بأمان — تستخدمه محادثة الوكيل تلقائيًّا"
    exit 0;;
  --model)
    [ -n "$2" ] || { echo "الاستخدام: gs-qwen --model <اسم>"; exit 1; }
    mkdir -p /root/.config
    printf "%s" "$2" > /root/.config/gs-qwen-model
    echo "✅ ضُبط نموذج كوين: $2"
    exit 0;;
  --official)
    [ -n "$2" ] || { echo "الاستخدام: gs-qwen --official <مفتاح-Qwen-API>"; exit 1; }
    mkdir -p /root/.config
    printf "%s" "https://dashscope-intl.aliyuncs.com/compatible-mode/v1" > /root/.config/gs-qwen-endpoint
    printf "%s" "$2" > /root/.config/gs-qwen-key
    chmod 600 /root/.config/gs-qwen-key
    printf "%s" "qwen-plus" > /root/.config/gs-qwen-model
    echo "✅ رُبط وكيل كوين بالحساب الرسمي (Qwen API / DashScope)"
    echo "   النموذج الافتراضي: qwen-plus — غيّره بـ: gs-qwen --model <اسم>"
    exit 0;;
  --bridge)
    mkdir -p /root/.config
    case "${2:-on}" in
      off) echo off > /root/.config/gs-qwen-bridge-off
           echo "⛔ عُطّل جسر واجهة كوين — سيبحث الوكيل عن نقاط API البديلة";;
      on)  rm -f /root/.config/gs-qwen-bridge-off
           echo "✅ فُعّل جسر واجهة كوين (chat.qwen.ai داخل كرومك)";;
      *)   echo "الاستخدام: gs-qwen --bridge [on|off]"; exit 1;;
    esac
    exit 0;;
esac
CFG_EP="$(cat /root/.config/gs-qwen-endpoint 2>/dev/null || true)"
CFG_M="$(cat /root/.config/gs-qwen-model 2>/dev/null || true)"
export DEEPSEEK_ENDPOINT="${GS_QWEN_ENDPOINT:-${CFG_EP:-https://dashscope-intl.aliyuncs.com/compatible-mode/v1}}"
export DEEPSEEK_MODEL="${GS_QWEN_MODEL:-${CFG_M:-qwen-plus}}"
export DEEPSEEK_API_KEY="${GS_QWEN_API_KEY:-$(cat /root/.config/gs-qwen-key 2>/dev/null || true)}"
exec /usr/local/bin/gs-do "$@"
'''

