puzzle_drag_py = r'''#!/usr/bin/env python3
# puzzle_drag — سحب بشري سلس من نقطة البداية لمسافة محددة (ease-out + اهتزاز + توقيت متغير).
import random, subprocess, sys, time

def _xd(*args):
    subprocess.run(["xdotool"] + [str(a) for a in args],
                   stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                   env=dict(__import__("os").environ, DISPLAY=__import__("os").environ.get("DISPLAY", ":1")))

def human_drag(x0, y0, dist=260, hold=True):
    x0, y0, dist = int(x0), int(y0), int(dist)
    _xd("mousemove", x0, y0)
    time.sleep(0.15)
    _xd("mousedown", 1)
    time.sleep(0.25)
    steps = 48
    for i in range(1, steps + 1):
        t = i / steps
        ease = 1 - (1 - t) ** 2
        x = x0 + int(dist * ease) + random.randint(-1, 1)
        y = y0 + random.randint(-1, 1)
        _xd("mousemove", x, y)
        time.sleep(0.012 + random.random() * 0.02)
    if hold:
        time.sleep(0.3 + random.random() * 0.2)
    _xd("mouseup", 1)

if __name__ == "__main__":
    if len(sys.argv) < 3:
        print("usage: puzzle_drag.py X Y [DIST]")
        sys.exit(2)
    human_drag(sys.argv[1], sys.argv[2], sys.argv[3] if len(sys.argv) > 3 else 260)
'''
with open('/tmp/puzzle_drag.py', 'w', encoding='utf-8') as f:
    f.write(puzzle_drag_py)
run("sudo cp /tmp/puzzle_drag.py /usr/local/lib/puzzle_drag.py && "
    "sudo chmod 644 /usr/local/lib/puzzle_drag.py")

chrome_session_restore_py = r'''#!/usr/bin/env python3
# chrome-session-restore — يجعل كروم الأصلي يستعيد صفحات الجلسة السابقة تلقائيًّا.
import json, os
root = os.environ.get("CHROME_USER_DATA_DIR", os.path.expanduser("~/.config/google-chrome"))
p = os.path.join(root, "Default", "Preferences")
try:
    d = {}
    if os.path.exists(p):
        try:
            d = json.load(open(p, encoding="utf-8"))
        except Exception:
            d = {}
    if not isinstance(d, dict):
        d = {}
    changed = False
    sess = d.setdefault("session", {})
    if sess.get("restore_on_startup") != 1:
        sess["restore_on_startup"] = 1
        changed = True
    prof = d.setdefault("profile", {})
    if prof.get("exit_type") != "Normal":
        prof["exit_type"] = "Normal"
        changed = True
    if prof.get("exited_cleanly") is not True:
        prof["exited_cleanly"] = True
        changed = True
    if changed:
        os.makedirs(os.path.dirname(p), exist_ok=True)
        tmp = p + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(d, f)
        os.replace(tmp, p)
except Exception:
    pass
'''
with open('/tmp/chrome-session-restore', 'w', encoding='utf-8') as f:
    f.write(chrome_session_restore_py)
run("sudo cp /tmp/chrome-session-restore /usr/local/bin/chrome-session-restore && "
    "sudo chmod +x /usr/local/bin/chrome-session-restore")
# دمج التفضيلات مرة عند الإقلاع — restore_on_startup=1 يستمر دائمًا في البروفايل
_session_profiles = ["/root/.config/google-chrome", "/root/.qwen-login-profile",
                     "/root/.google-signup-profile"]
try:
    for _d in sorted(os.listdir("/root/.chrome-profiles")):
        if _d.startswith("profile-"):
            _session_profiles.append("/root/.chrome-profiles/" + _d)
except Exception:
    pass
for _prof in _session_profiles:
    run("CHROME_USER_DATA_DIR=%s python3 /usr/local/bin/chrome-session-restore >/dev/null 2>&1 || true" % _prof)
