vpn_local_sh = r'''#!/bin/bash
# vpn-local — مفتاح «الشبكة المحلية» عبر Cloudflare WARP مع إثبات تغيّر العنوان.
case "$1" in
  on)
    echo "[i] تجهيز وضع الشبكة المحلية (WARP)..."
    if ! command -v warp-cli >/dev/null 2>&1; then
      echo "[i] تثبيت cloudflare-warp لأول مرة (قد يستغرق دقيقة)..."
      curl -fsSL https://pkg.cloudflareclient.com/pubkey.gpg | sudo gpg --dearmor -o /usr/share/keyrings/cloudflare-warp.gpg 2>/dev/null && \
      echo "deb [signed-by=/usr/share/keyrings/cloudflare-warp.gpg] https://pkg.cloudflareclient.com/ $(. /etc/os-release && echo $VERSION_CODENAME) main" | sudo tee /etc/apt/sources.list.d/cloudflare-client.list >/dev/null && \
      sudo apt-get update -qq && sudo DEBIAN_FRONTEND=noninteractive apt-get install -y -qq cloudflare-warp || {
        echo "[!] تعذّر تثبيت WARP الآن — جرّب نافذة الإنشاء بدونه أولًا."; exit 1; }
    fi
    warp-cli registration new >/dev/null 2>&1 || warp-cli register >/dev/null 2>&1 || true
    if warp-cli connect 2>&1; then
      sleep 2
      NEWIP="$(curl -fsS -m 8 https://ipinfo.io/ip 2>/dev/null || curl -fsS -m 8 https://api.ipify.org 2>/dev/null || echo '?')"
      NEWORG="$(curl -fsS -m 8 'https://ipinfo.io/org' 2>/dev/null || true)"
      echo "✅ فُعّل وضع الشبكة المحلية — عنوان الخروج الجديد: $NEWIP"
      [ -n "$NEWORG" ] && echo "    الشبكة: $NEWORG"
      echo "    افتح/أعد فتح نافذة الإنشاء الآن. للإيقاف: vpn-local off"
    else
      echo "[!] تعذّر اتصال WARP الآن — جرّب نافذة الإنشاء بدونه أولًا."
    fi
    ;;
  off)
    warp-cli disconnect >/dev/null 2>&1 || true
    echo "✅ عُطّل وضع الشبكة المحلية — عادت الشبكة لمسارها العادي."
    ;;
  status)
    warp-cli status 2>/dev/null || echo "WARP غير مثبّت بعد — شغّل أولًا: vpn-local on"
    echo -n "عنوان الخروج الحالي: "
    curl -fsS -m 8 https://ipinfo.io/ip 2>/dev/null || echo "(تعذّر الجلب)"
    echo
    ;;
  *)
    echo "الاستخدام: vpn-local on|off|status"
    ;;
esac
'''

