translate_prefs_fix_py = r'''#!/usr/bin/env python3
# translate-prefs-fix — يفعّل ترجمة كروم المدمجة في كل ملفات التعريف.
import json, os

_env = os.environ.get("TRANSLATE_FIX_PROFILES", "")
PROFILES = [p for p in _env.split(":") if p] or [
    "/root/.config/google-chrome", "/root/.qwen-login-profile",
    "/root/.google-signup-profile"]
try:
    for d in sorted(os.listdir("/root/.chrome-profiles")):
        if d.startswith("profile-"):
            PROFILES.append("/root/.chrome-profiles/" + d)
except Exception:
    pass

def fix(prefs_path):
    if not os.path.isfile(prefs_path):
        return False
    try:
        data = json.load(open(prefs_path, encoding="utf-8"))
    except Exception:
        return False
    if not isinstance(data, dict):
        return False
    tr = data.setdefault("translate", {})
    if not isinstance(tr, dict):
        data["translate"] = tr = {}
    tr["enabled"] = True
    tr["site_blacklist"] = []
    tr["blocked_languages"] = []
    tr["recent_target"] = "ar"
    tmp = prefs_path + ".trtmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False)
    os.replace(tmp, prefs_path)
    return True

count = 0
for prof in PROFILES:
    for sub in ("", "Default", "Profile 1"):
        p = os.path.join(prof, sub, "Preferences") if sub else os.path.join(prof, "Preferences")
        if fix(p):
            count += 1
print("translate prefs fixed in %d Preferences files" % count)
'''
with open('/tmp/translate-prefs-fix', 'w', encoding='utf-8') as f:
    f.write(translate_prefs_fix_py)
run("sudo cp /tmp/translate-prefs-fix /usr/local/bin/translate-prefs-fix && "
    "sudo chmod +x /usr/local/bin/translate-prefs-fix")
run("python3 /usr/local/bin/translate-prefs-fix >/dev/null 2>&1 || true")
