opencode_install_sh = r'''#!/bin/bash
# opencode-install — تثبيت OpenCode (idempotent) مع التحقق النهائي.
if command -v opencode >/dev/null 2>&1; then
  echo "opencode already installed: $(opencode --version 2>/dev/null | head -1)"
  exit 0
fi
echo "[i] installing opencode via official script..."
curl -fsSL https://opencode.ai/install | bash || true
if ! command -v opencode >/dev/null 2>&1; then
  echo "[i] fallback: GitHub release binary..."
  arch=x64; [ "$(uname -m)" = "aarch64" ] && arch=arm64
  url=$(curl -fsSL https://api.github.com/repos/anomalyco/opencode/releases/latest 2>/dev/null | grep -oE "https://[^\"]*linux-${arch}[^\"]*\.(zip|tar\.gz)" | head -1)
  if [ -n "$url" ]; then
    cd /tmp && curl -fsSL "$url" -o opencode.pkg
    case "$url" in
      *.zip) unzip -o opencode.pkg >/dev/null ;;
      *.tar.gz) tar xzf opencode.pkg ;;
    esac
    [ -f /tmp/opencode ] && chmod +x /tmp/opencode && sudo mv /tmp/opencode /usr/local/bin/
  fi
fi
[ -f "$HOME/.opencode/bin/opencode" ] && sudo ln -sf "$HOME/.opencode/bin/opencode" /usr/local/bin/opencode
if command -v opencode >/dev/null 2>&1; then
  echo "OK: $(opencode --version 2>/dev/null | head -1)"
  exit 0
fi
echo "[!] opencode install incomplete — see log"
exit 1
'''

