agent_apk_sh = r'''#!/bin/bash
# agent-apk — بيئة بناء Android منفصلة للوكلاء: تحضير، إنشاء، بناء، تحقق وتصدير.
set -euo pipefail
AGENT="${AGENT_WORKBENCH:-}"
case "$AGENT" in deepseek|qwen) ;; *) echo "الاستخدام: AGENT_WORKBENCH=deepseek|qwen agent-apk <prepare|create|build|verify|export|status> ..."; exit 64;; esac
ROOT="/root/agent-workspaces/$AGENT"; PROJECTS="$ROOT/projects"; BUILDS="$ROOT/builds"; LOGS="$ROOT/logs"; SDK=/root/Android/Sdk
mkdir -p "$PROJECTS" "$BUILDS" "$LOGS"
safe_name(){ [[ "${1:-}" =~ ^[A-Za-z][A-Za-z0-9_-]{1,48}$ ]]; }
project(){ safe_name "${1:-}" || { echo "اسم المشروع غير صالح"; exit 64; }; printf '%s' "$PROJECTS/$1"; }
prepare(){ /usr/local/bin/android-env-install >>"$LOGS/android-env.log" 2>&1; test -x "$SDK/cmdline-tools/latest/bin/sdkmanager"; command -v java >/dev/null; command -v gradle >/dev/null; echo "READY agent=$AGENT sdk=$SDK gradle=$(command -v gradle)"; }
create(){ local n="$1" p; p="$(project "$n")"; [ ! -e "$p" ] || { echo "المشروع موجود: $p"; exit 65; }; prepare; mkdir -p "$p/app/src/main/java/com/agent/app" "$p/app/src/main/res/values"; cat >"$p/settings.gradle" <<EOF
pluginManagement { repositories { google(); mavenCentral(); gradlePluginPortal() } }
dependencyResolutionManagement { repositoriesMode.set(RepositoriesMode.FAIL_ON_PROJECT_REPOS); repositories { google(); mavenCentral() } }
rootProject.name = '$n'
include ':app'
EOF
cat >"$p/build.gradle" <<'EOF'
plugins { id 'com.android.application' version '8.7.3' apply false }
EOF
cat >"$p/app/build.gradle" <<'EOF'
plugins { id 'com.android.application' }
android { namespace 'com.agent.app'; compileSdk 34
 defaultConfig { applicationId 'com.agent.app'; minSdk 24; targetSdk 34; versionCode 1; versionName '1.0' }
}
EOF
cat >"$p/app/src/main/AndroidManifest.xml" <<'EOF'
<manifest xmlns:android="http://schemas.android.com/apk/res/android"><application android:theme="@style/AppTheme" android:label="Agent App"><activity android:name=".MainActivity" android:exported="true"><intent-filter><action android:name="android.intent.action.MAIN"/><category android:name="android.intent.category.LAUNCHER"/></intent-filter></activity></application></manifest>
EOF
cat >"$p/app/src/main/res/values/styles.xml" <<'EOF'
<resources><style name="AppTheme" parent="android:style/Theme.Material.Light.NoActionBar"/></resources>
EOF
cat >"$p/app/src/main/java/com/agent/app/MainActivity.java" <<'EOF'
package com.agent.app; import android.app.Activity; import android.os.Bundle; import android.widget.TextView; public class MainActivity extends Activity { public void onCreate(Bundle b){super.onCreate(b); TextView v=new TextView(this); v.setText("Agent APK workspace ready"); v.setTextSize(20); setContentView(v);} }
EOF
gradle --no-daemon --console=plain -p "$p" wrapper --gradle-version 8.9 >>"$LOGS/$n-wrapper.log" 2>&1; printf 'AGENT=%s\nPROJECT=%s\n' "$AGENT" "$n" >"$p/.agent-project"; echo "CREATED $p"; }
build(){ local n="$1" p; p="$(project "$n")"; [ -x "$p/gradlew" ] || { echo "مشروع Gradle غير موجود: $p"; exit 66; }; prepare; (cd "$p" && ANDROID_HOME="$SDK" ./gradlew --no-daemon --console=plain assembleDebug) >"$LOGS/$n-build.log" 2>&1; local apk; apk=$(find "$p/app/build/outputs/apk/debug" -type f -name '*.apk' -print -quit); [ -n "$apk" ] && [ -s "$apk" ] || { tail -n 80 "$LOGS/$n-build.log"; exit 67; }; cp -f "$apk" "$BUILDS/$n-debug.apk"; sha256sum "$BUILDS/$n-debug.apk" >"$BUILDS/$n-debug.apk.sha256"; echo "BUILT $BUILDS/$n-debug.apk"; }
verify(){ local n="$1" a="$BUILDS/$n-debug.apk"; [ -s "$a" ] || { echo "APK غير موجود: $a"; exit 68; }; unzip -t "$a" >/dev/null; sha256sum -c "$BUILDS/$n-debug.apk.sha256"; echo "VERIFIED $a"; }
export_apk(){ local n="$1"; verify "$n"; cp -f "$BUILDS/$n-debug.apk" "/root/Desktop/$n-debug.apk"; cp -f "$BUILDS/$n-debug.apk.sha256" "/root/Desktop/$n-debug.apk.sha256"; echo "EXPORTED /root/Desktop/$n-debug.apk"; }
case "${1:-status}" in prepare) prepare;; create) create "${2:-}";; build) build "${2:-}";; verify) verify "${2:-}";; export) export_apk "${2:-}";; status) echo "agent=$AGENT root=$ROOT"; find "$BUILDS" -maxdepth 1 -type f -name '*.apk' -printf '%f\n' 2>/dev/null || true;; *) echo "الاستخدام: agent-apk <prepare|create|build|verify|export|status>"; exit 64;; esac
'''

android_env_install_sh = r'''#!/bin/bash
# android-env-install — يجهّز بيئة أندرويد (JDK + cmdline-tools + platform + build-tools + gradle) — idempotent.
SDK=/root/Android/Sdk
GRADLE_HOME=/opt/gradle
mkdir -p "$SDK/cmdline-tools"
if ! command -v java >/dev/null 2>&1; then
  echo "[i] installing JDK..."
  sudo apt-get update -qq && sudo DEBIAN_FRONTEND=noninteractive apt-get install -y -qq openjdk-17-jdk-headless || true
fi
if [ ! -x "$SDK/cmdline-tools/latest/bin/sdkmanager" ]; then
  echo "[i] installing Android cmdline-tools..."
  cd /tmp && curl -fsSL https://dl.google.com/android/repository/commandlinetools-linux-11076708_latest.zip -o cmdtools.zip || { echo "[!] download failed"; exit 1; }
  rm -rf /tmp/cmdline-tools && unzip -q cmdtools.zip
  mkdir -p "$SDK/cmdline-tools/latest"
  cp -r /tmp/cmdline-tools/* "$SDK/cmdline-tools/latest/"
fi
export ANDROID_HOME="$SDK"
export PATH="$SDK/cmdline-tools/latest/bin:$SDK/platform-tools:$PATH"
if [ ! -f "$SDK/.gs-ready" ]; then
  echo "[i] installing platform + build-tools (may take minutes)..."
  yes | sdkmanager --licenses >/dev/null 2>&1 || true
  sdkmanager "platform-tools" "platforms;android-34" "build-tools;34.0.0" >/dev/null 2>&1 || true
  [ -d "$SDK/platform-tools" ] && touch "$SDK/.gs-ready"
fi
if ! command -v gradle >/dev/null 2>&1; then
  echo "[i] installing gradle..."
  cd /tmp && curl -fsSL https://services.gradle.org/distributions/gradle-8.9-bin.zip -o gradle.zip || true
  if [ -f gradle.zip ]; then
    sudo rm -rf "$GRADLE_HOME" && sudo mkdir -p "$GRADLE_HOME"
    sudo unzip -q gradle.zip -d "$GRADLE_HOME"
    sudo ln -sf "$GRADLE_HOME"/gradle-8.9/bin/gradle /usr/local/bin/gradle
  fi
fi
printf 'export ANDROID_HOME=/root/Android/Sdk\nexport PATH=$ANDROID_HOME/cmdline-tools/latest/bin:$ANDROID_HOME/platform-tools:$PATH\n' | sudo tee /etc/profile.d/android.sh >/dev/null
echo "[OK] android env: java=$(command -v java | head -1) sdkmanager=$([ -x $SDK/cmdline-tools/latest/bin/sdkmanager ] && echo yes || echo no) gradle=$(command -v gradle | head -1)"
'''

gs_watchdog_py = r'''#!/usr/bin/env python3
# gs-watchdog — حارس إشرافي: خادما الوكيل + مدير النوافذ واللوحة وسطح المكتب (كل 120ث) — للأبد.
import os, socket, subprocess, time
import fcntl as _fcntl
try:
    _sg_lock = open("/tmp/gs-watchdog.lock", "w")
    _fcntl.flock(_sg_lock, _fcntl.LOCK_EX | _fcntl.LOCK_NB)
except Exception:
    raise SystemExit(0)

LOG = "/tmp/gs-watchdog.log"
DISPLAY = os.environ.get("DISPLAY", ":1")

def log(msg):
    try:
        with open(LOG, "a", encoding="utf-8") as f:
            f.write("[%d] %s\n" % (int(time.time()), msg))
    except Exception:
        pass

def listening(port):
    try:
        with socket.socket() as s:
            s.settimeout(2)
            return s.connect_ex(("127.0.0.1", port)) == 0
    except Exception:
        return False

def restart(launcher):
    try:
        subprocess.Popen(["setsid", launcher], stdout=subprocess.DEVNULL,
                         stderr=subprocess.DEVNULL, start_new_session=True,
                         env=dict(os.environ, DISPLAY=DISPLAY))
        log("restarted: " + launcher)
    except Exception as e:
        log("restart failed %s: %s" % (launcher, e))

def proc_running(name):
    try:
        p = subprocess.run(["pgrep", "-x", name], stdout=subprocess.DEVNULL,
                           stderr=subprocess.DEVNULL, timeout=6)
        return p.returncode == 0
    except Exception:
        return True

def fix_workspace_count():
    try:
        p = subprocess.run(["xfconf-query", "-c", "xfwm4", "-p", "/general/workspace_count"],
                           stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, text=True,
                           timeout=8, env=dict(os.environ, DISPLAY=DISPLAY))
        val = (p.stdout or "").strip()
        if p.returncode == 0 and val and val != "1":
            subprocess.Popen(["/usr/local/bin/xfce-desktop-fix"],
                             stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                             start_new_session=True,
                             env=dict(os.environ, DISPLAY=DISPLAY))
            log("workspace_count reverted to %s — reapplying fix" % val)
    except Exception:
        pass

CHECKS = [(8787, "/usr/local/bin/gs-agent-ui"), (8788, "/usr/local/bin/gs-qwen")]
DESKTOP_PROCS = ["xfwm4", "xfce4-panel", "xfdesktop"]
while True:
    try:
        for port, launcher in CHECKS:
            if not listening(port) and os.path.isfile(launcher):
                restart(launcher)
        for name in DESKTOP_PROCS:
            if not proc_running(name):
                restart("/usr/local/bin/xfce-desktop-fix")
                break
        fix_workspace_count()
    except Exception:
        pass
    time.sleep(120)
'''

gs_backup_py = r'''#!/usr/bin/env python3
# gs-backup — نسخ احتياطي تزايدي (المحادثات + ملفات كروم الحرجة + إعدادات gs-*) كل 15 دقيقة.
import os, shutil, time

DEST = "/root/.backups"
CHROME_PROFILES = ["/root/.config/google-chrome", "/root/.qwen-login-profile",
                   "/root/.google-signup-profile"]
CRITICAL = ["Preferences", "Cookies", "Login Data", "Bookmarks", "Web Data"]

def copy_if_newer(src, dst):
    try:
        if not os.path.isfile(src):
            return False
        if os.path.isfile(dst) and os.path.getmtime(dst) >= os.path.getmtime(src):
            return False
        os.makedirs(os.path.dirname(dst), exist_ok=True)
        shutil.copy2(src, dst)
        return True
    except Exception:
        return False

def cycle():
    n = 0
    if os.path.isdir("/root/workspace/.agent-chats"):
        for root, _dirs, files in os.walk("/root/workspace/.agent-chats"):
            for fn in files:
                if fn.endswith(".json"):
                    p = os.path.join(root, fn)
                    rel = os.path.relpath(p, "/root/workspace")
                    if copy_if_newer(p, os.path.join(DEST, "workspace", rel)):
                        n += 1
    for prof in CHROME_PROFILES:
        for sub in ("", "Default"):
            base = os.path.join(prof, sub) if sub else prof
            for fn in CRITICAL:
                p = os.path.join(base, fn)
                rel = os.path.join("chrome", os.path.basename(prof), sub or "root", fn)
                if copy_if_newer(p, os.path.join(DEST, rel)):
                    n += 1
    cfg = os.path.expanduser("~/.config")
    if os.path.isdir(cfg):
        for fn in os.listdir(cfg):
            if fn.startswith("gs-"):
                p = os.path.join(cfg, fn)
                if os.path.isfile(p) and copy_if_newer(p, os.path.join(DEST, "config", fn)):
                    n += 1
    return n

while True:
    try:
        n = cycle()
        with open("/tmp/gs-backup-last", "w") as f:
            f.write("%d files @%d" % (n, int(time.time())))
    except Exception:
        pass
    time.sleep(900)
'''

