xfce_desktop_fix_sh = r'''#!/bin/bash
# xfce-desktop-fix — إصلاح سطح المكتب نهائيًّا: مساحة واحدة + بلا مركّب معطوب + إدارة نوافذ حية — بتحقق مُسجَّل.
export DISPLAY="${DISPLAY:-:1}"
_XPID=$(pgrep -n xfconfd 2>/dev/null | head -1)
[ -z "$_XPID" ] && _XPID=$(pgrep -n xfce4-session 2>/dev/null | head -1)
_DBUS=""
if [ -n "$_XPID" ]; then
  _DBUS=$(tr '\0' '\n' < /proc/$_XPID/environ 2>/dev/null | grep '^DBUS_SESSION_BUS_ADDRESS=' | cut -d= -f2-)
fi
if [ -n "$_DBUS" ]; then
  export DBUS_SESSION_BUS_ADDRESS="$_DBUS"
else
  export DBUS_SESSION_BUS_ADDRESS="${DBUS_SESSION_BUS_ADDRESS:-unix:path=/run/user/0/bus}"
fi
echo "DBUS resolved: $DBUS_SESSION_BUS_ADDRESS" >> "$LOG"
LOG=/tmp/xfce-desktop-fix.log
echo "--- fix at $(date +%s) ---" >> "$LOG"
for i in $(seq 1 30); do
  xfconf-query -c xfwm4 -p /general/workspace_count >/dev/null 2>&1 && break
  sleep 1
done
xfconf-query -c xfwm4 -p /general/workspace_count -s 1 2>>"$LOG"
xfconf-query -c xfwm4 -p /general/sync_to_vblank -s false 2>>"$LOG"
xfconf-query -c xfwm4 -p /general/compositing -s false 2>/dev/null
xfconf-query -c xfwm4 -p /general/composite -s false 2>/dev/null
echo "VERIFY workspace_count=$(xfconf-query -c xfwm4 -p /general/workspace_count 2>/dev/null)" >> "$LOG"
echo "VERIFY sync_to_vblank=$(xfconf-query -c xfwm4 -p /general/sync_to_vblank 2>/dev/null)" >> "$LOG"
pgrep -x xfwm4 >/dev/null 2>&1 || setsid xfwm4 --replace >/dev/null 2>&1 &
pgrep -x xfce4-panel >/dev/null 2>&1 || setsid xfce4-panel >/dev/null 2>&1 &
pgrep -x xfdesktop >/dev/null 2>&1 || setsid xfdesktop >/dev/null 2>&1 &
sleep 1
echo "VERIFY procs: xfwm4=$(pgrep -xc xfwm4 2>/dev/null) panel=$(pgrep -xc xfce4-panel 2>/dev/null) desktop=$(pgrep -xc xfdesktop 2>/dev/null)" >> "$LOG"
setsid /usr/local/bin/gs-panel-setup >/dev/null 2>&1 &
exit 0
'''
with open('/tmp/xfce-desktop-fix', 'w', encoding='utf-8') as f:
    f.write(xfce_desktop_fix_sh)
