crx_install_py = r'''#!/usr/bin/env python3
# crx-install — ينزّل إضافة Colab Keep Alive الرسمية من خادم سوق Chrome ويثبّتها كإضافة محلية دائمة.
import os, struct, time, urllib.request, zipfile

EXT_ID = "bokldcdphgknojlbfhpbbgkggjfhhaek"
DEST = "/opt/ext-colab-keep-alive"
URL = ("https://clients2.google.com/service/update2/crx?response=redirect"
       "&prodversion=131.0.0.0&acceptformat=crx2,crx3&x=id%3D" + EXT_ID + "%26uc")

def _extract_crx(data, dest):
    if data[:4] != b"Cr24":
        raise ValueError("not a crx file")
    ver = struct.unpack("<I", data[4:8])[0]
    if ver == 2:
        pub = struct.unpack("<I", data[8:12])[0]
        sig = struct.unpack("<I", data[12:16])[0]
        off = 16 + pub + sig
    else:
        hdr = struct.unpack("<I", data[8:12])[0]
        off = 12 + hdr
    tmp = dest + ".pkg.zip"
    with open(tmp, "wb") as f:
        f.write(data[off:])
    os.makedirs(dest, exist_ok=True)
    with zipfile.ZipFile(tmp) as z:
        z.extractall(dest)
    os.unlink(tmp)

def main():
    if os.path.isfile(os.path.join(DEST, "manifest.json")):
        print("already installed at " + DEST)
        return
    last = None
    data = None
    for attempt in range(3):
        try:
            req = urllib.request.Request(URL, headers={"User-Agent": "Mozilla/5.0 (X11; Linux x86_64) Chrome/131.0.0.0"})
            with urllib.request.urlopen(req, timeout=60) as r:
                data = r.read()
            break
        except Exception as e:
            last = e
            time.sleep(3)
    if data is None:
        raise SystemExit("download failed: %s" % last)
    _extract_crx(data, DEST)
    mf = os.path.join(DEST, "manifest.json")
    if not os.path.isfile(mf):
        raise SystemExit("manifest.json missing after extract")
    print("installed to " + DEST)


if __name__ == "__main__":
    main()
'''
with open('/tmp/crx-install.py', 'w', encoding='utf-8') as f:
    f.write(crx_install_py)
run("sudo cp /tmp/crx-install.py /usr/local/lib/crx-install.py && "
    "sudo chmod 644 /usr/local/lib/crx-install.py")
run("sudo python3 /usr/local/lib/crx-install.py >/tmp/crx-install.log 2>&1 || true")
