keeper_content_js = r'''// Colab Session Keeper v2 — نبض مقاوم للخنق + إعادة اتصال تلقائية.
(function(){
  if (window.__gsKeeperV2) return;
  window.__gsKeeperV2 = true;
  function beat(){
    try {
      var el = document.body || document.documentElement;
      if(!el) return;
      ['mousemove','mousedown','mouseup','keydown','keyup'].forEach(function(t){
        try { el.dispatchEvent(new Event(t, {bubbles:true})); } catch(e){}
      });
      fetch('./', {method:'HEAD', credentials:'include'}).catch(function(){});
    } catch(e){}
  }
  try {
    var workerSrc = 'setInterval(function(){postMessage(1);},25000);';
    var blob = new Blob([workerSrc], {type:'application/javascript'});
    var w = new Worker(URL.createObjectURL(blob));
    w.onmessage = function(){ beat(); };
  } catch(e) {
    setInterval(beat, 25000);
  }
  function clickIfFound(){
    try {
      var btns = document.querySelectorAll('button, [role="button"], paper-button');
      for (var i=0;i<btns.length;i++){
        var t = (btns[i].textContent||'').trim();
        if (/^(Reconnect|Connect|إعادة الاتصال|اتصال)$/i.test(t)){
          btns[i].click();
          return true;
        }
      }
    } catch(e){}
    return false;
  }
  try {
    var mo = new MutationObserver(function(){ clickIfFound(); });
    mo.observe(document.documentElement, {childList:true, subtree:true});
  } catch(e){}
  setInterval(clickIfFound, 15000);
})();
'''
