gs_session_pulse_py = r'''#!/usr/bin/env python3
# gs-session-pulse — نبض نشاط خفيف من داخل الـruntime كل 60ث (CPU ضئيل + شبكة محلية).
import time, urllib.request
while True:
    x = 0
    for i in range(200000):
        x += i * i % 7
    try:
        urllib.request.urlopen("http://127.0.0.1:8787/token", timeout=3).read(64)
    except Exception:
        pass
    try:
        with open("/tmp/gs-session-pulse", "w") as f:
            f.write("%d %d" % (int(time.time()), x % 97))
    except Exception:
        pass
    time.sleep(60)
'''
