gs_auth_persist_py = r'''#!/usr/bin/env python3
# gs-auth-persist — ثبات تسجيل الدخول: يحفظ إعدادات الوكيل وملف جسر كوين ويستعيدها
# عند الإقلاع (من أحدث لقطة محلية أو درايف — الأحدث يفوز).
import os, shutil, time

BACKUP_DIR = "/root/.backups/auth"
KEEP = 5
CONFIG_DIR = os.path.expanduser("~/.config")

def _collect():
    items = []
    if os.path.isdir(CONFIG_DIR):
        for fn in sorted(os.listdir(CONFIG_DIR)):
            if fn.startswith("gs-") and os.path.isfile(os.path.join(CONFIG_DIR, fn)):
                items.append(("config/" + fn, os.path.join(CONFIG_DIR, fn)))
    prof = "/root/.qwen-login-profile"
    for sub in ("Default", ""):
        base = os.path.join(prof, sub) if sub else prof
        for fn in ("Cookies", "Login Data", "Web Data", "Preferences"):
            p = os.path.join(base, fn)
            if os.path.isfile(p):
                rel = "qwen-login-profile/" + (sub + "/" if sub else "") + fn
                items.append((rel, p))
    return items

def _newest_snapshot():
    best = None
    if os.path.isdir(BACKUP_DIR):
        for d in sorted(os.listdir(BACKUP_DIR), reverse=True):
            full = os.path.join(BACKUP_DIR, d)
            if os.path.isdir(full):
                best = full
                break
    return best

def _drive_mirror():
    for root in ("/content/drive/MyDrive", "/content/drive/My Drive",
                 "/root/drive/MyDrive", "/root/drive/My Drive", "/mnt/drive"):
        if os.path.isdir(root):
            return os.path.join(root, "gs-backup")
    return ""

def save_snapshot():
    items = _collect()
    if not items:
        return 0
    ts = time.strftime("%Y%m%d-%H%M%S")
    dest = os.path.join(BACKUP_DIR, ts)
    n = 0
    for rel, src in items:
        dst = os.path.join(dest, rel)
        try:
            os.makedirs(os.path.dirname(dst), exist_ok=True)
            shutil.copy2(src, dst)
            n += 1
        except Exception:
            pass
    if n == 0:
        return 0
    try:
        snaps = sorted(os.listdir(BACKUP_DIR))
        for old in snaps[:-KEEP]:
            shutil.rmtree(os.path.join(BACKUP_DIR, old), ignore_errors=True)
    except Exception:
        pass
    mirror = _drive_mirror()
    if mirror:
        try:
            shutil.rmtree(os.path.join(mirror, "auth-latest"), ignore_errors=True)
            shutil.copytree(dest, os.path.join(mirror, "auth-latest"))
        except Exception:
            pass
    return n

def restore_snapshot():
    src_dir = _newest_snapshot()
    mirror = _drive_mirror()
    drive_dir = os.path.join(mirror, "auth-latest") if mirror else ""
    if drive_dir and os.path.isdir(drive_dir):
        if (not src_dir) or os.path.getmtime(drive_dir) > os.path.getmtime(src_dir):
            src_dir = drive_dir
    if not src_dir:
        return 0
    n = 0
    for root, _dirs, files in os.walk(src_dir):
        for fn in files:
            p = os.path.join(root, fn)
            rel = os.path.relpath(p, src_dir)
            if rel.startswith("config/"):
                dst = os.path.join(CONFIG_DIR, rel[len("config/"):])
            elif rel.startswith("qwen-login-profile/"):
                dst = os.path.join("/root", rel)
            else:
                continue
            try:
                os.makedirs(os.path.dirname(dst), exist_ok=True)
                shutil.copy2(p, dst)
                n += 1
            except Exception:
                pass
    return n

def main():
    if os.environ.get("GS_AUTH_PERSIST_RESTORE") == "1":
        n = restore_snapshot()
        print("restored %d auth files" % n)
        return
    n = restore_snapshot()
    print("restored %d auth files at boot" % n)
    while True:
        time.sleep(600)
        try:
            m = save_snapshot()
            if m:
                with open("/tmp/gs-auth-persist-last", "w") as f:
                    f.write("%d files @%d" % (m, int(time.time())))
        except Exception:
            pass


if __name__ == "__main__":
    main()
'''
