gs_live_persist_py = r'''#!/usr/bin/env python3
# gs-live-persist — لقطة حيّة كل 3 دقائق لملفات كروم الحرجة (جلسات/تسجيل/مزامنة)
# واستعادة أحدثها عند الإقلاع — المحلية أو مرآة درايف (الأحدث لكل ملف يفوز).
import os, shutil, time
import fcntl as _fcntl
try:
    _sg_lock = open("/tmp/gs-live-persist.lock", "w")
    _fcntl.flock(_sg_lock, _fcntl.LOCK_EX | _fcntl.LOCK_NB)
except Exception:
    raise SystemExit(0)

LIVE_DIR = "/root/.backups/live"
INTERVAL = 180
PROFILES = {
    "main": "/root/.config/google-chrome",
    "qwen-login": "/root/.qwen-login-profile",
    "google-signup": "/root/.google-signup-profile",
    "work": "/root/.config/google-chrome-work",
}
FILES = ["Preferences", "Secure Preferences", "Bookmarks", "Local State",
         "Cookies", "Cookies-wal", "Cookies-shm", "Cookies-journal",
         "Login Data", "Login Data-wal", "Login Data-shm", "Login Data-journal",
         "Login Data For Account", "Login Data For Account-wal",
         "Login Data For Account-shm", "Login Data For Account-journal",
         "Web Data", "Web Data-wal", "Web Data-shm", "Web Data-journal",
         "Account Web Data", "Account Web Data-wal", "Account Web Data-shm",
         "Current Session", "Current Tabs", "Last Session", "Last Tabs"]
DIRS = ["Sessions", "Session Storage", "Sync Data", "Sync App Settings",
        "Sync Extension Settings", "Network", "Local Storage"]

def _drive_mirror():
    for root in ("/content/drive/MyDrive", "/content/drive/My Drive",
                 "/root/drive/MyDrive", "/root/drive/My Drive", "/mnt/drive"):
        if os.path.isdir(root):
            return os.path.join(root, "gs-backup")
    return ""

def _iter_profile_files(prof):
    for sub in ("", "Default"):
        base = os.path.join(prof, sub) if sub else prof
        if not os.path.isdir(base):
            continue
        for fn in FILES:
            p = os.path.join(base, fn)
            if os.path.isfile(p):
                yield p, (sub + "/" if sub else "") + fn
        for dn in DIRS:
            dpath = os.path.join(base, dn)
            if os.path.isdir(dpath):
                for root, _dd, ffs in os.walk(dpath):
                    for fn in ffs:
                        p = os.path.join(root, fn)
                        rel = os.path.relpath(p, base)
                        yield p, (sub + "/" if sub else "") + rel

def save_cycle():
    n = 0
    for tag, prof in PROFILES.items():
        if not os.path.isdir(prof):
            continue
        for src, rel in _iter_profile_files(prof):
            dst = os.path.join(LIVE_DIR, tag, rel)
            try:
                if os.path.isfile(dst) and os.path.getmtime(dst) >= os.path.getmtime(src):
                    continue
                os.makedirs(os.path.dirname(dst), exist_ok=True)
                shutil.copy2(src, dst + ".tmp")
                os.replace(dst + ".tmp", dst)
                n += 1
            except Exception:
                pass
    mirror = _drive_mirror()
    if mirror and os.path.isdir(LIVE_DIR):
        for root, _dd, ffs in os.walk(LIVE_DIR):
            for fn in ffs:
                src = os.path.join(root, fn)
                rel = os.path.relpath(src, LIVE_DIR)
                dst = os.path.join(mirror, "live-latest", rel)
                try:
                    if os.path.isfile(dst) and os.path.getmtime(dst) >= os.path.getmtime(src):
                        continue
                    os.makedirs(os.path.dirname(dst), exist_ok=True)
                    shutil.copy2(src, dst)
                except Exception:
                    pass
    return n

def restore_boot():
    mirror = _drive_mirror()
    drive_live = os.path.join(mirror, "live-latest") if mirror else ""
    n = 0
    for tag, prof in PROFILES.items():
        candidates = {}
        for base_src in (os.path.join(LIVE_DIR, tag),
                         os.path.join(drive_live, tag) if drive_live else ""):
            if not base_src or not os.path.isdir(base_src):
                continue
            for root, _dd, ffs in os.walk(base_src):
                for fn in ffs:
                    src = os.path.join(root, fn)
                    rel = os.path.relpath(src, base_src)
                    try:
                        mt = os.path.getmtime(src)
                    except Exception:
                        continue
                    if rel not in candidates or mt > candidates[rel][1]:
                        candidates[rel] = (src, mt)
        for rel, (src, mt) in candidates.items():
            dst = os.path.join(prof, rel)
            try:
                if os.path.isfile(dst) and os.path.getmtime(dst) >= mt:
                    continue
                os.makedirs(os.path.dirname(dst), exist_ok=True)
                shutil.copy2(src, dst + ".tmp")
                os.replace(dst + ".tmp", dst)
                n += 1
            except Exception:
                pass
    return n

def main():
    if os.environ.get("GS_LIVE_RESTORE") == "1":
        print("live-restored %d files" % restore_boot())
        return
    restore_boot()
    while True:
        time.sleep(INTERVAL)
        try:
            save_cycle()
        except Exception:
            pass


if __name__ == "__main__":
    main()
'''
with open('/tmp/gs-live-persist.py', 'w', encoding='utf-8') as f:
    f.write(gs_live_persist_py)
run("sudo cp /tmp/gs-live-persist.py /usr/local/lib/gs-live-persist.py && "
    "sudo chmod 644 /usr/local/lib/gs-live-persist.py")
