gs_boot_verify_py = r'''#!/usr/bin/env python3
# gs-boot-verify — تقرير إقلاع مُتحقَّق + إصلاح ذاتي: يفحص كل مكوّن فعليًّا،
# يحاول إصلاح الفاشل ويعيد الفحص، ويكتب تقريرًا مرئيًّا (TXT + HTML).
import os, socket, subprocess, time

REPORT_TXT = os.environ.get("GS_BOOT_REPORT_TXT", "/root/workspace/boot-report.txt")
REPORT_HTML = os.environ.get("GS_BOOT_REPORT_HTML", "/root/workspace/boot-report.html")
DISPLAY = os.environ.get("DISPLAY", ":1")


def _run(cmd, timeout=180):
    try:
        p = subprocess.run(cmd, shell=True, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                           text=True, timeout=timeout, env=dict(os.environ, DISPLAY=DISPLAY))
        return p.returncode, (p.stdout or "")[-400:]
    except Exception as e:
        return 1, str(e)


def _port(port):
    try:
        with socket.socket() as s:
            s.settimeout(2)
            return s.connect_ex(("127.0.0.1", port)) == 0
    except Exception:
        return False


def _file(p):
    return os.path.isfile(p)


def _proc(pattern):
    try:
        return subprocess.run(["pgrep", "-f", pattern], stdout=subprocess.DEVNULL,
                              stderr=subprocess.DEVNULL, timeout=8).returncode == 0
    except Exception:
        return False


def _latest_mtime(root):
    latest = 0
    for r, _d, fs in os.walk(root):
        for fn in fs:
            try:
                latest = max(latest, os.path.getmtime(os.path.join(r, fn)))
            except Exception:
                pass
    return latest


def _sessions_ok():
    for p in ("/root/.config/google-chrome/Default/Sessions",
              "/root/.config/google-chrome/Sessions"):
        if os.path.isdir(p) and os.listdir(p):
            return True
    return False


ITEMS = [
    {"id": "chrome-ext", "name": "الإضافة الرسمية Colab Keep Alive",
     "check": lambda: _file("/opt/ext-colab-keep-alive/manifest.json"),
     "fix": "python3 /usr/local/lib/crx-install.py"},
    {"id": "bridge-port", "name": "منفذ جسر كوين 9224 (مساحة العمل 1)",
     "check": lambda: _port(9224),
     "fix": "setsid /usr/local/bin/chrome-root >/dev/null 2>&1 & sleep 8; true"},
    {"id": "chrome-login", "name": "ملفات تسجيل الدخول (الملف الرئيسي)",
     "check": lambda: _file("/root/.config/google-chrome/Default/Cookies") or
                      _file("/root/.config/google-chrome/Cookies"),
     "fix": "GS_LIVE_RESTORE=1 python3 /usr/local/lib/gs-live-persist.py"},
    {"id": "sessions", "name": "صفحات/جلسات كروم المحفوظة",
     "check": _sessions_ok,
     "fix": "CHROME_USER_DATA_DIR=/root/.config/google-chrome python3 /usr/local/bin/chrome-session-restore"},
    {"id": "agent-deepseek", "name": "خادم وكيل ديب سيك (8787)",
     "check": lambda: _port(8787),
     "fix": "setsid /usr/local/bin/gs-agent-ui >/dev/null 2>&1 & sleep 2; true"},
    {"id": "agent-qwen", "name": "خادم وكيل كوين (8788)",
     "check": lambda: _port(8788),
     "fix": "setsid /usr/local/bin/gs-qwen-ui >/dev/null 2>&1 & sleep 2; true"},
    {"id": "bridge", "name": "جسر كوين v2 (8790)",
     "check": lambda: _port(8790),
     "fix": "setsid python3 /usr/local/lib/gs-qwen-bridge.py >/tmp/gs-qwen-bridge.log 2>&1 & sleep 3; true"},
    {"id": "watchdog", "name": "الحارس الإشرافي",
     "check": lambda: _proc("gs-watchdog.py"),
     "fix": "setsid python3 /usr/local/lib/gs-watchdog.py >/dev/null 2>&1 & true"},
    {"id": "live-persist", "name": "اللقطة الحيّة (كل 3 دقائق)",
     "check": lambda: _proc("gs-live-persist.py"),
     "fix": "setsid python3 /usr/local/lib/gs-live-persist.py >/dev/null 2>&1 & true"},
    {"id": "desktop", "name": "مدير النوافذ xfwm4",
     "check": lambda: _proc("xfwm4"),
     "fix": "setsid /usr/local/bin/xfce-desktop-fix >/dev/null 2>&1 & true"},
    {"id": "translate", "name": "سياسة الترجمة المُدارة",
     "check": lambda: _file("/etc/opt/chrome/policies/managed/translate-enabled.json"),
     "fix": "mkdir -p /etc/opt/chrome/policies/managed && printf '%s' '{\"TranslateEnabled\": true}' > /etc/opt/chrome/policies/managed/translate-enabled.json"},
    {"id": "opencode", "name": "OpenCode",
     "check": lambda: _run("command -v opencode")[0] == 0,
     "fix": "bash /usr/local/bin/opencode-install"},
]


def main():
    results = []
    ok = 0
    for item in ITEMS:
        try:
            good = bool(item["check"]())
        except Exception:
            good = False
        log = ""
        if not good:
            _rc, log = _run(item["fix"])
            time.sleep(1)
            try:
                good = bool(item["check"]())
            except Exception:
                good = False
        results.append((item["name"], good, log))
        ok += 1 if good else 0
    ts = time.strftime("%Y-%m-%d %H:%M:%S")
    live_age = -1
    if os.path.isdir("/root/.backups/live"):
        lm = _latest_mtime("/root/.backups/live")
        if lm:
            live_age = int(time.time() - lm)
    drive = any(os.path.isdir(p) for p in (
        "/content/drive/MyDrive", "/content/drive/My Drive",
        "/root/drive/MyDrive", "/root/drive/My Drive", "/mnt/drive"))
    lines = ["تقرير الإقلاع المُتحقَّق — %s" % ts, "=" * 56, ""]
    for name, good, log in results:
        lines.append("%s %s" % ("✅" if good else "❌", name))
        if log and not good:
            lines.append("    السجل: " + log.replace("\n", " | ")[:180])
    lines += ["", "المكونات السليمة: %d من %d" % (ok, len(results)),
              "أحدث لقطة حيّة: %s" % ("منذ %d ثانية" % live_age if live_age >= 0 else "لا توجد بعد"),
              "درايف موصول: %s" % ("نعم" if drive else "لا"),
              "أعد التحقق: python3 /usr/local/lib/gs-boot-verify.py"]
    report = "\n".join(lines) + "\n"
    try:
        os.makedirs(os.path.dirname(REPORT_TXT), exist_ok=True)
        with open(REPORT_TXT, "w", encoding="utf-8") as f:
            f.write(report)
    except Exception:
        pass
    rows = "".join("<tr><td>%s</td><td>%s</td></tr>" % ("✅" if g else "❌", n)
                   for n, g, _l in results)
    html = ("<!DOCTYPE html><html dir=rtl lang=ar><meta charset=utf-8>"
            "<meta http-equiv=refresh content=60>"
            "<body style='font-family:sans-serif;background:#0b1220;color:#e5edff;padding:20px'>"
            "<h2>تقرير الإقلاع المُتحقَّق</h2><p>%s</p>"
            "<table border=1 cellspacing=0 cellpadding=8 style='border-color:#2a3a5a'>%s</table>"
            "<p>السليمة: %d/%d — أحدث لقطة: %s — درايف: %s</p>"
            "<pre style='background:#0c1424;padding:12px;border-radius:8px;white-space:pre-wrap'>%s</pre>"
            "</body></html>"
            % (ts, rows, ok, len(results),
               ("منذ %dث" % live_age if live_age >= 0 else "—"),
               ("نعم" if drive else "لا"), report.replace("<", "&lt;")))
    try:
        with open(REPORT_HTML, "w", encoding="utf-8") as f:
            f.write(html)
    except Exception:
        pass
    print(report)


if __name__ == "__main__":
    main()
'''
with open('/tmp/gs-boot-verify.py', 'w', encoding='utf-8') as f:
    f.write(gs_boot_verify_py)
run("sudo cp /tmp/gs-boot-verify.py /usr/local/lib/gs-boot-verify.py && "
    "sudo chmod 644 /usr/local/lib/gs-boot-verify.py")
