# ============================================================
# v69) وضع البرمجة: شاشة أوسع + إخفاء لوحات الـ IDE بلمسة واحدة
# ============================================================
# المشكلة: على شاشة 800×1280 يأخذ Android Studio معظم المساحة للوحات
# الجانبية فيختفي الكود. الحل: أمر واحد عكوسي تمامًا يوسع الدقة إلى
# 1600×900 (والغلاف يلائمها تلقائيًا بلا قطع) ويُخفي لوحات الـ IDE
# (Ctrl+Shift+F12 = اختصار JetBrains القياسي) ويكبر النافذة داخل الحدود.
# كل خطوة محمية بـ || true والدقة الأصلية تُخزّن للرجوع الفوري.
coding_mode_sh = r"""#!/bin/bash
export DISPLAY="${DISPLAY:-:1}" HOME=/root XAUTHORITY=/root/.Xauthority
STATE_DIR=/root/.config/colab-desktop
STATE="$STATE_DIR/coding-mode"
PREV="$STATE_DIR/coding-mode-prev"
mkdir -p "$STATE_DIR" 2>/dev/null
WIDE_W=1600
WIDE_H=900

say(){ echo "$*"; command -v notify-send >/dev/null 2>&1 && notify-send "وضع البرمجة" "$*" 2>/dev/null; true; }
out_name(){ xrandr 2>/dev/null | awk '/ connected/{print $1;exit}'; }
cur_geo(){ xdotool getdisplaygeometry 2>/dev/null | tr ' ' 'x'; }

set_res(){
  W="$1"; H="$2"; O="$(out_name)"
  [ -n "$O" ] || return 1
  xrandr --output "$O" --mode "${W}x${H}" >/dev/null 2>&1 && return 0
  if command -v cvt >/dev/null 2>&1; then
    ML=$(cvt "$W" "$H" 60 2>/dev/null | grep Modeline | sed 's/^ *Modeline *//')
    if [ -n "$ML" ]; then
      NAME=$(echo "$ML" | awk '{print $1}' | tr -d '\"')
      REST=$(echo "$ML" | cut -d' ' -f2-)
      xrandr --newmode "$NAME" $REST >/dev/null 2>&1
      xrandr --addmode "$O" "$NAME" >/dev/null 2>&1
      xrandr --output "$O" --mode "$NAME" >/dev/null 2>&1 && return 0
    fi
  fi
  xrandr -s "${W}x${H}" >/dev/null 2>&1 && return 0
  return 1
}

ide_window(){
  for c in jetbrains-studio android-studio jetbrains-idea Code Cursor; do
    W=$(xdotool search --onlyvisible --class "$c" 2>/dev/null | head -1)
    [ -n "$W" ] && { echo "$W"; return 0; }
  done
  xdotool getactivewindow 2>/dev/null
}

toggle_panels(){
  W="$(ide_window)"
  [ -n "$W" ] || return 0
  xdotool windowactivate --sync "$W" 2>/dev/null || true
  # Ctrl+Shift+F12 = Hide All Tool Windows (اختصار قياسي في JetBrains)
  xdotool key --clearmodifiers --window "$W" ctrl+shift+F12 2>/dev/null || true
  if command -v wmctrl >/dev/null 2>&1; then
    wmctrl -i -r "$W" -b add,maximized_vert,maximized_horz 2>/dev/null || true
  fi
}

refit(){ [ -x /usr/local/bin/window-fitter ] && pkill -USR1 -f window-fitter 2>/dev/null; true; }

mode_on(){
  G="$(cur_geo)"; [ -n "$G" ] && echo "$G" > "$PREV"
  if set_res "$WIDE_W" "$WIDE_H"; then
    echo on > "$STATE"
    toggle_panels; refit
    say "مفتوح: ${WIDE_W}×${WIDE_H} — الكود أوسع. اضغط ثانية للرجوع."
  else
    toggle_panels
    say "تعذّر توسيع الدقة — أُخفيت لوحات الـ IDE فقط (لا ضرر)."
  fi
}

mode_off(){
  G="$(cat "$PREV" 2>/dev/null)"
  [ -n "$G" ] || G="800x1280"
  W="${G%%x*}"; H="${G##*x}"
  case "$W$H" in ''|*[!0-9]*) W=800; H=1280;; esac
  set_res "$W" "$H" || true
  echo off > "$STATE"
  toggle_panels; refit
  say "عاد الوضع العادي: ${W}×${H}"
}

case "${1:-toggle}" in
  on) mode_on;;
  off) mode_off;;
  status) echo "mode=$(cat "$STATE" 2>/dev/null || echo off) screen=$(cur_geo)";;
  panels) toggle_panels;;
  *) if [ "$(cat "$STATE" 2>/dev/null)" = on ]; then mode_off; else mode_on; fi;;
esac
exit 0
"""
