# v45.30 non-blocking startup gate. Drive FUSE must never delay Kasm/XFCE or
# publication of the desktop link. Only /root is inspected here; a workspace
# that needs Drive restoration is restored later by its background launcher.
_STARTUP_DATA_READY = True
_CHROME_LOCAL_READY = {1: False, 2: False}
def _chrome_local_startup_proof(ws):
    """Constant-time local proof; no subprocess, Drive, hashing or DB scan."""
    import json as _j
    root="/root/.chrome-profiles-local/profile-%d"%ws
    marker=root+".restore-ready"
    if not (os.path.isfile(marker) and os.path.isdir(root)): return False
    try:
        with open(os.path.join(root,"Local State"),encoding="utf-8") as f:_j.load(f)
        profiles=[d for d in os.listdir(root) if d=="Default" or d.startswith("Profile ")]
        prefs=0;cookies=0
        for d in sorted(profiles)[:20]:
            pp=os.path.join(root,d,"Preferences")
            if os.path.isfile(pp):
                with open(pp,encoding="utf-8") as f:_j.load(f)
                prefs+=1
            for rel in ("Network/Cookies","Cookies"):
                q=os.path.join(root,d,rel)
                if os.path.isfile(q) and os.path.getsize(q)>=4096:
                    with open(q,"rb") as f:
                        if f.read(16)==b"SQLite format 3\x00":cookies+=1
        return prefs>0 and cookies>0
    except (OSError,ValueError,TypeError,_j.JSONDecodeError):
        return False

print("[i] فحص محلي فوري لمساحتي Chrome — دون ا��تظار Drive...")
for _ws in (1,2):
    _CHROME_LOCAL_READY[_ws]=_chrome_local_startup_proof(_ws)
    if _CHROME_LOCAL_READY[_ws]:
        print("[OK] مساحة Chrome %d محلية وجاهزة فورًا ✅"%_ws)
    else:
        print("[i] مساحة Chrome %d ستُستعاد في الخلفية عند تشغيلها؛ لن تؤخر سطح المكتب."%_ws)
_STRICT_RESTORED_WORKSPACES=[ws for ws,ok in _CHROME_LOCAL_READY.items() if ok]

