print("[2] تثبيت KasmVNC...")
def get_vncserver_path():
    """أعد مشغّل KasmVNC المتاح فعليًا مهما كان اسم الحزمة.

    بعض إصدارات/استعادات KasmVNC توفر ``kasmvncserver`` مباشرة بينما تنشئ
    حزم أخرى الاسم التوافقي ``vncserver`` عبر alternatives. لذلك يجب قبول
    الاسمين، مع تفضيل الاسم الرسمي المتوافق vncserver عند وجوده.
    """
    candidates = [
        shutil.which("vncserver"),
        "/usr/bin/vncserver",
        "/usr/local/bin/vncserver",
        shutil.which("kasmvncserver"),
        "/usr/bin/kasmvncserver",
        "/usr/local/bin/kasmvncserver",
    ]
    for candidate in candidates:
        if (candidate and os.path.isfile(candidate)
                and os.access(candidate, os.X_OK)):
            # لا نستخدم realpath: إبقاء اسم argv[0] مهم لبعض أغلفة Perl.
            return candidate
    return ""


def _runtime_exec(path):
    return os.path.isfile(path) and os.access(path,os.X_OK)


def _kasm_missing_runtime():
    """الأسماء العامة التي يفحصها kasmvncserver 1.4 حرفيًا قبل الإقلاع."""
    required=("/usr/bin/Xvnc","/usr/bin/vncpasswd")
    return [x for x in required if not _runtime_exec(x)]


def _link_runtime_alias(dst,candidates):
    if _runtime_exec(dst):
        return True
    target=next((x for x in candidates if _runtime_exec(x) and os.path.realpath(x)!=os.path.realpath(dst)),"")
    if not target:
        return False
    r=run("sudo rm -f '%s' && sudo ln -sfn '%s' '%s' && sudo chmod a+rx '%s'"
          % (dst,target,dst,target),timeout=30)
    return getattr(r,"returncode",1)==0 and _runtime_exec(dst)


def _repair_kasm_runtime_aliases():
    """أصلح alternatives المفقودة مباشرةً من أسماء Kasm الأصلية."""
    mapping=(
      ("/usr/bin/Xvnc",("/usr/bin/Xkasmvnc","/usr/lib/kasmvncserver/Xvnc",
                        "/usr/lib/kasmvncserver/Xkasmvnc","/usr/local/bin/Xkasmvnc")),
      ("/usr/bin/vncpasswd",("/usr/bin/kasmvncpasswd","/usr/lib/kasmvncserver/vncpasswd",
                              "/usr/local/bin/kasmvncpasswd")),
      # vncconfig ليس مطلوبًا في كل تشغيل، لكن إصلاحه يمنع الفشل في ميزات الحافظة.
      ("/usr/bin/vncconfig",("/usr/bin/kasmvncconfig","/usr/lib/kasmvncserver/vncconfig",
                              "/usr/local/bin/kasmvncconfig")),
    )
    repaired=[]
    for dst,candidates in mapping:
        before=_runtime_exec(dst)
        if _link_runtime_alias(dst,candidates) and not before:repaired.append(dst)
    missing=_kasm_missing_runtime()
    if repaired:
        print("[auto-fix] أُعيدت أسماء KasmVNC: %s ✅" % ", ".join(repaired))
    return not missing


def _xvnc_runtime_ready():
    # إبقاء الاسم للتوافق مع بقية طبقات الحماية القديمة.
    return _runtime_exec("/usr/bin/Xvnc")


def _repair_xvnc_alias():
    # أصبح الإصلاح شاملاً لـ Xvnc وvncpasswd بدل نجاح جزئي مضلل.
    return _repair_kasm_runtime_aliases()


def _install_kasm_deb_local(path):
    """أعد تثبيت الحزمة محليًا حتى لو سجل dpkg أنها مثبتة بالفعل."""
    if not path or not os.path.isfile(path) or os.path.getsize(path)<1_000_000:
        return False
    _apt_heal()
    run("sudo DEBIAN_FRONTEND=noninteractive dpkg --force-confold -i '%s' "
        ">/tmp/kasm-reinstall.log 2>&1" % path,timeout=600)
    run("sudo DEBIAN_FRONTEND=noninteractive apt-get install -y -qq -f "
        ">>/tmp/kasm-reinstall.log 2>&1",timeout=600)
    run("sudo ldconfig >/dev/null 2>&1 || true",timeout=120)
    return _repair_kasm_runtime_aliases() and bool(get_vncserver_path())


def _ensure_kasm_runtime():
    """بوابة تشغيل صارمة: كل ملفات wrapper أو إعادة الحزمة من Drive."""
    if _repair_kasm_runtime_aliases() and get_vncserver_path():
        return True
    cached=globals().get("KASM_CACHE_DEB","")
    if cached and _install_kasm_deb_local(cached):
        print("[auto-fix] أُعيدت ملفات تشغيل KasmVNC من نسخة Drive ✅")
        return True
    local=globals().get("KASM_DEB","")
    if local and _install_kasm_deb_local(local):
        return True
    return False


def kasm_installed():
    # التثبيت صالح عند وجود أحد اسمي المشغّل وخادم Kasm X التنفيذي.
    launcher = get_vncserver_path()
    runtime_ok = _repair_kasm_runtime_aliases() and not _kasm_missing_runtime()
    perl_ok = run("perl -MSwitch -e 1 >/dev/null 2>&1", timeout=20).returncode == 0
    return bool(launcher and runtime_ok and perl_ok)

def get_kasm_url():
    api = run("curl -fsSL https://api.github.com/repos/kasmtech/KasmVNC/releases/latest",
              timeout=30).stdout
    url = ""
    try:
        m = re.findall(r'https://[^"]+kasmvncserver_'
                       + DISTRIB_CODENAME + r'_[^"]*amd64\.deb', api)
        if m:
            url = m[0]
    except Exception:
        url = ""
    return url

KASM_DEB = "/tmp/kasmvncserver.deb"
ok_install = False
KASM_VERSION = "1.4.0"

# تسريع الإقلاع: إن كان KasmVNC مثبّتًا مسبقًا (جلسة مستأنفة) لا نعيد التنزيل
# والتثبيت إطلاقًا — نتخطّى مباشرة (يوفّر دقائق على كل إقلاع).
if kasm_installed():
    ok_install = True
    # ملاحظة: لا نستخدم `kasmvncserver --version` — هذا الخيار غير مدعوم في
    # بعض بُنى KasmVNC ويطبع 'Unrecognized option'. نعتمد على dpkg فقط (موثوق).
    _vq = run("dpkg -s kasmvncserver 2>/dev/null | grep -i '^Version'",
              timeout=15).stdout
    _mv = re.search(r'(\d+\.\d+\.\d+)', _vq or "")
    if _mv:
        KASM_VERSION = _mv.group(1)
    print("[OK] KasmVNC مثبّت مسبقًا (الإصدار %s) — تخطّينا التثبيت ⚡"
          % KASM_VERSION)

# Round 11: أولًا نحاول تثبيت KasmVNC من نسخة .deb محفوظة في Drive (بلا تنزي��)
KASM_CACHE_DEB = os.path.join(PKG_CACHE, "kasmvncserver.deb")
if not ok_install and DRIVE_OK and os.path.exists(KASM_CACHE_DEB):
    try:
        _sz = os.path.getsize(KASM_CACHE_DEB)
    except Exception:
        _sz = 0
    if _sz > 1000000:
        print("[⚡ تسريع] تثبيت KasmVNC من نسخة Drive المحفوظة (بلا تنزيل)...")
        _apt_heal()   # ضمان سلامة dpkg قبل تثبيت .deb (يمنع الفشل الصامت)
        run("cp -f '%s' %s 2>/dev/null" % (KASM_CACHE_DEB, KASM_DEB),
            timeout=180)
        _install_kasm_deb_local(KASM_DEB)
        if kasm_installed():
            ok_install = True
            _vq = run("dpkg -s kasmvncserver 2>/dev/null | grep -i version",
                      timeout=15).stdout
            _mv = re.search(r'(\d+\.\d+\.\d+)', _vq or "")
            if _mv:
                KASM_VERSION = _mv.group(1)
            print("[OK] KasmVNC مثبّت من Drive (الإصدار %s) ⚡⚡" % KASM_VERSION)

urls = []
if not ok_install:
    auto = get_kasm_url()
    if auto:
        urls.append(auto)
    # روابط احتياطية ثابتة (إصدارات معروفة مستقرة)
    for ver in ["1.4.0", "1.3.4", "1.3.3", "1.3.2", "1.3.1"]:
        urls.append("https://github.com/kasmtech/KasmVNC/releases/download/"
                    "v%s/kasmvncserver_%s_%s_amd64.deb"
                    % (ver, DISTRIB_CODENAME, ver))

for u in urls:
    print("[i] تنزيل: %s" % u)
    run("rm -f %s" % KASM_DEB)
    dl = run("curl -fSL --retry 3 --connect-timeout 30 '%s' -o %s" % (u, KASM_DEB), timeout=600)
    size = run("stat -c%%s %s 2>/dev/null" % KASM_DEB).stdout.strip()
    if dl.returncode != 0 or not size or int(size) < 1000000:
        print("[i]  - تعذّر، أجرّب التالي.")
        continue
    _apt_heal()   # إصلاح ذاتي قبل التثبيت (أقفال/dpkg مقطوع)
    inst_ok = _install_kasm_deb_local(KASM_DEB)
    if kasm_installed():
        ok_install = True
        _m = re.search(r'_(\d+\.\d+\.\d+)_', u)
        if _m:
            KASM_VERSION = _m.group(1)
