def _expand_browser_items():
    """يبني قائمة المسارات النسبية للملفات المهمّة الموجودة فعلًا في
    ملفّات تعريف المتصف��حات (إشارات مرجعية + تسجيل دخول) — متجاهلًا الكاش."""
    items = []
    home = "/root"
    # Chrome-family: لكل مجلد متصفّح، نمرّ على "Local State" + كل profile
    for base in _CHROME_DIRS:
        broot = os.path.join(home, base)
        if not os.path.isdir(broot):
            continue
        ls = os.path.join(base, "Local State")
        if os.path.exists(os.path.join(home, base, "Local State")):
            items.append(ls)
        try:
            for prof in os.listdir(broot):
                pdir = os.path.join(broot, prof)
                if not os.path.isdir(pdir):
                    continue
                # ملفّات التريف: Default, Profile 1, Profile 2, ...
                if prof != "Default" and not prof.startswith("Profile"):
                    continue
                for f in _CHROME_FILES:
                    fp = os.path.join(pdir, f)
                    if os.path.exists(fp):
                        items.append(os.path.join(base, prof, f))
        except Exception:
            pass
    # Firefox: نمرّ على مجلدات profiles ونلتقط الملفّات المهمّة
    froot = os.path.join(home, _FIREFOX_GLOB)
    if os.path.isdir(froot):
        try:
            for prof in os.listdir(froot):
                pdir = os.path.join(froot, prof)
                if not os.path.isdir(pdir):
                    continue
                for f in _FIREFOX_FILES:
                    fp = os.path.join(pdir, f)
                    if os.path.exists(fp):
                        items.append(os.path.join(_FIREFOX_GLOB, prof, f))
        except Exception:
            pass
    return items


def _saved_browser_items():
    """مثل _expand_browser_items لكنه يفحص النسخة المحفوظة على Drive
    (PERSIST_HOME) بدل /root — لمعرفة ما يمكن استعادته."""
    items = []
    home = PERSIST_HOME
    for base in _CHROME_DIRS:
        broot = os.path.join(home, base)
        if not os.path.isdir(broot):
            continue
        if os.path.exists(os.path.join(home, base, "Local State")):
            items.append(os.path.join(base, "Local State"))
        try:
            for prof in os.listdir(broot):
                pdir = os.path.join(broot, prof)
                if not os.path.isdir(pdir):
                    continue
                if prof != "Default" and not prof.startswith("Profile"):
                    continue
                for f in _CHROME_FILES:
                    if os.path.exists(os.path.join(pdir, f)):
                        items.append(os.path.join(base, prof, f))
        except Exception:
            pass
    froot = os.path.join(home, _FIREFOX_GLOB)
    if os.path.isdir(froot):
        try:
            for prof in os.listdir(froot):
                pdir = os.path.join(froot, prof)
                if not os.path.isdir(pdir):
                    continue
                for f in _FIREFOX_FILES:
                    if os.path.exists(os.path.join(pdir, f)):
                        items.append(os.path.join(_FIREFOX_GLOB, prof, f))
        except Exception:
            pass
    return items


