# v46 — إصلاح «مشاكل استعادة البيانات» جذريًّا.
# المشكلة سابقًا: (1) لا إعادة محاولة إطلاقًا  أي تعثّر عابر في Google Drive
# FUSE (وهو شائع جدًّا: مهلة، EIO، انقطاع لحظي) يُسقط عنصرًا واحدًا فيصير العدّ
# جزئيًّا؛ (2) العدّ الجزئي كان يرفع RuntimeError؛ (3) persist_restore ترفع
# استثناءً فيموت الإقلاع كلّه ولا يظهر رابط سطح المكتب مطلقًا؛ (4) الاستعادة
# تسلسلية بالكامل فتُبطئ الإقلاع على FUSE.
# الحل: إعادة محاولة متدرّجة لكل عنصر + توازٍ محدود + تقرير جزئي رشيق يُكمل
# الإقلاع مع إبلاغ واضح بدل قتل الجلسة.
_RESTORE_RETRIES = 3               # عدد المحاولات لكل عنصر
_RESTORE_BACKOFF = 1.5             # ثانية أولى، تتضاعف
_RESTORE_WORKERS = 4               # توازٍ محدود (FUSE يخنق أكثر من ذلك)


def _restore_one(rel, timeout_each):
    """يستعيد عنصرًا واحدًا مع إعادة محاولة متدرّجة.
    يعيد: 'ok' | 'absent' | 'fail'."""
    src = os.path.join(PERSIST_HOME, rel)
    if not os.path.exists(src):
        return "absent"
    dst = os.path.join("/root", rel)
    try:
        os.makedirs(os.path.dirname(dst) or dst, exist_ok=True)
    except Exception:
        pass
    is_dir = os.path.isdir(src)
    delay = _RESTORE_BACKOFF
    last_rc = None
    for attempt in range(1, _RESTORE_RETRIES + 1):
        # --partial + مهلة أطول في كل محاول��: rsync يُكمل ما نُسخ فعلًا.
        tmo = timeout_each * attempt
        if is_dir:
            r = run("rsync -a --partial %s '%s/' '%s/' 2>/dev/null"
                    % (_rsync_excludes(), src, dst), timeout=tmo)
        else:
            r = run("rsync -a --partial '%s' '%s' 2>/dev/null"
                    % (src, dst), timeout=tmo)
        last_rc = getattr(r, "returncode", 1)
        if last_rc == 0:
            return "ok"
        # rc=24 يعني «اختفت ملفات مصدر أثناء النسخ» — غير قاتل عمليًّا.
        if last_rc == 24:
            return "ok"
        if attempt < _RESTORE_RETRIES:
            time.sleep(delay)
            delay *= 2
    _diag_event("restore_item_failed_rc%s" % last_rc)
    return "fail"


def _restore_items(items, timeout_each):
    """يستعيد قائمة عناصر بتوازٍ محدود + إعادة محاولة.
    يعيد (عدد الناجح، قائمة الفاشل). التوقيع تغيّر عن v42 عن قصد."""
    ok_n = 0
    failed = []
    todo = [x for x in items if x]
    if not todo:
        return 0, []
    workers = max(1, min(_RESTORE_WORKERS, len(todo)))
    try:
        with _app_cf.ThreadPoolExecutor(max_workers=workers,
                                        thread_name_prefix="restore") as pool:
            futs = {pool.submit(_restore_one, rel, timeout_each): rel for rel in todo}
            for fut in _app_cf.as_completed(futs):
                rel = futs[fut]
                try:
                    res = fut.result()
                except Exception as exc:
                    _diag_event("restore_item_exception", exc)
                    res = "fail"
                if res == "ok":
                    ok_n += 1
                elif res == "fail":
                    failed.append(rel)
    except Exception as exc:
        # حتى لو انهار م��مّع الخيوط: نرجع تسلسليًّا بدل إسقاط الاستعادة كلها.
        _diag_event("restore_pool_fallback", exc)
        ok_n = 0; failed = []
        for rel in todo:
            res = _restore_one(rel, timeout_each)
            if res == "ok":
                ok_n += 1
            elif res == "fail":
                failed.append(rel)
    return ok_n, failed


_RESTORE_WORKER_ERROR = None
_RESTORE_REPORT = {"desktop_ok": 0, "desktop_total": 0, "desktop_failed": [],
                   "browser_ok": 0, "browser_total": 0, "browser_failed": [],
                   "complete": False}


def _restore_worker():
    """استعادة مرنة: تُعيد المحاولة، تُبلّغ عن الجزئي، ولا تقتل الإقلاع أبدًا."""
    global _RESTORE_WORKER_ERROR
    try:
        expected_fast = [x for x in _PERSIST_FAST
                         if os.path.exists(os.path.join(PERSIST_HOME, x))]
        got_fast, failed_fast = _restore_items(expected_fast, timeout_each=35)
        _RESTORE_REPORT.update(desktop_ok=got_fast, desktop_total=len(expected_fast),
                               desktop_failed=failed_fast)
        browser = _saved_browser_items()
        got_browser, failed_browser = _restore_items(browser, timeout_each=45)
        _RESTORE_REPORT.update(browser_ok=got_browser, browser_total=len(browser),
                               browser_failed=failed_browser)
        complete = (not failed_fast) and (not failed_browser)
        _RESTORE_REPORT["complete"] = complete
        if complete:
            print("[OK] اكتملت استعادة إعدادات سطح المكتب وكل عناصر المتصفح المحفوظة ✅")
        else:
            print("[!] استعادة جزئية بعد %d محاولات لكل عنصر — "
                  "سطح المكتب %d/%d، المتصفح %d/%d."
                  % (_RESTORE_RETRIES, got_fast, len(expected_fast),
                     got_browser, len(browser)))
            for rel in (failed_fast + failed_browser)[:8]:
                print("    • تعذّرت استعادة: %s" % rel)
            print("[i] سيُكمل النظام الإقلاع بالبيانات المستعادة، ولن تُحذف "
                  "النسخة على Drive — تُعاد المحاولة تلقائيًا في الخلفية.")
        # v46: العلامة تُرفع دائمًا كي لا يتجمّد الإقلاع على استعادة جزئية.
        _restore_done.set(); _mark_browser_restore_done()
        return complete
    except Exception as exc:
        _RESTORE_WORKER_ERROR = exc
        _diag_event("restore_worker", exc)
        print("[!] تعذّرت الاستعادة (%s) — يُكمل النظام دون حجب سطح المكتب." % exc)
        _restore_done.set(); _mark_browser_restore_done()
        return False


def _restore_retry_bg():
    """محاولة استعادة متأخّرة للعناصر التي فشلت — بعد استقرار Drive."""
    def _work():
        try:
            time.sleep(90)
            pending = list(_RESTORE_REPORT.get("desktop_failed") or []) + \
                      list(_RESTORE_REPORT.get("browser_failed") or [])
            if not pending:
                return
            print("[🔁 استعادة] إعادة محاولة %d عنصرًا تعذّر سابقًا..." % len(pending))
            ok_n, still = _restore_items(pending, timeout_each=90)
            if not still:
                _RESTORE_REPORT.update(desktop_failed=[], browser_failed=[],
                                       complete=True)
                print("[✅ استعادة] استُكملت كل العناصر المتأخّرة (%d) ✅" % ok_n)
                # v46: بعد اكتمال الاستعادة يعود الحفظ الكامل (مع المزامنة
                # الحاذفة) بأمان تام؛ نُخبر المستخدم لأن الوضع تغيّر لصالحه.
                global _ADDITIVE_SAVE_NOTICE_SHOWN
                if _ADDITIVE_SAVE_NOTICE_SHOWN:
                    _ADDITIVE_SAVE_NOTICE_SHOWN = False
                    print("[🛡️ حماية] اكتملت الاستعادة — عاد الحفظ الكامل "
                          "المتزامن للعمل بأمان ✅")
            else:
                print("[i] بقي %d عنصرًا غير مستعاد؛ النسخة على Drive سليمة "
                      "وستُحاول الجلسة القادمة مجددًا." % len(still))
        except Exception as exc:
            _diag_event("restore_retry_bg", exc)
    threading.Thread(target=_work, name="restore_retry", daemon=True).start()


def _sanitize_restored_desktop_state():
    """احذف حالة العرض المتطايرة محليًا فقط؛ لا تلمس أي ملف على Drive."""
    try:
        shutil.rmtree("/root/.config/sessions",ignore_errors=True)
        shutil.rmtree("/root/.cache/sessions",ignore_errors=True)
        for pat in ("/root/.config/xfce4/xfconf/xfce-perchannel-xml/xfwm4.xml",
                    "/root/.config/xfce4/xfconf/xfce-perchannel-xml/xsettings.xml",
                    "/root/.config/xfce4/xfconf/xfce-perchannel-xml/xfce4-panel.xml",
                    "/root/.config/xfce4/xfconf/xfce-perchannel-xml/xfce4-session.xml"):
            try: os.unlink(pat)
            except FileNotFoundError: pass
            except Exception: pass
        # تخطيط محفوظ لدقة قديمة يعيد النوافذ مقصوصة؛ الملف المحلي فقط يُصفّر.
        for f in ("/root/.config/colab-desktop/window-layout.txt",
                  "/root/.config/colab-desktop/screen-geometry"):
            try: os.unlink(f)
            except FileNotFoundError: pass
            except Exception: pass
        print("[OK] صُفّرت حالة العرض القديمة محليًا مع إبقاء كل بيانات Drive ✅")
    except Exception as exc:
        _diag_event("sanitize_desktop_state",exc,"warning")


_PERSIST_VAULT_V46 = os.path.join(PERSIST_DIR, "home-vault")
_PERSIST_KEEP = max(3, min(8, _env_int("DESKTOP_PERSIST_KEEP", 5)))
# استبعادات الحالة المتطايرة لسطح المكتب (مسارات نسبية داخل /root).
_PERSIST_SAVE_EXCLUDES = tuple(x.replace("*/", "").rstrip("/*") for x in _PERSIST_EXCLUDE)


def _persist_v46():
    if not _DV_OK:
        raise RuntimeError("drive-vault engine unavailable")
    return _DV.Vault(_PERSIST_VAULT_V46, name="home-desktop", keep=_PERSIST_KEEP)


def persist_restore():
    """استعادة قبل التشغيل — مرنة ولا تمنع ظهور سطح المكتب مطلقًا.
    v46: خزنة أجيال موثّقة بدل مرآة rsync؛ الفشل يُبلَّغ ولا يقتل الإقلاع."""
    if not DRIVE_OK:
        print("[!] Drive غير متصل — لا استعادة هذه الجلسة (سطح المكتب يعمل، "
              "والحفظ سيُستأنف تلقائيًّا عند عودة Drive).")
        _restore_done.set(); _mark_browser_restore_done(); return False

    complete = False
    # 1) خزنة v46 الموثّقة.
    if _DV_OK:
        try:
            vault = _persist_v46()
            if vault.has_saved_data():
                print("[i] استعادة إعدادات سطح المكتب من جيل v46 موثّق...")
                gen = vault.restore("/root", apply_journal=False)
                if gen:
                    _RESTORE_REPORT.update(
                        desktop_ok=1, desktop_total=1, desktop_failed=[],
                        browser_ok=0, browser_total=0, browser_failed=[],
                        complete=True)
                    complete = True
                    print("[OK] استُعيدت إعدادات سطح المكتب من جيل موثّق (%d) ✅" % gen)
                else:
                    _RESTORE_REPORT["desktop_failed"] = ["home-vault"]
                    print("[!] كل أجيال سطح المكتب فشلت فحوص السلامة — تُترك للاسترداد.")
        except Exception as exc:
            _diag_event("persist_v46_restore", exc)
            _RESTORE_REPORT["desktop_failed"] = ["home-vault-error"]
    # 2) ترحيل المرآة القديمة (home_root) عند غياب خزنة v46.
    if not complete and os.path.isdir(PERSIST_HOME) and os.listdir(PERSIST_HOME):
        print("[i] ترحيل إعدادات سطح المكتب من المرآة القديمة...")
        try:
            complete = _restore_worker()
        except Exception as exc:
            _diag_event("persist_legacy_restore", exc)
    elif not complete and not _RESTORE_REPORT.get("desktop_failed"):
        # لا بيانات محفوظة بعد (أول تشغيل) — هذا ليس خطأ.
        _RESTORE_REPORT["complete"] = True
        complete = True
    _sanitize_restored_desktop_state()
    _restore_done.set(); _mark_browser_restore_done()
    if not complete:
        _restore_retry_bg()
    return complete


_PERSIST_FILE_SIG = {}

def _file_sig(path):
    try:
        st=os.stat(path); return (int(st.st_size), int(st.st_mtime_ns))
    except Exception:
        return None

def _atomic_copy_file(src, dst):
    """نسخ ذري لملف عا��ي؛ لا ي��رك ملفًا جزئيًا في Drive عند انقطاع الجلسة."""
    os.makedirs(os.path.dirname(dst), exist_ok=True)
    sig=_file_sig(src)
    if sig is not None and _PERSIST_FILE_SIG.get(src)==sig and os.path.exists(dst):
        return True
    fd, tmp = tempfile.mkstemp(prefix=".persist-", dir=os.path.dirname(dst))
    os.close(fd)
    try:
        shutil.copy2(src, tmp)
        os.replace(tmp, dst)
        if sig is not None: _PERSIST_FILE_SIG[src]=sig
        return True
    finally:
        try:
            if os.path.exists(tmp): os.unlink(tmp)
        except Exception:
            pass


def _atomic_sqlite_backup(src, dst):
    """لقطة SQLite متسقة حتى لو كان المتصفح مفتوحًا؛ ثم استبدال ذري للوجهة."""
    os.makedirs(os.path.dirname(dst), exist_ok=True)
    sig=_file_sig(src)
    if sig is not None and _PERSIST_FILE_SIG.get(src)==sig and os.path.exists(dst):
        return True
    fd, tmp = tempfile.mkstemp(prefix=".persist-sqlite-", dir=os.path.dirname(dst))
    os.close(fd)
    try:
        source = sqlite3.connect("file:%s?mode=ro" % src, uri=True, timeout=5)
        target = sqlite3.connect(tmp, timeout=5)
        try:
            source.backup(target)
        finally:
            target.close(); source.close()
        os.replace(tmp, dst)
        if sig is not None: _PERSIST_FILE_SIG[src]=sig
        return True
    except Exception:
        try:
            if os.path.exists(tmp): os.unlink(tmp)
        except Exception:
            pass
        return False


def _browser_manifest_path():
    return os.path.join(PERSIST_HOME, ".persist-browser-manifest.json")


def _load_browser_manifest():
    try:
        with open(_browser_manifest_path(), encoding="utf-8") as f:
            v = json.load(f)
        return set(x for x in v if isinstance(x, str) and not x.startswith("/") and ".." not in x.split(os.sep))
    except Exception:
        return set()


def _save_browser_manifest(items):
    dst = _browser_manifest_path()
    fd, tmp = tempfile.mkstemp(prefix=".persist-manifest-", dir=PERSIST_HOME)
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            json.dump(sorted(items), f, ensure_ascii=False)
            f.flush(); os.fsync(f.fileno())
        os.replace(tmp, dst)
    finally:
        try:
            if os.path.exists(tmp): os.unlink(tmp)
        except Exception:
            pass


_ADDITIVE_SAVE_NOTICE_SHOWN = False


def _persist_save_additive_only():
    """حفظ آمن عند عدم اكتمال الاستعادة — لا حذف أبدًا. في v46 لا يمكن أن
    يستبدل النشر جيلًا موثّقًا (النشر ذري ويبقى الأقدم محصّنًا)، لذا ننشر
    جيلًا جديدًا فوق القديم بأمان ونُبقي التنبيه."""
    global _ADDITIVE_SAVE_NOTICE_SHOWN
    if not _ADDITIVE_SAVE_NOTICE_SHOWN:
        _ADDITIVE_SAVE_NOTICE_SHOWN = True
        print("[🛡️ حماية] الاستعادة غير مكتملة — يُحفَظ جيل جديد فوق القديم "
              "المحصّن (لا حذف أبدًا) ✅")
    try:
        _persist_home_vault_save()
    except Exception as exc:
        _diag_event("additive_save", exc)


def _persist_home_vault_save():
    """ينشر جيل v46 موثّقًا لإعدادات سطح المكتب. يعيد True عند النشر."""
    if not _DV_OK:
        return False
    try:
        free = _drive_free_mb()
        if 0 <= free < _DRIVE_MIN_FREE_MB:
            print("[!] مساحة Drive أقل من حد الأمان — أُجّل حفظ سطح المكتب.")
            return False
    except Exception:
        pass
    vault = _persist_v46()
    stage = tempfile.mkdtemp(prefix="persist-save-", dir="/tmp")
    try:
        items = [rel for rel in _PERSIST_INCLUDE if os.path.exists(os.path.join("/root", rel))]
        if not items:
            return False
        n = vault.snapshot("/root", stage, items, excludes=_PERSIST_SAVE_EXCLUDES)
        if n == 0:
            return False
        owner = "colab-%d" % os.getpid()
        lock = _DV.VaultLock(_PERSIST_VAULT_V46, owner, ttl=180)
        if not lock.acquire():
            return False
        try:
            vault.sweep_stale()
            gen = vault.publish(stage, owner=owner)
        finally:
            lock.release()
        if gen:
            print("[💾 سطح المكتب] حُفظ جيل موثّق (%d) ✅" % gen)
            return True
        return False
    finally:
        shutil.rmtree(stage, ignore_errors=True)


def persist_save():
    """v46: خزنة أجيال موثّقة لسطح المكتب + Chrome الأصلي — بلا rsync --delete
    وبلا مرايا قابلة للفساد. النشر ذري ولا يستبدل جيلًا سليمًا إلا بجيل موثّق."""
    if not DRIVE_OK or not _restore_done.is_set():
        return
    if not _RESTORE_REPORT.get("complete", False):
        _persist_save_additive_only()
        return
    try:
        _original_chrome_save_transactional()
    except Exception as exc:
        _diag_event("persist_original_chrome", exc)
    try:
        _persist_home_vault_save()
    except Exception as e:
        print("[!] تعذّر حفظ بعض البيانات: %s" % e)



# ============================================================
# v45.4 — Transactional vault for the ORIGINAL Chrome profile
# ============================================================
# The old per-file mirror could combine files from different moments, restore a
# partial directory, and preserve broken extension binaries. This vault creates
# complete generations, SQLite-consistent snapshots, hashes every file, restores
# atomically, falls back to an older valid generation, and blocks the link when
# saved data exists but cannot be proven intact.
_ORIGINAL_CHROME_LOCAL = "/root/.config/google-chrome"
_ORIGINAL_CHROME_LEGACY = os.path.join(PERSIST_HOME, ".config", "google-chrome")
_ORIGINAL_CHROME_VAULT = os.path.join(PERSIST_DIR, "chrome-original-vault-v45")
_ORIGINAL_CHROME_GEN = os.path.join(_ORIGINAL_CHROME_VAULT, "generations")
_ORIGINAL_CHROME_READY_FILE = "/tmp/.original_chrome_restore_ready.json"
_ORIGINAL_CHROME_KEEP = max(3, min(8, _env_int("ORIGINAL_CHROME_ARCHIVE_KEEP", 5)))
_ORIGINAL_CHROME_LOCK = threading.RLock()
_ORIGINAL_CHROME_READY = False
_ORIGINAL_MANAGED_EXTENSION_IDS = (
    "jplgfhpmjnbigmhklmmbgecoobifkmpa",
    "ddkjiahejlhfcafbddmgiahcphecmpfh",
    "bokldcdphgknojlbfhpbbgkggjfhhaek",
)
_ORIGINAL_SKIP_DIRS = {
    "Cache", "Code Cache", "GPUCache", "GrShaderCache", "ShaderCache",
    "Media Cache", "Crashpad", "BrowserMetrics", "CacheStorage", "ScriptCache",
    "Application Cache", "DawnCache", "GraphiteDawnCache", "component_crx_cache",
}
_ORIGINAL_SQLITE_NAMES = {
    "Cookies", "Login Data", "Login Data For Account", "Web Data", "History",
    "Favicons", "Top Sites", "Affiliation Database", "Shortcuts", "Network Action Predictor",
}

def _orig_sha256(path):
    import hashlib
    h=hashlib.sha256()
    with open(path,"rb") as f:
        for b in iter(lambda:f.read(1024*1024),b""):h.update(b)
    return h.hexdigest()

def _orig_profiles(root):
    try:
        return sorted(d for d in os.listdir(root) if d=="Default" or
                      (d.startswith("Profile ") and os.path.isdir(os.path.join(root,d))))
    except Exception:return []

def _orig_cookie_rows(root):
    total=0;files=0
    for prof in _orig_profiles(root):
        for rel in ("Cookies",os.path.join("Network","Cookies")):
            p=os.path.join(root,prof,rel)
            if not os.path.isfile(p) or os.path.getsize(p)<4096:continue
            con=sqlite3.connect("file:"+p+"?mode=ro&immutable=1",uri=True,timeout=10)
            try:
                q=con.execute("pragma integrity_check").fetchone()
                if not q or q[0]!="ok":raise RuntimeError("cookies-integrity")
                total+=int(con.execute("select count(*) from cookies").fetchone()[0]);files+=1
            finally:con.close()
    return files,total

def _orig_account_hint(root):
    needles=(b'"account_info"',b'"gaia_id"',b'"user_name"',b'"email"')
    for rel in ("Local State",)+tuple(os.path.join(p,"Preferences") for p in _orig_profiles(root)):
        try:
            data=open(os.path.join(root,rel),"rb").read(8*1024*1024)
            if any(x in data for x in needles):return True
        except Exception:pass
    return False

def _orig_critical_sig(root):
    rows=[]
    rels=["Local State"]
    for prof in _orig_profiles(root):
        rels += [os.path.join(prof,x) for x in
                 ("Preferences","Secure Preferences","Cookies",os.path.join("Network","Cookies"),
                  "Login Data","Login Data For Account","Web Data","History")]
    for rel in rels:
        p=os.path.join(root,rel)
        try:
            st=os.stat(p);rows.append((rel,st.st_size,st.st_mtime_ns))
        except OSError:pass
    return tuple(rows)

def _orig_copy_snapshot(src,dst):
    """Copy a complete profile locally, then replace live SQLite copies with backup snapshots."""
    shutil.rmtree(dst,ignore_errors=True);os.makedirs(dst,exist_ok=True)
    for base,dirs,files in os.walk(src,topdown=True,followlinks=False):
        relbase=os.path.relpath(base,src)
        kept=[]
        for d in dirs:
            p=os.path.join(base,d)
            if d in _ORIGINAL_SKIP_DIRS or os.path.islink(p):continue
            # Managed executable payloads are reproducible; settings remain persisted.
            if os.path.basename(base)=="Extensions" and d in _ORIGINAL_MANAGED_EXTENSION_IDS:continue
            kept.append(d)
        dirs[:]=kept
        outbase=dst if relbase=="." else os.path.join(dst,relbase);os.makedirs(outbase,exist_ok=True)
        for name in files:
            sp=os.path.join(base,name)
            if name.startswith("Singleton") or os.path.islink(sp):continue
            dp=os.path.join(outbase,name);os.makedirs(os.path.dirname(dp),exist_ok=True)
            try:shutil.copy2(sp,dp)
            except FileNotFoundError:pass
    # SQLite online backup captures WAL content consistently while Chrome is open.
    for base,dirs,files in os.walk(src,topdown=True,followlinks=False):
        dirs[:]=[d for d in dirs if d not in _ORIGINAL_SKIP_DIRS]
        for name in files:
            sp=os.path.join(base,name)
            try:
                if name not in _ORIGINAL_SQLITE_NAMES and open(sp,"rb").read(16)!=b"SQLite format 3\x00":continue
            except Exception:continue
            rel=os.path.relpath(sp,src);dp=os.path.join(dst,rel);os.makedirs(os.path.dirname(dp),exist_ok=True)
            fd,tmp=tempfile.mkstemp(prefix=".sqlite-",dir=os.path.dirname(dp));os.close(fd)
            try:
                a=sqlite3.connect("file:"+sp+"?mode=ro",uri=True,timeout=10);b=sqlite3.connect(tmp,timeout=10)
                try:a.backup(b,pages=256,sleep=.02);b.commit();b.execute("pragma journal_mode=delete");b.commit()
                finally:b.close();a.close()
                c=sqlite3.connect(tmp);q=c.execute("pragma integrity_check").fetchone();c.close()
                if not q or q[0]!="ok":raise RuntimeError("sqlite:"+rel)
                os.replace(tmp,dp)
                for suffix in ("-wal","-shm","-journal"):
                    try:os.unlink(dp+suffix)
                    except OSError:pass
            finally:
                try:os.unlink(tmp)
                except OSError:pass

def _orig_manifest_write(root,generation):
    import hashlib
    rows=[];total=0
    for base,dirs,files in os.walk(root,topdown=True,followlinks=False):
        dirs[:]=[d for d in dirs if not os.path.islink(os.path.join(base,d))]
        for name in sorted(files):
            if name==".manifest.json" or name.startswith("Singleton"):continue
            p=os.path.join(base,name)
            if os.path.islink(p):raise RuntimeError("symlink")
            rel=os.path.relpath(p,root).replace(os.sep,"/");size=os.path.getsize(p)
            rows.append((rel,size,_orig_sha256(p)));total+=size
    rh=hashlib.sha256()
    for rel,size,h in sorted(rows):rh.update((rel+"\0"+str(size)+"\0"+h+"\n").encode())
    cookie_files,cookie_rows=_orig_cookie_rows(root)
    m={"format":451,"generation":int(generation),"created_at":time.time(),
       "created_utc":time.strftime("%Y-%m-%dT%H:%M:%SZ",time.gmtime()),
       "file_count":len(rows),"bytes":total,"tree_sha256":rh.hexdigest(),
       "cookie_files":cookie_files,"cookie_rows":cookie_rows,
       "account_hint":bool(_orig_account_hint(root))}
    fd,tmp=tempfile.mkstemp(prefix=".manifest-",dir=root)
    with os.fdopen(fd,"w",encoding="utf-8") as f:
        json.dump(m,f,separators=(",",":"));f.flush();os.fsync(f.fileno())
    os.replace(tmp,os.path.join(root,".manifest.json"));return m

def _orig_validate(root,require_manifest=True):
    import hashlib
    ls=os.path.join(root,"Local State")
    if not os.path.isfile(ls):raise RuntimeError("missing Local State")
    json.load(open(ls,encoding="utf-8"))
    profiles=_orig_profiles(root)
    if not profiles:raise RuntimeError("missing profile")
    pref_count=0
    for prof in profiles:
        for name in ("Preferences","Secure Preferences"):
            p=os.path.join(root,prof,name)
            if os.path.isfile(p):json.load(open(p,encoding="utf-8"));pref_count+=name=="Preferences"
    if not pref_count:raise RuntimeError("missing Preferences")
    for base,dirs,files in os.walk(root,topdown=True,followlinks=False):
        for name in files:
            p=os.path.join(base,name)
            try:
                if open(p,"rb").read(16)!=b"SQLite format 3\x00":continue
            except Exception:continue
            c=sqlite3.connect("file:"+p+"?mode=ro&immutable=1",uri=True,timeout=10)
            try:q=c.execute("pragma integrity_check").fetchone()
            finally:c.close()
            if not q or q[0]!="ok":raise RuntimeError("sqlite:"+os.path.relpath(p,root))
    mp=os.path.join(root,".manifest.json")
    if not os.path.isfile(mp):
        if require_manifest:raise RuntimeError("missing manifest")
        return {"cookie_files":_orig_cookie_rows(root)[0],"cookie_rows":_orig_cookie_rows(root)[1],"account_hint":_orig_account_hint(root)}
    m=json.load(open(mp,encoding="utf-8"))
    if int(m.get("format",0))!=451:raise RuntimeError("manifest format")
    rows=[];total=0
    for base,dirs,files in os.walk(root,topdown=True,followlinks=False):
        for name in sorted(files):
            if name==".manifest.json" or name.startswith("Singleton"):continue
            p=os.path.join(base,name)
            if os.path.islink(p):raise RuntimeError("symlink")
            rel=os.path.relpath(p,root).replace(os.sep,"/");size=os.path.getsize(p)
            rows.append((rel,size,_orig_sha256(p)));total+=size
    rh=hashlib.sha256()
    for rel,size,h in sorted(rows):rh.update((rel+"\0"+str(size)+"\0"+h+"\n").encode())
    if len(rows)!=int(m.get("file_count",-1)) or total!=int(m.get("bytes",-1)) or rh.hexdigest()!=m.get("tree_sha256"):
        raise RuntimeError("tree mismatch")
    cf,cr=_orig_cookie_rows(root)
    if cf!=int(m.get("cookie_files",-1)) or cr!=int(m.get("cookie_rows",-1)):raise RuntimeError("session mismatch")
    if bool(_orig_account_hint(root))!=bool(m.get("account_hint")):raise RuntimeError("account metadata mismatch")
    return m

def _orig_sanitize_extensions(root):
    for prof in _orig_profiles(root):
        p=os.path.join(root,prof)
        for eid in _ORIGINAL_MANAGED_EXTENSION_IDS:
            shutil.rmtree(os.path.join(p,"Extensions",eid),ignore_errors=True)
        for name in ("Extension State","Extension Rules","Extension Scripts"):
            q=os.path.join(p,name)
            if os.path.isdir(q):shutil.rmtree(q,ignore_errors=True)
            elif os.path.isfile(q):
                try:os.unlink(q)
                except OSError:pass

def _orig_meta_list():
    vals=[]
    if not os.path.isdir(_ORIGINAL_CHROME_GEN):return vals
    for p in Path(_ORIGINAL_CHROME_GEN).glob("*.json"):
        try:
            m=json.load(open(p));
            if int(m.get("format",0))==451:vals.append((int(m["generation"]),float(m["created_at"]),str(p),m))
        except Exception:pass
    return sorted(vals,reverse=True)

_ORIG_LEASE_TTL=max(120,min(_env_int("ORIGINAL_CHROME_LEASE_TTL",240),900))
_ORIG_LEASE_WAIT=max(5,min(_env_int("ORIGINAL_CHROME_LEASE_WAIT",25),120))

def _orig_lease_owner_read(lock):
    p=os.path.join(lock,"owner.json")
    try:
        d=json.load(open(p,encoding="utf-8"))
        if isinstance(d,dict) and isinstance(d.get("token"),str):return d
    except Exception:pass
    # v45.7 and older wrote a bare PID. Such locks had no heartbeat and were
    # left behind on notebook interruption, so they are treated as legacy.
    try:
        legacy=Path(os.path.join(lock,"owner")).read_text(encoding="utf-8").strip()
        if legacy:return {"legacy":True,"pid":legacy}
    except Exception:pass
    return {}

def _orig_lease_age(lock,owner=None):
    owner=owner or {}
    try:
        stamp=float(owner.get("heartbeat",0) or 0)
        if stamp<=0:stamp=os.path.getmtime(os.path.join(lock,"owner.json"))
    except Exception:
        try:stamp=os.path.getmtime(lock)
        except OSError:return 10**9
    return max(0.0,time.time()-stamp)

def _orig_lease_is_stale(lock):
    owner=_orig_lease_owner_read(lock);age=_orig_lease_age(lock,owner)
    if owner.get("token"):return age>_ORIG_LEASE_TTL
    # Legacy/malformed locks cannot prove liveness. Give a short grace period,
    # then recover them; this fixes crash leftovers without waiting 15 minutes.
    return age>30

def _orig_lease_write(lock,token,created):
    data={"schema":2,"token":token,"pid":os.getpid(),"host":socket.gethostname(),
          "created":created,"heartbeat":time.time()}
    fd,tmp=tempfile.mkstemp(prefix=".owner-",dir=lock)
    try:
        with os.fdopen(fd,"w",encoding="utf-8") as f:
            json.dump(data,f,separators=(",",":"));f.flush();os.fsync(f.fileno())
        os.replace(tmp,os.path.join(lock,"owner.json"));os.utime(lock,None)
    finally:
        try:os.unlink(tmp)
        except OSError:pass

def _orig_lease_heartbeat(lock,token,created,stop):
    # v46: stop.wait كان خارج try؛ استثناء واحد يوقف النبضة فتُعدّ الحيازة
    # «قديمة» ويستولي عليها طرف آخر أثناء استخدامنا لها = خطر تلف بيانات
    # ملف Chrome الأصلي. الآن الانتظار نفسه محميّ أيضًا.
    while True:
        try:
            if stop.wait(15):return
            current=_orig_lease_owner_read(lock)
            if current.get("token")!=token:return
            _orig_lease_write(lock,token,created)
        except Exception as _exc:
            try:_diag_event("orig_lease_heartbeat",_exc)
            except Exception:pass
            return

def _orig_lease_acquire(strict=False):
    lock=os.path.join(_ORIGINAL_CHROME_VAULT,".lease")
    os.makedirs(_ORIGINAL_CHROME_VAULT,exist_ok=True)
    deadline=time.monotonic()+_ORIG_LEASE_WAIT
    token=secrets.token_hex(16);created=time.time()
    while True:
        try:
            os.mkdir(lock);_orig_lease_write(lock,token,created)
            stop=threading.Event();th=threading.Thread(target=_orig_lease_heartbeat,args=(lock,token,created,stop),daemon=True);th.start()
            return {"path":lock,"token":token,"stop":stop,"thread":th}
        except FileExistsError:
            if _orig_lease_is_stale(lock):
                stale=lock+".stale-"+token[:10]
                try:
                    os.replace(lock,stale);shutil.rmtree(stale,ignore_errors=True)
                    continue
                except (FileNotFoundError,FileExistsError,OSError):pass
            if time.monotonic()>=deadline:
                if strict:raise RuntimeError("original Chrome vault is actively used by another session")
                return None
            time.sleep(2)
        except Exception:
            if strict:raise
            return None

def _orig_lease_release(lease):
    if not lease:return
    if isinstance(lease,str):
        # Compatibility only; never remove a lock unless ownership can be proven.
        return
    stop=lease.get("stop");th=lease.get("thread");lock=lease.get("path");token=lease.get("token")
    if stop:stop.set()
    if th:
        try:th.join(timeout=3)
        except Exception:pass
    try:
        if _orig_lease_owner_read(lock).get("token")==token:shutil.rmtree(lock)
    except Exception:pass

def _orig_archive_extract(meta_path,out):
    import stat,zipfile
    m=json.load(open(meta_path));name=m["archive"]
    if os.path.basename(name)!=name or not name.endswith(".zip"):raise RuntimeError("archive name")
    arc=os.path.join(os.path.dirname(meta_path),name)
    if os.path.getsize(arc)!=int(m["bytes"]) or _orig_sha256(arc)!=m["sha256"]:raise RuntimeError("archive hash")
    tmp=out+".extract";shutil.rmtree(tmp,ignore_errors=True);os.makedirs(tmp)
    try:
        with zipfile.ZipFile(arc) as z:
            total=0
            for i in z.infolist():
                p=i.filename.replace("\\","/");parts=[x for x in p.split("/") if x not in ("",".")]
                if p.startswith("/") or ".." in parts or ((i.external_attr>>16)&0o170000)==stat.S_IFLNK:raise RuntimeError("unsafe archive")
                total+=i.file_size
                if total>12*1024**3:raise RuntimeError("expanded size")
            if z.testzip():raise RuntimeError("zip crc")
            z.extractall(tmp)
        _orig_validate(tmp,True);shutil.rmtree(out,ignore_errors=True);os.replace(tmp,out)
    except Exception:
        shutil.rmtree(tmp,ignore_errors=True);raise

# ============================================================
# v46 — خزنة Chrome الأصلي على محرك drive-vault
# ============================================================
# الصيغة الجديدة: gen-*.zip + بيان sha256/bytes + مؤشر current.json ذري، مع
# نشر .partial ← تحقق مزدوج ← rename ← readback، واستعادة بالتدرّج الأحدث-
# فالأقدم. الصيغ القديمة (v45 format 451 ومرآة home_root) تُقرأ وتُرحَّل
# تلقائيًّا — لا تُفقد أي بيانات محفوظة سابقًا.
_ORIGINAL_CHROME_VAULT_V46 = os.path.join(PERSIST_DIR, "chrome-original-vault")
_ORIGINAL_SKIP_LIST = sorted(_ORIGINAL_SKIP_DIRS)


def _orig_v46():
    if not _DV_OK:
        raise RuntimeError("drive-vault engine unavailable")
    return _DV.Vault(_ORIGINAL_CHROME_VAULT_V46, name="chrome-original",
                     keep=_ORIGINAL_CHROME_KEEP)


def _orig_required_files(root):
    req = ["Local State"]
    for prof in _orig_profiles(root):
        if os.path.isfile(os.path.join(root, prof, "Preferences")):
            req.append(os.path.join(prof, "Preferences"))
            break
    return req


def _orig_write_ready(state):
    cf, cr = _orig_cookie_rows(_ORIGINAL_CHROME_LOCAL)
    data = {"ready": True, "state": state, "cookie_files": cf, "cookie_rows": cr,
            "account_hint": _orig_account_hint(_ORIGINAL_CHROME_LOCAL),
            "verified_at": time.time()}
    Path(_ORIGINAL_CHROME_READY_FILE).write_text(json.dumps(data, separators=(",", ":")))
    return data


def _original_chrome_save_transactional(force=False, raise_on_error=False):
    if not DRIVE_OK or not os.path.isfile(os.path.join(_ORIGINAL_CHROME_LOCAL, "Local State")):
        return False
    profiles = _orig_profiles(_ORIGINAL_CHROME_LOCAL)
    if not any(os.path.isfile(os.path.join(_ORIGINAL_CHROME_LOCAL, p, "Preferences")) for p in profiles):
        return False
    if not _ORIGINAL_CHROME_LOCK.acquire(blocking=False):
        return False
    stage = None
    try:
        vault = _orig_v46()
        live_hint = _orig_account_hint(_ORIGINAL_CHROME_LOCAL)
        live_cf, live_cr = _orig_cookie_rows(_ORIGINAL_CHROME_LOCAL)
        stage = tempfile.mkdtemp(prefix="original-chrome-save-", dir="/tmp")
        n = vault.snapshot(_ORIGINAL_CHROME_LOCAL, stage, ["."],
                           excludes=tuple(_ORIGINAL_SKIP_LIST))
        if n == 0:
            raise RuntimeError("nothing copied")
        if not vault.structural_check(stage, _orig_required_files(_ORIGINAL_CHROME_LOCAL)):
            raise RuntimeError("structural check failed")
        st_hint = _orig_account_hint(stage)
        _st_cf, st_cr = _orig_cookie_rows(stage)
        # حارس الجلسة: لا يُنشر جيل فقد أدلة تسجيل الدخول الحية أبدًا.
        if live_hint and not st_hint:
            raise RuntimeError("account hint lost during snapshot")
        if live_cf > 0 and live_cr > 0 and st_cr < 1:
            raise RuntimeError("login cookies lost during snapshot")
        owner = "colab-%d" % os.getpid()
        lock = _DV.VaultLock(_ORIGINAL_CHROME_VAULT_V46, owner, ttl=_ORIG_LEASE_TTL)
        if not lock.acquire():
            if raise_on_error:
                raise RuntimeError("original chrome vault locked by another writer")
            return False
        try:
            vault.sweep_stale()
            gen = vault.publish(stage, extra_meta={
                "cookie_rows": st_cr, "account_hint": bool(st_hint)}, owner=owner)
        finally:
            lock.release()
        if not gen:
            raise RuntimeError("publish failed")
        print("[💾 Chrome الأصلي] حُفظ جيل موثّق وفُحص بالكامل (%d) ✅" % gen)
        return True
    except Exception as exc:
        print("[!] فشل حفظ Chrome الأصلي دون استبدال آخر نسخة سليمة: %s" % exc)
        if raise_on_error:
            raise
        return False
    finally:
        if stage:
            shutil.rmtree(stage, ignore_errors=True)
        _ORIGINAL_CHROME_LOCK.release()


def _orig_atomic_activate(stage,state):
    _orig_validate(stage,True)
    _orig_sanitize_extensions(stage)
    try:os.unlink(os.path.join(stage,".manifest.json"))
    except OSError:pass
    parent=os.path.dirname(_ORIGINAL_CHROME_LOCAL);os.makedirs(parent,exist_ok=True)
    old=_ORIGINAL_CHROME_LOCAL+".pre-v45";shutil.rmtree(old,ignore_errors=True)
    if os.path.isdir(_ORIGINAL_CHROME_LOCAL):os.replace(_ORIGINAL_CHROME_LOCAL,old)
    try:os.replace(stage,_ORIGINAL_CHROME_LOCAL)
    except Exception:
        if os.path.isdir(old):os.replace(old,_ORIGINAL_CHROME_LOCAL)
        raise
    shutil.rmtree(old,ignore_errors=True)
    cf,cr=_orig_cookie_rows(_ORIGINAL_CHROME_LOCAL)
    data={"ready":True,"state":state,"cookie_files":cf,"cookie_rows":cr,"account_hint":_orig_account_hint(_ORIGINAL_CHROME_LOCAL),"verified_at":time.time()}
    Path(_ORIGINAL_CHROME_READY_FILE).write_text(json.dumps(data,separators=(",",":")))
    return data

def _orig_restore_immutable_generations():
    """Read only complete immutable generations; no writer lease is required.

    Publishers create archive+metadata atomically and retention keeps several
    generations. A concurrent save cannot mutate an already published archive.
    We reload once to tolerate a retention race between listing and opening.
    """
    all_errors=[];saw_saved=False
    for reload_attempt in range(2):
        metas=_orig_meta_list();saw_saved=saw_saved or bool(metas)
        for _,__,mp,m in metas:
            stage=tempfile.mkdtemp(prefix="original-chrome-restore-",dir="/tmp")
            try:
                shutil.rmtree(stage);_orig_archive_extract(mp,stage)
                data=_orig_atomic_activate(stage,"vault-generation-%s"%m.get("generation"))
                print("[OK] استُعيد Chrome الأصلي من جيل ثابت سليم دون انتظار قفل الحفظ ✅")
                return data,saw_saved,all_errors
            except Exception as exc:
                all_errors.append(os.path.basename(mp)+":"+type(exc).__name__)
                shutil.rmtree(stage,ignore_errors=True)
        if metas and reload_attempt==0:time.sleep(2)
    return None,saw_saved,all_errors

def _original_chrome_restore_gate():
    try:
        os.unlink(_ORIGINAL_CHROME_READY_FILE)
    except OSError:
        pass
    if not DRIVE_OK:
        raise RuntimeError("Drive disconnected before original Chrome restore")

    new_errors = []
    saw_new = False
    # 1) خزنة v46 (الصيغة الجديدة): استعادة بالتدرّج مع فحص sha256+CRC+بنيوي.
    if _DV_OK:
        vault = _orig_v46()
        saw_new = vault.has_saved_data()
        if saw_new:
            # لا نفترض أن ملف المستخدم يدعى Default؛ Chrome يدعم Profile 1 وما بعده.
            # التحقق اللاحق عبر _orig_validate يثبت وجود Preferences صالح في أي ملف مكتشف.
            gen = vault.restore(_ORIGINAL_CHROME_LOCAL,
                                required=["Local State"])
            if gen:
                try:
                    _orig_validate(_ORIGINAL_CHROME_LOCAL, require_manifest=False)
                    _orig_sanitize_extensions(_ORIGINAL_CHROME_LOCAL)
                    data = _orig_write_ready("vault-v46-generation-%s" % gen)
                    print("[OK] استُعيد Chrome الأصلي من جيل v46 موثّق ✅")
                    return data
                except Exception as exc:
                    new_errors.append("post-activate:%s" % type(exc).__name__)
            else:
                new_errors.append("all v46 generations rejected")

    # 2) مسار الترحيل: أجيال v45 الثابتة (format 451) تُقرأ بالأدوات القديمة
    #    ثم تُعاد كتابتها فورًا بصيغة v46 — بيانات الجلسات السابقة لا تُفقد.
    data, saw_legacy, errors = _orig_restore_immutable_generations()
    if data:
        try:
            _original_chrome_save_transactional(force=True)
            print("[OK] رُحّلت أجيال Chrome الأصلية v45 إلى خزنة v46 الموثّقة ✅")
        except Exception as exc:
            _diag_event("original_chrome_v46_migration", exc)
        return data

    # 3) المرآة الأقدم (home_root/.config/google-chrome) — آخر مصدر للاسترداد.
    legacy_evidence = (os.path.isfile(os.path.join(_ORIGINAL_CHROME_LEGACY, "Local State")) or
                       bool(_orig_profiles(_ORIGINAL_CHROME_LEGACY)))
    if legacy_evidence:
        stage = tempfile.mkdtemp(prefix="original-chrome-legacy-", dir="/tmp")
        try:
            _orig_copy_snapshot(_ORIGINAL_CHROME_LEGACY, stage)
            m = _orig_validate(stage, require_manifest=False)
            if int(m.get("cookie_files", 0)) > 0 and int(m.get("cookie_rows", 0)) < 1:
                raise RuntimeError("legacy session empty")
            data = _orig_atomic_activate(stage, "legacy-migrated")
        except Exception:
            shutil.rmtree(stage, ignore_errors=True)
            raise
        if not _original_chrome_save_transactional(force=True, raise_on_error=True):
            raise RuntimeError("legacy migration publish failed")
        print("[OK] رُحّلت بيانات Chrome الأصلية القديمة إلى خزنة v46 ✅")
        return data

    # وُجدت بيانات محفوظة لكن كل مصادرها فشلت فحوص السلامة — نرفض الملف الفارغ.
    if saw_new or saw_legacy:
        raise RuntimeError("all original Chrome generations rejected: " +
                           ",".join((new_errors + errors)[:8]))

    os.makedirs(_ORIGINAL_CHROME_LOCAL, exist_ok=True)
    data = {"ready": True, "state": "new-no-saved-original-profile", "cookie_files": 0,
            "cookie_rows": 0, "account_hint": False, "verified_at": time.time()}
    Path(_ORIGINAL_CHROME_READY_FILE).write_text(json.dumps(data, separators=(",", ":")))
    print("[i] لا توجد نسخة سابقة لملف Chrome الأصلي؛ لم تُستبدل أي بيانات.")
    return data

# Original Chrome recovery can read a large Drive archive. Run it in the
# background in fast mode; Chrome is not started until this verifier publishes
# its marker, so no empty profile can overwrite a saved one.
_ORIGINAL_CHROME_RESTORE_EVENT=threading.Event()
_ORIGINAL_CHROME_RESTORE_STATUS={"ready":False,"state":"pending-background-restore"}
_ORIGINAL_CHROME_READY=False

def _run_original_chrome_restore():
    global _ORIGINAL_CHROME_RESTORE_STATUS, _ORIGINAL_CHROME_READY
    try:
        _ORIGINAL_CHROME_RESTORE_STATUS=_original_chrome_restore_gate()
    except Exception as _occ_err:
        _diag_event("original_chrome_restore_gate", _occ_err)
        _ORIGINAL_CHROME_RESTORE_STATUS={"ready":False,"state":"restore-failed",
                                         "error":str(_occ_err)}
        print("[!] تعذّرت استعادة ملف Chrome الأصلي: %s" % _occ_err)
        print("[i] ستبقى بيانات Drive دون حذف؛ لن يبدأ Chrome بملف غير متحقق.")
    finally:
        _ORIGINAL_CHROME_READY=bool(_ORIGINAL_CHROME_RESTORE_STATUS.get("ready") and os.path.isfile(_ORIGINAL_CHROME_READY_FILE))
        _ORIGINAL_CHROME_RESTORE_EVENT.set()

if FAST_INTERACTIVE_BOOT:
    threading.Thread(target=_run_original_chrome_restore,
                     name="original_chrome_restore", daemon=True).start()
    print("[⚡] استعادة Chrome الأصلية تعمل بالخلفية؛ رابط سطح المكتب لن ينتظر Drive.", flush=True)
else:
    _run_original_chrome_restore()


# استعادة فورية قبل تشغيل سطح المكتب (كي تظهر بياناتك من اللحظة الأولى).
# v46: تُنفَّذ بـ«ميزانية زمنية» — إن كان Drive بطيئًا جدًّا لا نُجمّد الإقلاع؛
# نُكمل ونُتابع الاستعادة في الخلفية. هذا يحسم شكوى «بطء عند الإقلاع» لأن
# استعادة FUSE كانت تنفَّذ تسلسليًّا وحاجزةً قبل تشغيل سطح المكتب.
_PERSIST_RESTORE_BUDGET_SECONDS = (_FAST_RESTORE_FOREGROUND_SECONDS if FAST_INTERACTIVE_BOOT else 150)


def _persist_restore_with_budget():
    """يمنح الاستعادة مهلة محدّدة؛ ما تبقّى يُكمل في الخلفية دون حجب الإقلاع."""
    result = {"done": False}

    def _run_restore():
        # v46: كانت العلامتان تُضبطان داخل معالج الاستثناء فقط وبلا حماية؛
        # لو رفع _mark_browser_restore_done استثناءً بدوره لبقيت بوّابات
        # الجاهزية تنتظر إلى الأبد. الآن الضبط في finally ومحميّ فرديًّا،
        # فالإقلاع يتقدّم دائمًا حتى لو تعذّرت الاستعادة تمامًا.
        try:
            result["done"] = bool(persist_restore())
        except Exception as exc:      # حماية مزدوجة — لا يجوز أن يقتل الإقلاع
            try:
                _diag_event("persist_restore_thread", exc)
                print("[!] تعذّرت الاستعادة (%s) — سطح المكتب يعمل ✅" % exc)
            except Exception:
                pass
        finally:
            try: _restore_done.set()
            except Exception: pass
            try: _mark_browser_restore_done()
            except Exception as _mexc: _diag_event("mark_browser_restore_done", _mexc)

    _t = threading.Thread(target=_run_restore, name="persist_restore", daemon=True)
    _t.start()
    _t.join(timeout=_PERSIST_RESTORE_BUDGET_SECONDS)
    if _t.is_alive():
        print("[i] الاستعادة تستغرق أطول من %dث (Drive بطيء) — نُكمل الإقلاع الآن ✅ "
              "وستستمر الاستعادة في الخلفية دون تعطيل سطح المكتب."
              % _PERSIST_RESTORE_BUDGET_SECONDS)
        # لا نعلن اكتمال الاستعادة قبل اكتمالها فعليًا. بهذه الطريقة لا يبدأ
        # مشغّل Chrome ملفًا جديدًا فوق بيانات جلسة لم تصل بعد من Drive.
        # الخيط نفسه سيضبط العلامات في finally عند نهاية الاستعادة.


_persist_restore_with_budget()
# v81: ملف Antigravity المحلي يُستعاد في الخلفية أيضًا (كان يحجز حتى 210ث).
