# اختصارات ثابتة على سطح المكتب؛ ستعمل فور اكتمال تثبيت الحزم في الخلفية.
def _write_dev_launchers():
    if CHROME_ONLY:
        for fn in ("01-Workspace.desktop", "02-Geany.desktop", "03-Terminal.desktop",
                   "04-PostgreSQL-Terminal.desktop", "05-Remmina.desktop"):
            try: os.unlink(os.path.join("/root/Desktop", fn))
            except Exception: pass
        return
    launchers = {
        "01-Workspace.desktop": ("🗂️ مساحة العمل الدائمة", "thunar /root/Workspace", "folder"),
        "02-Geany.desktop": ("💻 Geany محرر البرمجة", "geany", "geany"),
        "03-Terminal.desktop": ("⌨️ Terminal", "xfce4-terminal", "utilities-terminal"),
        "04-PostgreSQL-Terminal.desktop": ("🐘 PostgreSQL", "xfce4-terminal --command='bash -lc \"sudo -u postgres psql; exec bash\"'", "database"),
        "05-Remmina.desktop": ("🌐 Remote Desktop", "remmina", "remmina"),
    }
    desk="/root/Desktop"
    os.makedirs(desk, exist_ok=True)
    for fn,(name,cmd,icon) in launchers.items():
        try:
            dst=os.path.join(desk,fn)
            text="[Desktop Entry]\nVersion=1.0\nType=Application\nName=%s\nExec=%s\nIcon=%s\nTerminal=false\nCategories=Development;Utility;\n" % (name,cmd,icon)
            with open(dst,"w",encoding="utf-8") as f: f.write(text)
            os.chmod(dst,0o755)
        except Exception: pass
_write_dev_launchers()

