# ============================================================
# >>> نظام دوام التطبيقات الكامل (مزروع من الملف 59 + تحسين إلغاء التثبيت) <<<
#   • myapt install: يثبّت + يسجّل السم في Drive + يحفظ حزم .deb في Drive.
#   • myapt remove : يلغي التثبيت + يحذف الاسم من السجلّ + يحذف حزمته من Drive.
#   • دالة apt في .bashrc: أي «apt install» عادي يُسجَّل تلقائيًّا.
#   • عند الإقلاع: يُعاد تثبيت كل الحزم المسّلة تلقائيًّا (من كاش Drive أولًا).
#   • deb-install: تثبيت أي ملف .deb منزَّل من المتصفّح بنقرة (مع الحفظ في Drive).
# ============================================================
# حزمة أدوات التطوير الأساسة: تُسجَّل مرة واحدة في Drive ثم تُثبّت في الخلفية.
# كلها من مستودعات Ubuntu القياسية؛ لذلك لا نضيف PPAs أو Snap ولا نؤخّر إقلاع Colab.
_DEV_DESKTOP_PACKAGES = []
_PKG_LIST_REL = "installed_packages.txt"


def _ensure_list_file(path):
    """يضمن أن ملف قائمة الحزم ملفّ نصّي (لا مجلّدًا خاطئًا)."""
    try:
        if os.path.isdir(path):
            import shutil as _sh
            _sh.rmtree(path, ignore_errors=True)
        os.makedirs(os.path.dirname(path), exist_ok=True)
        if not os.path.exists(path):
            open(path, "a").close()
    except Exception:
        pass


_PKG_LIST_PATH = os.path.join(PERSIST_HOME, _PKG_LIST_REL) if DRIVE_OK \
    else os.path.join("/root", _PKG_LIST_REL)
_ensure_list_file(_PKG_LIST_PATH)
_ensure_list_file(os.path.join("/root", _PKG_LIST_REL))
if CHROME_ONLY:
    for _old_list in (_PKG_LIST_PATH, os.path.join("/root", _PKG_LIST_REL)):
        try: open(_old_list, "w").close()
        except Exception: pass

# manifest صغير ومقروء بمسار ثابت يطلبه المستخدم: $PERSISTDIR/packages-manifest.txt
# يُكتب سطر لكل حزمة بعد ناح تثبيتها فعليًّا فقط (اسم<TAB>تاريخ UTC).
PKG_MANIFEST_TXT = os.path.join(PERSIST_DIR, "packages-manifest.txt")
try:
    _ensure_list_file(PKG_MANIFEST_TXT)
except Exception:
    pass

# لا نُشغّل apt هنا: نسجل الحزمة فقط، ثم يستدعي الخيط الخلفي الموجود أصلًا
# reinstall_saved_pkgs بعد فتح سطح المكتب؛ لذا لا يتأخر رابط Colab أو XFCE.
def _seed_dev_packages():
    for path in (_PKG_LIST_PATH, os.path.join("/root", _PKG_LIST_REL)):
        try:
            existing = set()
            with open(path, encoding="utf-8") as f:
                existing = {x.strip() for x in f if x.strip()}
            missing = [x for x in _DEV_DESKTOP_PACKAGES if x not in existing]
            if missing:
                with open(path, "a", encoding="utf-8") as f:
                    f.write("\n".join(missing) + "\n")
        except Exception:
            pass
_seed_dev_packages()


def _saved_pkg_list():
    out, seen = [], set()
    for path in (_PKG_LIST_PATH, os.path.join("/root", _PKG_LIST_REL)):
        try:
            if os.path.isfile(path):
                with open(path) as f:
                    for line in f:
                        nm = line.strip()
                        if nm and nm not in seen:
                            seen.add(nm); out.append(nm)
        except Exception:
            pass
    return out


def reinstall_saved_pkgs():
    """Chrome-only mode never reinstalls previously recorded development apps."""
    if CHROME_ONLY:
        return
    pkgs = _saved_pkg_list()
    if not pkgs:
        return
    todo = [p for p in pkgs
            if getattr(run("dpkg -s %s >/dev/null 2>&1" % p), "returncode", 1) != 0]
    if not todo:
        print("[📦 حزم] كل تطبيقاتك المسجّلة مثبّتة أصلًا ✅")
        return
    print("[📦 حزم] إعادة تثبيت تطبيقاتك المحفوظة (%d): %s ..."
          % (len(todo), ", ".join(todo)))
    # إصلاح نظام الحزم أولًا (أقفال/dpkg مقطوع/اعتماديات) ثم استعادة الكاش
    _apt_heal()
    # استعادة كاش .deb من Drive أولًا (تثبيت محلّي بلا تنزيل إن أمكن)
    run("cp -f '%s'/*.deb /var/cache/apt/archives/ 2>/dev/null" % PKG_CACHE,
        timeout=300)
    _apt_update()
    ok = 0
    for p in todo:
        r = run("sudo DEBIAN_FRONTEND=noninteractive apt-get install -y -qq "
                "%s > /dev/null 2>&1" % p, timeout=300)
        if getattr(r, "returncode", 1) == 0:
            ok += 1
    # حفظ أي حزم ديدة نزلت إلى كاش Drive
    run("rsync -a --ignore-existing /var/cache/apt/archives/*.deb '%s/' "
        "2>/dev/null" % PKG_CACHE, timeout=300)
    run("refresh-app-menu >/dev/null 2>&1 || true")
    print("[📦 حزم] أُعيد تثبيت %d/%d من تطبيقاتك المحفوظة ✅" % (ok, len(todo)))


# --- سكربت refresh-app-menu: يُظهر التطبيق فورًا في القائم وسطح المكتب ---
_refresh_menu_sh = r"""#!/bin/bash
export DISPLAY="${DISPLAY:-%s}"
update-desktop-database /usr/share/applications        >/dev/null 2>&1 || true
update-desktop-database /root/.local/share/applications >/dev/null 2>&1 || true
command -v update-menus >/dev/null 2>&1 && update-menus >/dev/null 2>&1 || true
rm -f /root/.cache/garcon/*.menu 2>/dev/null || true
rm -rf /root/.cache/menus       2>/dev/null || true
xfdesktop --reload >/dev/null 2>&1 || true
echo "🔄 حُدِّثت قائمة التطبيقات وأيقونات سطح المكتب."
""" % DISPLAY_NUM
with open("/usr/local/bin/refresh-app-menu", "w") as f:
    f.write(_refresh_menu_sh)
run("chmod +x /usr/local/bin/refresh-app-menu")

# --- سكربت myapt: تثبيت/إزالة مع الدوام الكامل عبر Drive ---
myapt_sh = r"""#!/bin/bash
# myapt: طبقة اختيارية لحفظ أسماء الحزم المطلوبة، ن دون اعتراض APT أو تغيير أقفاله.
set -u
export DEBIAN_FRONTEND=noninteractive
PKGFILE="__PKGFILE__"
DRIVE_LIST="__DRIVE_LIST__"
MANIFEST_TXT="__MANIFEST_TXT__"
# يُكتب اسم الحزمة + تاريخ UTC في manifest المقروء (بعد نجاح التثبيت فقط).
manifest_add() {
  [ -n "$MANIFEST_TXT" ] || return 0
  mkdir -p "$(dirname "$MANIFEST_TXT")" 2>/dev/null; touch "$MANIFEST_TXT" 2>/dev/null
  grep -qF -- "	$1	" "$MANIFEST_TXT" 2>/dev/null && return 0
  grep -q "	$1	" "$MANIFEST_TXT" 2>/dev/null || \
    printf '%s\t%s\n' "$(date -u +%Y-%m-%dT%H:%M:%SZ)" "$1" >> "$MANIFEST_TXT" 2>/dev/null
}
record() {
  for f in "$PKGFILE" "$DRIVE_LIST"; do
    [ -n "$f" ] || continue
    mkdir -p "$(dirname "$f")"; touch "$f"
    grep -qxF -- "$1" "$f" 2>/dev/null || printf '%s\n' "$1" >> "$f"
  done
  manifest_add "$1"
}
unrecord() {
  for f in "$PKGFILE" "$DRIVE_LIST"; do
    [ -f "$f" ] && sed -i "\|^$1\$|d" "$f"
  done
}
case "${1:-}" in
  record) [ $# -eq 2 ] && record "$2" ;;
  install)
    shift
    apt-get update --allow-releaseinfo-change
    apt-get install -y "$@"
    for p in "$@"; do case "$p" in -*) ;; *) dpkg-query -W -f='${db:Status-Status}' "$p" 2>/dev/null | grep -qx installed && record "$p";; esac; done
    refresh-app-menu >/dev/null 2>&1 || true ;;
  remove|purge)
    cmd="$1"; shift
    apt-get "$cmd" --purge -y "$@"
    for p in "$@"; do case "$p" in -*) ;; *) dpkg-query -W -f='${db:Status-Status}' "$p" 2>/dev/null | grep -qx installed || unrecord "$p";; esac; done
    refresh-app-menu >/dev/null 2>&1 || true ;;
  *) echo "Usage: myapt {install|remove|purge|record} package..." >&2; exit 2 ;;
esac
"""
myapt_sh = (myapt_sh
            .replace("__PKGFILE__", os.path.join("/root", _PKG_LIST_REL))
            .replace("__DRIVE_LIST__", _PKG_LIST_PATH)
            .replace("__MANIFEST_TXT__", PKG_MANIFEST_TXT)
            .replace("__DEB_CACHE__", PKG_CACHE))
with open("/usr/local/bin/myapt", "w") as f:
    f.write(myapt_sh)
run("chmod +x /usr/local/bin/myapt")

# لا نعترض apt أو apt-get في .bashrc؛ يجب أن تبقى أوامر مدير الحزم أصلية.
# ننظف hook قديمًا أضافته نسخ سابقة من السكربت، مع ا��إبقاء على بقية .bashrc.
try:
    _bashrc = "/root/.bashrc"
    if os.path.exists(_bashrc):
        _old = open(_bashrc).read()
        _old = re.sub(r"\n?# === دوام التطبيقات المثبّتة.*?apt remove <الحزمة>\"\n", "\n", _old, flags=re.S)
        with open(_bashrc, "w") as f:
            f.write(_old)
except Exception:
    pass

# --- deb-install: تثبيت ي ملف .deb منزَّل من المتصفّح بنقرة مزدوجة ---
deb_install_sh = r"""#!/bin/bash
# deb-install : تثبيت حزمة .deb محلّية (منزَّلة من المتصفّح) + دوام في Drive
export DEBIAN_FRONTEND=noninteractive
DEB="$1"; DEB_CACHE="__DEB_CACHE__"
[ -z "$DEB" ] && { zenity --error --text="لم يُحدَّد ملف .deb" 2>/dev/null; exit 1; }
case "$DEB" in file://*) DEB="${DEB#file://}";; esac
[ ! -f "$DEB" ] && { zenity --error --text="الملف غير موجود:\n$DEB" 2>/dev/null; exit 1; }
PKG=$(dpkg-deb -f "$DEB" Package 2>/dev/null)
LOG=/tmp/deb-install.log
run_install() {
  echo "⏳ تثبيت $PKG من $DEB ..."
  # APT يثبت ملف .deb المحلي ويحل الاعتماديات في عملية واحدة.
  apt-get install -y "$DEB" >>"$LOG" 2>&1
  if dpkg -s "$PKG" >/dev/null 2>&1; then
    # حفظ نسخة الحزمة في Drive + تسجيلها للدوام (myapt يعيد تثبيتها من الكاش)
    [ -d "$DEB_CACHE" ] && cp -f "$DEB" "$DEB_CACHE/${PKG}_local.deb" 2>/dev/null
    for f in "__PKGFILE__" "__DRIVE_LIST__"; do
      mkdir -p "$(dirname "$f")" 2>/dev/null; touch "$f" 2>/dev/null
      grep -qxF -- "$PKG" "$f" 2>/dev/null || echo "$PKG" >> "$f" 2>/dev/null
    done
    # manifest المقروء (بعد نجاح التثبيت فقط)
    MANIFEST_TXT="__MANIFEST_TXT__"
    if [ -n "$MANIFEST_TXT" ]; then
      mkdir -p "$(dirname "$MANIFEST_TXT")" 2>/dev/null; touch "$MANIFEST_TXT" 2>/dev/null
      grep -q "	$PKG	" "$MANIFEST_TXT" 2>/dev/null || \
        printf '%s\t%s\n' "$(date -u +%Y-%m-%dT%H:%M:%SZ)" "$PKG" >> "$MANIFEST_TXT" 2>/dev/null
    fi
    refresh-app-menu 2>/dev/null || true
    echo "✅ تم تثبيت $PKG بنجاح — ستجده في قائمة التطبيقات، وسيبقى بعد إعادة التشغيل."
  else
    echo "❌ فشل التثبيت — راجع $LOG"
  fi
}
if command -v xfce4-terminal >/dev/null 2>&1; then
  export -f run_install; export DEB PKG LOG DEB_CACHE
  xfce4-terminal --title="تثبيت $PKG" --hold -e "bash -c run_install" 2>/dev/null &
else
  run_install
fi
"""
deb_install_sh = (deb_install_sh
                  .replace("__DEB_CACHE__", PKG_CACHE)
                  .replace("__PKGFILE__", os.path.join("/root", _PKG_LIST_REL))
                  .replace("__MANIFEST_TXT__", PKG_MANIFEST_TXT)
                  .replace("__DRIVE_LIST__", _PKG_LIST_PATH))
with open("/usr/local/bin/deb-install", "w") as f:
    f.write(deb_install_sh)
run("chmod +x /usr/local/bin/deb-install")
# ربط نوع ملف .deb بالثبّت (نقرة مزدوجة في Thunar أو من تنزيلات المتصفّح)
_deb_desktop = """[Desktop Entry]
Type=Application
Name=Deb Package Installer
Name[ar]=مثبّت حزم .deb
Exec=/usr/local/bin/deb-install %f
Terminal=false
NoDisplay=true
MimeType=application/vnd.debian.binary-package;
"""
os.makedirs("/usr/share/applications", exist_ok=True)
with open("/usr/share/applications/deb-install.desktop", "w") as f:
    f.write(_deb_desktop)
run("xdg-mime default deb-install.desktop "
    "application/vnd.debian.binary-package 2>/dev/null || true")
run("update-desktop-database /usr/share/applications 2>/dev/null || true")

# ============================================================
# *** توافق «كالنظام المحلي»: تثبيت التطبيقات بلا أي أخطاء ***
# ============================================================
# بيئة Colab حاوية بلا systemd (PID 1 ليس systemd). سكربتات ما بعد التثبيت
# (postinst) لكثير من الحزم تستدعي systemctl/service فتفشل بأخطاء مزعجة أو
# توقف dpkg في منتصف التثبيت («dpkg was interrupted»). الطبقات العشر التالية
# تجعل apt/dpkg والتثبيت من المتصفّح يتصرّفان تمامًا كجهاز لينكس محلي:

# (1) policy-rc.d — المعيار الرسمي للحاويات (نفس ما تفعله صور Docker/Ubuntu
#     الرسمية): يمنع محاولات تشغيل الخدمات أثناء التثبيت بأدب (exit 101)
#     فتنجح postinst دائمًا بدل الفشل عند «Failed to start ...».
with open("/usr/sbin/policy-rc.d", "w") as f:
    f.write("#!/bin/sh\nexit 101\n")
run("chmod +x /usr/sbin/policy-rc.d")

# (2) لا نستبدل systemctl. policy-rc.d أعلاه هو الأسلوب القياسي لمنع تشغيل
# الخدمات ��ي الحاوية، ويُبقي ��دوات النظام وpostinst في سلوكها المتوقع.
# إن كانت نسخة سابقة من هذا السكربت قد عملت تحويلة systemctl، أعد الأصل بأمان.
if os.path.exists("/usr/bin/systemctl.distrib"):
    run("rm -f /usr/bin/systemctl && dpkg-divert --local --rename --remove /usr/bin/systemctl "
        ">/dev/null 2>&1 || true")

# (3) apt.conf عالمي — يسري على كل أدوات ��لتثبيت (apt/apt-get/gdebi/synaptic):
#     • لا أسئلة تفاعلية توقف التثبيت (confdef/confold لأسئلة ملفات الإعداد).
#     • انتظار قفل dpkg حتى 5 دقائق بدل خطأ «could not get lock» الشهير
#       (يمنع تصادم تثبيت المستخدم مع خيط إعادة التثبي�� الخلفي).
#     • إعادة محاولة التنزيل 3 مرات (شبكة متقلّبة ≠ فشل تثبيت).
with open("/etc/apt/apt.conf.d/90local-like", "w") as f:
    f.write('APT::Get::Assume-Yes "true";\n'
            'DPkg::Lock::Timeout "300";\n'
            'Acquire::Retries "3";\n'
            'Dpkg::Options { "--force-confdef"; "--force-confold"; };\n')
os.environ["DEBIAN_FRONTEND"] = "noninteractive"

# (4) debconf صامت دائمًا — يمنع الشاشات ال��رقاء التفاعلية (مثل سؤال منطقة
#     tzdata أو ترخيص خطوط MS) التي تعلّق التثبيت في الطرفية.
run("bash -c \"echo 'debconf debconf/frontend select Noninteractive' "
    "| sudo debconf-set-selections\" 2>/dev/null || true")

# (5) machine-id — بعض الحزم (dbus/جنوم) تفشل postinst بدونه ي لحاويات.
if not os.path.exists("/etc/machine-id") or \
        os.path.getsize("/etc/machine-id") == 0:
    run("bash -c 'dbus-uuidgen > /etc/machine-id' 2>/dev/null || "
        "systemd-machine-id-setup 2>/dev/null || true")

# (6) أدات التثبيت الرسومية كالنظام المحلي»:
#     • gdebi        : مثبّت .deb رسومي (نافذة تعرض الاعتماديات وزر تثبيت).
#     • synaptic     : مدير حزم رسومي كامل (بحث/تثبيت/إزالة بالنقر).
#     • libfuse2     : تشغيل تطبيقات AppImage المنزَّلة من المواقع.
#     • xarchiver    : فكّ ضغط tar.gz/zip المنزَّلة من المتصفّح بنقرة يمنى.
#     • software-properties-common: أمر add-apt-repository (إضافة PPA).
# >>> ULTRA-BOOT: أدوات التثبيت الرسومية + المستودعات تعمل في خيط خلفي —
#     لا تؤخّر ظهور سطح المكتب ثانية واحدة (كانت تستهلك 1-3 دقائق قبل
#     ظهور الرابط!). اللقطة الدائمة تحفظ ناتجها فلا تتكرّر في الإقلاعات. <<<
def _install_gui_tools_bg():
    try:
        if not os.path.exists("/usr/bin/gdebi"):
            _tools = ("software-properties-common gdebi synaptic "
                      "libfuse2 xarchiver")
            if run("sudo apt-get install -y -qq %s > /dev/null 2>&1" % _tools,
                   timeout=420).returncode != 0:
                run("sudo apt-get update -qq", timeout=180)
                run("sudo apt-get install -y -qq %s > /dev/null 2>&1" % _tools,
                    timeout=420)
        # (7) تفعيل مستودعات universe/multiverse/restricted — كي تتوفّر آلاف
        #     الحزم (vlc, gimp, obs-studio...) كتثبيت Ubuntu المكتبي.
        #     حارس: مرّة وحدة فقط (add-apt-repository يشغّل update داخليًّا).
        _repo_marker = "/var/lib/.repos-enabled"
        if not os.path.exists(_repo_marker):
            _srcs = run("grep -rhs '^deb ' /etc/apt/sources.list "
                        "/etc/apt/sources.list.d/ 2>/dev/null").stdout
            _missing = [c for c in ("universe", "multiverse", "restricted")
                        if c not in _srcs]
            if _missing:
                run("; ".join("sudo add-apt-repository -y %s > /dev/null 2>&1" % c
                              for c in _missing), timeout=300)
            run("touch %s" % _repo_marker)
        print("[OK] أدوات التثبيت الرسومية + المستودعات جاهزة (خلفية) ✅")
    except Exception:
        pass
if not CHROME_ONLY and not STABILITY_FIRST:
    threading.Thread(target=_install_gui_tools_bg, name="gui_tools_bg",
                     daemon=True).start()

# (8) تحديث قائمة التطبيقات تلقائيًّا بعد أي تثبيت — مهما كانت الأداة
#     (apt/gdebi/synaptic/dpkg): يظهر التطبيق فورًا في قائمة XFCE وسطح
#     المكتب بلا إعادة تشغيل، تمامًا كالأنظمة المحلية.
with open("/etc/apt/apt.conf.d/91refresh-menu", "w") as f:
    f.write('DPkg::Post-Invoke { '
            '"update-desktop-database /usr/share/applications '
            '2>/dev/null || true; '
            'gtk-update-icon-cache -f /usr/share/icons/hicolor '
            '2>/dev/null || true"; };\n')

# V20: مستخرج أرشيفات آمن مركزي — يمنع traversal والروابط الخارجة والأجهزة.
_SAFE_ARCHIVE_EXTRACT_PY = r'''#!/usr/bin/env python3
import os,sys,zipfile,tarfile,stat
if len(sys.argv)!=3: raise SystemExit(64)
src,dst=sys.argv[1:];root=os.path.realpath(dst);os.makedirs(root,exist_ok=True)
MAX_ENTRIES=500000;MAX_BYTES=20*1024**3

def target_ok(name):
 name=name.replace('\\','/');parts=[p for p in name.split('/') if p not in ('','.')]
 if name.startswith('/') or '..' in parts or '\x00' in name:return False
 out=os.path.realpath(os.path.join(root,*parts))
 return out==root or out.startswith(root+os.sep)

def safe_link(name,link):
 if not target_ok(name) or os.path.isabs(link):return False
 base=os.path.dirname(name.replace('\\','/'));resolved=os.path.normpath(os.path.join(base,link)).replace('\\','/')
 return target_ok(resolved)

if zipfile.is_zipfile(src):
 with zipfile.ZipFile(src) as z:
  infos=z.infolist()
  if len(infos)>MAX_ENTRIES:raise RuntimeError('too many entries')
  total=0
  for i in infos:
   if not target_ok(i.filename):raise RuntimeError('unsafe zip path')
   mode=(i.external_attr>>16)&0o170000
   if mode in (stat.S_IFLNK,stat.S_IFBLK,stat.S_IFCHR,stat.S_IFIFO,stat.S_IFSOCK):raise RuntimeError('unsafe zip type')
   total+=i.file_size
   if total>MAX_BYTES:raise RuntimeError('expanded size limit')
  if z.testzip():raise RuntimeError('zip crc')
  z.extractall(root)
elif tarfile.is_tarfile(src):
 with tarfile.open(src,'r:*') as t:
  members=t.getmembers()
  if len(members)>MAX_ENTRIES:raise RuntimeError('too many entries')
  total=0
  for m in members:
   if not target_ok(m.name) or m.isdev() or m.isfifo():raise RuntimeError('unsafe tar member')
   if (m.issym() or m.islnk()) and not safe_link(m.name,m.linkname):raise RuntimeError('unsafe tar link')
   total+=max(0,m.size)
   if total>MAX_BYTES:raise RuntimeError('expanded size limit')
  try:t.extractall(root,members=members,filter='data')
  except TypeError:t.extractall(root,members=members)
else:raise RuntimeError('unsupported or invalid archive')
print('SAFE_EXTRACT_OK')
'''
Path('/usr/local/bin/safe-archive-extract').write_text(_SAFE_ARCHIVE_EXTRACT_PY,encoding='utf-8')
os.chmod('/usr/local/bin/safe-archive-extract',0o755)

# (8.5) مُثب��ت موحّد للتنزيلات من الم��صفح: يفتح Downloads ويختار المعالج الصحيح.
# لا ينقل ملفات التنزيل إلى Drive؛ يحفظ فقط سجل الحزم القابلة لإعادة التثبيت.
_download_installer_sh = r"""#!/bin/bash
set -u
F="${1:-}"
if [ -z "$F" ]; then
  F=$(zenity --file-selection --title="اختر ملفًا من Downloads لتثبيته أو فتحه" \
      --filename="$HOME/Downloads/" 2>/dev/null) || exit 0
fi
case "$F" in file://*) F="${F#file://}";; esac
[ -f "$F" ] || { zenity --error --text="الملف غير موجود" 2>/dev/null; exit 1; }
case "${F,,}" in
  *.deb) exec /usr/local/bin/deb-install "$F" ;;
  *.appimage) exec /usr/local/bin/appimage-run "$F" ;;
  *.zip|*.tar.gz|*.tgz|*.tar.xz|*.txz|*.tar.bz2|*.tar)
    D="$HOME/Downloads/extracted-$(basename "$F" | sed 's/[^A-Za-z0-9._-]/-/g')-$(date +%s)"
    mkdir -p "$D" || exit 1
    if ! /usr/local/bin/safe-archive-extract "$F" "$D"; then
      rmdir "$D" 2>/dev/null || true
      zenity --error --title="أرشيف مرفوض" --text="الأرشيف تالف أو يحوي مسارًا/رابطًا غير آمن. لم يُكتب شيء خارج مجلد الاستخراج." 2>/dev/null
      exit 3
    fi
    zenity --info --title="تم فك الضغط بأمان" --text="فُك الملف بعد فحص المسارات وCRC في:\n$D\n\nاقرأ README/INSTALL قبل تشغيل أي ملف." 2>/dev/null
    thunar "$D" >/dev/null 2>&1 &
    ;;
  *.flatpakref|*.flatpakrepo) exec /usr/local/bin/flatpakref-handler "$F" ;;
  *.snap) zenity --warning --text="حزم Snap لا تعمل بصورة موثوقة في Colab. ابحث عن .deb أو AppImage أو حزمة apt." 2>/dev/null ;;
  *.exe|*.msi|*.dmg|*.pkg) zenity --error --text="هذا ليس تطبيق Linux قابلًا للتثبيت هنا. نزّل إصدار Linux (.deb أو AppImage)." 2>/dev/null ;;
  *) zenity --info --text="نوع الملف غير معروف للتثبيت التلقائي. الملف: $F" 2>/dev/null ;;
esac
"""
with open("/usr/local/bin/install-download", "w") as f:
    f.write(_download_installer_sh)
run("chmod +x /usr/local/bin/install-download")

# ============================================================
# v75) مُثبّت برامج لينكس ��لشامل (تنزيل من المواقع عبر Chrome → تشغيل فوري)
#
# الفلسفة: أكثر فشل للبرامج المُنزّلة داخل الحاويات سببه ثلاثة أمور لا أكثر:
#   1) مكتبات مفقودة (libnss3، libgbm1 …) → نزرع طقم تشغيل رسومي كامل مرة واحدة
#      ثم نقرأ مخرج ldd ونسد أي نقص متبقٍّ تلقائيًا.
#   2) تشغيل Electron/Chromium بصلاحية root بلا sandbox → نكتب غلافًا يضيف
#      --no-sandbox تلقائيًا للبرامج المبنية على Electron فقط.
#   3) FUSE غير متاح للـAppImage → نفكّ المحتوى ونشغّله من القرص (يعمل دائمًا).
# وكل ما يُثبّت يقع تحت /opt أو حزم dpkg وهي مشمولة أصلاً بلقطة Drive
# فيبقى البرنامج بعد إعادة تشغيل Colab.
# ============================================================
_APP_RUNTIME_PACKAGES = (
    "libnss3 libnspr4 libatk1.0-0 libatk-bridge2.0-0 libcups2 libdrm2 libgbm1 "
    "libgtk-3-0 libgdk-pixbuf2.0-0 libglib2.0-0 libpango-1.0-0 libcairo2 "
    "libx11-xcb1 libxcomposite1 libxdamage1 libxfixes3 libxrandr2 libxkbcommon0 "
    "libxshmfence1 libxss1 libxtst6 libasound2 libsecret-1-0 libnotify4 "
    "libappindicator3-1 libayatana-appindicator3-1 libwebkit2gtk-4.0-37 "
    "libqt5widgets5 libqt5gui5 libqt5core5a libfuse2 zlib1g libstdc++6 "
    "libcanberra-gtk-module libcanberra-gtk3-module gvfs-bin xdg-utils "
    "desktop-file-utils shared-mime-info hicolor-icon-theme p7zip-full unzip "
    "binutils file alien"
)
_APP_INSTALLER_SH = r'''#!/bin/bash
# install-linux-app : مُثبّت موحّد لأي برنامج لينكس تُنزّله من موقع عبر Chrome.
set -u
export DEBIAN_FRONTEND=noninteractive
export DISPLAY="${DISPLAY:-:1}"
export HOME=/root
LOG=/tmp/app-install.log
APPS=/opt/user-apps
AIS=/opt/appimages
BIN=/usr/local/bin
DESK=/usr/share/applications
RUNTIME_MARK="$APPS/.runtime-ready"
RUNTIME_PKGS="__RUNTIME_PKGS__"
PKG_CACHE="__PKG_CACHE__"
mkdir -p "$APPS" "$AIS" "$DESK" "$PKG_CACHE" 2>/dev/null
touch "$LOG" 2>/dev/null
log(){ printf '%s %s\n' "$(date +%H:%M:%S)" "$*" >>"$LOG" 2>/dev/null; }
gui(){ [ -n "${DISPLAY:-}" ] && command -v zenity >/dev/null 2>&1; }
info(){ log "INFO: $1"; gui && zenity --info --width=430 --title="مُثبّت برامج لينكس" --text="$1" 2>/dev/null; true; }
fail(){ log "FAIL: $1"; gui && zenity --error --width=430 --title="مُثبّت برامج لينكس" --text="$1" 2>/dev/null; true; }
ask(){ gui || return 0; zenity --question --width=430 --title="مُثبّت برامج لينكس" --text="$1" 2>/dev/null; }
# شريط تقدم غير معرّف المدة (يُغلق مع نهاية السكربت)
PULSE_PID=""
start_pulse(){ gui || return 0; (zenity --progress --pulsate --auto-close --no-cancel --width=420 \
  --title="جارٍ التثبيت" --text="$1" < <(sleep 100000) >/dev/null 2>&1) & PULSE_PID=$!; }
stop_pulse(){ [ -n "$PULSE_PID" ] && kill "$PULSE_PID" >/dev/null 2>&1; PULSE_PID=""; }
trap stop_pulse EXIT

apt_fix(){ dpkg --configure -a >>"$LOG" 2>&1; apt-get -f install -y -qq >>"$LOG" 2>&1; }
apt_get(){ apt-get install -y -qq $* >>"$LOG" 2>&1 || { apt_fix; apt-get install -y -qq $* >>"$LOG" 2>&1; }; }

# (1) طقم التشغيل الرسومي مرة واحدة فقط
ensure_runtime(){
  [ -f "$RUNTIME_MARK" ] && return 0
  log "installing GUI runtime set"
  apt-get update -qq >>"$LOG" 2>&1
  for p in $RUNTIME_PKGS; do apt-get install -y -qq "$p" >>"$LOG" 2>&1; done
  ldconfig >/dev/null 2>&1
  touch "$RUNTIME_MARK" 2>/dev/null
  return 0
}

# (2) إصلاح المكتبات المفقودة لملف تنفيذي معيّن
lib_to_pkg(){
  case "$1" in
    libnss3*|libnssutil3*|libsmime3*) echo libnss3;;
    libnspr4*) echo libnspr4;;
    libgbm*) echo libgbm1;;
    libgtk-3*) echo libgtk-3-0;;
    libgtk-4*) echo libgtk-4-1;;
    libatk-1*) echo libatk1.0-0;;
    libatk-bridge*) echo libatk-bridge2.0-0;;
    libcups*) echo libcups2;;
    libdrm*) echo libdrm2;;
    libasound*) echo libasound2;;
    libxss*) echo libxss1;;
    libxtst*) echo libxtst6;;
    libxkbcommon*) echo libxkbcommon0;;
    libxshmfence*) echo libxshmfence1;;
    libsecret*) echo libsecret-1-0;;
    libnotify*) echo libnotify4;;
    libappindicator3*) echo libappindicator3-1;;
    libwebkit2gtk*) echo libwebkit2gtk-4.0-37;;
    libQt5Widgets*) echo libqt5widgets5;;
    libQt5Gui*) echo libqt5gui5;;
    libQt5Core*) echo libqt5core5a;;
    libfuse.so.2*) echo libfuse2;;
    libcrypt.so.1*) echo libcrypt1;;
    libpng16*) echo libpng16-16;;
    libjpeg*) echo libjpeg-turbo8;;
    libtiff*) echo libtiff5;;
    libsqlite3*) echo libsqlite3-0;;
    libicu*) echo libicu70;;
    *) echo "";;
  esac
}
fix_libs(){
  local target="$1" missing pkg found=0
  command -v ldd >/dev/null 2>&1 || return 0
  [ -f "$target" ] || return 0
  missing=$(ldd "$target" 2>/dev/null | awk '/not found/{print $1}' | sort -u)
  for m in $missing; do
    pkg=$(lib_to_pkg "$m")
    if [ -n "$pkg" ]; then log "missing $m -> $pkg"; apt_get "$pkg"; found=1; fi
  done
  if [ "$found" = "1" ]; then ldconfig >/dev/null 2>&1; fi
  # محاولة ثانية لما لم يُعرف اسم حزمته عبر apt-file إن توفّر
  missing=$(ldd "$target" 2>/dev/null | awk '/not found/{print $1}' | sort -u)
  if [ -n "$missing" ] && command -v apt-file >/dev/null 2>&1; then
    for m in $missing; do
      pkg=$(apt-file search -x "/${m}$" 2>/dev/null | head -1 | cut -d: -f1)
      [ -n "$pkg" ] && { log "apt-file $m -> $pkg"; apt_get "$pkg"; }
    done
    ldconfig >/dev/null 2>&1
  fi
  return 0
}

# (3) هل البرنامج مبني على Electron/Chromium؟ (يحتاج --no-sandbox مع root)
is_electron(){
  local d
  d=$(dirname "$1")
  [ -f "$d/chrome-sandbox" ] && return 0
  [ -f "$d/resources/app.asar" ] && return 0
  [ -f "$d/libEGL.so" ] && [ -f "$d/icudtl.dat" ] && return 0
  grep -qa "electron" "$1" 2>/dev/null && return 0
  return 1
}

# (4) غلاف تشغيل آمن (يضبط البيئة ويضيف --no-sandbox عند الحاجة فقط)
make_wrapper(){
  local name="$1" exe="$2" extra=""
  if is_electron "$exe"; then extra="--no-sandbox --disable-gpu-sandbox --disable-dev-shm-usage"; fi
  {
    printf '#!/bin/bash\n'
    printf 'export DISPLAY="${DISPLAY:-:1}"\n'
    printf 'export HOME=/root\n'
    printf 'export XAUTHORITY=/root/.Xauthority\n'
    printf 'export GDK_BACKEND=x11\n'
    printf 'export LIBGL_ALWAYS_SOFTWARE=1\n'
    printf 'export ELECTRON_DISABLE_SANDBOX=1\n'
    printf 'cd "%s" 2>/dev/null || true\n' "$(dirname "$exe")"
    printf 'exec "%s" %s "$@"\n' "$exe" "$extra"
  } > "$BIN/$name" 2>/dev/null
  chmod +x "$BIN/$name" 2>/dev/null
  log "wrapper $BIN/$name -> $exe $extra"
}

# (5) أيقونة ومدخل في قائمة التطبيقات وسطح المكتب
make_desktop(){
  local name="$1" label="$2" icon="${3:-application-x-executable}"
  {
    printf '[Desktop Entry]\nVersion=1.0\nType=Application\n'
    printf 'Name=%s\n' "$label"
    printf 'Exec=%s/%s %%F\n' "$BIN" "$name"
    printf 'Icon=%s\nTerminal=false\nStartupNotify=true\n' "$icon"
    printf 'Categories=Utility;Application;\n'
  } > "$DESK/$name-user.desktop" 2>/dev/null
  cp -f "$DESK/$name-user.desktop" /root/Desktop/ 2>/dev/null
  chmod +x "/root/Desktop/$name-user.desktop" 2>/dev/null
  update-desktop-database "$DESK" >/dev/null 2>&1
  refresh-app-menu >/dev/null 2>&1 || true
}

# (6) اختيار الملف التنفيذي الرئيسي داخل مجلد مفكوك
pick_exec(){
  local root="$1" base="$2" c
  c=$(find "$root" -maxdepth 3 -type f -executable -iname "$base" 2>/dev/null | head -1)
  [ -n "$c" ] && { echo "$c"; return 0; }
  c=$(find "$root" -maxdepth 3 -type f -executable \( -path "*/bin/*" -o -path "*/usr/bin/*" \) 2>/dev/null | head -1)
  [ -n "$c" ] && { echo "$c"; return 0; }
  c=$(find "$root" -maxdepth 2 -type f -executable ! -name "*.so*" ! -name "*.sh" 2>/dev/null | head -1)
  echo "$c"
}

safe_name(){ echo "$1" | tr '[:upper:]' '[:lower:]' | sed 's/[^a-z0-9._-]/-/g; s/-\+/-/g; s/^-//; s/-$//' | cut -c1-40; }

# ---------- المعالجات ----------
do_deb(){
  local f="$1" pkg ver digest _deb_name
  pkg=$(dpkg-deb -f "$f" Package 2>/dev/null);ver=$(dpkg-deb -f "$f" Version 2>/dev/null);digest=$(sha256sum "$f" 2>/dev/null|awk '{print $1}')
  task "ستعمل postinst للحزمة بصلاحية root. ثبّت فقط حزمة من الموقع الرسمي.\n\nالحزمة: ${pkg:-غير معروفة}\nالإصدار: ${ver:-؟}\nSHA-256: ${digest:-تعذر الحساب}\n\nمتابعة؟" || return 0
  start_pulse "تثبيت الحزمة ${pkg:-$(basename "$f")} وحل اعتمادياتها…"
  ensure_runtime
  apt-get install -y -qq "$f" >>"$LOG" 2>&1 || { apt_fix; dpkg -i "$f" >>"$LOG" 2>&1; apt_fix; }
  stop_pulse
  if [ -n "$pkg" ] && dpkg -s "$pkg" >/dev/null 2>&1; then
    # احفظ ملف deb نفسه ذريًا في مخزن Drive كي يمكن إعادة تثبيته بعد runtime جديد.
    _deb_name="${pkg}_${ver:-manual}_$(dpkg --print-architecture 2>/dev/null || echo amd64).deb"
    _deb_name=$(printf '%s' "$_deb_name"|sed 's/[^A-Za-z0-9._+-]/_/g')
    if [ -d "$PKG_CACHE" ]; then
      cp -f "$f" "$PKG_CACHE/$_deb_name.partial" 2>>"$LOG" && \
      [ "$(sha256sum "$f"|awk '{print $1}')" = "$(sha256sum "$PKG_CACHE/$_deb_name.partial"|awk '{print $1}')" ] && \
      mv -f "$PKG_CACHE/$_deb_name.partial" "$PKG_CACHE/$_deb_name" || rm -f "$PKG_CACHE/$_deb_name.partial"
    fi
    log "deb ok (registered for persistent cache)"
    for e in $(dpkg -L "$pkg" 2>/dev/null | grep '\.desktop$' | head -3); do
      cp -f "$e" /root/Desktop/ 2>/dev/null; chmod +x "/root/Desktop/$(basename "$e")" 2>/dev/null
    done
    # إصلاح أي مكتبة مفقودة في ملفات الحزمة التنفيذية
    for b in $(dpkg -L "$pkg" 2>/dev/null | grep -E '^/(usr/)?s?bin/|^/opt/.*/[^/]+$' | head -6); do
      [ -x "$b" ] && [ -f "$b" ] && fix_libs "$b"
    done
    refresh-app-menu >/dev/null 2>&1 || true
    update-desktop-database "$DESK" >/dev/null 2>&1
    info "تم تثبيت: $pkg ✅\n\nستجده في قائمة ال��طبيقات وعلى سطح المكتب، وسيبقى بعد إعادة تشغيل Colab."
    return 0
  fi
  fail "فشل تثبيت الحزمة.\nالسجل: $LOG"
  return 1
}

do_appimage(){
  local f="$1" base name dest stage new old exe icon digest
  base=$(basename "$f"); name=$(safe_name "${base%.*}");digest=$(sha256sum "$f" 2>/dev/null|awk '{print $1}')
  task "AppImage ملف تنفيذي غير موثوق تلقائيًا. سنفكّه أولًا كمستخدم محدود، لكن شغّله فقط من الموقع الرسمي.\n\n$base\nSHA-256: ${digest:-؟}\n\nمتابعة؟" || return 0
  ensure_runtime;start_pulse "فحص وتجهيز $base بصلاحية محدودة…"
  dest="$AIS/$name";stage=$(mktemp -d /tmp/appimage-v20-XXXXXX) || { stop_pulse;return 1; }
  cp -f "$f" "$stage/app.AppImage" || { rm -rf "$stage";stop_pulse;return 1; }
  chmod 755 "$stage/app.AppImage";chown -R nobody:nogroup "$stage" 2>/dev/null || true
  if ! runuser -u nobody -- bash -c 'cd "$1" && ./app.AppImage --appimage-extract' _ "$stage" >>"$LOG" 2>&1; then
    rm -rf "$stage";stop_pulse;fail "فشل فك AppImage بالمستخدم المحدود؛ لم يتغير أي تثبيت سابق.";return 1
  fi
  # اقبل الروابط الداخلية المعتادة في AppImage وارفض أي رابط يهرب أو جهاز/FIFO/socket.
  if ! python3 - "$stage/squashfs-root" <<'PYAPP'
import os,sys,stat
root=os.path.realpath(sys.argv[1]);ok=True
for base,dirs,files in os.walk(root,followlinks=False):
 for name in dirs+files:
  p=os.path.join(base,name)
  try:
   st=os.lstat(p)
   if stat.S_ISLNK(st.st_mode):
    q=os.path.realpath(p)
    if q!=root and not q.startswith(root+os.sep):ok=False;break
   elif not (stat.S_ISREG(st.st_mode) or stat.S_ISDIR(st.st_mode)):ok=False;break
  except OSError:ok=False;break
 if not ok:break
raise SystemExit(0 if ok else 1)
PYAPP
  then
    rm -rf "$stage";stop_pulse;fail "AppImage يحوي رابطًا خارج الحزمة أو نوع ملف غير آمن؛ رُفض قبل التفعيل.";return 3
  fi
  chown -R root:root "$stage" 2>/dev/null || true
  new="$AIS/.${name}.new-$$";old="$AIS/.${name}.old-$$";rm -rf "$new" "$old";mkdir -p "$new"
  mv "$stage/app.AppImage" "$new/app.AppImage";mv "$stage/squashfs-root" "$new/squashfs-root";rm -rf "$stage"
  [ -d "$dest" ] && mv "$dest" "$old" 2>/dev/null || true
  mv "$new" "$dest" || { [ -d "$old" ] && mv "$old" "$dest";stop_pulse;return 1; }
  rm -rf "$old" 2>/dev/null || true
  exe="$dest/squashfs-root/AppRun";[ -x "$exe" ] || exe="$dest/app.AppImage"
  fix_libs "$exe"
  for b in $(find "$dest/squashfs-root" -maxdepth 2 -type f -executable ! -name "*.so*" 2>/dev/null | head -4); do fix_libs "$b"; done
  icon=$(find "$dest/squashfs-root" -maxdepth 2 -iname "*.png" 2>/dev/null | head -1)
  if [ -n "$icon" ]; then cp -f "$icon" "/usr/share/pixmaps/$name.png" 2>/dev/null; icon="/usr/share/pixmaps/$name.png"; else icon="application-x-executable"; fi
  make_wrapper "$name" "$exe";make_desktop "$name" "${base%.*}" "$icon"
  stop_pulse;info "تم تثبيت: ${base%.*} ✅\n\nالأمر: $name\nوأيقونته على سطح المكتب وفي قائمة التطبيقات."
  return 0
}

do_archive(){
  local f="$1" base name dest stage old root exe icon inner _arc_sha
  base=$(basename "$f"); name=$(safe_name "$(echo "${base}" | sed 's/\.tar\.\(gz\|xz\|bz2\)$//; s/\.\(tgz\|zip\|txz\)$//')")
  _arc_sha=$(sha256sum "$f" 2>/dev/null|awk '{print $1}')
  task "سيُفحص الأرشيف ثم يُنشأ مشغّل لملفه التنفيذي. استخدم حزمة من المصدر الرسمي فقط.\n\n$base\nSHA-256: ${_arc_sha:-؟}\n\nمتابعة؟" || return 0
  ensure_runtime
  start_pulse "فحص وفك وتجهيز $base…"
  dest="$APPS/$name";stage="$APPS/.${name}.new-$$";old="$APPS/.${name}.old-$$"
  rm -rf "$stage" "$old" 2>/dev/null;mkdir -p "$stage" || { stop_pulse;return 1; }
  case "${f,,}" in
    *.tar.gz|*.tgz|*.tar.xz|*.txz|*.tar.bz2|*.tar|*.zip)
      /usr/local/bin/safe-archive-extract "$f" "$stage" >>"$LOG" 2>&1 || { rm -rf "$stage";stop_pulse;fail "الأرشيف تالف أو يحوي مسارًا/رابطًا غير آمن؛ لم يتغير التثبيت السابق.";return 3; };;
    *.7z) rm -rf "$stage";stop_pulse;fail "لا نفك 7z تلقائيًا بصلاحية root. فكّه يدويًا داخل Downloads بعد التحقق من مصدره.";return 3;;
    *) rm -rf "$stage";stop_pulse;fail "نوع أرشيف غير مدعوم";return 1;;
  esac
  # فعّل المرحلة ذرّيًا؛ لا تحذف تثبيتًا سابقًا قبل نجاح الفحص والاستخراج.
  [ -d "$dest" ] && mv "$dest" "$old" 2>/dev/null || true
  if ! mv "$stage" "$dest"; then
    [ -d "$old" ] && mv "$old" "$dest" 2>/dev/null || true
    rm -rf "$stage";stop_pulse;return 1
  fi
  rm -rf "$old" 2>/dev/null || true
  root="$dest"
  inner=$(find "$dest" -mindepth 1 -maxdepth 1 2>/dev/null)
  if [ "$(printf '%s\n' "$inner" | sed '/^$/d' | wc -l)" = "1" ] && [ -d "$inner" ]; then root="$inner"; fi
  dest="$root"
  exe=$(pick_exec "$dest" "$name")
  if [ -z "$exe" ]; then
    stop_pulse
    info "فُك الملف في:\n$dest\n\nلم أجد ملفًا تنفيذيًا واضحًا — ��قرأ README/INSTALL داخله."
    return 0
  fi
  chmod +x "$exe" 2>/dev/null
  fix_libs "$exe"
  icon=$(find "$dest" -maxdepth 3 -iname "*.png" 2>/dev/null | head -1)
  if [ -n "$icon" ]; then cp -f "$icon" "/usr/share/pixmaps/$name.png" 2>/dev/null; icon="/usr/share/pixmaps/$name.png"; else icon="application-x-executable"; fi
  make_wrapper "$name" "$exe"
  make_desktop "$name" "$name" "$icon"
  stop_pulse
  info "تم تثبيت: $name ✅\n\nالمسار: $dest\nالأمر: $name"
  return 0
}

do_rpm(){
  local f="$1"
  command -v alien >/dev/null 2>&1 || { start_pulse "تجهيز محوّل حزم RPM…"; apt_get alien; stop_pulse; }
  command -v alien >/dev/null 2>&1 || { fail "تعذر تجهيز محوّل RPM. ابحث عن إصدار .deb أو AppImage من نفس الموقع."; return 1; }
  start_pulse "تحويل $(basename "$f") إلى حزمة deb وتثبيتها…"
  local tmp out
  tmp=$(mktemp -d) || { stop_pulse; return 1; }
  ( cd "$tmp" && alien -d -k "$f" >>"$LOG" 2>&1 )
  out=$(find "$tmp" -maxdepth 1 -name "*.deb" | head -1)
  stop_pulse
  [ -n "$out" ] || { fail "فشل تحويل حزمة RPM.\nالسجل: $LOG"; rm -rf "$tmp"; return 1; }
  do_deb "$out"; local r=$?; rm -rf "$tmp"; return $r
}

do_script(){
  local f="$1"
  ask "هذا ملف تثبيت نصّي (سكربت) ويُنفّذ أوامر بصلاحية كاملة.\nلا تشغّله إلا إن كان من موقع البرنامج الرسمي.\n\nمتابعة؟\n\n$f" || return 0
  ensure_runtime
  chmod +x "$f" 2>/dev/null
  if command -v xfce4-terminal >/dev/null 2>&1; then
    xfce4-terminal --title="تنفيذ $(basename "$f")" --hold -e "bash '$f'" >/dev/null 2>&1 &
  else
    bash "$f" >>"$LOG" 2>&1
  fi
  return 0
}

# ---------- المدخل ----------
F="${1:-}"
if [ -z "$F" ]; then
  gui || { echo "usage: install-linux-app <file>"; exit 1; }
  START="$HOME/Downloads/"
  [ -d /root/PhoneFiles ] && [ -z "$(ls -A "$HOME/Downloads" 2>/dev/null)" ] && START="/root/PhoneFiles/"
  F=$(zenity --file-selection --title="اختر ملف البرنامج المُنزّل (deb / AppImage / tar.gz / zip / rpm)" \
      --filename="$START" 2>/dev/null) || exit 0
fi
case "$F" in file://*) F="${F#file://}";; esac
[ -f "$F" ] || { fail "الملف غير موجود:\n$F"; exit 1; }
# رفض الملفات الناقصة (تنزيل لم يكتمل) قبل لمس النطام
case "${F,,}" in *.crdownload|*.part|*.tmp) fail "التنزيل لم يكتمل بعد. انتطر انتهاءه ثم أعد المحاولة."; exit 1;; esac
log "=== request: $F ==="
SZ=$(stat -c %s "$F" 2>/dev/null || echo 0)
[ "$SZ" -lt 1024 ] && { fail "الملف صغير جدًا أو تالف ($SZ بايت)."; exit 1; }
case "${F,,}" in
  *.deb) do_deb "$F" ;;
  *.appimage) do_appimage "$F" ;;
  *.tar.gz|*.tgz|*.tar.xz|*.txz|*.tar.bz2|*.tar|*.zip|*.7z) do_archive "$F" ;;
  *.rpm) do_rpm "$F" ;;
  *.sh|*.run|*.bin) do_script "$F" ;;
  *.flatpakref|*.flatpakrepo) if [ -x "$BIN/flatpakref-handler" ]; then exec "$BIN/flatpakref-handler" "$F"; elif [ -x "$BIN/flathub-install" ]; then exec "$BIN/flathub-install" "$F"; else fail "أدوات Flatpak لم تجهز بعد — انتظر دقيقة ثم أعد المحاولة."; fi ;;
  *.snap) fail "حزم Snap تحتاج systemd ولا تعمل داخل Colab. ابحث عن .deb أو AppImage من نفس الموقع." ;;
  *.exe|*.msi|*.dmg|*.pkg) fail "هذا ملف لنطام آخر (ويندوز/ماك). نزّل إصدار Linux (.deb أو AppImage أو tar.gz)." ;;
  *)
    T=$(file -b "$F" 2>/dev/null)
    case "$T" in
      *"Debian binary package"*) do_deb "$F" ;;
      *"gzip compressed"*) do_archive "$F.tar.gz" 2>/dev/null || { cp -f "$F" "$F.tar.gz" && do_archive "$F.tar.gz"; } ;;
      *"Zip archive"*) cp -f "$F" "$F.zip" && do_archive "$F.zip" ;;
      *"ELF 64-bit"*)
        NM=$(safe_name "$(basename "$F")"); chmod +x "$F" 2>/dev/null
        mkdir -p "$APPS/$NM" && cp -f "$F" "$APPS/$NM/$NM" && chmod +x "$APPS/$NM/$NM"
        ensure_runtime; fix_libs "$APPS/$NM/$NM"
        make_wrapper "$NM" "$APPS/$NM/$NM"; make_desktop "$NM" "$NM" "application-x-executable"
        info "تم تجهيز البرنامج: $NM ✅"
        ;;
      *) fail "لم أتعرف على نوع الملف:\n$T" ;;
    esac
    ;;
esac
exit 0
'''

_APP_WATCH_SH = r'''#!/bin/bash
# download-install-watch : يراقب مجلدات التنزيل ويعرض عرض تثبيت فوريًا.
export DISPLAY="${DISPLAY:-:1}"
export HOME=/root
export XAUTHORITY=/root/.Xauthority
STATE=/root/.config/colab-desktop/seen-downloads
mkdir -p "$(dirname "$STATE")" 2>/dev/null; touch "$STATE" 2>/dev/null
exec 9>/tmp/.download-install-watch.lock 2>/dev/null || true
if command -v flock >/dev/null 2>&1; then flock -n 9 || exit 0; fi
# لا نعرض أي ملف موجود قبل بدء المراقبة (حتى لا تأتي نوافذ مزعجة عند الإقلاع)
for d in /root/Downloads /root/PhoneFiles; do
  [ -d "$d" ] || continue
  find "$d" -maxdepth 1 -type f 2>/dev/null | while read -r f; do
    grep -qxF -- "$f" "$STATE" 2>/dev/null || echo "$f" >> "$STATE"
  done
done
while true; do
  sleep 20
  for d in /root/Downloads /root/PhoneFiles; do
    [ -d "$d" ] || continue
    while IFS= read -r f; do
      [ -f "$f" ] || continue
      case "${f,,}" in
        *.deb|*.appimage|*.tar.gz|*.tgz|*.tar.xz|*.txz|*.tar.bz2|*.zip|*.rpm) : ;;
        *) continue ;;
      esac
      grep -qxF -- "$f" "$STATE" 2>/dev/null && continue
      # نتأكد أن التنزيل اكتمل: حجم ثابت ولا يوجد ملف جزئي مرافق
      S1=$(stat -c %s "$f" 2>/dev/null || echo 0); sleep 6
      S2=$(stat -c %s "$f" 2>/dev/null || echo 0)
      [ "$S1" != "$S2" ] && continue
      [ -f "$f.crdownload" ] && continue
      [ "$S2" -lt 1024 ] && continue
      echo "$f" >> "$STATE"
      if zenity --question --width=430 --title="تنزيل جديد" \
         --text="اكتمل تنزيل:\n$(basename "$f")\n\nهل تريد تثبيته وتجهيزه للعمل الأن؟" 2>/dev/null; then
        setsid /usr/local/bin/install-linux-app "$f" >/dev/null 2>&1 &
      fi
    done < <(find "$d" -maxdepth 1 -type f -newermt '-10 minutes' 2>/dev/null)
  done
done
'''



# ============================================================
# v76) طرفية لينكس كاملة القدرات: بيئة + أدوات + فحص شامل
#  • الجلسة تعمل أصلاً بـroot، فالطرفية تملك كل الصلاحيات دون قاعدة sudo عامة.
#  • لا نع��رض أي أمر أصلي (apt/dpkg/rm...) — فقط نُضيف بيئة وأدوات.
#  • التثبيت خلفي ومتسامح: فشل حزمة لا يوقف البقية ولا يعطل سطح المكتب.
# ============================================================
_TERM_TOOLS_MARK = "/root/.config/colab-desktop/.term-tools-ready"
_TERM_BASHRC_MARK = "# === colab-power-terminal v76 ==="
_TERM_TOOL_PACKAGES = [
    "build-essential", "make", "cmake", "pkg-config", "gdb", "git", "patch",
    "curl", "wget", "ca-certificates", "openssh-client", "net-tools", "iproute2",
    "iputils-ping", "dnsutils", "netcat-openbsd", "socat", "traceroute",
    "lsof", "strace", "htop", "procps", "psmisc", "sysstat", "ncdu", "tree",
    "vim", "nano", "less", "jq", "ripgrep", "bash-completion", "man-db",
    "dos2unix", "bc", "rsync", "zip", "unzip", "p7zip-full", "xz-utils",
    "bzip2", "zstd", "cpio", "tmux", "screen", "file", "poppler-utils",
    "openssl", "gnupg", "sudo", "parallel", "expect", "python3-venv", "sqlite3",
]
_TERM_BASHRC = r'''
# === colab-power-terminal v76 ===
case $- in *i*) ;; *) return ;; esac
export TERM="${TERM:-xterm-256color}"
export EDITOR="${EDITOR:-nano}"
export VISUAL="$EDITOR"
export PAGER="${PAGER:-less}"
export LESSCHARSET=utf-8
export PYTHONIOENCODING=UTF-8
export HISTSIZE=200000
export HISTFILESIZE=400000
export HISTCONTROL=ignoreboth:erasedups
export HISTTIMEFORMAT='%F %T  '
shopt -s histappend cmdhist checkwinsize globstar 2>/dev/null
PROMPT_COMMAND="history -a${PROMPT_COMMAND:+; $PROMPT_COMMAND}"
for _p in /usr/local/bin /usr/local/sbin /opt/user-apps/bin /root/.local/bin /root/Android/Sdk/platform-tools; do
  case ":$PATH:" in *":$_p:"*) ;; *) [ -d "$_p" ] && PATH="$_p:$PATH";; esac
done
export PATH
[ -r /usr/share/bash-completion/bash_completion ] && . /usr/share/bash-completion/bash_completion
_git_branch(){ git rev-parse --abbrev-ref HEAD 2>/dev/null | sed 's/.*/ (&)/'; }
PS1='\[\e[1;32m\]colab\[\e[0m\]:\[\e[1;34m\]\w\[\e[0;33m\]$(_git_branch)\[\e[0m\]\$ '
alias ls='ls --color=auto'
alias ll='ls -alhF --color=auto'
alias la='ls -A --color=auto'
alias grep='grep --color=auto'
alias df='df -h'
alias du='du -h'
alias free='free -h'
alias ..='cd ..'
alias ...='cd ../..'
alias ports='ss -tulpn 2>/dev/null || netstat -tulpn'
alias psg='ps aux | grep -v grep | grep -i'
alias myip='curl -s ifconfig.me 2>/dev/null; echo'
extract(){
  [ -f "${1:-}" ] || { echo "usage: extract <file>"; return 1; }
  case "$1" in
    *.tar.gz|*.tgz) tar -xzvf "$1";;
    *.tar.xz|*.txz) tar -xJvf "$1";;
    *.tar.bz2|*.tbz2) tar -xjvf "$1";;
    *.tar.zst) tar --zstd -xvf "$1";;
    *.tar) tar -xvf "$1";;
    *.zip) unzip -o "$1";;
    *.7z) 7z x "$1";;
    *.gz) gunzip -k "$1";;
    *.xz) unxz -k "$1";;
    *.bz2) bunzip2 -k "$1";;
    *.deb) dpkg-deb -x "$1" "${1%.deb}";;
    *) echo "unknown archive: $1"; return 1;;
  esac
}
sysinfo(){ /usr/local/bin/sysinfo "$@"; }
linuxtest(){ /usr/local/bin/linux-power-test "$@"; }
'''
_SYSINFO_SH = r'''#!/bin/bash
# sysinfo : ملخص سريع لحالة الجهاز والجلسة
printf '\n\033[1;36m=== ملخص النظام ===\033[0m\n'
printf 'المستخدم        : %s (uid=%s)\n' "$(id -un)" "$(id -u)"
printf 'النظام          : %s\n' "$(. /etc/os-release 2>/dev/null; echo "${PRETTY_NAME:-Linux}")"
printf 'النواة          : %s\n' "$(uname -r)"
printf 'المعالجات       : %s نواة\n' "$(nproc 2>/dev/null || echo '?')"
printf 'الذاكرة         : %s\n' "$(free -h 2>/dev/null | awk '/Mem:/{print $3" من "$2}')"
printf 'القرص (/)       : %s\n' "$(df -h / 2>/dev/null | awk 'NR==2{print $3" من "$2" ("$5")"}')"
printf 'مدة التشغيل     : %s\n' "$(uptime -p 2>/dev/null || uptime)"
printf 'عدد العمليات    : %s\n' "$(ps -e --no-headers 2>/dev/null | wc -l)"
printf 'الشاشة (DISPLAY): %s\n' "${DISPLAY:-غير محدد��}"
printf 'منافذ مستمعة    : %s\n' "$(ss -tuln 2>/dev/null | tail -n +2 | wc -l)"
printf '\nللفحص الشامل للقدرات: \033[1;33mlinux-power-test\033[0m\n\n'
'''
_LINUX_POWER_TEST_SH = r'''#!/bin/bash
# linux-power-test : فحص شامل لقدرات الطرفية ولينكس — لا يغير شيئاً في النظام
set -u
PASS=0; FAIL=0; SKIP=0
REPORT="${REPORT:-/root/Desktop/terminal-test-report.txt}"
TMP="$(mktemp -d /tmp/linuxtest.XXXXXX)" || exit 1
cleanup(){ cd /tmp 2>/dev/null || true; rm -rf "$TMP" 2>/dev/null || true; }
trap cleanup EXIT
LOG="$TMP/report.txt"
say(){ printf '%s\n' "$1"; printf '%s\n' "$1" >> "$LOG"; }
ok(){   PASS=$((PASS+1)); say "  [✔] $1"; }
bad(){  FAIL=$((FAIL+1)); say "  [✖] $1"; }
skip(){ SKIP=$((SKIP+1)); say "  [-] $1"; }
note(){ say "  [معلومة] $1"; }
hdr(){ say ""; say "== $1 =="; }
check(){ if eval "$2" >/dev/null 2>&1; then ok "$1"; else bad "$1"; fi; }
have(){ command -v "$1" >/dev/null 2>&1; }
check_cmd(){ if have "$1"; then ok "$2 ($1)"; else bad "$2 — غير مثبت ($1)"; fi; }

say "فحص قدرات الطرفية ولينكس — $(date '+%Y-%m-%d %H:%M:%S')"

hdr "1) الصلاحيات"
if [ "$(id -u)" = "0" ]; then ok "صلاحية root كاملة"; else bad "لا تعمل بـroot"; fi
check "الكتابة في /etc و/usr و/opt" "touch /etc/.wt && rm -f /etc/.wt && touch /usr/.wt && rm -f /usr/.wt && mkdir -p /opt && touch /opt/.wt && rm -f /opt/.wt"
check "chown/chmod وبت setuid" "touch $TMP/p && chown root:root $TMP/p && chmod 4755 $TMP/p"
if have sudo; then check "sudo بلا كلمة مرور" "sudo -n true"; else skip "sudo غير مثبت (غير لازم لأن الجلسة root)"; fi
check "قراءة /proc و/sys" "head -1 /proc/cpuinfo && ls /sys/class"

hdr "2) مدير الحزم"
check_cmd apt-get "مدير الحزم"
check_cmd dpkg "قاعدة الحزم"
check "فهرس الحزم مقروء" "apt-cache policy bash"
dpkg_clean(){ dpkg -l 2>/dev/null | tail -n +6 | cut -c1-2 | grep -qv -e "^ii" -e "^rc" && return 1 || return 0; }
check "لا توجد حزم ناقصة التهيئة في dpkg" "dpkg_clean"

hdr "3) البناء والترجمة"
if have gcc; then
  printf '#include <stdio.h>\nint main(){printf("okc");return 0;}\n' > "$TMP/t.c"
  if gcc "$TMP/t.c" -o "$TMP/t" 2>/dev/null && [ "$("$TMP/t")" = "okc" ]; then ok "ترجمة وتشغيل C"; else bad "فشل ترجمة C"; fi
else bad "gcc غير مثبت"; fi
if have g++; then
  printf '#include <iostream>\nint main(){std::cout<<"okcpp";}\n' > "$TMP/t.cpp"
  if g++ "$TMP/t.cpp" -o "$TMP/tp" 2>/dev/null && [ "$("$TMP/tp")" = "okcpp" ]; then ok "ترجمة وتشغيل C++"; else bad "فشل ترجمة C++"; fi
else bad "g++ غير مثبت"; fi
check_cmd make "أداة make"
if have cmake; then ok "أداة cmake (cmake)"; else skip "أداة cmake — cmake لم يكتمل تنزيله بعد"; fi
check_cmd git "إدارة الإصدارات"
check "إنشاء مستودع git وإيداع" "cd $TMP && git init -q r && cd r && git -c user.email=a@b -c user.name=c commit -q --allow-empty -m t"

hdr "4) اللغات"
check "Python 3" "python3 -c 'print(1+1)'"
check "pip" "python3 -m pip --version"
check "بيئة venv" "python3 -m venv $TMP/venv && $TMP/venv/bin/python -c 'print(1)'"
if have node; then check "Node.js" "node -e 'process.stdout.write(String(4))'"; else skip "Node.js غير مثبت"; fi
if have java; then check "Java" "java -version"; else skip "Java عام غير مثبت (JBR داخل Android Studio مستقل)"; fi
if have sqlite3; then ok "sqlite3 (sqlite3)"; else skip "sqlite3 — sqlite3 لم يكتمل تنزيله بعد"; fi

mkbig(){ [ -s "$TMP/big" ] || dd if=/dev/zero of="$TMP/big" bs=1M count=10 2>/dev/null; }
hdr "5) الملفات والأرشفة"
check "ملف 10MB قراءة/كتابة" "dd if=/dev/zero of=$TMP/big bs=1M count=10 2>/dev/null && [ -s $TMP/big ]"
check "tar+gzip" "mkbig; tar -czf $TMP/a.tgz -C $TMP big && tar -tzf $TMP/a.tgz"
if have zip && have unzip; then check "zip+unzip" "mkbig; cd $TMP && zip -q a.zip big && unzip -tq a.zip"; else skip "zip/unzip غير مثبت بعد"; fi
if have xz; then check "xz" "mkbig; xz -k -c $TMP/big > $TMP/big.xz && [ -s $TMP/big.xz ]"; else skip "xz غير مثبت بعد"; fi
if have zstd; then check "zstd" "mkbig; zstd -q -k -o $TMP/big.zst $TMP/big && [ -s $TMP/big.zst ]"; else skip "zstd غير مثبت بعد"; fi
if have 7z; then check "7z" "mkbig; cd $TMP && 7z a -bso0 -bsp0 a.7z big && 7z t -bso0 a.7z"; else skip "7z غير مثبت بعد"; fi
check "روابط رمزية/صلبة" "mkbig; ln -s $TMP/big $TMP/lns && ln $TMP/big $TMP/lnh && [ -L $TMP/lns ]"
if have rsync; then check "rsync محلي" "mkbig; mkdir -p $TMP/rs && rsync -a $TMP/big $TMP/rs/ && [ -s $TMP/rs/big ]"; else skip "rsync غير مثبت بعد"; fi
check "بحث متكرر (grep -r)" "grep -rl . $TMP >/dev/null"

hdr "6) العمليات"
check "تشغيل عملية خلفية وإنهاءها" "sleep 30 & pid=\$!; kill \$pid"
check "أولوية nice" "nice -n 5 true"
check "حدود ulimit" "ulimit -n"
if have htop; then ok "مراقب العمليات (htop)"; else skip "مراقب العمليات — htop لم يكتمل تنزيله بعد"; fi
if have lsof; then ok "الملفات المفتوحة (lsof)"; else skip "الملفات المفتوحة — lsof لم يكتمل تنزيله بعد"; fi
if have strace; then ok "تعقب نداءات النطام (strace)"; else skip "تعقب نداءات النطام — strace لم يكتمل تنزيله بعد"; fi
if have tmux; then check "جلسة tmux منفصلة" "tmux new-session -d -s ltest 'sleep 5' && tmux kill-session -t ltest"; else skip "tmux لم يكتمل تنزيله بعد"; fi

hdr "7) الشبكة"
check_cmd curl "عميل HTTP"
check_cmd wget "منزل ملفات"
check "DNS" "getent hosts github.com || getent hosts google.com"
check "طلب HTTPS خارجي" "curl -sSf -m 25 -o /dev/null https://api.github.com"
check "الاستماع على منفذ محلي" "python3 -c \"import socket;s=socket.socket();s.bind(('127.0.0.1',0));s.listen(1);s.close()\""
if have ss || have netstat; then check "عرض المنافذ" "ss -tuln || netstat -tuln"; else skip "أدوات عرض المنافذ غير مثبتة بعد"; fi
if have ip || have ifconfig; then check "عرض واجهات الشبكة" "ip a || ifconfig"; else skip "أدوات عرض الواجهات غير مثبتة بعد"; fi
if have ping; then check "ping (ICMP)" "ping -c1 -W3 1.1.1.1"; else skip "ping غير مثبت"; fi
check "توليد مفتاح SSH" "ssh-keygen -q -t ed25519 -N '' -f $TMP/k"

hdr "8) الوسائط والتشفير"
if have ffmpeg; then check "توليد فيديو بـffmpeg" "ffmpeg -y -f lavfi -i testsrc=size=64x64:rate=5 -t 1 $TMP/v.mp4"; else skip "ffmpeg لم يكتمل تنزيله بعد"; fi
if have convert; then check "إنشاء وتحويل صورة" "convert -size 32x32 xc:red $TMP/i.png && convert $TMP/i.png $TMP/i.jpg"; else skip "ImageMagick لم يكتمل تنزيله بعد"; fi
if have jq; then ok "محلل JSON (jq)"; else skip "jq لم يكتمل تنزيله بعد"; fi
check "openssl تشفير وفك" "echo secret | openssl enc -aes-256-cbc -pbkdf2 -pass pass:x -out $TMP/e && openssl enc -d -aes-256-cbc -pbkdf2 -pass pass:x -in $TMP/e | grep -q secret"
check "بصمة sha256" "printf abc > $TMP/h && sha256sum $TMP/h"

hdr "9) الطرفية والبيئة الرسومية"
check "العربية UTF-8 في الطرفية" "printf '%s' 'اختبار' | grep -q 'اختبار'"
check "إعداد الصدفة محمل (.bashrc)" "grep -q colab-power-terminal /root/.bashrc"
if have xfce4-terminal; then ok "طرفية رسومية (xfce4-terminal)"; else bad "xfce4-terminal غير مثبت"; fi
if [ -n "${DISPLAY:-}" ] && have xdotool; then check "الاتصال بسيرف�� X" "xdotool getdisplaygeometry"; else skip "فحص X تجاوزناه (لا يوجد DISPLAY في هذا الس��اق)"; fi
if have man; then ok "صفحات المساعدة (man)"; else skip "صفحات المساعدة — man لم يكتمل تنزيله بعد"; fi

hdr "10) حدود حقيقية للبيئة (ليست أخطاء)"
if [ -d /run/systemd/system ]; then ok "systemd متاح"; else note "لا يوجد systemd داخل Colab — شغل الخدمات مباشرة أو بـtmux بدل systemctl"; fi
if [ -e /dev/kvm ]; then ok "��سريع KVM متاح"; else note "لا يوجد /dev/kvm — المحاكيات والأنطمة الوهمية تعمل بالمحاكاة البرمجية فقط"; fi
if have insmod && [ -d /lib/modules/"$(uname -r)" ]; then note "تحميل وحدات النواة قد يعمل جزئياً"; else note "لا يمكن تحميل وحدات نواة (النواة ��شتركة مع مضيف Colab)"; fi
if have docker && docker info >/dev/null 2>&1; then ok "Docker يعمل"; else note "لا يوجد ديمن Docker — البديل podman/chroot أو التشغيل المباشر"; fi
if have snap; then note "snap موجود لكنه يحتاج systemd للعمل"; else note "snap غير متاح (يحتاج systemd) — استخدم .deb أو AppImage"; fi

hdr "النتيجة"
say "نجح: $PASS   |   فشل: $FAIL   |   تجاوز: $SKIP"
if [ "$FAIL" -eq 0 ]; then say "كل القدرات المفحوصة تعمل ✔"; else say "راجع البنود المعلمة بـ[✖] — غالباً أداة لم تكتمل تنزيلاتها بعد"; fi
mkdir -p "$(dirname "$REPORT")" 2>/dev/null || true
cp -f "$LOG" "$REPORT" 2>/dev/null && say "حُفظ التقرير في: $REPORT"
[ "$FAIL" -eq 0 ] || exit 1
exit 0
'''
