        for _name, _title, _cmd, _icon in _launchers:
            _txt = ("[Desktop Entry]\nVersion=1.0\nType=Application\n"
                    "Name=%s\nComment=أدوات لينكس داخل Colab\nExec=%s\n"
                    "Icon=%s\nTerminal=false\nCategories=System;Utility;\n"
                    % (_title, _cmd, _icon))
            for _dir in ("/usr/share/applications", "/root/Desktop"):
                try:
                    os.makedirs(_dir, exist_ok=True)
                    _p = os.path.join(_dir, _name)
                    with open(_p, "w") as _f:
                        _f.write(_txt)
                    os.chmod(_p, 0o755)
                except Exception:
                    pass
        _diag_event("power_terminal_write")
