# Stability-first mode: no surprise package/snapshot work while using desktop.
BACKGROUND_MAINTENANCE = (os.environ.get("BACKGROUND_MAINTENANCE", "0").strip() == "1")

# ---------------------------------------------------------------------------
# 🚨 v46 — إصلاح حرج دًّا لبطء الإقلاع (اسبب الجذري الثاني)
# ---------------------------------------------------------------------------
# كان بناء اللقطة مُجدولًا عبر _deferred_job، وهذه الدالة تُلغي المهمة تمامًا
# إذا لم يضبط المستخدم BACKGROUND_MAINTENANCE=1 — والافتراضي "0"!
# النتيجة: اللقطة *لا تُبنى أبدًا* في الوضع الافتراضي ⇒ كل إقلاع بارد 2-3 دقائق
# إلى الأبد، ولو كانت كل التطبيقات سليمة. هذا يفسّر البطء الدائم عند المستخدم.
#
# الحل: نفصل «مهام الصيانة الاختيارية» (flatpak، مركز البرمجيات، appstream...)
# عن «مهام تسريع الإقلاع» (اللقطة). اللقطة ساسية للأداء ⇒ تعمل دائمً��،
# ويمكن تعطيلها صاحةً عبر SNAPSHOT_AUTOBUILD=0 لمن يريد ذلك.
SNAPSHOT_AUTOBUILD = (os.environ.get("SNAPSHOT_AUTOBUILD", "1").strip() != "0")


def _deferred_job(delay, fn, name, essential=False):
    """يؤجّل مهمة خلفية. essential=True ⇒ تعمل دون الحاجة إلى
    BACKGROUND_MAINTENANCE (تُستخدم لمهام تسريع الإقلاع مثل بناء اللقطة)."""
    if not (BACKGROUND_MAINTENANCE or essential):
        return None

    def _runner():
        try:
            time.sleep(delay)
        except Exception:
            return
        try:
            fn()
        except Exception as _exc:
            try:
                _diag_event("deferred_" + str(name)[:40], _exc)
            except Exception:
                pass

    try:
        threading.Thread(target=_runner, name=name, daemon=True).start()
    except Exception as _exc:
        try:
            _diag_event("deferred_start_" + str(name)[:40], _exc)
        except Exception:
            pass
    return None

def _ensure_flatpak_stack():
    try:
        if not os.path.exists("/usr/bin/flatpak") or not os.path.exists("/usr/bin/proot"):
            _apt_heal()
            run("sudo DEBIAN_FRONTEND=noninteractive apt-get install -y -qq "
                "flatpak bubblewrap proot xdg-desktop-portal xdg-desktop-portal-gtk "
                "gnome-software-plugin-flatpak > /dev/null 2>&1", timeout=900)
        if os.path.exists("/usr/bin/flatpak"):
            run("/usr/bin/flatpak remote-add --user --if-not-exists flathub "
                "https://flathub.org/repo/flathub.flatpakrepo "
                "> /dev/null 2>&1", timeout=180)
            return True
    except Exception:
        pass
    return False

def _restore_flatpak_apps_bg():
    """استعادة + دوام تطبيقات Flatpak مثل النظام المحلي تمامًا: البيان يعيش
    في Drive (لا يُفقد بإعادة تعيين الـ runtime)، مع دمج النسخة المحلية."""
    local_manifest = "/root/.config/flatpak-apps.txt"
    drive_manifest = os.path.join(PERSIST_DIR, "flatpak-apps.txt")
    apps = set()
    for path in (local_manifest, drive_manifest):
        try:
            with open(path, encoding="utf-8") as f:
                apps.update(x.strip() for x in f
                            if re.fullmatch(r"[A-Za-z0-9._-]+", x.strip()))
        except Exception:
            pass
    if not apps:
        return
    if not _ensure_flatpak_stack():
        return
    try:
        for app_id in sorted(apps):
            present = run("/usr/bin/flatpak info --user '%s' > /dev/null 2>&1" % app_id)
            if getattr(present, "returncode", 1) != 0:
                run("nice -n 19 ionice -c3 /usr/bin/flatpak install --user -y "
                    "--noninteractive flathub '%s' > /dev/null 2>&1" % app_id,
                    timeout=1800)
        # v127: سجّل المجموعة الكاملة المثبّتة فعليًّا في البيانين (محلي +
        #     Drive) — يشمل ما ثبّته المستخدم يدويًّا: دوام حقيقي كالمحلي.
        cur = run("/usr/bin/flatpak list --user --app --columns=application 2>/dev/null")
        if getattr(cur, "returncode", 1) == 0 and (cur.stdout or "").strip():
            apps.update(x.strip() for x in cur.stdout.splitlines()
                        if re.fullmatch(r"[A-Za-z0-9._-]+", x.strip()))
        merged = "\n".join(sorted(apps)) + "\n"
        for path in (local_manifest, drive_manifest):
            try:
                os.makedirs(os.path.dirname(path), exist_ok=True)
                tmp = path + ".v127tmp"
                with open(tmp, "w", encoding="utf-8") as f:
                    f.write(merged)
                os.replace(tmp, path)
            except Exception:
                pass
        run("/usr/local/bin/refresh-flatpak-launchers >/dev/null 2>&1 || true")
    except Exception:
        pass

# v127: «مثل النظام المحلي» يعني أن Flathub جاهز دائمًا من أول نقرة
#     متصفح — أزلنا بوابة CHROME_ONLY التي كانت تمنع التجهيز والاستعادة
#     افتراضيًّا. الخلفية المؤجلة (5/6 دقائق) تحفظ سرعة الإقلاع كما هي.
_deferred_job(300, _ensure_flatpak_stack, "flatpak_setup_delayed")
_deferred_job(360, _restore_flatpak_apps_bg, "flatpak_restore_delayed")


# ============================================================
# (11) *** مركز البرامج الرسومي + PackageKit + AppStream (إصلاح جذري) ***
# ============================================================
# المشكلة المُبلَّغة: «Failed to execute child process 'gnome-software'
# (No such file or directory)» + «No Apps available».
# السبب الجذري: عناصر XFCE/exo وروابط التثبيت في المتصفّح تستدعي
# gnome-software بالاسم وهو غير مثبّت، وقاعدة بيانات AppStream فارغة
# (لا packagekit ولا appstream ولا بيانات وصفية مُحدَّثة).
# الحل الدائم (3 طبقات):
#   أ) تثبيت البنية: packagekit + appstream + gnome-software (إن توفّر).
#   ب) غلاف /usr/local/bin/gnome-software — لا يفشل أبدًا: يشغّل
#      gnome-software الحقيقي إن وُجد، وإلا synaptic (الأنسب لـXFCE)،
#      وإلا نافذة install-app. أي استدعاء باسم gnome-software ينجح.
#   ) تحديث بيانات AppStream وتوليد الكاش (يحلّ «No Apps available»).
print("[11] مركز البرامج: PackageKit + AppStream + مدير رسومي (خلفية)...")
# >>> ULTRA-BOOT: تثبيت PackageKit/gnome-software (كان يستهلك 1-2 دقيقة
#     قبل ظهور سطح المكتب!) يعمل الآن في خيط خلفي — الغلاف أدناه يضمن
#     بديلًا فوريًّا (synaptic/install-app) حتى قبل اكتماله. اللقطة
#     الدائمة تلتقط ناتجه فلا يتكرّر في الإقلاعات الادمة إطلاقًا. <<<
def _install_software_center_bg():
    try:
        if not os.path.exists("/usr/libexec/packagekitd") and \
                not os.path.exists("/usr/lib/packagekit/packagekitd"):
            _apt_heal()
            run("sudo DEBIAN_FRONTEND=noninteractive apt-get install -y -qq "
                "packagekit packagekit-tools gir1.2-packagekitglib-1.0 "
                "appstream > /dev/null 2>&1", timeout=600)
        # gnome-software: نحاول تثبيته (يعمل على XFCE عبر D-Bus بلا systemd)؛
        # فشله ليس حرجًا — الغلاف يضمن ديلًا يعمل دائمًا.
        if not os.path.exists("/usr/bin/gnome-software"):
            run("sudo DEBIAN_FRONTEND=noninteractive apt-get install -y -qq "
                "gnome-software gnome-software-common "
                "gnome-software-plugin-flatpak > /dev/null 2>&1",
                timeout=600)
        print("[OK] مركز البرامج اكتمل تثبيته (خلفية) ✅")
    except Exception:
        pass
if not CHROME_ONLY:
    _deferred_job(420, _install_software_center_bg, "sw_center_delayed")

# (ب) الغلاف الذي لا يفشل أبدًا — يعترض أي استدعاء لـ gnome-software
#     (PATH يقدّم /usr/local/bin على /usr/bin) ويضمن فتح مدير برامج يعمل.
_gsw_sh = r"""#!/bin/bash
# gnome-software wrapper : يضمن فتح مدير برامج رسومي يعمل دائمًا (XFCE)
# 1) gnome-software الحقيقي (إن ثُبّت وعمل packagekitd)
if [ -x /usr/bin/gnome-software ]; then
  /usr/bin/gnome-software "$@" 2>/tmp/gnome-software.log && exit 0
fi
# 2) البديل الأنسب لـ XFCE: synaptic (تثبيت/إزالة/بحث كامل)
if command -v synaptic >/dev/null 2>&1; then
  exec synaptic "$@"
fi
# 3) شبكة أمان أخيرة: نافذة تثبيت بالاسم
exec /usr/local/bin/install-app
"""
with open("/usr/local/bin/gnome-software", "w") as f:
    f.write(_gsw_sh)
run("chmod +x /usr/local/bin/gnome-software")

# مُطلِق «البرامج» في قائمة التطبيقات — يشير للغلاف (يعمل دائمًا)
_sw_desktop = """[Desktop Entry]
Version=1.0
Type=Application
Name=Software
Name[ar]=البرامج
Comment=Install and manage applications
Comment[ar]=تثبيت التطبيقات وإدارتها
Exec=/usr/local/bin/gnome-software
Icon=system-software-install
Terminal=false
Categories=System;Settings;PackageManager;
"""
with open("/usr/share/applications/software-center.desktop", "w") as f:
    f.write(_sw_desktop)
# أيقونة على سطح المكتب أيضًا
try:
    _swd = os.path.join(desktop_dir, "software-center.desktop")
    with open(_swd, "w") as f:
        f.write(_sw_desktop)
    run("chmod +x '%s'" % _swd)
except Exception:
    pass

# (ج) بيانات AppStream: تحديث الفهارس وتوليد الكاش — يحلّ «No Apps available»
#     (appstreamcli يقرأ بيانات المستودعات التي جلبها apt update).
def _refresh_appstream():
    run("nice -n 19 ionice -c3 sudo appstreamcli refresh --force > /dev/null 2>&1 || "
        "nice -n 19 ionice -c3 sudo appstreamcli refresh-cache --force > /dev/null 2>&1 || true",
        timeout=300)
    # كاش PackageKit (يغذّي gnome-software)
    run("sudo pkcon refresh force -p > /dev/null 2>&1 || true", timeout=300)
_deferred_job(720, _refresh_appstream, "appstream_delayed")

# (د) روابط MIME الدائمة — النقر المزدوج و«فتح باستخدام» من المتصفّح:
#     .deb→deb-install | AppImage→appimage-run | flatpakref/snap→موجّه ذكي
_flatref_sh = r"""#!/bin/bash
set -u
TARGET="${1:-}"
LOG=/tmp/flatpak-browser-install.log
STATUS=/tmp/flatpak-browser-install.status
APPFILE=/tmp/flatpak-browser-install.app
TMP=""
rm -f "$APPFILE"
rm -f "$STATUS" "$LOG"
cleanup(){ [ -n "$TMP" ] && rm -f "$TMP" 2>/dev/null || true; }
trap cleanup EXIT

# Convert URI forms safely.
case "$TARGET" in
  flatpak+https://*) TARGET="${TARGET#flatpak+}" ;;
  file://*)
    TARGET=$(python3 -c 'import sys,urllib.parse; print(urllib.parse.unquote(sys.argv[1][7:]))' "$TARGET") ;;
esac

prep_userns(){
  sysctl -w kernel.unprivileged_userns_clone=1 >>"$LOG" 2>&1 || true
  sysctl -w user.max_user_namespaces=15000 >>"$LOG" 2>&1 || true
  [ -x /usr/bin/bwrap ] && chmod u+s /usr/bin/bwrap >>"$LOG" 2>&1 || true
}
install_stack(){
  prep_userns
  if [ ! -x /usr/bin/flatpak ]; then
    apt-get update -qq >>"$LOG" 2>&1 || true
    DEBIAN_FRONTEND=noninteractive apt-get install -y -qq --no-install-recommends \
      flatpak bubblewrap >>"$LOG" 2>&1 || true
    DEBIAN_FRONTEND=noninteractive apt-get install -y -qq --no-install-recommends \
      proot xdg-desktop-portal xdg-desktop-portal-gtk >>"$LOG" 2>&1 || true
    [ -x /usr/bin/flatpak ] || return 1
  fi
  prep_userns
  /usr/bin/flatpak remote-add --user --if-not-exists flathub \
    https://flathub.org/repo/flathub.flatpakrepo >>"$LOG" 2>&1 || return 1
}

install_target(){
  install_stack || return 1
  case "$TARGET" in
    appstream://*)
      APP="${TARGET#appstream://}"; APP="${APP%%\?*}"
      [[ "$APP" =~ ^[A-Za-z0-9._-]+$ ]] || return 2
      echo "$APP" > "$APPFILE"
      /usr/bin/flatpak install --user -y --noninteractive --or-update flathub "$APP" >>"$LOG" 2>&1
      ;;
    https://*)
      TMP=$(mktemp /tmp/browser-app-XXXXXX.flatpakref)
      curl -fL --retry 4 --connect-timeout 20 --max-time 300 "$TARGET" -o "$TMP" >>"$LOG" 2>&1 || return 3
      grep -Eq '^\[(Flatpak Ref|Flatpak Repo)\]' "$TMP" || return 4
      grep -m1 '^Name=' "$TMP" | cut -d= -f2 > "$APPFILE" 2>/dev/null || true
      /usr/bin/flatpak install --user -y --noninteractive --or-update "$TMP" >>"$LOG" 2>&1
      ;;
    *.flatpakref|*.flatpakrepo)
      [ -f "$TARGET" ] || return 5
      grep -m1 '^Name=' "$TARGET" | cut -d= -f2 > "$APPFILE" 2>/dev/null || true
      /usr/bin/flatpak install --user -y --noninteractive --or-update "$TARGET" >>"$LOG" 2>&1
      ;;
    *) return 6 ;;
  esac
}

(
  echo 5; echo '# Preparing Flatpak...'
  install_target
  RC=$?
  echo "$RC" > "$STATUS"
  [ "$RC" -eq 0 ] && { echo 100; echo '# Installed successfully'; }
) | zenity --progress --title="Install application" --pulsate --auto-close \
      --no-cancel --width=430 2>/dev/null

RC=$(cat "$STATUS" 2>/dev/null || echo 99)
if [ "$RC" -eq 0 ]; then
  mkdir -p /root/.config /root/.local/share/applications
  /usr/bin/flatpak list --user --app --columns=application 2>/dev/null \
    | sed '/^$/d' | sort -u > /root/.config/flatpak-apps.txt
  /usr/local/bin/refresh-flatpak-launchers >/dev/null 2>&1 || true
  NEWAPP=$(cat "$APPFILE" 2>/dev/null || true)
  if [[ "$NEWAPP" =~ ^[A-Za-z0-9._-]+$ ]]; then
    /usr/local/bin/flatpak-run-compatible "$NEWAPP" >/tmp/flatpak-autostart.log 2>&1 &
  fi
  zenity --info --title="Installed" \
    --text="The application was installed successfully and added to the applications menu." \
    --width=430 2>/dev/null
else
  # v79: لا نتوقف عند فشل Flatpak: نمرّر الطلب للمسار المرن (flathub-install)
  # الذي يُعيد المحاولة ثم يجرّب مستودع Ubuntu، ويُري رسالة عربية واضحة دائمًا.
  ALT=$(cat "$APPFILE" 2>/dev/null || true)
  [ -n "$ALT" ] || ALT="$TARGET"
  if [ -x /usr/local/bin/flathub-install ] && \
     /usr/local/bin/flathub-install "$ALT" >>"$LOG" 2>&1; then
    RC=0
  else
    zenity --error --title="فشل التثبيت" \
      --text="لم يكتمل التثبيت. التفاصيل في: $LOG
جرّب من الطرفية: flathub-install <معرّف التطبيق>" --width=470 2>/dev/null
  fi
fi
exit "$RC"
"""
with open("/usr/local/bin/flatpakref-handler", "w") as f:
    f.write(_flatref_sh)
run("chmod +x /usr/local/bin/flatpakref-handler")
# >>> v79: مسار تثبيت مرن ومُشخّص من Flathub (يعمل من المتصفّح ومن الأيقونة
#     ومن الطرفية): يرفع حدود user-namespaces قدر الممكن، يركّب flathub،
#     يُثبّت، وإن تعذّر Flatpak داخل الحاوية يُجرّب مستودع Ubuntu تلقائيًا،
#     وفي كل الحالا�� يُظهر نتيجة واضحة بالعربية بدل الصمت. <<<
_FLATHUB_INSTALL_SH = r'''#!/bin/bash
# flathub-install: تثبيت تطبيق من Flathub بمعرّفه أو برابطه، مع تشخيص واضح
# ومسار بديل تلقائي عبر apt عندما يتعذّر Flatpak داخل حاوية Colab.
set -u
LOG=/tmp/flathub-install.log
DISPLAY="${DISPLAY:-:1}"
export DISPLAY

note(){ printf '%b\n' "$*"; }
gui(){ command -v zenity >/dev/null 2>&1 && [ -n "${DISPLAY:-}" ]; }
info(){ local m; m=$(printf '%b' "$*"); if gui; then zenity --info --width=470 --title="Flathub" --text="$m" >/dev/null 2>&1; else note "$m"; fi; }
errbox(){ local m; m=$(printf '%b' "$*"); if gui; then zenity --error --width=470 --title="Flathub" --text="$m" >/dev/null 2>&1; else note "$m"; fi; }

prep_userns(){
  sysctl -w kernel.unprivileged_userns_clone=1 >>"$LOG" 2>&1 || true
  sysctl -w user.max_user_namespaces=15000 >>"$LOG" 2>&1 || true
  [ -x /usr/bin/bwrap ] && chmod u+s /usr/bin/bwrap >>"$LOG" 2>&1 || true
}

ensure_stack(){
  prep_userns
  if [ ! -x /usr/bin/flatpak ]; then
    note "[i] تثبيت Flatpak لأول مرة..."
    apt-get update -qq >>"$LOG" 2>&1 || true
    DEBIAN_FRONTEND=noninteractive apt-get install -y -qq --no-install-recommends \
      flatpak bubblewrap >>"$LOG" 2>&1 || true
  fi
  [ -x /usr/bin/flatpak ] || return 1
  /usr/bin/flatpak remote-add --user --if-not-exists flathub \
    https://flathub.org/repo/flathub.flatpakrepo >>"$LOG" 2>&1 || return 2
  return 0
}

# يستخرج معرّف التطبيق من: appid | رابط flathub | رابط/ملف flatpakref
parse_app(){
  local t="$1"
  case "$t" in
    flatpak+*) t="${t#flatpak+}" ;;
  esac
  case "$t" in
    appstream://*) t="${t#appstream://}"; t="${t%%\?*}" ;;
    *flathub.org/apps/*)
      t="${t##*/apps/}"; t="${t%%\?*}"; t="${t%/}"
      case "$t" in
        */*) t="${t##*/}" ;;
      esac ;;
    *.flatpakref)
      local n=""
      if [ -f "$t" ]; then
        n=$(grep -m1 '^Name=' "$t" 2>/dev/null | cut -d= -f2)
      else
        n=$(curl -fsL --connect-timeout 15 --max-time 60 "$t" 2>>"$LOG" \
            | grep -m1 '^Name=' | cut -d= -f2)
      fi
      [ -n "$n" ] && t="$n" ;;
  esac
  printf '%s' "$t"
}

apt_fallback(){
  local app="$1" short pkg
  short=$(printf '%s' "$app" | awk -F. '{print tolower($NF)}')
  [ -n "$short" ] || return 1
  case "$short" in
    [A-Za-z0-9+._-]*) : ;;
    *) return 1 ;;
  esac
  pkg=$(apt-cache policy "$short" 2>/dev/null | head -n1 | cut -d: -f1)
  [ -n "$pkg" ] || return 1
  note "[i] محاولة بديلة من مستودع Ubuntu: $pkg"
  DEBIAN_FRONTEND=noninteractive apt-get install -y -qq "$pkg" >>"$LOG" 2>&1 || return 1
  /usr/local/bin/refresh-app-menu >/dev/null 2>&1 || true
  return 0
}

ask_target(){
  gui || return 1
  zenity --entry --width=470 --title="تثبيت من Flathub" \
    --text="اكتب معرّف التطبيق أو الصق رابط صفحته في Flathub:" \
    --entry-text="page.codeberg.snensmens.Chapterize" 2>/dev/null
}

TARGET="${1:-}"
if [ -z "$TARGET" ]; then
  TARGET=$(ask_target) || TARGET=""
  [ -n "$TARGET" ] || { note "الاستخدام: flathub-install <معرّف التطبيق | رابط Flathub>"; exit 2; }
fi

: > "$LOG"
APP=$(parse_app "$TARGET")
case "$APP" in
  [A-Za-z0-9][A-Za-z0-9._-]*) : ;;
  *) errbox "لم أتعرّف على معرّف التطبيق من: $TARGET"; exit 2 ;;
esac
note "[i] التطبيق: $APP"

ensure_stack; RC=$?
if [ "$RC" -ne 0 ]; then
  if apt_fallback "$APP"; then
    info "تعذّر تجهيز Flatpak داخل Colab، لكن تم تثبيت التطبيق من مستودع Ubuntu ✅\nستجده في قائمة التطبيقات."
    exit 0
  fi
  errbox "تعذّر تجهيز Flatpak داخل هذه الجلسة.\nالتفاصيل: $LOG\n\nالبديل الموثوق: نزّل ملف .deb أو AppImage من موقع البرنامج ثم انقره نقرة مزدوجة."
  exit 1
fi

run_install(){
  /usr/bin/flatpak install --user -y --noninteractive --or-update flathub "$APP" >>"$LOG" 2>&1
}

if gui; then
  (
    echo 10; echo "# جارٍ التثبيت من Flathub: $APP"
    run_install; echo $? > /tmp/.flathub-install.rc
    echo 100
  ) | zenity --progress --pulsate --auto-close --no-cancel --width=470 \
        --title="تثبيت من Flathub" 2>/dev/null
  IRC=$(cat /tmp/.flathub-install.rc 2>/dev/null || echo 1)
else
  run_install; IRC=$?
fi

if [ "${IRC:-1}" -eq 0 ]; then
  /usr/bin/flatpak list --user --app --columns=application 2>/dev/null \
    | sed '/^$/d' | sort -u > /root/.config/flatpak-apps.txt 2>/dev/null || true
  /usr/local/bin/refresh-flatpak-launchers >/dev/null 2>&1 || true
  /usr/local/bin/refresh-app-menu >/dev/null 2>&1 || true
  BW="يعمل"
  /usr/bin/bwrap --dev-bind / / true >/dev/null 2>&1 || BW="غير متاح"
  if [ "$BW" = "يعمل" ]; then
    info "تم تثبيت $APP بنجاح ✅\nستجده في قائمة التطبيقات."
    /usr/local/bin/flatpak-run-compatible "$APP" >>/tmp/flatpak-autostart.log 2>&1 &
  else
    info "تم تنزيل $APP وتثبيته ✅\nملاحظة: عزل bubblewrap غير متاح في هذه الحاوية، لذا سيُشغَّل التطبيق بوضع التوافق (بلا صندوق رمل)."
    /usr/local/bin/flatpak-run-compatible "$APP" >>/tmp/flatpak-autostart.log 2>&1 &
  fi
  exit 0
fi

if apt_fallback "$APP"; then
  info "تعذّر تثبيت نسخة Flathub، لكن تم تثبيت التطبيق من مستودع Ubuntu ✅\nستجده في قائمة التطبيقات."
  exit 0
fi
errbox "فشل التثبيت من Flathub ولا يوجد بديل في مستودع Ubuntu.\nآخر 12 سطرًا من السجل:\n$(tail -n 12 "$LOG" 2>/dev/null | sed 's/&/\&amp;/g;s/</\&lt;/g')\n\nالسجل الكامل: $LOG"
exit 1
'''
try:
    with open("/usr/local/bin/flathub-install", "w") as f:
        f.write(_FLATHUB_INSTALL_SH)
    os.chmod("/usr/local/bin/flathub-install", 0o755)
    _flathub_desktop = (
        "[Desktop Entry]\nVersion=1.0\nType=Application\n"
        "Name=Install from Flathub\n"
        "Name[ar]=🛍️ تثبيت تطبيق من Flathub\n"
        "Comment[ar]=الصق رابط صفحة التطبيق أو معرّفه وسيُثبَّت مع بديل تلقائي\n"
        "Exec=/usr/local/bin/flathub-install\nTerminal=false\n"
        "Icon=system-software-install\nCategories=System;Settings;\n")
    for _d in ("/usr/share/applications", "/root/Desktop"):
        try:
            os.makedirs(_d, exist_ok=True)
            _p = os.path.join(_d, "flathub-install.desktop")
            with open(_p, "w") as f:
                f.write(_flathub_desktop)
            os.chmod(_p, 0o755)
        except Exception:
            pass
    _diag_event("flathub_install_write")
except Exception as _fh_err:
    _diag_event("flathub_install_write_failed")
    print("[!] تعذّر كتابة مسار Flathub المرن: %s" % _fh_err)

_flatref_desktop = """[Desktop Entry]
Type=Application
Name=Flatpak / Flathub Installer
Name[ar]=مثبّت تطبيقات Flathub
Exec=/usr/local/bin/flatpakref-handler %u
Terminal=false
NoDisplay=true
StartupNotify=true
MimeType=application/vnd.flatpak.ref;application/vnd.flatpak;application/vnd.flatpak.repo;x-scheme-handler/flatpak+https;x-scheme-handler/appstream;
"""
with open("/usr/share/applications/flatpakref-handler.desktop", "w") as f:
    f.write(_flatref_desktop)

