def start_audio():
    run("pkill -9 pulseaudio")
    time.sleep(1)
    run("rm -f %s" % PULSE_SERVER)
    # setsid: عملية مفصولة تمامًا (لا تموت بإغلاق المتصفح أو الطرفية)
    _pa_env=dict(os.environ,PULSE_SERVER="unix:"+PULSE_SERVER)
    subprocess.Popen(["pulseaudio","--exit-idle-time=-1","--disable-shm=true",
        "--load=module-native-protocol-unix socket=%s auth-anonymous=1"%PULSE_SERVER,
        "--load=module-null-sink sink_name=virtual_speaker sink_properties=device.description=Virtual_Speaker",
        "--load=module-always-sink","--log-target=stderr"],shell=False,
        stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,start_new_session=True,env=_pa_env)
    time.sleep(3)
    # virtual_speaker هو الوجهة الافتراضية؛ أي صوت يُشغَّل يذهب إليه،
    # و parec يلتقطه من virtual_speaker.monitor ويبثّه للمتصفح.
    run("PULSE_SERVER=unix:%s pactl set-default-sink virtual_speaker"
        % PULSE_SERVER)
    # نضمن أن مستوى الصوت 100% وغير مكتوم
    run("PULSE_SERVER=unix:%s pactl set-sink-volume virtual_speaker 100%%"
        % PULSE_SERVER)
    run("PULSE_SERVER=unix:%s pactl set-sink-mute virtual_speaker 0"
        % PULSE_SERVER)
    # متغيّرات بيئة عامة كي تستخدم كل التطبيقات هذا الخادم الصوتي
    os.environ["PULSE_SERVER"] = "unix:" + PULSE_SERVER

def _hard_cleanup_display():
    """تنظيف قسري كامل لجلسة العرض :1 — يزيل كل قفل/PID عالق يمنع البدء.

    السبب الجذري لـ 'A VNC server is already running as :1' هو بقاء ملفات
    القفل (/tmp/.X1-lock) و PID (~/.vnc/*:1.pid) بعد سقوط الخادم دون تنظيف.
    نحذفها كلها قسريًا قبل كل تشغيل حتى يبدأ الخادم دائمًا بلا تعارض.
    """
    # 1) اقتل أي خادم Xvnc/kasmvnc قديم بالقوة
    run("pkill -9 -f Xvnc 2>/dev/null")
    run("pkill -9 -f kasmvnc 2>/dev/null")
    run("pkill -9 -f Xtigervnc 2>/dev/null")
    # 2) محاولة الإيقاف الرسمية (قد تفشل بصمت لو الـ PID عالق)
    _kill_launcher = get_vncserver_path()
    if _kill_launcher:
        run("'%s' -kill %s > /dev/null 2>&1" % (_kill_launcher, DISPLAY_NUM))
    time.sleep(1)
    # 3) *** الأهم: احذف كل ملفات القفل والـ PID العالقة قسريًا ***
    run("rm -f /tmp/.X1-lock /tmp/.X11-unix/X1 2>/dev/null")
    run("rm -f /root/.vnc/*:1.pid 2>/dev/null")
    run("rm -f /root/.vnc/*.pid 2>/dev/null")
    run("rm -f /root/.vnc/*.log.old 2>/dev/null")
    # قفل خاص بـ KasmVNC نفسه
    run("rm -f /root/.vnc/*_1.pid 2>/dev/null")
    run("rm -rf /tmp/.X11-unix/X1 2>/dev/null")
    time.sleep(1)


def start_kasm():
    # لا نسمح للمشغّل بالبدء قبل وجود الاسم ��لذي يطلبه حرفيًا.
    if not _ensure_kasm_runtime():
        raise RuntimeError("KasmVNC غير مكتمل؛ ملفات التشغيل المفقودة: %s"
                           % (", ".join(_kasm_missing_runtime()) or "غير معروفة"))
    # تنظيف قسري كامل (يزيل قفل :1 العالق — الإصلاح الجوهري للاستقرار)
    _hard_cleanup_display()
    # ضمان Xauthority
    run("touch /root/.Xauthority && chmod 600 /root/.Xauthority")
    # ضمان تخطّي سؤال DE في كل تشغيل (الإصلاح الجوهري)
    run("mkdir -p /root/.vnc && touch /root/.vnc/.de-was-selected")
    # ===========================================================
    # *** الإصلاح: أمر تشغيل نظيف وموثوق 100% ***
    #   - أزلنا `nice -n -5` نهائيًا: يفشل في Colab (Permission denied) و��ان
    #     يفسد الأمر المركّب فيمرّر --version للخادم → Fatal server error.
    #   - أزلنا ا��خيارات CLI غير المدعومة (-websocketPort/-interface) من
    #     المسار الأساسي: كل الإعدادات في kasmvnc.yaml (الصدر الموثوق).
    #   - .de-was-selected يتخطّى select-de تمامًا (لا سؤال DE).
    #   - XFCE يأتي من xstartup. setsid: عملية مفصولة لا تموت بإغلاق المتصفح.
    # ===========================================================
    _kasm_env=dict(os.environ,HOME="/root",USER="root",PULSE_SERVER="unix:"+PULSE_SERVER,
                   XDG_RUNTIME_DIR="/tmp",XAUTHORITY="/root/.Xauthority")
    _vnc_launcher = get_vncserver_path()
    if not _vnc_launcher:
        raise RuntimeError(
            "تثبيت KasmVNC غير مكتمل: لا vncserver ولا kasmvncserver قابل للتنفيذ"
        )
    with open(KASM_LOG,"ab",buffering=0) as _klog:
        # المنفذ والواجهة موجودان أصلًا في kasmvnc.yaml. عدم تمريرهما هنا
        # يمنع تعارض wrapper/binary بين إصدارات KasmVNC المختلفة.
        _proc = subprocess.Popen(
            [_vnc_launcher, DISPLAY_NUM,
             "-geometry", "%dx%d" % (SCREEN_W, SCREEN_H),
             "-depth", str(DEPTH)],
            shell=False, env=_kasm_env, stdin=subprocess.DEVNULL,
            stdout=_klog, stderr=subprocess.STDOUT, start_new_session=True)
    return _proc


# ============================================================
# 6.5) *** الإصلاح الجوهري: بروكسي يحقن المصادقة (HTTP + WebSocket) ***
# ============================================================
# لماذا؟ KasmVNC 1.4.0 يفرض Basic Auth حتى على اتصال WebSocket. والمتصفحات
# الحديثة على الجوال تتجاهل user:pass@host عند فتح wss:// فيُرفض الاتصال
# ويظهر "Failed to connect to server". هذا البروكسي يجلس أمام KasmVNC،
# ويضيف ترويسة Authorization: Basic إلى كل طلب (بما فيه ترقية WebSocket)،
# فيفتح الهاتفُ الرابطَ بلا أي مصادقة ويعمل كل شيء. (مُختبَر: 101 Switching
# Protocols + Sec-WebSocket-Accept).
import base64 as _b64

_PROXY_AUTH = _b64.b64encode(
    ("%s:%s" % (VNC_USER, VNC_PASS)).encode("latin-1")
).decode("ascii")


def _proxy_inject_auth(head):
    """يضيف/يستبدل ترويسة Authorization داخل رؤوس HTTP الواردة."""
    try:
        sep = b"\r\n\r\n"
        if sep not in head:
            return head
        headers_part, body = head.split(sep, 1)
        lines = headers_part.split(b"\r\n")
        request_line = lines[0]
        rest = [ln for ln in lines[1:]
                if not ln.lower().startswith(b"authorization:")]
        auth_line = ("Authorization: Basic " + _PROXY_AUTH).encode("latin-1")
        return b"\r\n".join([request_line] + rest + [auth_line]) + sep + body
    except Exception:
        return head


def _proxy_tune(sock):
    """تحسينات السرعة: TCP_NODELAY + مخازن كبيرة (للسرعة العالية).

    >>> أقصى سرعة: مخازن 8 ميجابايت (بدل 4) — تسمح بدفعات أكبر عبر النفق
        دون انتظار ACK، فيمتلئ عرض النطاق المتاح بالكامل. <<<"""
    try:
        sock.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)
        _buf = 4 * 1024 * 1024 if FAST_NETWORK else 8 * 1024
        sock.setsockopt(socket.SOL_SOCKET, socket.SO_RCVBUF, _buf)
        sock.setsockopt(socket.SOL_SOCKET, socket.SO_SNDBUF, _buf)
        sock.setsockopt(socket.SOL_SOCKET, socket.SO_KEEPALIVE, 1)
        _notsent=getattr(socket,"TCP_NOTSENT_LOWAT",None)
        if _notsent is not None:sock.setsockopt(socket.IPPROTO_TCP,_notsent,2048)
        for _opt, _val in ((getattr(socket, "TCP_KEEPIDLE", None), 20),
                           (getattr(socket, "TCP_KEEPINTVL", None), 10),
                           (getattr(socket, "TCP_KEEPCNT", None), 3)):
            if _opt is not None:
                sock.setsockopt(socket.IPPROTO_TCP, _opt, _val)
    except Exception:
        pass


_TRAFFIC_LOCK = threading.Lock()
_TRAFFIC = {"up":0,"down":0,"sample_up":0,"sample_down":0,
            "sample_at":time.time(),"started_at":time.time(),"connections":0,
            "accepted":0,"rejected":0,"slow_writes":0}
MAX_PROXY_CONNECTIONS = _env_int_bounded("MAX_PROXY_CONNECTIONS", 32, 4, 128)
_PROXY_CONNECTION_SLOTS=threading.BoundedSemaphore(MAX_PROXY_CONNECTIONS)

class _StrictSharedEgress:
    """موفّر race-to-idle: متوسط صارم، ورصيد الخمول يسرّع نتيجة اللمس فقط."""
    def __init__(self,kbps):
        self.unlimited = float(kbps) <= 0
        self.rate=max(1024.0,float(kbps)*1024.0) if not self.unlimited else 1024.0
        self.capacity=self.rate*0.20      # 200ms فقط: لا طابور محسوس على وصلة الهاتف
        self.tokens=self.rate*0.08       # بدء هادئ
        self.peak=self.rate*1.15         # ذروة قصيرة لا تتجاوز هامش الوصلة
        self.last=time.monotonic()
        self.peak_next=self.last
        self.lock=threading.Lock()
        self.boost_until=0.0             # v108: نافذة إقلاع لكل اتصال جديد
        self.boost_rate=self.rate
    def kickstart(self,seconds=1.0,mult=1.12):
        """دفعة اتصال محدودة في الوضع المقيد؛ fast network لا يستخدم token bucket."""
        if self.unlimited:return
        with self.lock:
            now=time.monotonic()
            self.tokens=self.capacity
            self.boost_rate=self.rate*mult
            self.boost_until=now+seconds
            self.peak_next=now
    def wait(self,nbytes):
        if self.unlimited or nbytes<=0:return
        need=float(nbytes)
        while True:
            with self.lock:
                now=time.monotonic()
                rate_now=self.boost_rate if now<self.boost_until else self.rate
                elapsed=max(0.0,now-self.last)
                self.tokens=min(self.capacity,self.tokens+elapsed*rate_now)
                self.last=now
                token_delay=max(0.0,(need-self.tokens)/rate_now)
                peak_slot=max(now,self.peak_next)
                peak_delay=peak_slot-now
                if now<self.boost_until:peak_delay=0.0  # v108: لا كبح ذروة أثناء الإقلاع
                delay=max(token_delay,peak_delay)
                if delay<=0.0005:
                    self.tokens=max(0.0,self.tokens-need)
                    self.peak_next=peak_slot+(need/self.peak)
                    return
            time.sleep(min(delay,0.05))

_STRICT_EGRESS=_StrictSharedEgress(HARD_EGRESS_CAP_KBPS)
_STRICT_EGRESS_CHUNK=262144 if FAST_NETWORK else 2048

def _egress_send(sock,data,count=True):
    """يرسل قطعًا صغيرة موزعة زمنيًا؛ لا دفعات تتجاوز السقف ولو تحرك فيديو."""
    view=memoryview(data)
    for off in range(0,len(view),_STRICT_EGRESS_CHUNK):
        part=view[off:off+_STRICT_EGRESS_CHUNK]
        _STRICT_EGRESS.wait(len(part))
        sock.sendall(part)
        if count:
            with _TRAFFIC_LOCK:_TRAFFIC["down"]+=len(part)

def _proxy_pipe(src,dst,direction=""):
    try:
        chunk_size=262144 if FAST_NETWORK else (16384 if direction=="up" else 2048)
        while True:
            data=src.recv(chunk_size)
            if not data:break
            started=time.monotonic()
            if direction=="down":
                _egress_send(dst,data,count=True)
            else:
                dst.sendall(data)
                with _TRAFFIC_LOCK:_TRAFFIC["up"]+=len(data)
            elapsed=time.monotonic()-started
            with _TRAFFIC_LOCK:
                if elapsed>2.0:_TRAFFIC["slow_writes"]+=1
            if elapsed>5.0 and direction!="down":_diag_event("proxy_backpressure_"+direction)
    except Exception as exc:
        _diag_event("proxy_pipe_"+str(direction),exc)
    finally:
        for sock in (src,dst):
            try:sock.shutdown(socket.SHUT_RDWR)
            except Exception:pass


# ------------------------------------------------------------
# الصوت: KClient مبسّط بـ Python — يلتقط من PulseAudio (parec) ويبثّ
# PCM للمتصفح عبر WebSocket. صفحة wrapper تضع KasmVNC دال iframe وتشغّل
# الصوت تلقائيًا (مع زر «تفعيل الصوت» لتجاوز سياسة autoplay في المتصفح).
# ------------------------------------------------------------
import hashlib as _hashlib
import struct as _struct

_WS_MAGIC = "258EAFA5-E914-47DA-95CA-C5AB0DC85B11"


def _ws_accept_key(client_key):
    return _b64.b64encode(
        _hashlib.sha1((client_key + _WS_MAGIC).encode()).digest()
    ).decode()


def _ws_send(sock, data, opcode=0x2):
    """يرسل إطار WebSocket (binary افتراضيًا) — بدون قناع (من الخادم)."""
    n = len(data)
    hdr = bytearray([0x80 | opcode])
    if n < 126:
        hdr.append(n)
    elif n < 65536:
        hdr.append(126); hdr += _struct.pack(">H", n)
    else:
        hdr.append(127); hdr += _struct.pack(">Q", n)
    _egress_send(sock, bytes(hdr) + data, count=True)


def _parse_headers(head):
    # نحلّل منطقة الرؤوس فقط (قبل أول CRLFCRLF). مهم جدًا لطلبات POST
    # متعددة الأجزاء: جسم multipart نفسه حتوي على أسطر "Content-Type"
    # و "Content-Length" داخلية يجب ألّا تُخلط برؤوس الطلب الحقيقية،
    # وإلّا يُقرأ نوع المحتوى الخاطئ (مثل image/jpeg) فيفشل تحليل الرفع.
    out = {}
    try:
        sep = b"\r\n\r\n"
        hsec = head.split(sep, 1)[0] if sep in head else head
        for ln in hsec.split(b"\r\n")[1:]:
            if b":" in ln:
                k, v = ln.split(b":", 1)
                out[k.strip().lower().decode("latin-1")] = \
                    v.strip().decode("latin-1")
    except Exception:
        pass
    return out


def _handle_audio_ws(client, head):
    """يرقّ�� إلى WebSocket ويبثّ صوت PulseAudio (PCM s16le ستيريو).

    >>> ��صلاح الاستهلاك المستمر بعد إغلاق الفيديو/المتصفح:
        سابقًا كان يبثّ PCM خام 44100×2×2 = ~176KB/s *باستمرار* حتى أثناء
        الصمت التامّ (الـ monitor يُنتج أصفارًا بلا توقّف) — هذا هو سبب
        «الاستهلاك الباقي بعد إغلاق الفيديو». الإصلاحان:
        1) بوابة الصمت: نف��ص كل دفعة؛ لو صامتة (سعة ≈ صفر) لا نرسل شيئًا
           إطلاقًا (بعد إرسال دفعة صمت واحدة قصيرة لتفريغ مخزن المتصفح).
           → أثناء الصمت = صفر بايت عبر الشبكة.
        2) معدّل عينات حسب وضع الش��كة (AUDIO_RATE): في وضع التوفير
           24kHz بدل 44.1kHz → ~96KB/s بدل 176KB/s أثناء التشغيل الفعلي
           فقط (جودة ممتازة لكلام/يوتيوب على الهاتف). <<<"""
    hdrs = _parse_headers(head)
    key = hdrs.get("sec-websocket-key")
    if not key:
        client.close(); return
    resp = (
        "HTTP/1.1 101 Switching Protocols\r\n"
        "Upgrade: websocket\r\nConnection: Upgrade\r\n"
        "Sec-WebSocket-Accept: %s\r\n\r\n" % _ws_accept_key(key)
    )
    client.sendall(resp.encode())
    # parec يقرأ من الـ monitor الخاص بالـ sink الافتراضي
    # Round 10: latency أكبر قليلًا (120ms) = حزم أكبر وأقل عددًا → بثّ صوتي
    # أكثر استقرارًا عبر النفق (يقلّل احتمالية «التقطيع» الناتج عن الازدحام).
    # >>> وضع التوفير الفائق: مونو 16kHz (AUDIO_CHANNELS=1) = 32KB/s بدل
    #     96KB/s — المتصفح يعرف عدد القنوات عبر __AUDIO_CH__ المحقون. <<<
    _frame_bytes = 2 * AUDIO_CHANNELS   # s16le: 2 بايت × عدد القنوات
    _parec_env=dict(os.environ,PULSE_SERVER="unix:"+PULSE_SERVER)
    parec=subprocess.Popen(["parec","--format=s16le","--rate=%d"%AUDIO_RATE,
        "--channels=%d"%AUDIO_CHANNELS,"--latency-msec=%d"%AUDIO_LATENCY_MS,
        "-d","virtual_speaker.monitor"],shell=False,env=_parec_env,
        stdout=subprocess.PIPE,stderr=subprocess.DEVNULL,start_new_session=True)
    # نقرأ بأحجام مضاعفة ل 4 بايت (إطار ستيريو s16le = 4 بايت) لضمان
    # محاذاة Int16Array اثنائية في المتصفح.
    # بوابة الصمت: عتبة سعة صغيرة (تسمح بضجيج أرضي رقمي بسيط دون اعتباره صوتًا)
    SILENCE_AMP = 12        # من 32768 — أقل منها = صمت فعلي
    silent_run = 0          # عدد الدفعات الصامتة المتتالية
    SILENT_FLUSH = 3        # نرسل أول 3 دفعات صامتة (لتفريغ ذيل الصوت) ثم نصمت
    try:
        import array as _arr
        while True:
            chunk = parec.stdout.read(8192)
            if not chunk:
                break
            extra = len(chunk) % _frame_bytes
            if extra:
                pad = parec.stdout.read(_frame_bytes - extra)
                if pad:
                    chunk += pad
            # فحص الصمت: أقصى سعة مطلقة في الدفعة
            samples = _arr.array("h")
            samples.frombytes(chunk[: len(chunk) - (len(chunk) % 2)])
            peak = max(max(samples), -min(samples)) if len(samples) else 0
            if peak <= SILENCE_AMP:
                silent_run += 1
                if silent_run > SILENT_FLUSH:
                    continue     # صمت مستقرّ → صفر بايت عبر الشبكة
            else:
                silent_run = 0
            _ws_send(client, chunk, opcode=0x2)
    except Exception:
        pass
    finally:
        try:
            parec.kill()
        except Exception:
            pass
        try:
            client.close()
        except Exception:
            pass


