_FILE_BROWSER_VIRTUAL_DIRS = {"proc", "sys", "dev", "run"}
MAX_REQUEST_BODY = _env_int_bounded("MAX_UPLOAD_MB", 64, 1, 512) * 1024 * 1024
# رمز جلسة عشوائي قصير العمر لماية حذف لفات PhoneFiles (CSRF) — يُحقن في
# صفحة wrapper فقط ويُطلب في رأس طلب /_delete. لا نسجّل يمته في أي سجل.
