def _safe_join(base, rel):
    """يمنع traversal والخروج عبر الروابط الرمزية بإحكام."""
    base = os.path.realpath(base)
    rel = _urlparse.unquote(rel or "")
    if "\x00" in rel:
        return base
    p = os.path.realpath(os.path.join(base, rel.lstrip("/")))
    try:
        if os.path.commonpath([base, p]) != base:
            return base
    except ValueError:
        return base
    return p


def _read_request_body(client, head):
    """يقرأ جسم طلب POST بالكامل اعتمادًا على Content-Length."""
    hdrs = _parse_headers(head)
    try:
        clen = int(hdrs.get("content-length", "0"))
    except Exception:
        raise ValueError("Content-Length غير صالح")
    if clen < 0 or clen > MAX_REQUEST_BODY:
        raise ValueError("حجم الطلب يتجاوز الحد المسموح")
    sep = b"\r\n\r\n"
    body = head.split(sep, 1)[1] if sep in head else b""
    while len(body) < clen:
        chunk = client.recv(min(262144, clen - len(body)))
        if not chunk:
            break
        body += chunk
    return body, hdrs


def _handle_files_list(client, query):
    """ير��ع JSON بمحتويات مجلد (للتصفّح من لوحة الملفات)."""
    qs = _urlparse.parse_qs(query)
    rel = qs.get("path", [""])[0]
    target = _safe_join(_FILES_ROOT, rel)
    items = []
    # هل المجلد المعروض حاليًّا هو PhoneFiles نفسه؟ (يحدّد إظهار زر الحذف)
    try:
        is_phonedir = (os.path.realpath(target)
                       == os.path.realpath(_PHONE_UPLOAD_DIR))
    except Exception:
        is_phonedir = False
    try:
        if os.path.isdir(target):
            for name in sorted(os.listdir(target), key=lambda x: (not os.path.isdir(os.path.join(target, x)), x.lower())):
                # لا نعرض ملفات dot الحساسة ولا pseudo-filesystems من /.
                if name.startswith("."):
                    continue
                if os.path.realpath(target) == "/" and name in _FILE_BROWSER_VIRTUAL_DIRS:
                    continue
                full = os.path.join(target, name)
                try:
                    is_link = os.path.islink(full)
                    is_dir = os.path.isdir(full)
                    size = 0 if is_dir else os.path.getsize(full)
                except Exception:
                    is_link = False; is_dir = False; size = 0
                items.append({"name": name, "dir": is_dir,
                              "link": is_link, "size": size})
    except Exception:
        pass
    rel_clean = os.path.relpath(target, _FILES_ROOT)
    if rel_clean == ".":
        rel_clean = ""
    quick = []
    for label, icon, qpath in (("سطح المكتب", "🖥️", "/root/Desktop"),
                               ("التنزيلات", "⬇️", "/root/Downloads"),
                               ("ملفات الهاتف", "📱", _PHONE_UPLOAD_DIR),
                               ("ملفات Colab", "📦", "/content"),
                               ("Google Drive", "☁️", "/content/drive/MyDrive"),
                               ("المجلد الرئيسي", "🏠", "/root")):
        try:
            qreal = os.path.realpath(qpath)
            if os.path.isdir(qreal) and os.path.commonpath([_FILES_ROOT, qreal]) == _FILES_ROOT:
                qrel = os.path.relpath(qreal, _FILES_ROOT)
                quick.append({"label": label, "icon": icon,
                              "path": "" if qrel == "." else qrel})
        except Exception:
            pass
    payload = _json.dumps({"ok": True, "cwd": rel_clean, "items": items,
                           "quick": quick, "phonedir": is_phonedir},
                          ensure_ascii=False).encode("utf-8")
    _serve_local(client, payload, ctype="application/json; charset=utf-8")


def _handle_download(client, query, head=b"", method=b"GET"):
    """Resumable file transfer for Android/Chrome download managers.

    Supports HEAD and single RFC 7233 byte ranges with stable ETag/Last-Modified.
    If the mobile network, browser tab or Cloudflare connection drops, Chrome can
    reconnect with Range and continue from the received byte instead of restarting.
    """
    qs = _urlparse.parse_qs(query)
    rel = qs.get("path", [""])[0]
    target = _safe_join(_FILES_ROOT, rel)

    def _close():
        try: client.close()
        except Exception: pass

    if not os.path.isfile(target):
        body=b"Not Found"
        try: client.sendall(("HTTP/1.1 404 Not Found\r\nContent-Length: %d\r\nConnection: close\r\n\r\n"%len(body)).encode()+body)
        finally: _close()
        return
    try:
        st=os.stat(target);size=int(st.st_size)
        etag='"%x-%x-%x"'%(int(getattr(st,"st_ino",0)),size,int(getattr(st,"st_mtime_ns",int(st.st_mtime*1e9))))
        lastmod=_email_utils.formatdate(st.st_mtime,usegmt=True)
        hdrs=_parse_headers(head) if head else {}
        range_hdr=(hdrs.get("range","") or "").strip()
        if_range=(hdrs.get("if-range","") or "").strip()
        # A stale If-Range must receive the full current file, never mixed bytes.
        if range_hdr and if_range and if_range not in (etag,lastmod):
            range_hdr=""
        start=0;end=max(0,size-1);partial=False
        if range_hdr and size>0:
            m=re.fullmatch(r"bytes=(\d*)-(\d*)",range_hdr,re.I)
            if not m or (not m.group(1) and not m.group(2)):
                start=size
            elif not m.group(1):
                suffix=int(m.group(2));start=max(0,size-suffix);end=size-1;partial=True
            else:
                start=int(m.group(1));end=int(m.group(2)) if m.group(2) else size-1
                end=min(end,size-1);partial=True
            if start>=size or start<0 or end<start:
                resp=("HTTP/1.1 416 Range Not Satisfiable\r\nAccept-Ranges: bytes\r\nContent-Range: bytes */%d\r\nETag: %s\r\nContent-Length: 0\r\nConnection: close\r\n\r\n"%(size,etag)).encode("latin-1")
                client.sendall(resp);_close();return
        length=(end-start+1) if size else 0
        fname=os.path.basename(target).replace("\r","_").replace("\n","_")
        fallback=re.sub(r"[^A-Za-z0-9._-]+","_",fname).strip("._") or "download"
        fname_enc=_urlparse.quote(fname,safe="")
        ctype=_mimetypes.guess_type(fname)[0] or "application/octet-stream"
        status="206 Partial Content" if partial else "200 OK"
        lines=["HTTP/1.1 "+status,
               "Content-Type: "+ctype,
               "Content-Length: %d"%length,
               "Content-Disposition: attachment; filename=\"%s\"; filename*=UTF-8''%s"%(fallback,fname_enc),
               "Accept-Ranges: bytes","ETag: "+etag,"Last-Modified: "+lastmod,
               "Cache-Control: private, no-cache, no-transform",
               "Content-Encoding: identity","X-Content-Type-Options: nosniff",
               "Access-Control-Expose-Headers: Accept-Ranges, Content-Range, Content-Length, ETag",
               "Connection: close"]
        if partial: lines.insert(3,"Content-Range: bytes %d-%d/%d"%(start,end,size))
        client.sendall(("\r\n".join(lines)+"\r\n\r\n").encode("latin-1"))
        if method==b"HEAD" or length<=0:
            _close();return
        try:
            client.setsockopt(socket.SOL_SOCKET,socket.SO_KEEPALIVE,1)
        except Exception:pass
        remain=length
        with open(target,"rb",buffering=0) as f:
            f.seek(start)
            while remain>0:
                chunk=f.read(min(524288,remain))
                if not chunk:break
                client.sendall(chunk);remain-=len(chunk)
    except (BrokenPipeError,ConnectionResetError,TimeoutError,OSError):
        # A disconnect is normal on mobile; the browser retries with Range.
        pass
    except Exception:
        pass
    finally:
        _close()


def _handle_upload(client, head, query):
    """يرفع ملفًا من الهاتف إلى النظام (multipart/form-data)."""
    qs = _urlparse.parse_qs(query)
    rel = qs.get("dir", [""])[0]
    if rel:
        # المستخدم فتح مجلًا بعينه → نرفع إليه
        dest_dir = _safe_join(_FILES_ROOT, rel)
        if not os.path.isdir(dest_dir):
            dest_dir = _PHONE_UPLOAD_DIR
    else:
        # لا مجلد محدّد → نرفع للمجلد الموحّد الواضح (PhoneFiles) ليسهل
        # العثور عليه لاحقًا من مُنتقي الرفع بأي موقع.
        dest_dir = _PHONE_UPLOAD_DIR
    try:
        os.makedirs(dest_dir, exist_ok=True)
    except Exception:
        pass
    body, hdrs = _read_request_body(client, head)
    saved = []
    try:
        ctype = hdrs.get("content-type", "")
        if "boundary=" in ctype:
            boundary = ctype.split("boundary=", 1)[1].strip()
            bmark = ("--" + boundary).encode("latin-1")
            parts = body.split(bmark)
            for part in parts:
                if b"\r\n\r\n" not in part:
                    continue
                phead, pdata = part.split(b"\r\n\r\n", 1)
                if b"filename=" not in phead:
                    continue
                # استخراج اسم الملف
                m = re.search(rb'filename="([^"]*)"', phead)
                if not m:
                    continue
                fname = m.group(1).decode("utf-8", "replace")
                if not fname:
                    continue
                fname = os.path.basename(fname)
                # إزالة \r\n الأخيرة قبل الحدّ التالي
                if pdata.endswith(b"\r\n"):
                    pdata = pdata[:-2]
                outp = _safe_join(dest_dir, fname)
                if os.path.dirname(outp) != os.path.realpath(dest_dir):
                    continue
                flags = os.O_WRONLY | os.O_CREAT | os.O_TRUNC
                if hasattr(os, "O_NOFOLLOW"):
                    flags |= os.O_NOFOLLOW
                fd = os.open(outp, flags, 0o600)
                with os.fdopen(fd, "wb") as f:
                    f.write(pdata)
                saved.append(fname)
    except Exception:
        pass
    payload = _json.dumps({"ok": bool(saved), "saved": saved},
                          ensure_ascii=False).encode("utf-8")
    _serve_local(client, payload, ctype="application/json; charset=utf-8")


def _handle_delete(client, head, query=""):
    """حذف يدوي آمن لملف واحد م�� PhoneFiles فقط. POST حصراً. يق��ل اسم ملف
    نسبيًّا بسيطًا (لا مس��ر مطلق) في جسم JSON {"name": "..."} مع رأس رمز
    الجلسة. التحقق كله في الخادم: الاسم ليس فارغًا ولا يحوي / أو \\ أو ..
    أو null byte؛ والمسار الن��تج عبر realpath يقع مباشرةً داخل
    realpath(_PHONE_UPLOAD_DIR)؛ والعنصر ملف عادي وليس مجلدًا/رابطًا رمزيًّا.
    لا shell ولا rm — os.unlink للملف المتحقق ��نه فقط."""
    def _reply(code, obj):
        body = _json.dumps(obj, ensure_ascii=False).encode("utf-8")
        resp = ("HTTP/1.1 %s\r\nContent-Type: application/json; charset=utf-8"
                "\r\nContent-Length: %d\r\nConnection: close\r\n\r\n"
                % (code, len(body))).encode("latin-1")
        try:
            client.sendall(resp + body)
        finally:
            client.close()
    try:
        body, hdrs = _read_request_body(client, head)
        # تحقّق رمز الجلسة (CSRF) — لا نسجّل قيمته
        tok = hdrs.get("x-delete-token", "")
        if not tok or tok != _DELETE_TOKEN:
            _reply("403 Forbidden", {"ok": False, "reason": "bad_token"})
            return
        try:
            data = _json.loads(body.decode("utf-8", "replace") or "{}")
        except Exception:
            data = {}
        name = data.get("name", "")
        if not isinstance(name, str):
            name = ""
        # 1) الاسم ليس فارغًا ولا يحوي فواصل مسار أو .. أو null byte
        if (not name or "/" in name or "\\" in name or ".." in name
                or "\x00" in name or name in (".", "..")):
            _reply("400 Bad Request", {"ok": False, "reason": "bad_name"})
            return
        base_rp = os.path.realpath(_PHONE_UPLOAD_DIR)
        cand = os.path.join(base_rp, name)
        # لا نتبع ا��روابط الرمزية عند الحسم: نفحص lexists + islink صراحةً
        if not os.path.lexists(cand):
            _reply("404 Not Found", {"ok": False, "reason": "not_found"})
            return
        if os.path.islink(cand):
            _reply("400 Bad Request", {"ok": False, "reason": "is_symlink"})
            return
        # 2) المسار الناتج يقع مباشرةً داخل realpath(PHONEUPLOADDIR)
        cand_rp = os.path.realpath(cand)
        if os.path.dirname(cand_rp) != base_rp:
            _reply("400 Bad Request", {"ok": False, "reason": "outside"})
            return
        # 3) ملف عادي فقط — لا مجلد ولا device ولا symlink
        if not os.path.isfile(cand_rp) or os.path.islink(cand_rp):
            _reply("400 Bad Request", {"ok": False, "reason": "not_file"})
            return
        try:
            os.unlink(cand_rp)
        except FileNotFoundError:
            _reply("200 OK", {"ok": True, "already": True})
            return
        except Exception:
            _reply("500 Internal Server Error",
                   {"ok": False, "reason": "delete_failed"})
            return
        _reply("200 OK", {"ok": True})
    except Exception:
        try:
            _reply("500 Internal Server Error", {"ok": False})
        except Exception:
            pass


_KASM_FAST_CLIENT_CACHE={"at":0.0,"path":"/"}
def _kasm_client_path():
    """اختر vnc_lite.html إن كان KasmVNC يقدمه فعلًا؛ وإلا ارجع للجذر فورًا."""
    now=time.monotonic()
    if _KASM_FAST_CLIENT_CACHE["at"] and now-_KASM_FAST_CLIENT_CACHE["at"]<3600:
        return _KASM_FAST_CLIENT_CACHE["path"]
    chosen="/"
    for cand in ("/vnc_lite.html",):
        sock=None
        try:
            sock=socket.create_connection(("127.0.0.1",VNC_PORT),timeout=1.2)
            req=("GET %s HTTP/1.1\r\nHost: 127.0.0.1:%d\r\n"
                 "Authorization: Basic %s\r\nConnection: close\r\n\r\n"
                 %(cand,VNC_PORT,_PROXY_AUTH)).encode("latin-1")
            sock.sendall(req);sock.settimeout(1.2);head=sock.recv(2048)
            status=head.split(b"\r\n",1)[0]
            if b" 200 " in status:
                chosen=cand;break
        except Exception:
            pass
        finally:
            try:sock.close()
            except Exception:pass
    _KASM_FAST_CLIENT_CACHE.update(at=now,path=chosen)
    return chosen


def _wrapper_html():
    """صفحة wrapper: iframe لـ KasmVNC + ص��ت + كيبورد الجوال + إدارة الملفات.

    نحقن معاملَي جودة/ضغط noVNC ديناميكيًّا حسب وضع الشبكة (مطابق للملف 59)."""
    html = (_WRAPPER_HTML
            .replace("__DELETE_TOKEN__", _DELETE_TOKEN)
            .replace("__VNC_CLIENT_PATH__", _kasm_client_path())
            .replace("__NOVNC_QUALITY__", str(NOVNC_QUALITY))
            .replace("__NOVNC_COMPRESSION__", str(NOVNC_COMPRESSION))
            # >>> أبعاد سطح المكتب الحقيقية — لحساب تمديد إزالة الفراغات
            #     السوداء ند ظهور الكيبورد (scaleX/scaleY في JS) <<<
            .replace("__SCREEN_W__", str(SCREEN_W))
            .replace("__SCREEN_H__", str(SCREEN_H))
            # >>> معدّل عينات الصوت حسب وضع الشبكة (16k فائق/24k توفير/44.1k جودة)
            .replace("__AUDIO_RATE__", str(AUDIO_RATE))
            # >>> عد قنوات الصوت (1 مونو في التوفير الفائق / 2 ستيريو)
            .replace("__AUDIO_CH__", str(AUDIO_CHANNELS))
            .replace("__SERVER_BANDWIDTH__", str(BANDWIDTH_KBPS))
            # >>> مخزن jitter أكبر قليلً على الشبكة الضيقة (يمن التقطيع)
            .replace("__JITTER__", ("0.18" if RESPONSIVE_ECO else
                                    ("0.30" if ULTRA_SAVER else "0.18"))))
    return html.encode("utf-8")


