def _serve_local(client, body, ctype="text/html; charset=utf-8", extra_headers="", status="200 OK"):
    if isinstance(body,str): body=body.encode("utf-8")
    security=("Cross-Origin-Embedder-Policy: require-corp\r\n"
      "Cross-Origin-Opener-Policy: same-origin\r\nX-Content-Type-Options: nosniff\r\n"
      "Referrer-Policy: no-referrer\r\nPermissions-Policy: camera=(),geolocation=(),microphone=()\r\n"
      "Content-Security-Policy: default-src 'self' data: blob:; script-src 'self' 'unsafe-inline'; "
      "style-src 'self' 'unsafe-inline'; img-src 'self' data: blob:; connect-src 'self' ws: wss:; "
      "frame-src 'self'; object-src 'none'; base-uri 'none'; frame-ancestors 'self'\r\n"
      "Cache-Control: no-store, max-age=0\r\nPragma: no-cache\r\n")
    resp=("HTTP/1.1 %s\r\nContent-Type: %s\r\nContent-Length: %d\r\nConnection: close\r\n%s%s\r\n"
          %(status,ctype,len(body),security,extra_headers)).encode("latin-1")
    client.sendall(resp+body);client.close()


def _write_x11_selection_text(text, selection="clipboard"):
    """Replace one X11 selection, wait for ownership/readback, and reject stale data."""
    if not isinstance(text,str):
        return False
    data=text.encode("utf-8")
    env=dict(os.environ,DISPLAY=DISPLAY_NUM,
             XAUTHORITY=os.environ.get("XAUTHORITY","/root/.Xauthority"))
    sel_flag="-b" if selection=="clipboard" else "-p"
    read_cmd=["xsel",sel_flag,"-o"]
    try:
        subprocess.run(["xsel",sel_flag,"-d"],env=env,stdout=subprocess.DEVNULL,
                       stderr=subprocess.DEVNULL,timeout=3)
    except Exception:
        pass
    writers=[["xsel",sel_flag,"-i"]]
    if shutil.which("xclip"):
        writers.append(["xclip","-selection",selection,"-in"])
    for command in writers:
        try:
            proc=subprocess.Popen(command,env=env,stdin=subprocess.PIPE,
                                  stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,
                                  start_new_session=True)
            proc.communicate(input=data,timeout=8)
            if proc.returncode!=0:
                continue
            for _ in range(12):
                time.sleep(0.08)
                check=subprocess.run(read_cmd,env=env,stdout=subprocess.PIPE,
                                     stderr=subprocess.DEVNULL,timeout=3)
                if check.returncode==0 and check.stdout==data:
                    return True
        except Exception:
            continue
    return False


def _read_x11_clipboard_text(limit=1048576):
    """Read UTF-8 clipboard robustly with xsel then xclip and PRIMARY fallback."""
    env=dict(os.environ,DISPLAY=DISPLAY_NUM)
    commands=(["xsel","-b","-o"],
              ["xclip","-selection","clipboard","-o"],
              ["xsel","-p","-o"],
              ["xclip","-selection","primary","-o"])
    for cmd in commands:
        try:
            pr=subprocess.run(cmd,env=env,stdout=subprocess.PIPE,
                              stderr=subprocess.DEVNULL,timeout=4)
            if pr.returncode==0 and pr.stdout:
                raw=pr.stdout[:limit]
                return raw.decode("utf-8","replace").rstrip("\x00")
        except Exception:
            continue
    return ""


def _reply_clip_text(client,text):
    try:
        body=_json.dumps({"ok":bool(text),"text":text},ensure_ascii=False).encode("utf-8")
        _serve_local(client,body,ctype="application/json; charset=utf-8")
    except Exception:
        try:_serve_local(client,b'{"ok":false,"text":""}',ctype="application/json; charset=utf-8")
        except Exception:pass


def _handle_desktop_clip(client):
    """Return the freshest X11 CLIPBOARD/PRIMARY text independently of noVNC."""
    _reply_clip_text(client,_read_x11_clipboard_text())


def _handle_copy_selected(client):
    """Copy active selection, wait for X11 ownership, and return the resulting text."""
    before=_read_x11_clipboard_text()
    try:
        env=dict(os.environ,DISPLAY=DISPLAY_NUM)
        subprocess.run(["xdotool","key","--clearmodifiers","ctrl+c"],env=env,
                       stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,timeout=5)
    except Exception:pass
    text=""
    for delay in (0.12,0.16,0.22,0.30,0.38):
        time.sleep(delay)
        text=_read_x11_clipboard_text()
        if text and (text!=before or delay>=0.30):break
    _reply_clip_text(client,text or before)


_clip_accum = {"buf": ""}
# v29: request receipts prevent duplicate Ctrl+V when a mobile response is lost.
_paste_receipts = {}
_paste_inflight = set()
_paste_receipt_lock = threading.Lock()   # نص تراكمي للّصق المُقسَّم (ذاكرة فقط، بلا قرص)


def _handle_clip(client, head, query=""):
    """Round 21: يستقبل نصًّا (UTF-8) من الهاتف ويضعه في حافظة سطح المكتب
    عبر xsel (‏CLIPBOARD + PRIMARY). حافظة VNC القياسية (clipboardPasteFrom)
    تُرمَّز Latin-1 فتُشوّه العربية — أمّا xsel فيكتب الحافظة بترميز UTF-8
    كامل فيصل النص سليمًا 100%. مع ?append=1 نُلحق الدفعة بالنص السابق
    (لصق مُقسَّم) ونكتب الحافظة بالنص المتراكم الكامل والمرتّب — ذاكرة فقط."""
    try:
        hdr, _, rest = head.partition(b"\r\n\r\n")
        clen = 0
        for line in hdr.split(b"\r\n"):
            if line.lower().startswith(b"content-length:"):
                try:
                    clen = int(line.split(b":", 1)[1].strip())
                except Exception:
                    clen = 0
        if clen < 0 or clen > MAX_REQUEST_BODY:
            raise ValueError("حجم نص الحافظة يتجاوز الحد المسموح")
        body = rest
        while len(body) < clen:
            chunk = client.recv(65536)
            if not chunk:
                break
            body += chunk
        piece = body[:clen].decode("utf-8", "replace")
        append = ("append=1" in query)
        if append:
            _clip_accum["buf"] += piece
        else:
            _clip_accum["buf"] = piece
        text = _clip_accum["buf"]
        ok = False
        if text:
            # يبقى النص في الذاكرة فقط، ولا يُكتب في ملف أو سجل.
            # CLIPBOARD (Ctrl+V) وPRIMARY؛ التحقق بالقراءة يمنع لصق قيمة قديمة.
            ok = _write_x11_selection_text(text, "clipboard")
            _write_x11_selection_text(text, "primary")
        _serve_local(client,
                     b'{"ok":true}' if ok else b'{"ok":false}',
                     ctype="application/json; charset=utf-8")
    except Exception:
        try:
            _serve_local(client, b'{"ok":false}',
                         ctype="application/json; charset=utf-8")
        except Exception:
            pass


def _handle_safe_cleanup(client, query=""):
    """زر «تنظيف مساحة Colab الآمن»: mode=preview يعيد المرشّحات الآمنة فقط
    (لا يحذف شيئًا)، mode=run ينفّذ التنظيف الآمن (بعد تأكيد Zenity الثاني).
    حجم PERSIST_DIR للعرض فقط — القر��ر على عناصر السكربت حصراً."""
    try:
        if "mode=run" in query:
            freed, n = _run_safe_cleanup()
            body = json.dumps({"ok": True, "freed": freed, "count": n},
                              ensure_ascii=False)
        else:
            cands = _cleanup_candidates()
            base = os.path.realpath(PKG_CACHE)
            items = []
            for cat, p, sz in cands[:30]:
                try:
                    rel = os.path.relpath(os.path.realpath(p), base)
                except Exception:
                    rel = os.path.basename(p)
                items.append({"cat": cat, "rel": rel, "size": sz})
            cats = {}
            total = 0
            for cat, _p, sz in cands:
                c = cats.setdefault(cat, {"n": 0, "size": 0})
                c["n"] += 1
                c["size"] += sz
                total += sz
            body = json.dumps({
                "ok": True, "persist_mb": _path_size_mb(PERSIST_DIR),
                "managed_mb": round(_managed_bytes() / 1048576.0, 1),
                "limit_gb": DRIVE_PROJECT_LIMIT_GB,
                "reserve_gb": DRIVE_EMERGENCY_FREE_GB,
                "count": len(cands), "total": total,
                "cats": cats, "items": items}, ensure_ascii=False)
        _serve_local(client, body.encode("utf-8"),
                     ctype="application/json; charset=utf-8")
    except Exception:
        try:
            _serve_local(client, b'{"ok":false}',
                         ctype="application/json; charset=utf-8")
        except Exception:
            pass


def _handle_paste(client, query=""):
    """Idempotent safe paste. A short random rid guarantees that reconnect/retry
    cannot paste the same quick-bar operation twice when the HTTP response is lost."""
    rid = ""
    try:
        rid = _urlparse.parse_qs(query).get("rid", [""])[0][:80]
        if rid and not all(c.isalnum() or c in "-_" for c in rid):
            rid = ""
        if rid:
            now = time.time()
            with _paste_receipt_lock:
                for k, ts in list(_paste_receipts.items()):
                    if now - ts > 900:
                        _paste_receipts.pop(k, None)
                if rid in _paste_receipts:
                    _serve_local(client, b'{"ok":true,"duplicate":true}', ctype="application/json; charset=utf-8")
                    return
                if rid in _paste_inflight:
                    _serve_local(client, b'{"ok":false,"reason":"inflight"}', ctype="application/json; charset=utf-8")
                    return
                _paste_inflight.add(rid)
        env = dict(os.environ, DISPLAY=DISPLAY_NUM)
        def _xd(args):
            try:
                pr = subprocess.run(["xdotool"] + args, env=env, stdout=subprocess.PIPE,
                                    stderr=subprocess.DEVNULL, timeout=10)
                return pr.returncode == 0, pr.stdout.decode("utf-8", "replace").strip()
            except Exception:
                return False, ""
        ok, wid = _xd(["getactivewindow"])
        wcls = ""
        if ok and wid:
            try:
                pr = subprocess.run(["xprop", "-id", wid, "WM_CLASS"], env=env,
                                    stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, timeout=10)
                wcls = pr.stdout.decode("utf-8", "replace").lower()
            except Exception:
                pass
        if not (ok and wid) or "xfdesktop" in wcls:
            _serve_local(client, b'{"ok":false,"reason":"no_focus"}', ctype="application/json; charset=utf-8")
            return
        is_term = any(k in wcls for k in ("terminal", "xterm", "terminator"))
        is_chrome = any(k in wcls for k in ("chrome", "chromium", "brave"))
        is_open = "open=1" in query
        if is_open and not is_chrome:
            _serve_local(client, b'{"ok":false,"reason":"no_browser"}', ctype="application/json; charset=utf-8")
            return
        if (("url=1" in query) or is_open) and is_chrome:
            _xd(["key", "--clearmodifiers", "ctrl+l"]); time.sleep(0.2)
        paste_ok, _ = _xd(["key", "--clearmodifiers", "ctrl+shift+v" if is_term else "ctrl+v"])
        if not paste_ok:
            _serve_local(client, b'{"ok":false,"reason":"paste_failed"}', ctype="application/json; charset=utf-8")
            return
        if is_open:
            time.sleep(0.12); _xd(["key", "--clearmodifiers", "Return"])
        if rid:
            with _paste_receipt_lock:
                _paste_receipts[rid] = time.time()
        _serve_local(client, b'{"ok":true}', ctype="application/json; charset=utf-8")
    except Exception:
        try: _serve_local(client, b'{"ok":false}', ctype="application/json; charset=utf-8")
        except Exception: pass
    finally:
        if rid:
            with _paste_receipt_lock:
                _paste_inflight.discard(rid)


def _send_auth_required(client):
    body = b"Authentication required"
    resp = ("HTTP/1.1 401 Unauthorized\r\n"
            "Content-Type: text/plain; charset=utf-8\r\n"
            "Cache-Control: no-store\r\n"
            "Content-Length: %d\r\nConnection: close\r\n\r\n" % len(body))
    client.sendall(resp.encode("latin-1") + body)
    client.close()


def _cookie_token(head):
    cookies = _parse_headers(head).get("cookie", "")
    for item in cookies.split(";"):
        key, sep, value = item.strip().partition("=")
        if sep and key == _SESSION_COOKIE:
            return value
    return ""


def _valid_access_token(value):
    try:return bool(value) and hmac.compare_digest(str(value),REMOTE_ACCESS_TOKEN)
    except Exception:return False

def _valid_session_token(value):
    try:
        return time.time() < _SESSION_EXPIRES_AT and bool(value) and hmac.compare_digest(str(value),_SESSION_TOKEN)
    except Exception:return False


def _establish_session(client, req_path, query):
    """يتحقق من رمز الرابط مرة واحدة ثم ينشئ Cookie آمنة ويزيل الرمز من URL."""
    pairs = _urlparse.parse_qsl(query, keep_blank_values=True)
    supplied = next((v for k, v in pairs if k == "access_token"), "")
    if not _valid_access_token(supplied):
        return False
    clean = [(k, v) for k, v in pairs if k != "access_token"]
    location = req_path.decode("latin-1", "replace") or "/"
    if clean:
        location += "?" + _urlparse.urlencode(clean)
    resp = ("HTTP/1.1 303 See Other\r\nLocation: %s\r\n"
            "Set-Cookie: %s=%s; Path=/; Secure; HttpOnly; SameSite=Lax; Max-Age=43200\r\n"
            "Cache-Control: no-store\r\nContent-Length: 0\r\n"
            "Connection: close\r\n\r\n"
            % (location, _SESSION_COOKIE, _SESSION_TOKEN))
    client.sendall(resp.encode("latin-1"))
    client.close()
    return True



# v17 adaptive-performance state. Fast mode delays Drive writes, but the final
# shutdown save remains active. All state is in memory and scoped to this runtime.
_PERFORMANCE_PAUSE_UNTIL = 0.0
_PERF_MUTED_FOR_20 = False
_METRIC_LOCK = threading.Lock()
_METRIC_CPU_PREV = [None, None]


_WORKSPACE_MAX = 100

def _valid_workspace_id(value):
    try:
        return 1 <= int(value) <= _WORKSPACE_MAX and str(int(value)) == str(value)
    except (TypeError, ValueError):
        return False


def _known_workspace_ids():
    """المساحات الموجودة أو التي تملك خزنة؛ الفحص لا ينشئ ملفات جديدة."""
    ids = {1, 2}
    roots = ("/root/.chrome-profiles-local", os.path.join(PERSIST_DIR, "chrome-profiles"))
    for root in roots:
        try:
            for name in os.listdir(root):
                prefix = "profile-" if root.endswith(".chrome-profiles-local") else "vault-profile-"
                if name.startswith(prefix):
                    tail = name[len(prefix):]
                    if _valid_workspace_id(tail):
                        ids.add(int(tail))
        except OSError:
            pass
    return sorted(ids)


def _workspace_status_data():
    """حالة حفظ غير حساسة للمساحات الموجودة حتى الحد 100."""
    out = {}
    for n in _known_workspace_ids():
        candidates = [
            "/root/.chrome-profiles-local/status-%d.json" % n,
            os.path.join(PERSIST_DIR, "chrome-profiles", ".profile-%d-status.json" % n),
        ]
        data = None
        for path in candidates:
            try:
                with open(path, encoding="utf-8") as f:
                    data = json.load(f)
                if isinstance(data, dict):
                    break
            except Exception:
                data = None
        if not isinstance(data, dict):
            data = {"workspace": n, "state": "not_started", "message": "لم يبدأ الحفظ بعد", "generation": 0}
        data.pop("session", None)
        try:
            data["age_seconds"] = max(0, int(time.time() - float(data.get("updated_at", 0))))
        except Exception:
            data["age_seconds"] = None
        active = False
        try:
            lock = "/root/.chrome-profiles-local/profile-%d.lock" % n
            pid = int(open(lock).read().strip())
            os.kill(pid, 0)
            active = True
        except Exception:
            pass
        data["active"] = active
        out[str(n)] = data
    return out


import zipfile as _checkpoint_zipfile

_SESSION_CHECKPOINT_DIR = os.path.join(PERSIST_DIR, "desktop-session-checkpoint")
_SESSION_CHECKPOINT_LOCAL_ROOT = "/root/.chrome-profiles-local"
_SESSION_CHECKPOINT_LOCK = threading.Lock()
_SESSION_CHECKPOINT_MANIFEST = "desktop-session-checkpoint.json"


def _checkpoint_write_json_atomic(path, data):
    os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
    fd, temp = tempfile.mkstemp(prefix=".checkpoint-", dir=os.path.dirname(path) or ".")
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as handle:
            json.dump(data, handle, ensure_ascii=False, separators=(",", ":"))
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temp, path)
    finally:
        try:
            os.unlink(temp)
        except OSError:
            pass


def _checkpoint_read_json(path):
    with open(path, encoding="utf-8") as handle:
        return json.load(handle)


def _checkpoint_profile_ids(root):
    ids = []
    try:
        names = os.listdir(root)
    except OSError:
        return ids
    for name in names:
        if not name.startswith("profile-"):
            continue
        tail = name[len("profile-"):]
        if not _valid_workspace_id(tail):
            continue
        profile = os.path.join(root, name)
        if os.path.isfile(os.path.join(profile, "Local State")) and os.path.isfile(
                os.path.join(profile, "Default", "Preferences")):
            ids.append(int(tail))
    return sorted(set(ids))


def _checkpoint_profiles_valid(root, ids):
    """فحص غير حساس: JSON أساسي + قاعدة Cookies إن كانت موجودة."""
    if not ids:
        return False
    for n in ids:
        base = os.path.join(root, "profile-%d" % n)
        try:
            with open(os.path.join(base, "Local State"), encoding="utf-8") as f:
                json.load(f)
            with open(os.path.join(base, "Default", "Preferences"), encoding="utf-8") as f:
                json.load(f)
        except Exception:
            return False
        for candidate in (os.path.join(base, "Default", "Network", "Cookies"),
                          os.path.join(base, "Default", "Cookies")):
            if not os.path.isfile(candidate):
                continue
            try:
                with open(candidate, "rb") as f:
                    if not f.read(16).startswith(b"SQLite format 3"):
                        return False
            except OSError:
                return False
    return True


def _checkpoint_any_workspace_active():
    for n in _checkpoint_profile_ids(_SESSION_CHECKPOINT_LOCAL_ROOT):
        try:
            lock = "/root/.chrome-profiles-local/profile-%d.lock" % n
            pid = int(open(lock).read().strip())
            os.kill(pid, 0)
            return True
        except Exception:
            continue
    return False


def _checkpoint_prune_to_current(vault, current_generation):
    """لا نحذف إلا بعد نشر أحدث نقطة واستيفاء SHA/CRC؛ نحتفظ بجيل واحد فقط."""
    for generation, meta, meta_path in vault.list_generations():
        if generation == current_generation:
            continue
        for path in (meta_path, os.path.join(vault.dir, os.path.basename(meta.get("archive", "")))):
            try:
                if os.path.isfile(path) and not os.path.islink(path):
                    os.unlink(path)
            except OSError:
                pass
    journal = vault.journal_dir
    try:
        for name in os.listdir(journal):
            path = os.path.join(journal, name)
            if os.path.isfile(path) and not os.path.islink(path):
                os.unlink(path)
    except OSError:
        pass


def _session_checkpoint_save():
    """ينشر نقطة حفظ واحدة لجميع ملفات تعريف Chrome الموجودة محليًا.

    لا يلمس أي جيل سابق قبل نشر الأرشيف الجديد والتحقق منه وإعلان current.json.
    وتُكتب نقطة واحدة فقط حتى لا تختلط مساحات عمل من أزمنة مختلفة.
    """
    if not (_DV_OK and _DV is not None and DRIVE_OK and os.path.isdir("/content/drive/MyDrive")):
        return {"ok": False, "reason": "drive_offline"}
    if not _SESSION_CHECKPOINT_LOCK.acquire(blocking=False):
        return {"ok": False, "reason": "busy"}
    stage = None
    try:
        ids = _checkpoint_profile_ids(_SESSION_CHECKPOINT_LOCAL_ROOT)
        if not _checkpoint_profiles_valid(_SESSION_CHECKPOINT_LOCAL_ROOT, ids):
            return {"ok": False, "reason": "profiles_not_ready", "workspaces": ids}
        vault = _DV.Vault(_SESSION_CHECKPOINT_DIR, name="desktop-session-checkpoint", keep=2)
        stage = tempfile.mkdtemp(prefix=".desktop-checkpoint-")
        items = ["profile-%d" % n for n in ids]
        copied = vault.snapshot(_SESSION_CHECKPOINT_LOCAL_ROOT, stage, items,
                                excludes=("Cache", "Code Cache", "GPUCache", "GrShaderCache",
                                          "ShaderCache", "Media Cache", "Crashpad", "BrowserMetrics",
                                          "CacheStorage", "ScriptCache"))
        if copied <= 0 or not _checkpoint_profiles_valid(stage, ids):
            return {"ok": False, "reason": "stage_invalid", "workspaces": ids}
        manifest = {"schema": 1, "kind": "desktop-session-checkpoint",
                    "created_at": time.time(), "created_utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
                    "workspaces": ids, "files": copied}
        _checkpoint_write_json_atomic(os.path.join(stage, _SESSION_CHECKPOINT_MANIFEST), manifest)
        owner = "desktop-checkpoint-%d" % os.getpid()
        lock = _DV.VaultLock(vault.dir, owner, ttl=300)
        if not lock.acquire():
            return {"ok": False, "reason": "locked"}
        try:
            generation = vault.publish(stage, extra_meta={"checkpoint": True,
                                                           "workspaces": ids}, owner=owner)
        finally:
            lock.release()
        if not generation:
            return {"ok": False, "reason": "publish_failed"}
        matching = [m for g, m, _ in vault.list_generations() if g == generation]
        if len(matching) != 1 or not vault._verify_archive(matching[0]):
            return {"ok": False, "reason": "verify_failed"}
        # الحذف يحدث بعد نجاح النشر والتحقق فقط؛ يبقى آخر checkpoint منشور وحده.
        _checkpoint_prune_to_current(vault, generation)
        return {"ok": True, "generation": generation, "workspaces": ids,
                "files": copied, "retention": 1}
    except Exception as exc:
        return {"ok": False, "reason": "exception", "detail": str(exc)[:160]}
    finally:
        if stage:
            shutil.rmtree(stage, ignore_errors=True)
        _SESSION_CHECKPOINT_LOCK.release()


def _session_checkpoint_restore_boot():
    """يستعيد نقطة الحفظ قبل فتح Chrome فقط، ولا يكتب فوق مساحة تعمل بالفعل."""
    if not (_DV_OK and _DV is not None and DRIVE_OK and os.path.isdir("/content/drive/MyDrive")):
        return {"ok": False, "reason": "drive_offline"}
    if _checkpoint_any_workspace_active():
        return {"ok": False, "reason": "workspace_active"}
    vault = _DV.Vault(_SESSION_CHECKPOINT_DIR, name="desktop-session-checkpoint", keep=2)
    gens = vault.list_generations()
    if not gens:
        return {"ok": False, "reason": "absent"}
    for generation, meta, _ in gens:
        arc = vault._verify_archive(meta)
        if not arc:
            continue
        stage = tempfile.mkdtemp(prefix=".desktop-checkpoint-restore-")
        try:
            with _checkpoint_zipfile.ZipFile(arc) as z:
                if z.testzip():
                    continue
                for item in z.infolist():
                    if item.filename.startswith("/") or ".." in item.filename.split("/"):
                        raise RuntimeError("unsafe archive member")
                z.extractall(stage)
            manifest_path = os.path.join(stage, _SESSION_CHECKPOINT_MANIFEST)
            manifest = _checkpoint_read_json(manifest_path)
            ids = manifest.get("workspaces", []) if isinstance(manifest, dict) else []
            if not isinstance(ids, list) or not all(_valid_workspace_id(str(n)) for n in ids):
                continue
            ids = [int(n) for n in ids]
            if not _checkpoint_profiles_valid(stage, ids):
                continue
            # التفعيل ذري؛ عند فشله يعيد Vault الشجرة القديمة قبل الخروج.
            vault._activate(stage, _SESSION_CHECKPOINT_LOCAL_ROOT)
            stage = None
            for n in ids:
                marker = os.path.join(_SESSION_CHECKPOINT_LOCAL_ROOT,
                                      "profile-%d.manual-checkpoint-ready" % n)
                _checkpoint_write_json_atomic(marker, {"generation": generation, "restored_at": time.time(),
                                                       "source": "desktop-session-checkpoint"})
            return {"ok": True, "generation": generation, "workspaces": ids}
        except Exception:
            continue
        finally:
            if stage:
                shutil.rmtree(stage, ignore_errors=True)
    return {"ok": False, "reason": "all_generations_rejected"}


def _handle_workspace_checkpoint(client):
    result = _session_checkpoint_save()
    _serve_local(client, json.dumps(result, ensure_ascii=False, separators=(",", ":")).encode("utf-8"),
                 ctype="application/json; charset=utf-8")


def _handle_workspace_status(client):
    body = json.dumps({"ok": True, "drive_ok": bool(DRIVE_OK and os.path.isdir("/content/drive/MyDrive")),
                       "workspaces": _workspace_status_data()}, ensure_ascii=False,
                      separators=(",", ":")).encode("utf-8")
    _serve_local(client, body, ctype="application/json; charset=utf-8")


def _handle_workspace_save(client):
    results = {}
    any_profile = False
    for n in _known_workspace_ids():
        local_dir = "/root/.chrome-profiles-local/profile-%d" % n
        if not os.path.isfile(os.path.join(local_dir, "Local State")):
            continue
        any_profile = True
        try:
            pr = subprocess.run(["/usr/local/bin/chrome-profile-sync", str(n)],
                                stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                                timeout=150)
            results[str(n)] = (pr.returncode == 0)
        except Exception:
            results[str(n)] = False
    payload = {"ok": bool(any_profile and results and all(results.values())),
               "saved": results, "workspaces": _workspace_status_data()}
    _serve_local(client, json.dumps(payload, ensure_ascii=False,
                                    separators=(",", ":")).encode("utf-8"),
                 ctype="application/json; charset=utf-8")


def _repair_protection_files():
    errs=[]
    try:
        for _policy_dir in ("/etc/opt/chrome/policies/managed", "/etc/chromium/policies/managed"):
            os.makedirs(_policy_dir, exist_ok=True)
            _adult_policy_path = os.path.join(_policy_dir, "strict-adult-protection.json")
            with open(_adult_policy_path, "w", encoding="utf-8") as _pf:
                json.dump(_adult_policy, _pf, ensure_ascii=True, separators=(",", ":"))
            os.chmod(_adult_policy_path, 0o644)
        _safe_dir = "/opt/strict-safe-search"
        os.makedirs(_safe_dir, exist_ok=True)
        with open(os.path.join(_safe_dir, "manifest.json"), "w", encoding="utf-8") as _mf:
            json.dump(_safe_search_manifest, _mf, ensure_ascii=True, separators=(",", ":"))
        with open(os.path.join(_safe_dir, "safe-search.js"), "w", encoding="utf-8") as _sf:
            _sf.write(_safe_search_js)
        os.chmod(_safe_dir, 0o755)
        os.chmod(os.path.join(_safe_dir, "manifest.json"), 0o644)
        os.chmod(os.path.join(_safe_dir, "safe-search.js"), 0o644)
        for _policy_dir in ("/etc/opt/chrome/policies/managed", "/etc/chromium/policies/managed"):
            _managed_path = os.path.join(_policy_dir, "proton-vpn-extension.json")
            _managed_tmp = _managed_path + ".tmp-%d" % os.getpid()
            with open(_managed_tmp, "w", encoding="utf-8") as _mp:
                json.dump(_vpn_policy, _mp, ensure_ascii=True, separators=(",", ":"))
                _mp.flush(); os.fsync(_mp.fileno())
            os.chmod(_managed_tmp, 0o644)
            os.replace(_managed_tmp, _managed_path)
    except Exception as exc:
        errs.append(str(exc))
    return {"ok": not errs, "errors": errs}


def _protection_status_data():
    expected = {
        "SafeSearchForceEnabled": True,
        "ForceYouTubeRestrict": 2,
        "DnsOverHttpsMode": "secure",
        "DnsOverHttpsTemplates": "https://family.cloudflare-dns.com/dns-query",
        "IncognitoModeAvailability": 0,
        "URLBlocklist": list(_adult_policy.get("URLBlocklist", [])),
    }
    policies=[]
    for _policy_dir in ("/etc/opt/chrome/policies/managed", "/etc/chromium/policies/managed"):
        path=os.path.join(_policy_dir, "strict-adult-protection.json")
        item={"path":path,"exists":False,"valid":False}
        try:
            with open(path, encoding="utf-8") as f:
                data=json.load(f)
            item["exists"]=True
            item["valid"]=all(data.get(k)==v for k,v in expected.items())
        except Exception:
            pass
        policies.append(item)
    manifest_ok=False; script_ok=False
    try:
        with open('/opt/strict-safe-search/manifest.json', encoding='utf-8') as f:
            manifest_ok = json.load(f) == _safe_search_manifest
    except Exception:
        manifest_ok = False
    try:
        script_ok = open('/opt/strict-safe-search/safe-search.js', encoding='utf-8').read() == _safe_search_js
    except Exception:
        script_ok = False
    policy_ok = any(p.get('valid') for p in policies)
    managed_extension_policies=[]
    for _policy_dir in ("/etc/opt/chrome/policies/managed", "/etc/chromium/policies/managed"):
        _managed_path=os.path.join(_policy_dir,"proton-vpn-extension.json")
        _item={"path":_managed_path,"exists":False,"valid":False}
        try:
            with open(_managed_path,encoding="utf-8") as _mf:
                _managed_data=json.load(_mf)
            _item["exists"]=True
            _item["valid"]=(_managed_data==_vpn_policy)
        except Exception:
            pass
        managed_extension_policies.append(_item)
    extensions_policy_ok=any(p.get("valid") for p in managed_extension_policies)
    colab_keep_alive_managed=bool(globals().get("_COLAB_MINUTE_REFRESH_READY",False))
    colab_local_refresh_ready=colab_keep_alive_managed
    overall = bool(policy_ok and manifest_ok and script_ok and extensions_policy_ok and colab_local_refresh_ready)
    return {"ok": True, "overall": overall, "policy_ok": policy_ok, "manifest_ok": manifest_ok,
            "script_ok": script_ok, "policies": policies,
            "extensions_policy_ok": extensions_policy_ok,
            "colab_keep_alive_managed": colab_keep_alive_managed,
            "colab_local_refresh_ready": colab_local_refresh_ready,
            "managed_extension_policies": managed_extension_policies}


def _handle_protection_status(client, query):
    repaired=False; repair_ok=None
    try:
        qs=_urlparse.parse_qs(query)
        if qs.get('repair',['0'])[0]=='1':
            rr=_repair_protection_files(); repaired=bool(rr.get('ok')); repair_ok=rr
    except Exception:
        pass
    body=_protection_status_data(); body['repaired']=repaired
    if repair_ok is not None: body['repair_result']=repair_ok
    _serve_local(client, json.dumps(body, ensure_ascii=False, separators=(",", ":")).encode('utf-8'),
                 ctype='application/json; charset=utf-8')


def _recovery_csrf_ok(head):
    try:
        return hmac.compare_digest(_parse_headers(head).get("x-delete-token", ""), _DELETE_TOKEN)
    except Exception:
        return False


def _workspace_active(n):
    try:
        pid = int(open("/root/.chrome-profiles-local/profile-%d.lock" % n).read().strip())
        os.kill(pid, 0); return True
    except Exception:
        return False


def _recovery_slot_path(n, slot):
    root = os.path.join(PERSIST_DIR, "chrome-profiles")
    names = {"slot-a":"profile-%d.slot-a"%n,"slot-b":"profile-%d.slot-b"%n,
             "slot-c":"profile-%d.slot-c"%n,"pre-upgrade":"profile-%d.pre-upgrade"%n,
             "legacy":"profile-%d"%n}
    name = names.get(slot)
    return os.path.join(root, name) if name else None


def _inspect_recovery_slot(n, slot, full=False):
    import hashlib as _hashlib, sqlite3 as _sqlite3
    path = _recovery_slot_path(n, slot)
    if not path or not os.path.isdir(path): return {"slot":slot,"exists":False,"valid":False}
    info={"slot":slot,"exists":True,"valid":True,"size":0,"files":0}
    try:
        for base,dirs,files in os.walk(path):
            for name in files:
                try: info["size"]+=os.path.getsize(os.path.join(base,name));info["files"]+=1
                except OSError: pass
        mp=os.path.join(path,'.manifest.json'); manifest={}
        if os.path.isfile(mp): manifest=json.load(open(mp,encoding='utf-8'))
        info.update({k:manifest.get(k) for k in ('generation','created_utc','chrome_version','tree_sha256') if k in manifest})
        for rel in ('Local State','Default/Preferences'):
            json.load(open(os.path.join(path,rel),encoding='utf-8'))
        for rel in ('Default/Cookies','Default/Network/Cookies','Default/Login Data','Default/Web Data','Default/History'):
            p=os.path.join(path,rel)
            if os.path.isfile(p):
                q=_sqlite3.connect('file:'+p+'?mode=ro',uri=True,timeout=5).execute('PRAGMA quick_check').fetchone()
                if not q or q[0]!='ok': raise ValueError('sqlite:'+rel)
        if full:
            for rel,want in manifest.get('sha256',{}).items():
                h=_hashlib.sha256()
                with open(os.path.join(path,rel),'rb') as f:
                    for b in iter(lambda:f.read(1048576),b''):h.update(b)
                if h.hexdigest()!=want: raise ValueError('hash:'+rel)
            info['verified_now']=True
        audit=os.path.join(path,'.full-audit.json')
        if os.path.isfile(audit): info['full_audit']=json.load(open(audit,encoding='utf-8'))
    except Exception as e:
        info['valid']=False;info['error']=str(e)[:120]
    return info


def _append_recovery_audit(n,event,detail=''):
    try:
        root=os.path.join(PERSIST_DIR,'chrome-profiles');os.makedirs(root,exist_ok=True)
        with open(os.path.join(root,'chrome-save-audit.log'),'a',encoding='utf-8') as f:
            f.write('%s|workspace=%d|event=%s|%s\n'%(time.strftime('%Y-%m-%dT%H:%M:%SZ',time.gmtime()),n,event,detail))
    except Exception: pass


def _recovery_info_payload():
    root=os.path.join(PERSIST_DIR,'chrome-profiles'); work={}
    for n in _known_workspace_ids():
        pointer=''
        try:pointer=open(os.path.join(root,'.profile-%d-current'%n)).read().strip()
        except Exception:pass
        work[str(n)]={'active':_workspace_active(n),'pointer':pointer,
                      'slots':[_inspect_recovery_slot(n,x,False) for x in ('slot-a','slot-b','slot-c','pre-upgrade','legacy')]}
    try: free=shutil.disk_usage(root).free
    except Exception: free=0
    audit=[]
    try:audit=open(os.path.join(root,'chrome-save-audit.log'),encoding='utf-8').read().splitlines()[-60:]
    except Exception:pass
    try:sensitive_until=float(open('/root/.chrome-profiles-local/sensitive-mode-until').read())
    except Exception:sensitive_until=0
    return {'ok':True,'drive_ok':bool(DRIVE_OK and os.path.isdir('/content/drive/MyDrive')),
            'free_bytes':free,'sensitive_until':sensitive_until,'workspaces':work,'audit':audit}


def _handle_recovery_info(client):
    _serve_local(client,json.dumps(_recovery_info_payload(),ensure_ascii=False,separators=(',',':')).encode(),ctype='application/json; charset=utf-8')


def _recovery_params(query):
    q=_urlparse.parse_qs(query)
    try:n=int(q.get('n',['0'])[0])
    except Exception:n=0
    return n,q.get('slot',[''])[0]


def _handle_recovery_verify(client,query):
    n,slot=_recovery_params(query); info=_inspect_recovery_slot(n,slot,True) if _valid_workspace_id(n) else {'valid':False}
    _append_recovery_audit(n if _valid_workspace_id(n) else 0,'manual_verify','slot=%s;valid=%s'%(slot,info.get('valid')))
    _serve_local(client,json.dumps({'ok':bool(info.get('valid')),'slot':info},ensure_ascii=False).encode(),ctype='application/json; charset=utf-8')


def _handle_recovery_restore(client,query):
    n,slot=_recovery_params(query)
    if not _valid_workspace_id(n) or _workspace_active(n):
        payload={'ok':False,'reason':'workspace_active_or_invalid'}
    else:
        info=_inspect_recovery_slot(n,slot,True); path=_recovery_slot_path(n,slot)
        if not info.get('valid') or slot not in ('slot-a','slot-b','slot-c','pre-upgrade','legacy'):
            payload={'ok':False,'reason':'invalid_backup'}
        else:
            root=os.path.join(PERSIST_DIR,'chrome-profiles');pointer=os.path.join(root,'.profile-%d-current'%n);tmp=pointer+'.manual'
            with open(tmp,'w') as f:f.write(os.path.basename(path)+'\n');f.flush();os.fsync(f.fileno())
            os.replace(tmp,pointer);_append_recovery_audit(n,'manual_restore_selected','slot='+slot)
            payload={'ok':True,'message':'سيتم تطبيق النسخة عند فتح مساحة العمل التالية'}
    _serve_local(client,json.dumps(payload,ensure_ascii=False).encode(),ctype='application/json; charset=utf-8')


def _handle_sensitive_mode(client):
    path='/root/.chrome-profiles-local/sensitive-mode-until';now=time.time()
    try:old=float(open(path).read())
    except Exception:old=0
    until=0 if old>now else now+1800
    os.makedirs(os.path.dirname(path),exist_ok=True)
    if until:open(path,'w').write(str(until))
    else:
        try:os.unlink(path)
        except OSError:pass
    _append_recovery_audit(0,'sensitive_mode','enabled=%s'%bool(until))
    _serve_local(client,json.dumps({'ok':True,'enabled':bool(until),'until':until}).encode(),ctype='application/json; charset=utf-8')


def _handle_recovery_export(client,query):
    n,slot=_recovery_params(query); key=os.environ.get('CHROME_BACKUP_PASSPHRASE','')
    info=_inspect_recovery_slot(n,slot,True) if _valid_workspace_id(n) else {'valid':False}; path=_recovery_slot_path(n,slot)
    if not key or not info.get('valid'):
        payload={'ok':False,'reason':'passphrase_missing' if not key else 'invalid_backup'}
    else:
        name='Chrome-Workspace-%d-%s-Recovery.enc'%(n,slot);out=os.path.join(_PHONE_UPLOAD_DIR,name);tmp=out+'.tmp'
        env=dict(os.environ);env['CHROME_BACKUP_PASSPHRASE']=key
        try:
            tar=subprocess.Popen(['tar','-C',path,'-cf','-','.'],stdout=subprocess.PIPE,stderr=subprocess.DEVNULL)
            gz=subprocess.Popen(['gzip','-1'],stdin=tar.stdout,stdout=subprocess.PIPE,stderr=subprocess.DEVNULL);tar.stdout.close()
            enc=subprocess.run(['openssl','enc','-aes-256-cbc','-pbkdf2','-salt','-pass','env:CHROME_BACKUP_PASSPHRASE','-out',tmp],stdin=gz.stdout,env=env,timeout=600)
            gz.stdout.close();gz.wait(timeout=30);tar.wait(timeout=30)
            if enc.returncode:raise RuntimeError('encrypt')
            os.replace(tmp,out);_append_recovery_audit(n,'encrypted_export','slot='+slot)
            payload={'ok':True,'download':'/_download?path='+_urlparse.quote(name)}
        except Exception:
            try:os.unlink(tmp)
            except OSError:pass
            payload={'ok':False,'reason':'export_failed'}
    _serve_local(client,json.dumps(payload,ensure_ascii=False).encode(),ctype='application/json; charset=utf-8')

_VISIBLE_APPS_CACHE={"at":0.0,"count":0}
def _visible_app_windows():
    """عدد نوافذ التطبيقات المرئية فعليًا؛ يستخدم فقط لتأكيد تلف إطار العميل."""
    now=time.monotonic()
    if now-_VISIBLE_APPS_CACHE["at"]<3.0:return int(_VISIBLE_APPS_CACHE["count"])
    cmd=("DISPLAY=%s bash -lc 'for w in $(xdotool search --onlyvisible --name . 2>/dev/null); do "
         "xprop -id $w _NET_WM_WINDOW_TYPE 2>/dev/null | grep -Eq \"NORMAL|DIALOG|UTILITY\" && echo 1; done'"%DISPLAY_NUM)
    try:
        out=run(cmd,timeout=5).stdout or ''
        count=min(200,sum(1 for x in out.splitlines() if x.strip()=="1"))
    except Exception:count=0
    _VISIBLE_APPS_CACHE.update(at=now,count=count)
    return count


def _runtime_metrics():
    mem = {}
    try:
        with open('/proc/meminfo') as f:
            for ln in f:
                k, _, rest = ln.partition(':')
                try: mem[k] = int(rest.strip().split()[0])
                except Exception: pass
    except Exception:
        pass
    cpu_pct = 0.0
    try:
        vals = [int(x) for x in open('/proc/stat').readline().split()[1:]]
        total = sum(vals); idle = vals[3] + (vals[4] if len(vals)>4 else 0)
        with _METRIC_LOCK:
            pt, pi = _METRIC_CPU_PREV
            _METRIC_CPU_PREV[:] = [total, idle]
        if pt is not None and total > pt:
            cpu_pct = max(0.0, min(100.0, 100.0*(1.0-(idle-pi)/float(total-pt))))
        else:
            cpu_pct = min(100.0, os.getloadavg()[0]/max(1, CPU_COUNT)*100.0)
    except Exception:
        pass
    swap_total=mem.get('SwapTotal',0); swap_free=mem.get('SwapFree',0)
    now=time.time()
    with _TRAFFIC_LOCK:
        elapsed=max(0.25,now-_TRAFFIC['sample_at'])
        up_rate=max(0,_TRAFFIC['up']-_TRAFFIC['sample_up'])/1024.0/elapsed
        down_rate=max(0,_TRAFFIC['down']-_TRAFFIC['sample_down'])/1024.0/elapsed
        _TRAFFIC['sample_up']=_TRAFFIC['up']; _TRAFFIC['sample_down']=_TRAFFIC['down']; _TRAFFIC['sample_at']=now
        up_total=_TRAFFIC['up']; down_total=_TRAFFIC['down']; connections=_TRAFFIC['connections']
    return {'ok':True,'cpu_pct':round(cpu_pct,1),
            'mem_available_mb':int(mem.get('MemAvailable',0)/1024),
            'swap_used_mb':int(max(0,swap_total-swap_free)/1024),
            'down_kbps':round(down_rate,1),'up_kbps':round(up_rate,1),'hard_cap_kbps':HARD_EGRESS_CAP_KBPS,
            'down_total_mb':round(down_total/1048576.0,1),
            'up_total_mb':round(up_total/1048576.0,1),
            'connections':connections,'connection_limit':MAX_PROXY_CONNECTIONS,
            'proxy_accepted':_TRAFFIC.get('accepted',0),'proxy_rejected':_TRAFFIC.get('rejected',0),
            'proxy_slow_writes':_TRAFFIC.get('slow_writes',0),
            'kasm_ok':bool(proc_running('Xvnc') and port_listening(VNC_PORT)),
            'visible_app_windows':_visible_app_windows(),
            'panel_alive':_proc_alive('xfce4-panel'),'xfdesktop_alive':_proc_alive('xfdesktop'),
            'tunnel_ok':bool(_cf_proc is not None and _cf_proc.poll() is None),
            'persist_paused':time.time() < _PERFORMANCE_PAUSE_UNTIL,
            'drive_ok':bool(DRIVE_OK and os.path.isdir('/content/drive/MyDrive')),
            'workspaces':_workspace_status_data()}

def _handle_metrics(client):
    body=json.dumps(_runtime_metrics(),separators=(',',':')).encode('utf-8')
    _serve_local(client,body,ctype='application/json; charset=utf-8')

def _handle_diagnostics(client):
    with _DIAG_LOCK: events=list(_DIAG_RING)[-50:]
    body=json.dumps({"ok":True,"version":"v45.13","components":V43_COMPONENTS,
                     "events":events,"count":len(events)},separators=(',',':')).encode('utf-8')
    _serve_local(client,body,ctype='application/json; charset=utf-8')

def _handle_performance(client, query):
    global _PERFORMANCE_PAUSE_UNTIL, _PERF_MUTED_FOR_20
    qs=_urlparse.parse_qs(query)
    pause=qs.get('pause',['0'])[0]=='1'
    mode=qs.get('mode',[''])[0]
    _PERFORMANCE_PAUSE_UNTIL=(time.time()+1800.0) if pause else 0.0
    if mode in ('ultra20', 'ultra10'):
        _PERF_MUTED_FOR_20=True
        run("DISPLAY=%s xdotool key --clearmodifiers XF86AudioStop 2>/dev/null || true" % DISPLAY_NUM, timeout=3)
        run("pactl set-sink-mute @DEFAULT_SINK@ 1 2>/dev/null || true", timeout=3)
        run("DISPLAY=%s xfconf-query -c xfwm4 -p /general/use_compositing -s false 2>/dev/null || true" % DISPLAY_NUM, timeout=3)
    elif _PERF_MUTED_FOR_20:
        run("pactl set-sink-mute @DEFAULT_SINK@ 0 2>/dev/null || true", timeout=3)
        _PERF_MUTED_FOR_20=False
    body=json.dumps({'ok':True,'paused':pause,'mode':mode}).encode('utf-8')
    _serve_local(client,body,ctype='application/json; charset=utf-8')

