_UI_SCALE_ALLOWED=(100,125,150,175,200)
_UI_SCALE_LOCK=threading.Lock()
_UI_SCALE_FILE=os.path.join(PERSIST_DIR if globals().get('DRIVE_OK') else '/root/.config/colab-desktop','ui-scale-v45.json')

def _read_ui_scale():
    try:
        data=json.load(open(_UI_SCALE_FILE,encoding='utf-8'))
        v=int(data.get('percent',150));schema=int(data.get('schema',1))
        # V29: V28 حفظ 300% للنظام بالخطأ؛ أعده مرة واحدة إلى الحجم الطبيعي.
        if schema<6 or v not in _UI_SCALE_ALLOWED:return 150
        return v
    except Exception:return 150

def _atomic_json_update(path,updates):
    data={}
    try:
        if os.path.isfile(path):data=json.load(open(path,encoding='utf-8'))
    except Exception:data={}
    if not isinstance(data,dict):data={}
    data.update(updates);os.makedirs(os.path.dirname(path),exist_ok=True)
    fd,tmp=tempfile.mkstemp(prefix='.ui-scale-',dir=os.path.dirname(path))
    with os.fdopen(fd,'w',encoding='utf-8') as f:json.dump(data,f,ensure_ascii=False,indent=2);f.write('\n');f.flush();os.fsync(f.fileno())
    os.replace(tmp,path);os.chmod(path,0o600)

# XFCE settings are owned by the D-Bus session created inside xstartup.
# DISPLAY alone is insufficient: xfconf-query silently talks to no active
# xfconfd when launched from the notebook process. These helpers import the
# real session environment and apply typed settings with an observable result.
_XFCE_SESSION_COMMAND=r'''#!/bin/bash
set -u
BUS=""; SESSION_DISPLAY=""; SESSION_RUNTIME=""
# عدد محاولات الانتظار قابل للضبط: أثناء الإقلاع (قبل بدء الجلسة)
# نمرّر XFCE_SESSION_TRIES=1 حتى يفشل فورًا بدل حجز الخيط عشر ثوانٍ لكل خاصية.
XFCE_SESSION_TRIES="${XFCE_SESSION_TRIES:-10}"
case "$XFCE_SESSION_TRIES" in ''|*[!0-9]*) XFCE_SESSION_TRIES=10;; esac
[ "$XFCE_SESSION_TRIES" -ge 1 ] 2>/dev/null || XFCE_SESSION_TRIES=1
for _try in $(seq 1 "$XFCE_SESSION_TRIES"); do
  for _name in xfce4-session xfconfd xfsettingsd xfce4-panel; do
    for _pid in $(pgrep -x "$_name" 2>/dev/null); do
      [ -r "/proc/$_pid/environ" ] || continue
      _env="$(tr '\0' '\n' < "/proc/$_pid/environ" 2>/dev/null)"
      BUS="$(printf '%s\n' "$_env"|sed -n 's/^DBUS_SESSION_BUS_ADDRESS=//p'|head -n1)"
      SESSION_DISPLAY="$(printf '%s\n' "$_env"|sed -n 's/^DISPLAY=//p'|head -n1)"
      SESSION_RUNTIME="$(printf '%s\n' "$_env"|sed -n 's/^XDG_RUNTIME_DIR=//p'|head -n1)"
      [ -n "$BUS" ] && break 2
    done
  done
  [ -n "$BUS" ] && break
  sleep 1
done
[ -n "$BUS" ] || { echo 'xfce-session-bus-unavailable' >&2; exit 70; }
export DBUS_SESSION_BUS_ADDRESS="$BUS"
export DISPLAY="${SESSION_DISPLAY:-:1}"
[ -z "$SESSION_RUNTIME" ] || export XDG_RUNTIME_DIR="$SESSION_RUNTIME"
exec "$@"
'''
_XFCE_SET_TYPED=r'''#!/bin/bash
set -u
[ "$#" -eq 4 ] || exit 64
CH="$1"; PROP="$2"; TYPE="$3"; VALUE="$4"
if xfconf-query -c "$CH" -p "$PROP" -s "$VALUE" >/dev/null 2>&1; then exit 0; fi
xfconf-query -c "$CH" -p "$PROP" -n -t "$TYPE" -s "$VALUE" >/dev/null 2>&1
'''
Path('/usr/local/bin/xfce-session-command').write_text(_XFCE_SESSION_COMMAND,encoding='utf-8')
Path('/usr/local/bin/xfce-set-typed').write_text(_XFCE_SET_TYPED,encoding='utf-8')
os.chmod('/usr/local/bin/xfce-session-command',0o755);os.chmod('/usr/local/bin/xfce-set-typed',0o755)

# فحص خاطف لوجود جلسة XFCE حيّة. بدونه كان كل نداء إعداد ينتظر عشر
# وانٍ داخل xfce-session-command قبل أن يفشل — وهذا مصدر التوقف الطويل
# بعد الرسالة [5]، لأن الجلسة لا تبدأ إلا لاحقًا في الخطوة [8].
_XFCE_SESSION_STATE={'at':0.0,'live':False}

def _xfce_session_live(force=False):
    now=time.time()
    if not force:
        age=now-_XFCE_SESSION_STATE['at']
        if _XFCE_SESSION_STATE['live'] and age<20:return True
        if (not _XFCE_SESSION_STATE['live']) and age<2:return False
    live=False
    try:
        r=run("pgrep -x xfconfd >/dev/null 2>&1 || pgrep -x xfce4-session >/dev/null 2>&1 "
              "|| pgrep -x xfsettingsd >/dev/null 2>&1",timeout=6)
        live=getattr(r,'returncode',1)==0
    except Exception:
        live=False
    _XFCE_SESSION_STATE['at']=now;_XFCE_SESSION_STATE['live']=live
    return live

def _xfce_set_live(channel,prop,kind,value):
    if not _xfce_session_live():return False
    cmd=['/usr/local/bin/xfce-session-command','/usr/local/bin/xfce-set-typed',str(channel),str(prop),str(kind),str(value).lower() if isinstance(value,bool) else str(value)]
    r=run(cmd,timeout=18)
    return getattr(r,'returncode',1)==0

def _xfce_get_live(channel,prop):
    if not _xfce_session_live():return ''
    r=run(['/usr/local/bin/xfce-session-command','xfconf-query','-c',str(channel),'-p',str(prop)],timeout=18)
    return (getattr(r,'stdout','') or '').strip() if getattr(r,'returncode',1)==0 else ''

def _apply_ui_scale(percent,persist=True):
    percent=int(percent)
    if percent not in _UI_SCALE_ALLOWED:raise ValueError('invalid scale')
    # Reflow mappings. Electron zoomLevel is layout-aware; JetBrains is kept
    # at <=1.25 to preserve dialog fit while desktop fonts/icons reach 200%.
    # V29: تكبير التطبيقات مستقل عن مقياس XFCE؛ لا تعُد تصغّر IDE عند استعادة النظام.
    zoom_level=4
    dpi={100:128,125:144,150:160,175:176,200:192}[percent]
    font={100:13,125:14,150:15,175:16,200:17}[percent]
    title={100:13,125:15,150:17,175:19,200:21}[percent]
    icon={100:56,125:68,150:80,175:92,200:104}[percent]
    cursor={100:28,125:34,150:40,175:44,200:48}[percent]
    jetbrains=1.5
    panel={100:44,125:52,150:60,175:68,200:74}[percent]
    chrome_scale=1.50
    wanted_theme={100:'Default-hdpi',125:'Default-hdpi',150:'Default-xhdpi',175:'Default-xhdpi',200:'Default-xhdpi'}[percent]
    xfwm_theme=next((t for t in (wanted_theme,'Default-xhdpi','Default-hdpi','Default') if os.path.isdir('/usr/share/themes/'+t+'/xfwm4')),'')
    with _UI_SCALE_LOCK:
        if persist:
            os.makedirs(os.path.dirname(_UI_SCALE_FILE),exist_ok=True)
            fd,tmp=tempfile.mkstemp(prefix='.ui-scale-',dir=os.path.dirname(_UI_SCALE_FILE))
            with os.fdopen(fd,'w',encoding='utf-8') as f:json.dump({'schema':6,'percent':percent,'jetbrainsScale':jetbrains},f,separators=(',',':'));f.flush();os.fsync(f.fileno())
            os.replace(tmp,_UI_SCALE_FILE);os.chmod(_UI_SCALE_FILE,0o600)
        # VS Code-compatible apps reflow panels/content rather than cropping a canvas.
        _atomic_json_update('/root/.config/Cursor/User/settings.json',{'window.zoomLevel':zoom_level})
        _atomic_json_update('/root/.config/Antigravity-IDE/User/settings.json',{'window.zoomLevel':zoom_level})
        # XFCE desktop: fonts/icons grow in place; xfdesktop recomputes its grid.
        display=str(globals().get('DISPLAY_NUM',':1'))
        panel_icon=max(28,panel-8)
        props=[
          ('xsettings','/Xft/DPI','int',dpi),
          ('xsettings','/Gtk/FontName','string','Sans %d'%font),
          ('xsettings','/Gtk/MonospaceFontName','string','Monospace %d'%font),
          ('xsettings','/Gtk/CursorThemeSize','int',cursor),
          ('xsettings','/Gtk/ToolbarIconSize','int',4),
          ('xsettings','/Gtk/ButtonImages','bool',True),
          ('xsettings','/Gtk/MenuImages','bool',True),
          ('xsettings','/Gtk/MenuPopupDelay','int',0),
          ('xsettings','/Gtk/MenuPopdownDelay','int',1200),
          ('xsettings','/Gtk/MenuBarPopupDelay','int',0),
          ('xfwm4','/general/title_font','string','Sans Bold %d'%title),
          ('xfwm4','/general/title_vertical_offset','int',4),
          ('xfwm4','/general/use_compositing','bool',False),
          ('xfwm4','/general/sync_to_vblank','bool',False),
          ('xfwm4','/general/snap_to_windows','bool',False),
          ('xfwm4','/general/wrap_windows','bool',False),
          ('xfwm4','/general/wrap_workspaces','bool',False),
          ('xfce4-desktop','/desktop-icons/icon-size','uint',icon),
          ('xfce4-desktop','/desktop-icons/show-tooltips','bool',False),
          ('xfce4-desktop','/desktop-icons/tooltip-size','uint',0),
          ('xfce4-panel','/panels/panel-1/size','uint',panel),
          ('xfce4-panel','/panels/panel-1/icon-size','uint',panel_icon),
          # Phone panel must be icon-only: labels at 175/200% consume the
          # entire 800px width and make the actual application icons tiny.
          ('xfce4-panel','/plugins/plugin-1/show-label','bool',False),
          ('xfce4-panel','/plugins/plugin-2/show-labels','bool',False),
          ('xfce4-panel','/plugins/plugin-2/show-handle','bool',False)]
        if xfwm_theme:props.append(('xfwm4','/general/theme','string',xfwm_theme))
        failed=[]
        for item in props:
            if not _xfce_set_live(*item):failed.append(item[1])
        run(['/usr/local/bin/xfce-session-command','xfdesktop','--reload'],timeout=18)
        # Read-after-write: never report success while still showing the tiny
        # Default frame or text-heavy task buttons from the screenshot.
        expected={'/panels/panel-1/size':str(panel),
                  '/panels/panel-1/icon-size':str(panel_icon),
                  '/plugins/plugin-1/show-label':'false',
                  '/plugins/plugin-2/show-labels':'false'}
        for prop,want in expected.items():
            got=_xfce_get_live('xfce4-panel',prop).lower()
            if got!=want.lower():failed.append(prop)
        if xfwm_theme and _xfce_get_live('xfwm4','/general/theme')!=xfwm_theme:
            failed.append('/general/theme')
        if failed and persist:
            raise RuntimeError('xfce live scale not applied: '+','.join(sorted(set(failed))))        # Store app-specific safe scales. Android remains 1x; Chrome may enlarge
        # controls up to 1.2 because the fixed 800px desktop still fits it.
        os.makedirs('/root/.config/colab-desktop',exist_ok=True)
        Path('/root/.config/colab-desktop/jetbrains-scale').write_text(str(jetbrains)+'\n',encoding='utf-8')
        Path('/root/.config/colab-desktop/chrome-scale').write_text(str(chrome_scale)+'\n',encoding='utf-8')
        Path('/root/.config/colab-desktop/ui-percent').write_text(str(percent)+'\n',encoding='utf-8')
        # بعد تغيير DPI قد تصبح نافذة في الخلفية خارج الحدود، ومنها حوار Chrome
        # الذي يظهر لاحقًا. fit-now لا يلمس النوافذ المصغرة ويقيّد الظاهرة فقط.
        run("DISPLAY=%s /usr/local/bin/fit-now >/tmp/ui-scale-fit.log 2>&1 || true"%display,timeout=18)
    return {'ok':True,'percent':percent,'zoomLevel':zoom_level,'jetbrainsScale':jetbrains,'chromeScale':chrome_scale,'panelSize':panel,'panelIconSize':max(28,panel-8),'taskLabels':False,'xfwmTheme':xfwm_theme}

def _handle_ui_scale(client,query,method):
    if method==b'GET':
        _serve_local(client,json.dumps({'ok':True,'percent':_read_ui_scale()},separators=(',',':')).encode(),ctype='application/json; charset=utf-8');return
    try:
        qtext=query if isinstance(query,str) else query.decode('utf-8','ignore');q=_urlparse.parse_qs(qtext);p=int((q.get('percent') or [''])[0]);res=_apply_ui_scale(p,True)
        _serve_local(client,json.dumps(res,separators=(',',':')).encode(),ctype='application/json; charset=utf-8')
    except Exception as exc:
        _diag_event('ui_scale',exc,'warning');_serve_local(client,b'{"ok":false,"reason":"invalid_scale"}',ctype='application/json; charset=utf-8')

# ============================================================
# v70) دقة سطح مكتب ديناميكية تُطابق اتجاه الهاتف (عمودي/أفقي)
# ============================================================
# الغلاف يُبلّ�� أبعاد منفذ العرض الحقيقية، وهنا نحوّلها إلى دقة X
# بنفس نسبة العرض/ال��رتفاع مع ثبات عدد البكسلات (فلا يزيد الاستهلاك).
# مع مقاومة ارتداد: تبريد 3 ثوانٍ + تجاهل الفروق الصغيرة + قفل واحد.
_SCREEN_LOCK = threading.Lock()
_SCREEN_STATE = {"w": 0, "h": 0, "at": 0.0, "busy": False, "fails": 0}
_SCREEN_AREA = 1150000          # ≈ مساحة 800×1280 الأصلية (1.02 ميغابكسل)
_SCREEN_AREA_MAX = 2300000      # سقف أمان للمعالج/الحزمة
_SCREEN_MIN_SIDE = 560
_SCREEN_MAX_SIDE = 2160
_SCREEN_PORTRAIT_MIN_W = 1080    # قياس حي: Chrome المزخرف بلغ 852px؛ 880 يمنع قص الحافتين
_SCREEN_LANDSCAPE_MIN_H = 620   # أفقيًا: لا يقل الارتفاع عن 620

def _screen_round8(value):
    try:
        v = int(value) // 8 * 8
    except Exception:
        return _SCREEN_MIN_SIDE
    return max(_SCREEN_MIN_SIDE, min(_SCREEN_MAX_SIDE, v))

def _screen_target(view_w, view_h):
    """يحوّل قياس منفذ المتصفح إلى دقة X بنفس النسبة تمامًا."""
    vw = max(1, int(view_w)); vh = max(1, int(view_h))
    aspect = float(vw) / float(vh)
    w = (float(_SCREEN_AREA) * aspect) ** 0.5
    h = w / aspect
    if aspect < 1.0 and w < _SCREEN_PORTRAIT_MIN_W:
        w = float(_SCREEN_PORTRAIT_MIN_W); h = w / aspect
    if aspect >= 1.0 and h < _SCREEN_LANDSCAPE_MIN_H:
        h = float(_SCREEN_LANDSCAPE_MIN_H); w = h * aspect
    if w * h > _SCREEN_AREA_MAX:
        k = (float(_SCREEN_AREA_MAX) / (w * h)) ** 0.5
        w *= k; h *= k
    return _screen_round8(w), _screen_round8(h)

def _screen_current_geometry():
    try:
        env = dict(os.environ); env["DISPLAY"] = DISPLAY_NUM
        out = subprocess.run(["xdotool", "getdisplaygeometry"], env=env,
                             capture_output=True, timeout=8).stdout.decode("utf-8", "ignore").split()
        if len(out) >= 2:
            return int(out[0]), int(out[1])
    except Exception as exc:
        _diag_event("screen_geometry", exc, "warning")
    return 0, 0

def _screen_apply(tw, th):
    env = dict(os.environ); env["DISPLAY"] = DISPLAY_NUM; env["HOME"] = "/root"
    proc = subprocess.run(["/usr/local/bin/screen-adapt", str(tw), str(th)],
                          env=env, capture_output=True, timeout=60)
    text = (proc.stdout or b"").decode("utf-8", "ignore").strip()
    return proc.returncode, text

def _handle_screen_adapt(client, query):
    def reply(payload, ok_status="200 OK"):
        _serve_local(client, json.dumps(payload, separators=(",", ":")).encode("utf-8"),
                     ctype="application/json; charset=utf-8", status=ok_status)
    try:
        qtext = query if isinstance(query, str) else (query or b"").decode("utf-8", "ignore")
        q = _urlparse.parse_qs(qtext)
        vw = int(float((q.get("w") or ["0"])[0]))
        vh = int(float((q.get("h") or ["0"])[0]))
    except Exception as exc:
        _diag_event("screen_adapt_args", exc, "warning")
        reply({"ok": False, "reason": "invalid"}); return
    if not (200 <= vw <= 8000 and 200 <= vh <= 8000):
        reply({"ok": False, "reason": "range"}); return
    tw, th = _screen_target(vw, vh)
    now = time.monotonic()
    with _SCREEN_LOCK:
        if _SCREEN_STATE["busy"]:
            reply({"ok": False, "reason": "busy"}); return
        if _SCREEN_STATE["fails"] >= 4:
            reply({"ok": False, "reason": "unsupported"}); return
        cur_w, cur_h = _screen_current_geometry()
        if cur_w and abs(tw - cur_w) <= 16 and abs(th - cur_h) <= 16:
            _SCREEN_STATE["w"], _SCREEN_STATE["h"] = cur_w, cur_h
            reply({"ok": True, "applied": False, "w": cur_w, "h": cur_h, "reason": "same"}); return
        if now - _SCREEN_STATE["at"] < 3.0:
            reply({"ok": False, "reason": "cooldown"}); return
        _SCREEN_STATE["busy"] = True
    try:
        rc, text = _screen_apply(tw, th)
        gw, gh = _screen_current_geometry()
        ok = (rc == 0 and gw and abs(gw - tw) <= 16 and abs(gh - th) <= 16)
        with _SCREEN_LOCK:
            _SCREEN_STATE["at"] = time.monotonic()
            if ok:
                _SCREEN_STATE["w"], _SCREEN_STATE["h"] = gw, gh
                _SCREEN_STATE["fails"] = 0
            else:
                _SCREEN_STATE["fails"] += 1
        if not ok:
            _diag_event("screen_adapt", RuntimeError("rc=%s out=%s" % (rc, text[:160])), "warning")
        reply({"ok": bool(ok), "applied": bool(ok), "w": gw or tw, "h": gh or th,
               "want": "%dx%d" % (tw, th)})
    except Exception as exc:
        _diag_event("screen_adapt", exc, "warning")
        with _SCREEN_LOCK:
            _SCREEN_STATE["at"] = time.monotonic(); _SCREEN_STATE["fails"] += 1
        reply({"ok": False, "reason": "error"})
    finally:
        with _SCREEN_LOCK:
            _SCREEN_STATE["busy"] = False

# Apply the persisted profile to the new XFCE session without changing X size.
# يُنفّذ في خيط خلفي وينتظر بدء جلسة XFCE فعليًا (الخطوة [8]).
# سابقًا كان يُنفّذ هنا مباشرة قبل وجود الجلسة، فيعلق الإقلاع دقائق
# عند الرسالة [5] (ـ 16 خاصية × انتظار 10 ثوانٍ لكل واحدة).
def _xfce_deferred_session_setup():
    deadline=time.time()+300
    ready=False
    while time.time()<deadline:
        if _xfce_session_live(True):ready=True;break
        time.sleep(3)
    if not ready:
        _diag_event('xfce_deferred_setup',RuntimeError('xfce session not detected'),'warning')
        return
    time.sleep(2)
    try:_apply_ui_scale(_read_ui_scale(),False)
    except Exception as _ui_exc:_diag_event('ui_scale_restore',_ui_exc,'warning')
    # Ctrl+Alt+L — لصق رابط محادثة داخل نافذة «العمل» النشطة.
    try:
        _xfce_set_live('xfce4-keyboard-shortcuts','/commands/custom/<Primary><Alt>l',
                       'string','/usr/local/bin/genspark-window url-active')
    except Exception as _sc_exc:
        _diag_event('genspark_url_shortcut',_sc_exc,'warning')

threading.Thread(target=_xfce_deferred_session_setup,
                 name='xfce_deferred_setup',daemon=True).start()

# ============================================================
# Constrained AI desktop bridge
# ============================================================
# This bridge deliberately exposes only a small allow-list of X11 operations.
# It has no shell/command endpoint, requires BOTH access_token and the separate
# control_token, rate-limits requests, and de-duplicates action receipts.  GET
# is intentional here because some trusted automation readers cannot issue
# POST requests.  All responses are no-store via _serve_local().
_AI_RECEIPTS = collections.OrderedDict()
_AI_LOCK = threading.RLock()

def _ai_authorized(query):
    try:
        supplied = _urlparse.parse_qs(query).get("control_token", [""])[0]
        return bool(supplied) and hmac.compare_digest(str(supplied), AI_CONTROL_TOKEN)
    except Exception:
        return False

def _ai_reply(client, payload, status="200 OK"):
    _serve_local(client, json.dumps(payload, ensure_ascii=False,
                                    separators=(",", ":")).encode("utf-8"),
                 ctype="application/json; charset=utf-8", status=status)

def _ai_xdotool(args, timeout=12):
    env = dict(os.environ, DISPLAY=DISPLAY_NUM,
               XAUTHORITY=os.environ.get("XAUTHORITY", "/root/.Xauthority"))
    try:
        p = subprocess.run(["xdotool"] + list(args), env=env,
                           stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                           timeout=timeout)
        return p.returncode == 0, p.stdout.decode("utf-8", "replace").strip(), \
               p.stderr.decode("utf-8", "replace").strip()[:240]
    except Exception as exc:
        return False, "", str(exc)[:240]

def _ai_desktop_apps():
    """List installed GUI applications from trusted desktop-entry folders."""
    roots = ("/usr/share/applications", "/usr/local/share/applications",
             "/root/.local/share/applications")
    apps = {}
    for root in roots:
        if not os.path.isdir(root):
            continue
        for base, _dirs, files in os.walk(root):
            for filename in files:
                if not filename.endswith(".desktop"):
                    continue
                path = os.path.join(base, filename)
                try:
                    data = {}; in_entry = False
                    with open(path, encoding="utf-8", errors="replace") as stream:
                        for raw in stream:
                            line = raw.strip()
                            if line.startswith("["):
                                in_entry = (line == "[Desktop Entry]"); continue
                            if not in_entry or "=" not in line:
                                continue
                            key, value = line.split("=", 1)
                            if key in ("Name", "Name[ar]", "Comment", "Categories", "Type",
                                       "Hidden", "NoDisplay", "Terminal", "Exec"):
                                data[key] = value.strip()
                    if data.get("Type", "Application") != "Application": continue
                    if data.get("Hidden", "false").lower() == "true": continue
                    if not data.get("Exec"): continue
                    rel = os.path.relpath(path, root).replace(os.sep, "-")
                    app_id = rel[:-8] if rel.endswith(".desktop") else rel
                    if not app_id or not all(c.isalnum() or c in "._-" for c in app_id): continue
                    apps[app_id] = {
                        "id": app_id,
                        "name": (data.get("Name[ar]") or data.get("Name") or app_id)[:160],
                        "comment": data.get("Comment", "")[:240],
                        "categories": [x for x in data.get("Categories", "").split(";") if x][:12],
                        "terminal": data.get("Terminal", "false").lower() == "true",
                        "visible": data.get("NoDisplay", "false").lower() != "true",
                        "path": path,
                    }
                except Exception:
                    continue
    return sorted(apps.values(), key=lambda app: (not app["visible"], app["name"].casefold()))

def _handle_ai_apps(client):
    apps = _ai_desktop_apps()
    _ai_reply(client, {"ok": True, "count": len(apps), "apps": apps})

def _ai_status_data():
    ok_geo, geo, _ = _ai_xdotool(["getdisplaygeometry"])
    width, height = SCREEN_W, SCREEN_H
    if ok_geo:
        try: width, height = [int(x) for x in geo.split()[:2]]
        except Exception: pass
    ok_wid, wid, _ = _ai_xdotool(["getactivewindow"])
    title = ""; geometry = {}
    if ok_wid and wid:
        ok_title, title, _ = _ai_xdotool(["getwindowname", wid])
        ok_g, raw_g, _ = _ai_xdotool(["getwindowgeometry", "--shell", wid])
        if ok_g:
            for line in raw_g.splitlines():
                k, sep, v = line.partition("=")
                if sep and k in ("X", "Y", "WIDTH", "HEIGHT", "SCREEN"):
                    try: geometry[k.lower()] = int(v)
                    except Exception: geometry[k.lower()] = v[:80]
    windows = []
    env = dict(os.environ, DISPLAY=DISPLAY_NUM,
               XAUTHORITY=os.environ.get("XAUTHORITY", "/root/.Xauthority"))
    try:
        p = subprocess.run(["wmctrl", "-lx"], env=env, stdout=subprocess.PIPE,
                           stderr=subprocess.DEVNULL, timeout=8)
        for line in p.stdout.decode("utf-8", "replace").splitlines()[-30:]:
            parts = line.split(None, 4)
            if len(parts) >= 5:
                windows.append({"id": parts[0], "desktop": parts[1],
                                "class": parts[3][:120], "title": parts[4][:240]})
    except Exception:
        pass
    if ok_wid and wid:
        try:
            active_hex="0x%08x" % int(wid)
            known={str(w.get("id","")).lower() for w in windows}
            if active_hex.lower() not in known:
                cls=""
                xp=subprocess.run(["xprop","-id",wid,"WM_CLASS"],env=env,
                                  stdout=subprocess.PIPE,stderr=subprocess.DEVNULL,timeout=5)
                if xp.returncode==0: cls=xp.stdout.decode("utf-8","replace").strip()[:120]
                windows.append({"id":active_hex,"desktop":"0","class":cls,
                                "title":title[:240],"active_fallback":True})
        except Exception:
            pass
    return {"ok": True, "display": DISPLAY_NUM,
            "screen": {"width": width, "height": height},
            "active": {"id": wid if ok_wid else "", "title": title[:300],
                       "geometry": geometry},
            "windows": windows, "browser_running": any(
                any(k in w.get("class", "").lower() for k in ("chrome", "chromium", "brave"))
                for w in windows), "time": int(time.time())}

def _handle_ai_status(client):
    _ai_reply(client, _ai_status_data())

def _handle_ai_screenshot(client):
    """لقطة سطح المكتب — مع بدائل متسلسلة بدل الاعتماد على أداة واحدة.

    v47: كان يعتمد على `import` وحده، وهو غير مثبّت افتراضيًّا في Colab،
    فيرجع 500 دائمًا. الآن نجرّب بالترتيب:
      1) import  (ImageMagick, الأسرع والأنقى)
      2) xwd | convert  (لو نقص `import` لكن `convert` موجود)
      3) ffmpeg x11grab  (موجود عادةً في Colab لصالح الصوت/الفيديو)
    ونذكر في رسالة الخطأ الحلّ الصريح إن فشلت كلّها.
    """
    env = dict(os.environ, DISPLAY=DISPLAY_NUM,
               XAUTHORITY=os.environ.get("XAUTHORITY", "/root/.Xauthority"))
    attempts = []
    live_w, live_h = _screen_current_geometry()
    live_w, live_h = (live_w or SCREEN_W), (live_h or SCREEN_H)
    # الفحص الحي أثبت أن import قد يعيد PNG أسودًا بحجم 324 بايت؛ ffmpeg أولًا.
    if shutil.which("ffmpeg"):
        attempts.append(("ffmpeg", [
            "ffmpeg", "-loglevel", "error", "-f", "x11grab",
            "-draw_mouse", "0", "-video_size", "%dx%d" % (live_w, live_h),
            "-i", DISPLAY_NUM, "-frames:v", "1", "-f", "image2pipe",
            "-vcodec", "png", "pipe:1"]))
    if shutil.which("xwd") and shutil.which("convert"):
        attempts.append(("xwd+convert",
                         ["bash", "-c",
                          "xwd -root -silent | convert xwd:- png:-"]))
    if shutil.which("import"):
        attempts.append(("import", ["import", "-window", "root", "png:-"]))
    errors = []
    for name, cmd in attempts:
        try:
            p = subprocess.run(cmd, env=env, stdout=subprocess.PIPE,
                               stderr=subprocess.PIPE, timeout=25)
            if (p.returncode == 0 and len(p.stdout) > 4096
                    and p.stdout.startswith(b"\x89PNG")):
                _serve_local(
                    client, p.stdout, ctype="image/png",
                    extra_headers='Content-Disposition: inline; '
                                  'filename="desktop.png"\r\n')
                return
            errors.append("%s: %s" % (
                name, (p.stderr.decode("utf-8", "replace").strip()
                       or "rc=%s" % p.returncode)[:90]))
        except Exception as exc:
            errors.append("%s: %s" % (name, str(exc)[:90]))
    if not attempts:
        errors.append("لا توجد أداة لقطة مثبّتة")
    _ai_reply(client, {"ok": False, "reason": "screenshot_failed",
                       "detail": " | ".join(errors)[:400],
                       "fix": "myapt install imagemagick x11-apps"},
              status="500 Internal Server Error")

def _ai_decode_text(q):
    raw = (q.get("text_b64") or [""])[0]
    if raw:
        if len(raw) > 24000: raise ValueError("text_too_long")
        raw += "=" * ((4 - len(raw) % 4) % 4)
        return _b64.urlsafe_b64decode(raw.encode("ascii")).decode("utf-8")
    return (q.get("text") or [""])[0]

def _handle_ai_action(client, query):
    q = _urlparse.parse_qs(query, keep_blank_values=True)
    action = (q.get("type") or [""])[0].strip().lower()
    rid = (q.get("rid") or [""])[0][:96]
    if not rid or not all(c.isalnum() or c in "-_" for c in rid):
        _ai_reply(client, {"ok": False, "reason": "invalid_rid"}, "400 Bad Request"); return
    with _AI_LOCK:
        now = time.time()
        for old, ts in list(_AI_RECEIPTS.items()):
            if now - ts > 1800: _AI_RECEIPTS.pop(old, None)
        if rid in _AI_RECEIPTS:
            _ai_reply(client, {"ok": True, "duplicate": True,
                               "status": _ai_status_data()}); return
    try:
        ok = False; detail = ""
        if action == "ping":
            ok = True
        elif action in ("launch_browser", "open_url"):
            url = (q.get("url") or ["https://www.google.com"])[0].strip()
            parsed = _urlparse.urlparse(url)
            if parsed.scheme not in ("http", "https") or not parsed.netloc or len(url) > 4096:
                raise ValueError("invalid_url")
            env = dict(os.environ, DISPLAY=DISPLAY_NUM, HOME="/root",
                       XAUTHORITY=os.environ.get("XAUTHORITY", "/root/.Xauthority"))
            subprocess.Popen(["/usr/local/bin/google-chrome", url], env=env,
                             stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL,
                             stderr=subprocess.DEVNULL, start_new_session=True)
            ok = True; detail = "browser_started"
            time.sleep(min(8.0, max(0.0, float((q.get("wait") or ["2"])[0]))))
        elif action == "launch_terminal":
            env = dict(os.environ, DISPLAY=DISPLAY_NUM, HOME="/root",
                       XAUTHORITY=os.environ.get("XAUTHORITY", "/root/.Xauthority"))
            terminal = next((p for p in ("/usr/bin/xfce4-terminal", "/usr/bin/x-terminal-emulator",
                                         "/usr/bin/xterm") if os.path.isfile(p)), None)
            if not terminal: raise RuntimeError("terminal_not_found")
            subprocess.Popen([terminal], env=env, stdin=subprocess.DEVNULL,
                             stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                             start_new_session=True)
            ok = True; detail = "terminal_started"
            time.sleep(min(8.0, max(0.0, float((q.get("wait") or ["2"])[0]))))
        elif action == "launch_app":
            app_id = (q.get("app_id") or [""])[0].strip()
            catalog = {app["id"]: app for app in _ai_desktop_apps()}
            app = catalog.get(app_id)
            if not app: raise ValueError("unknown_app_id")
            env = dict(os.environ, DISPLAY=DISPLAY_NUM, HOME="/root",
                       XAUTHORITY=os.environ.get("XAUTHORITY", "/root/.Xauthority"))
            if os.path.isfile("/usr/bin/gtk-launch"):
                command = ["/usr/bin/gtk-launch", app_id]
            elif os.path.isfile("/usr/bin/gio"):
                command = ["/usr/bin/gio", "launch", app["path"]]
            else:
                raise RuntimeError("desktop_launcher_not_found")
            subprocess.Popen(command, env=env, stdin=subprocess.DEVNULL,
                             stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                             start_new_session=True)
            ok = True; detail = "app_started:" + app_id
            time.sleep(min(10.0, max(0.0, float((q.get("wait") or ["2"])[0]))))
        elif action in ("activate_window", "maximize_window", "minimize_window", "close_window"):
            wid = (q.get("window_id") or [""])[0].strip().lower()
            if not wid.startswith("0x") or not wid[2:] or len(wid) > 18 or not all(c in "0123456789abcdef" for c in wid[2:]):
                raise ValueError("invalid_window_id")
            known = {w["id"].lower() for w in _ai_status_data().get("windows", [])}
            if wid not in known: raise ValueError("unknown_window_id")
            if action == "activate_window":
                ok, _, detail = _ai_xdotool(["windowactivate", "--sync", wid])
            elif action == "maximize_window":
                ok, _, detail = _ai_xdotool(["windowactivate", "--sync", wid,
                                             "windowsize", wid, "100%", "100%"])
            elif action == "minimize_window":
                ok, _, detail = _ai_xdotool(["windowminimize", wid])
            else:
                ok, _, detail = _ai_xdotool(["windowclose", wid])
        elif action == "click":
            x = int((q.get("x") or ["-1"])[0]); y = int((q.get("y") or ["-1"])[0])
            button = int((q.get("button") or ["1"])[0])
            if not (0 <= x < SCREEN_W and 0 <= y < SCREEN_H and button in (1, 2, 3)):
                raise ValueError("invalid_click")
            ok, _, detail = _ai_xdotool(["mousemove", "--sync", str(x), str(y),
                                         "click", str(button)])
        elif action == "move":
            x = int((q.get("x") or ["-1"])[0]); y = int((q.get("y") or ["-1"])[0])
            if not (0 <= x < SCREEN_W and 0 <= y < SCREEN_H): raise ValueError("invalid_move")
            ok, _, detail = _ai_xdotool(["mousemove", "--sync", str(x), str(y)])
        elif action == "key":
            key = (q.get("key") or [""])[0]
            allowed = {"Return","Enter","Tab","Escape","BackSpace","Delete","Home","End",
                       "Left","Right","Up","Down","Page_Up","Page_Down","space","F5","F6",
                       "ctrl+l","ctrl+t","ctrl+w","ctrl+r","ctrl+shift+t","alt+Left","alt+Right"}
            if key not in allowed: raise ValueError("key_not_allowed")
            ok, _, detail = _ai_xdotool(["key", "--clearmodifiers", key])
        elif action == "type":
            text = _ai_decode_text(q)
            if len(text) > 12000: raise ValueError("text_too_long")
            env = dict(os.environ, DISPLAY=DISPLAY_NUM,
                       XAUTHORITY=os.environ.get("XAUTHORITY", "/root/.Xauthority"))
            p = subprocess.run(["xsel", "--clipboard", "--input"], env=env,
                               input=text.encode("utf-8"), stdout=subprocess.DEVNULL,
                               stderr=subprocess.PIPE, timeout=10)
            if p.returncode != 0: raise RuntimeError("clipboard_failed")
            paste_key = "ctrl+v"
            okw, active_wid, _ = _ai_xdotool(["getactivewindow"])
            if okw and active_wid:
                try:
                    xp = subprocess.run(["xprop", "-id", active_wid, "WM_CLASS"], env=env,
                                        stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, timeout=6)
                    wclass = xp.stdout.decode("utf-8", "replace").lower()
                    if any(k in wclass for k in ("terminal", "xterm", "terminator")):
                        paste_key = "ctrl+shift+v"
                except Exception: pass
            ok, _, detail = _ai_xdotool(["key", "--clearmodifiers", paste_key])
        elif action == "scroll":
            amount = int((q.get("amount") or ["0"])[0])
            if not -20 <= amount <= 20 or amount == 0: raise ValueError("invalid_scroll")
            button = "4" if amount > 0 else "5"
            ok = True
            for _ in range(abs(amount)):
                one, _, detail = _ai_xdotool(["click", button])
                if not one: ok = False; break
        elif action == "wait":
            seconds = float((q.get("seconds") or ["1"])[0])
            if not 0 <= seconds <= 10: raise ValueError("invalid_wait")
            time.sleep(seconds); ok = True
        else:
            raise ValueError("action_not_allowed")
        if not ok:
            raise RuntimeError(detail or "action_failed")
        with _AI_LOCK:
            _AI_RECEIPTS[rid] = time.time()
            while len(_AI_RECEIPTS) > 500: _AI_RECEIPTS.popitem(last=False)
        _ai_reply(client, {"ok": True, "rid": rid, "action": action,
                           "detail": detail, "status": _ai_status_data()})
    except Exception as exc:
        _ai_reply(client, {"ok": False, "rid": rid, "action": action,
                           "reason": str(exc)[:240]}, "400 Bad Request")

# ============================================================
# MCP Streamable HTTP server (stateless, tools capability)
# ============================================================
_MCP_SERVER_NAME = "colab-remote-desktop"
_MCP_SERVER_VERSION = "2.4.0"
_MCP_SUPPORTED_PROTOCOLS = ("2025-06-18", "2025-03-26", "2024-11-05")
_MCP_ENDPOINT_PATH = "/mcp/" + MCP_PATH_TOKEN
_MCP_ENDPOINT_PATH_BYTES = _MCP_ENDPOINT_PATH.encode("ascii")
_MCP_MAX_BODY = 1024 * 1024

def _mcp_json_text(value):
    return json.dumps(value, ensure_ascii=False, separators=(",", ":"))

def _mcp_result(value, is_error=False):
    return {"content": [{"type": "text", "text": _mcp_json_text(value)}],
            "structuredContent": value, "isError": bool(is_error)}

def _mcp_wait_seconds(args, default=2.0, maximum=10.0):
    try: value=float(args.get("wait_seconds", default))
    except Exception: value=default
    return max(0.0, min(value, maximum))

def _mcp_launch_environment():
    return dict(os.environ, DISPLAY=DISPLAY_NUM, HOME="/root",
                XAUTHORITY=os.environ.get("XAUTHORITY", "/root/.Xauthority"))

def _mcp_type_text(text):
    if not isinstance(text, str) or len(text) > 12000:
        raise ValueError("text must be a string of at most 12000 characters")
    env=_mcp_launch_environment()
    if not _write_x11_selection_text(text,"clipboard"):
        raise RuntimeError("clipboard_write_or_readback_failed")
    time.sleep(0.18)
    paste_key="ctrl+v"
    okw,wid,_=_ai_xdotool(["getactivewindow"])
    if okw and wid:
        try:
            xp=subprocess.run(["xprop","-id",wid,"WM_CLASS"],env=env,
                              stdout=subprocess.PIPE,stderr=subprocess.DEVNULL,timeout=6)
            wclass=xp.stdout.decode("utf-8","replace").lower()
            if any(k in wclass for k in ("terminal","xterm","terminator")):
                paste_key="ctrl+shift+v"
        except Exception:pass
    ok,_,detail=_ai_xdotool(["key","--clearmodifiers",paste_key])
    if not ok:raise RuntimeError(detail or "paste_failed")
    return {"ok":True,"characters":len(text),"paste_key":paste_key,
            "status":_ai_status_data()}

def _mcp_call_tool(name, args):
    if not isinstance(args,dict):raise ValueError("arguments must be an object")
    if name=="desktop_status":
        return _mcp_result(_ai_status_data())
    if name=="list_apps":
        visible_only=bool(args.get("visible_only",True))
        apps=_ai_desktop_apps()
        if visible_only:apps=[a for a in apps if a.get("visible")]
        return _mcp_result({"ok":True,"count":len(apps),"apps":apps})
    if name=="open_browser":
        url=str(args.get("url") or "https://www.google.com").strip()
        parsed=_urlparse.urlparse(url)
        if parsed.scheme not in ("http","https") or not parsed.netloc or len(url)>4096:
            raise ValueError("invalid http/https URL")
        subprocess.Popen(["/usr/local/bin/google-chrome",url],env=_mcp_launch_environment(),
                         stdin=subprocess.DEVNULL,stdout=subprocess.DEVNULL,
                         stderr=subprocess.DEVNULL,start_new_session=True)
        time.sleep(_mcp_wait_seconds(args))
        return _mcp_result({"ok":True,"url":url,"status":_ai_status_data()})
    if name=="open_terminal":
        terminal=next((p for p in ("/usr/bin/xfce4-terminal","/usr/bin/x-terminal-emulator","/usr/bin/xterm") if os.path.isfile(p)),None)
        if not terminal:raise RuntimeError("terminal_not_found")
        subprocess.Popen([terminal],env=_mcp_launch_environment(),stdin=subprocess.DEVNULL,
                         stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,start_new_session=True)
        time.sleep(_mcp_wait_seconds(args))
        return _mcp_result({"ok":True,"terminal":terminal,"status":_ai_status_data()})
    if name=="launch_app":
        app_id=str(args.get("app_id") or "").strip()
        catalog={app["id"]:app for app in _ai_desktop_apps()}
        app=catalog.get(app_id)
        if not app:raise ValueError("unknown app_id; call list_apps first")
        if os.path.isfile("/usr/bin/gtk-launch"):command=["/usr/bin/gtk-launch",app_id]
        elif os.path.isfile("/usr/bin/gio"):command=["/usr/bin/gio","launch",app["path"]]
        else:raise RuntimeError("desktop_launcher_not_found")
        subprocess.Popen(command,env=_mcp_launch_environment(),stdin=subprocess.DEVNULL,
                         stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,start_new_session=True)
        time.sleep(_mcp_wait_seconds(args))
        return _mcp_result({"ok":True,"app":app,"status":_ai_status_data()})
    if name=="click":
        x=int(args.get("x",-1));y=int(args.get("y",-1));button=int(args.get("button",1))
        screen=_ai_status_data().get("screen",{})
        if not (0<=x<int(screen.get("width",SCREEN_W)) and 0<=y<int(screen.get("height",SCREEN_H)) and button in (1,2,3)):
            raise ValueError("click coordinates or button are outside the desktop")
        ok,_,detail=_ai_xdotool(["mousemove","--sync",str(x),str(y),"click",str(button)])
        if not ok:raise RuntimeError(detail or "click_failed")
        return _mcp_result({"ok":True,"x":x,"y":y,"button":button,"status":_ai_status_data()})
    if name=="move_pointer":
        x=int(args.get("x",-1));y=int(args.get("y",-1));screen=_ai_status_data().get("screen",{})
        if not (0<=x<int(screen.get("width",SCREEN_W)) and 0<=y<int(screen.get("height",SCREEN_H))):
            raise ValueError("pointer coordinates are outside the desktop")
        ok,_,detail=_ai_xdotool(["mousemove","--sync",str(x),str(y)])
        if not ok:raise RuntimeError(detail or "move_failed")
        return _mcp_result({"ok":True,"x":x,"y":y})
    if name=="type_text":
        return _mcp_result(_mcp_type_text(args.get("text")))
    if name=="press_key":
        import re as _mcp_re
        key=str(args.get("key") or "")
        if not _mcp_re.fullmatch(r"[A-Za-z0-9_+\-]{1,64}",key):
            raise ValueError("invalid key; examples: Return, ctrl+l, ctrl+shift+t")
        ok,_,detail=_ai_xdotool(["key","--clearmodifiers",key])
        if not ok:raise RuntimeError(detail or "key_failed")
        return _mcp_result({"ok":True,"key":key,"status":_ai_status_data()})
    if name=="scroll":
        amount=int(args.get("amount",0))
        if amount==0 or not -20<=amount<=20:raise ValueError("amount must be between -20 and 20, excluding zero")
        button="4" if amount>0 else "5"
        for _ in range(abs(amount)):
            ok,_,detail=_ai_xdotool(["click",button])
            if not ok:raise RuntimeError(detail or "scroll_failed")
        return _mcp_result({"ok":True,"amount":amount,"status":_ai_status_data()})
    if name=="manage_window":
        operation=str(args.get("operation") or "").strip().lower()
        wid=str(args.get("window_id") or "").strip().lower()
        if operation not in ("activate","maximize","minimize","close"):
            raise ValueError("operation must be activate, maximize, minimize, or close")
        if not wid.startswith("0x") or not wid[2:] or len(wid)>18 or not all(c in "0123456789abcdef" for c in wid[2:]):
            raise ValueError("invalid window_id")
        known={w["id"].lower() for w in _ai_status_data().get("windows",[])}
        if wid not in known:raise ValueError("window_id is not currently visible")
        if operation=="activate":cmd=["windowactivate","--sync",wid]
        elif operation=="maximize":cmd=["windowactivate","--sync",wid,"windowsize",wid,"100%","100%"]
        elif operation=="minimize":cmd=["windowminimize",wid]
        else:cmd=["windowclose",wid]
        ok,_,detail=_ai_xdotool(cmd)
        if not ok:raise RuntimeError(detail or "window_operation_failed")
        return _mcp_result({"ok":True,"operation":operation,"window_id":wid,"status":_ai_status_data()})
    if name=="wait":
        seconds=float(args.get("seconds",1))
        if not 0<=seconds<=10:raise ValueError("seconds must be between 0 and 10")
        time.sleep(seconds)
        return _mcp_result({"ok":True,"seconds":seconds,"status":_ai_status_data()})
    if name=="take_screenshot":
        env=_mcp_launch_environment();screen=_ai_status_data().get("screen",{})
        sw=int(screen.get("width") or SCREEN_W);sh=int(screen.get("height") or SCREEN_H)
        attempts=[]
        if shutil.which("ffmpeg"):
            attempts.append(["ffmpeg","-loglevel","error","-f","x11grab","-draw_mouse","0",
                             "-video_size","%dx%d"%(sw,sh),"-i",DISPLAY_NUM,"-frames:v","1",
                             "-f","image2pipe","-vcodec","png","pipe:1"])
        if shutil.which("xwd") and shutil.which("convert"):
            attempts.append(["bash","-c","xwd -root -silent | convert xwd:- png:-"])
        if shutil.which("import"):
            attempts.append(["import","-window","root","png:-"])
        png=b"";errors=[]
        for command in attempts:
            try:
                p=subprocess.run(command,env=env,stdout=subprocess.PIPE,
                                 stderr=subprocess.PIPE,timeout=25)
                if (p.returncode==0 and 4096<len(p.stdout)<=8*1024*1024
                        and p.stdout.startswith(b"\x89PNG")):
                    png=p.stdout;break
                errors.append(str(p.returncode))
            except Exception as exc:
                errors.append(type(exc).__name__)
        if not png:
            raise RuntimeError("screenshot_failed:"+",".join(errors[:3]))
        return {"content":[{"type":"image","data":_b64.b64encode(png).decode("ascii"),"mimeType":"image/png"},
                           {"type":"text","text":_mcp_json_text(_ai_status_data())}],"isError":False}
    raise ValueError("unknown tool")

def _mcp_tools():
    obj={"type":"object","additionalProperties":False}
    return [
      {"name":"desktop_status","description":"Read screen size, active window, and visible windows.","inputSchema":dict(obj,properties={})},
      {"name":"list_apps","description":"List installed desktop applications and their launch IDs.","inputSchema":dict(obj,properties={"visible_only":{"type":"boolean","default":True}})},
      {"name":"open_browser","description":"Open an HTTP or HTTPS URL in Chrome.","inputSchema":dict(obj,properties={"url":{"type":"string"},"wait_seconds":{"type":"number","minimum":0,"maximum":10}},required=["url"])},
      {"name":"open_terminal","description":"Open a visible XFCE terminal.","inputSchema":dict(obj,properties={"wait_seconds":{"type":"number","minimum":0,"maximum":10}})},
      {"name":"launch_app","description":"Launch an installed GUI app by an ID returned from list_apps.","inputSchema":dict(obj,properties={"app_id":{"type":"string"},"wait_seconds":{"type":"number","minimum":0,"maximum":10}},required=["app_id"])},
      {"name":"click","description":"Move the pointer and click desktop coordinates.","inputSchema":dict(obj,properties={"x":{"type":"integer"},"y":{"type":"integer"},"button":{"type":"integer","enum":[1,2,3],"default":1}},required=["x","y"])},
      {"name":"move_pointer","description":"Move the pointer without clicking.","inputSchema":dict(obj,properties={"x":{"type":"integer"},"y":{"type":"integer"}},required=["x","y"])},
      {"name":"type_text","description":"Paste text into the active window, including Arabic and terminal text.","inputSchema":dict(obj,properties={"text":{"type":"string","maxLength":12000}},required=["text"])},
      {"name":"press_key","description":"Press one X11 key or shortcut such as Return, ctrl+l, or ctrl+shift+t.","inputSchema":dict(obj,properties={"key":{"type":"string","maxLength":64}},required=["key"])},
      {"name":"scroll","description":"Scroll the active window; positive is up and negative is down.","inputSchema":dict(obj,properties={"amount":{"type":"integer","minimum":-20,"maximum":20}},required=["amount"])},
      {"name":"manage_window","description":"Activate, maximize, minimize, or close a visible window.","inputSchema":dict(obj,properties={"operation":{"type":"string","enum":["activate","maximize","minimize","close"]},"window_id":{"type":"string"}},required=["operation","window_id"])},
      {"name":"wait","description":"Wait briefly, then return current desktop status.","inputSchema":dict(obj,properties={"seconds":{"type":"number","minimum":0,"maximum":10}},required=["seconds"])},
      {"name":"take_screenshot","description":"Capture the complete desktop as a PNG image.","inputSchema":dict(obj,properties={})},
    ]

def _mcp_error(request_id,code,message,data=None):
    error={"code":int(code),"message":str(message)}
    if data is not None:error["data"]=data
    return {"jsonrpc":"2.0","id":request_id,"error":error}

def _mcp_dispatch(message):
    if not isinstance(message,dict) or message.get("jsonrpc")!="2.0" or not isinstance(message.get("method"),str):
        return _mcp_error(message.get("id") if isinstance(message,dict) else None,-32600,"Invalid Request")
    method=message["method"];request_id=message.get("id");is_notification=("id" not in message)
    params=message.get("params") or {}
    if not isinstance(params,dict):
        return None if is_notification else _mcp_error(request_id,-32602,"Invalid params")
    if method in ("notifications/initialized","notifications/cancelled"):
        return None
    if method=="initialize":
        requested=str(params.get("protocolVersion") or "")
        protocol=requested if requested in _MCP_SUPPORTED_PROTOCOLS else _MCP_SUPPORTED_PROTOCOLS[0]
        result={"protocolVersion":protocol,
                "capabilities":{"tools":{"listChanged":False}},
                "serverInfo":{"name":_MCP_SERVER_NAME,"title":"Colab Remote Desktop","version":_MCP_SERVER_VERSION},
                "instructions":"Use desktop_status before coordinate actions. Use list_apps before launch_app. Desktop actions are visible to the user."}
    elif method=="ping":result={}
    elif method=="tools/list":result={"tools":_mcp_tools()}
    elif method=="tools/call":
        tool_name=params.get("name");arguments=params.get("arguments") or {}
        if not isinstance(tool_name,str) or not isinstance(arguments,dict):
            return None if is_notification else _mcp_error(request_id,-32602,"Invalid tool call params")
        try:result=_mcp_call_tool(tool_name,arguments)
        except Exception as exc:result=_mcp_result({"ok":False,"tool":tool_name,"error":str(exc)[:400]},True)
    elif method in ("resources/list","prompts/list"):
        result={"resources":[]} if method=="resources/list" else {"prompts":[]}
    elif method=="logging/setLevel":result={}
    else:
        return None if is_notification else _mcp_error(request_id,-32601,"Method not found")
    return None if is_notification else {"jsonrpc":"2.0","id":request_id,"result":result}

def _mcp_origin_allowed(head):
    origin=_parse_headers(head).get("origin","").strip()
    if not origin:return True
    try:
        host=(_urlparse.urlparse(origin).hostname or "").lower()
        return host in ("localhost","127.0.0.1","notion.so","notion.com") or host.endswith(".notion.so") or host.endswith(".notion.com")
    except Exception:return False

def _mcp_serve_empty(client,status="202 Accepted",extra_headers=""):
    headers=("HTTP/1.1 %s\r\nContent-Length: 0\r\nCache-Control: no-store\r\n"
             "X-Content-Type-Options: nosniff\r\nConnection: close\r\n%s\r\n"%(status,extra_headers)).encode("latin-1")
    client.sendall(headers);client.close()

def _handle_mcp_http(client,head,method):
    allow="Allow: POST, GET, DELETE, OPTIONS\r\nAccess-Control-Allow-Methods: POST, GET, DELETE, OPTIONS\r\nAccess-Control-Allow-Headers: Content-Type, Accept, MCP-Protocol-Version, MCP-Session-Id\r\n"
    if not _mcp_origin_allowed(head):
        _serve_local(client,b'{"error":"origin_not_allowed"}',ctype="application/json",status="403 Forbidden");return
    if method==b"OPTIONS":_mcp_serve_empty(client,"204 No Content",allow);return
    if method==b"GET":
        _serve_local(client,b'{"jsonrpc":"2.0","error":{"code":-32000,"message":"SSE stream not enabled; use Streamable HTTP POST"},"id":null}',ctype="application/json",status="405 Method Not Allowed",extra_headers=allow);return
    if method==b"DELETE":_mcp_serve_empty(client,"200 OK",allow);return
    if method!=b"POST":_mcp_serve_empty(client,"405 Method Not Allowed",allow);return
    try:
        body,hdrs=_read_request_body(client,head)
        if len(body)>_MCP_MAX_BODY:raise ValueError("MCP request body too large")
        ctype=hdrs.get("content-type","").lower()
        if "application/json" not in ctype:raise ValueError("Content-Type must be application/json")
        payload=json.loads(body.decode("utf-8"))
    except Exception as exc:
        response=_mcp_error(None,-32700,"Parse error",str(exc)[:200])
        _serve_local(client,_mcp_json_text(response),ctype="application/json",status="400 Bad Request",extra_headers=allow);return
    if isinstance(payload,list):
        if not payload:
            responses=[_mcp_error(None,-32600,"Invalid Request")]
        else:responses=[r for r in (_mcp_dispatch(item) for item in payload) if r is not None]
        if not responses:_mcp_serve_empty(client,"202 Accepted",allow);return
        response=responses
    else:
        response=_mcp_dispatch(payload)
        if response is None:_mcp_serve_empty(client,"202 Accepted",allow);return
    _serve_local(client,_mcp_json_text(response),ctype="application/json",extra_headers=allow)

_MUTATING_PATHS={b"/_workspace_save",b"/_workspace_checkpoint",b"/_performance",b"/_clip",b"/_paste",b"/_delete",
 b"/_copy_selected",b"/_desktop_repair",b"/_fit",b"/_ui_scale",b"/_upload",b"/_recovery_verify",
 b"/_recovery_restore",b"/_recovery_export",b"/_sensitive_mode",b"/_protection_status",b"/_screen"}
_RATE_RULES={b"/_clip":(180,60),b"/_paste":(90,60),b"/_upload":(20,60),
 b"/_desktop_repair":(4,300),b"/_ui_scale":(20,60),b"/_screen":(20,60),b"/_workspace_save":(12,60),b"/_workspace_checkpoint":(2,600),b"/_protection_status":(8,60),
 b"/_ai_status":(120,60),b"/_ai_apps":(30,60),b"/_ai_screenshot":(60,60),b"/_ai_action":(90,60),b"/mcp":(300,60)}
_RATE_STATE=collections.defaultdict(collections.deque);_RATE_LOCK=threading.Lock()
def _same_origin_request(head):
    h=_parse_headers(head);site=h.get("sec-fetch-site","").lower()
    if site=="cross-site": return False
    origin=h.get("origin","");host=h.get("host","")
    if origin and host:
        try:
            if _urlparse.urlparse(origin).netloc.lower()!=host.lower(): return False
        except Exception as exc: _diag_event("origin_parse",exc);return False
    return True
def _rate_allowed(path):
    limit,window=_RATE_RULES.get(path,(120,60));now=time.monotonic()
    with _RATE_LOCK:
        q=_RATE_STATE[path]
        while q and now-q[0]>window:q.popleft()
        if len(q)>=limit:return False
        q.append(now);return True

def _proxy_handle(client):
    backend = None
    try:
        _proxy_tune(client)
        client.settimeout(30)
        head = b""
        while b"\r\n\r\n" not in head and len(head) < 65536:
            chunk = client.recv(65536)
            if not chunk:
                break
            head += chunk
        if not head:
            client.close()
            return
        # سطر الطلب: GET /path?query HTTP/1.1
        try:
            _req_line = head.split(b" ", 2)
            req_method = _req_line[0].upper()
            full_path = _req_line[1]
            req_path = full_path.split(b"?", 1)[0]
            query = (full_path.split(b"?", 1)[1].decode("latin-1")
                     if b"?" in full_path else "")
        except Exception:
            _send_auth_required(client)
            return
        # فحص صحة محلي لا يكشف بيانات ولا يُمرَّر إلى KasmVNC.
        if req_path == b"/_health":
            _serve_local(client, b"ok", ctype="text/plain; charset=utf-8")
            return
        # MCP is a stateless Streamable HTTP endpoint protected by an
        # unguessable capability path, so it does not depend on browser cookies.
        if req_path.startswith(b"/mcp/"):
            if not hmac.compare_digest(req_path,_MCP_ENDPOINT_PATH_BYTES):
                _serve_local(client,b'{"error":"not_found"}',ctype="application/json",status="404 Not Found");return
            if not _rate_allowed(b"/mcp"):
                _serve_local(client,b'{"error":"rate_limit"}',ctype="application/json",status="429 Too Many Requests",extra_headers="Retry-After: 3\r\n");return
            client.settimeout(60)
            _handle_mcp_http(client,head,req_method)
            return
        # كل ما عدا فحص الصحة يتطلب جلسة موثقة. رمز الدخول يظهر مرة واحدة
        # في الرابط ثم يتحول إلى Cookie آمنة ويُزال من شيط العنوان.
        q_token = _urlparse.parse_qs(query).get("access_token", [""])[0]
        bootstrap_cookie = ""
        if q_token:
            if not _valid_access_token(q_token):
                _send_auth_required(client)
                return
            # Set the cookie on the wrapper response itself. This avoids the
            # cross-site 303 redirect that some mobile browsers block.
            bootstrap_cookie = (
                "Set-Cookie: %s=%s; Path=/; Secure; HttpOnly; "
                "SameSite=Lax; Max-Age=43200\r\n"
                % (_SESSION_COOKIE, _SESSION_TOKEN))
        elif not _valid_session_token(_cookie_token(head)):
            _send_auth_required(client);return
        # Automation bridge: query-token authentication is required on every
        # request because trusted stateless readers do not retain cookies.
        if req_path in (b"/_ai_status", b"/_ai_apps", b"/_ai_screenshot", b"/_ai_action"):
            if req_method != b"GET":
                _serve_local(client,b'{"ok":false,"reason":"method"}',ctype="application/json",status="405 Method Not Allowed");return
            if not _ai_authorized(query):
                _serve_local(client,b'{"ok":false,"reason":"control_token"}',ctype="application/json",status="403 Forbidden");return
            if not _rate_allowed(req_path):
                _serve_local(client,b'{"ok":false,"reason":"rate_limit"}',ctype="application/json",extra_headers="Retry-After: 3\r\n",status="429 Too Many Requests");return
            if req_path == b"/_ai_status": _handle_ai_status(client); return
            if req_path == b"/_ai_apps": _handle_ai_apps(client); return
            if req_path == b"/_ai_screenshot": _handle_ai_screenshot(client); return
            _handle_ai_action(client, query); return
        # v31: every local state-changing action is POST-only, same-origin and rate-limited.
        _is_mutation=((req_path in _MUTATING_PATHS) and not (req_path==b"/_ui_scale" and req_method==b"GET")) or (req_path==b"/_safe_cleanup" and "mode=run" in query)
        if _is_mutation:
            if req_method!=b"POST":
                _serve_local(client,b'{"ok":false,"reason":"method"}',ctype="application/json",status="405 Method Not Allowed");return
            if not _same_origin_request(head):
                _serve_local(client,b'{"ok":false,"reason":"origin"}',ctype="application/json",status="403 Forbidden");return
            if not _rate_allowed(req_path):
                _diag_event("rate_limit_"+req_path.decode("latin-1","ignore"))
                _serve_local(client,b'{"ok":false,"reason":"rate_limit"}',ctype="application/json",extra_headers="Retry-After: 5\r\n",status="429 Too Many Requests");return
        # Local adaptive/PWA endpoints (all require the authenticated cookie).
        if req_path == b"/_metrics":
            _handle_metrics(client); return
        if req_path == b"/_diagnostics":
            if req_method != b"GET": _serve_local(client,b'{"ok":false}',ctype="application/json",status="405 Method Not Allowed"); return
            _handle_diagnostics(client); return
        if req_path == b"/_workspace_status":
            if req_method != b"GET":
                _serve_local(client,b'{"ok":false,"reason":"method"}',ctype="application/json; charset=utf-8"); return
            _handle_workspace_status(client); return
        if req_path == b"/_workspace_save":
            if req_method != b"POST":
                _serve_local(client,b'{"ok":false,"reason":"method"}',ctype="application/json; charset=utf-8"); return
            _handle_workspace_save(client); return
        if req_path == b"/_workspace_checkpoint":
            if req_method != b"POST":
                _serve_local(client,b'{"ok":false,"reason":"method"}',ctype="application/json; charset=utf-8"); return
            _handle_workspace_checkpoint(client); return
        if req_path == b"/_protection_status":
            if req_method not in (b"GET", b"POST"):
                _serve_local(client,b'{"ok":false,"reason":"method"}',ctype="application/json; charset=utf-8"); return
            _handle_protection_status(client,query); return
        if req_path == b"/_recovery_info":
            if req_method != b"GET": _serve_local(client,b'{"ok":false}',ctype="application/json"); return
            _handle_recovery_info(client); return
        if req_path in (b"/_recovery_verify",b"/_recovery_restore",b"/_recovery_export",b"/_sensitive_mode"):
            if req_method != b"POST" or not _recovery_csrf_ok(head):
                _serve_local(client,b'{"ok":false,"reason":"forbidden"}',ctype="application/json; charset=utf-8"); return
            if req_path == b"/_recovery_verify": _handle_recovery_verify(client,query); return
            if req_path == b"/_recovery_restore": _handle_recovery_restore(client,query); return
            if req_path == b"/_recovery_export": _handle_recovery_export(client,query); return
            _handle_sensitive_mode(client); return
        if req_path == b"/_ui_scale":
            if req_method not in (b"GET",b"POST"):
                _serve_local(client,b'{"ok":false,"reason":"method"}',ctype="application/json; charset=utf-8"); return
            _handle_ui_scale(client,query,req_method); return
        if req_path == b"/_performance":
            if req_method != b"POST":
                _serve_local(client,b'{"ok":false,"reason":"method"}',ctype="application/json; charset=utf-8"); return
            _handle_performance(client,query); return
        if req_path == b"/_manifest.webmanifest":
            _serve_local(client,_PWA_MANIFEST,ctype="application/manifest+json; charset=utf-8"); return
        if req_path == b"/_sw.js":
            _serve_local(client,_PWA_SW,ctype="application/javascript; charset=utf-8"); return
        if req_path == b"/_pwa_icon.svg":
            _serve_local(client,_PWA_ICON,ctype="image/svg+xml; charset=utf-8"); return
        # المسارات الخاصة (الصوت + الـ wrapper + الملفات) تُعالَج محليًا
        if req_path == b"/_audio_ws":
            client.settimeout(None)
            _handle_audio_ws(client, head)
            return
        if req_path == b"/_wrapper":
            _serve_local(client, _wrapper_html(),
                         extra_headers=bootstrap_cookie)
            return
        if req_path == b"/_files":
            _handle_files_list(client, query)
            return
        if req_path == b"/_download":
            if req_method not in (b"GET", b"HEAD"):
                _serve_local(client,b'{"ok":false,"reason":"method"}',ctype="application/json; charset=utf-8")
                return
            client.settimeout(None)
            _handle_download(client, query, head, req_method)
            return
        if req_path == b"/_upload":
            if req_method != b"POST":
                _serve_local(client, b'{"ok":false,"reason":"method"}',
                             ctype="application/json; charset=utf-8")
                return
            client.settimeout(120)
            _handle_upload(client, head, query)
            return
        if req_path == b"/_copy_selected":
            if req_method != b"POST":
                _serve_local(client, b'{"ok":false,"reason":"method"}',
                             ctype="application/json; charset=utf-8")
                return
            _handle_copy_selected(client)
            return
        if req_path == b"/_desktop_clip":
            if req_method != b"GET":
                _serve_local(client, b'{"ok":false,"reason":"method"}',
                             ctype="application/json; charset=utf-8")
                return
            _handle_desktop_clip(client)
            return
        if req_path == b"/_clip":
            # Round 21: نص من الهاتف → حافظة سطح المكتب (UTF-8 عبر xsel)
            _handle_clip(client, head, query)
            return
        if req_path == b"/_paste":
            # لصق آمن موحّد (Ctrl+V) بعد التحق من نافذة نشطة — عربي/روابط
            _handle_paste(client, query)
            return
        if req_path == b"/_delete":
            # حذف يدوي آمن لملف واحد من PhoneFiles فقط — POST حصراً
            if req_method != b"POST":
                _serve_local(client,
                             b'{"ok":false,"reason":"method"}',
                             ctype="application/json; charset=utf-8")
                return
            _handle_delete(client, head, query)
            return
        if req_path == b"/_safe_cleanup":
            # زر «تنظيف مساحة Colab لآمن» — معاينة/تنفيذ (Zenity)
            _handle_safe_cleanup(client, query)
            return
        if req_path == b"/_expert_report":
            if req_method != b"GET":
                _serve_local(client,b'{"ok":false,"reason":"method"}',ctype="application/json; charset=utf-8")
                return
            _handle_expert_report(client)
            return
        if req_path == b"/_expert_status":
            if req_method != b"GET":
                _serve_local(client,b'{"ok":false,"reason":"method"}',ctype="application/json; charset=utf-8")
                return
            _handle_expert_status(client)
            return
        if req_path == b"/_desktop_repair":
            # إصلاح سطح المكتب المتدرّج يدويًّا (أمر desktop-repair)
            try:
                msg = desktop_repair(manual=True)
            except Exception as e:
                _diag_event("desktop_repair",e,"error")
                msg = "خطأ داخلي أثناء الإصلاح"
            _serve_local(client, msg.encode("utf-8"),
                         ctype="text/plain; charset=utf-8")
            return
        if req_path == b"/_screen":
            # v70: ملاءمة دقة سطح المكتب لاتجاه الهاتف (POST حصرًا)
            if req_method != b"POST":
                _serve_local(client, b'{"ok":false,"reason":"method"}',
                             ctype="application/json; charset=utf-8")
                return
            client.settimeout(90)
            _handle_screen_adapt(client, query)
            return
        if req_path == b"/_fit":
            # تكبير النافذة النشطة لتملأ الشاشة (بطلب من زر ⛶ في الشريط)
            try:
                run("DISPLAY=%s /usr/local/bin/fit-now >/tmp/fit-now-api.log 2>&1"
                    % DISPLAY_NUM)
            except Exception:
                pass
            _serve_local(client, b'{"ok":true}',
                         ctype="application/json; charset=utf-8")
            return
        # غير ذلك: تمرير إلى KasmVNC مع حقن ��لمصادقة
        head = _proxy_inject_auth(head)
        backend = socket.create_connection(("127.0.0.1", VNC_PORT),
                                            timeout=30)
        _proxy_tune(backend)
        backend.sendall(head)
        client.settimeout(None)
        backend.settimeout(None)
        with _TRAFFIC_LOCK:
            _TRAFFIC["connections"] += 1
        t1 = threading.Thread(target=_proxy_pipe, args=(client, backend, "up"),
                              daemon=True)
        t2 = threading.Thread(target=_proxy_pipe, args=(backend, client, "down"),
                              daemon=True)
        t1.start(); t2.start(); t1.join(); t2.join()
    except Exception as exc:
        _diag_event("proxy_handle",exc,"error")
    finally:
        if backend is not None:
            try:
                with _TRAFFIC_LOCK:
                    _TRAFFIC["connections"] = max(0, _TRAFFIC["connections"] - 1)
            except Exception:
                pass
        for s in (client, backend):
            try:
                if s:
                    s.close()
            except Exception:
                pass


def _bounded_proxy_handle(client):
    try:_proxy_handle(client)
    finally:
        try:_PROXY_CONNECTION_SLOTS.release()
        except ValueError:_diag_event("proxy_slot_overrelease")

def _reject_busy(client):
    try:
        body=b"Desktop is busy; retry shortly"
        client.sendall(("HTTP/1.1 503 Service Unavailable\r\nContent-Type: text/plain; charset=utf-8\r\nRetry-After: 2\r\nCache-Control: no-store\r\nContent-Length: %d\r\nConnection: close\r\n\r\n"%len(body)).encode("latin-1")+body)
    except Exception:pass
    finally:
        try:client.close()
        except Exception:pass

# V26: أغلق مستمع الجيل السابق قبل bind جديد. في %run -i يبقى الخيط daemon
# حيًا، لكن إغلاق socket يحرر المنفذ ويجعل MCP الجديد هو صاحب الطلبات.
_proxy_srv = _V26_PREVIOUS_PROXY_SRV
if _proxy_srv is not None:
    try:_proxy_srv.shutdown(socket.SHUT_RDWR)
    except Exception:pass
    try:_proxy_srv.close()
    except Exception:pass
    _proxy_srv=None
    _v26_release_deadline=time.time()+4
    while port_listening(PROXY_PORT) and time.time()<_v26_release_deadline:time.sleep(.1)


def start_auth_proxy():
    """يشغّل البروكسي على PROXY_PORT (يحقن المصادقة → KasmVNC على VNC_PORT)."""
    global _proxy_srv
    try:
        if _proxy_srv is not None:
            try:
                _proxy_srv.close()
            except Exception:
                pass
        srv = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        srv.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        srv.bind(("127.0.0.1", PROXY_PORT))
        srv.listen(128)
        _proxy_srv = srv

        def _accept_loop():
            while True:
                try:
                    client, _ = srv.accept()
                    if not _PROXY_CONNECTION_SLOTS.acquire(blocking=False):
                        with _TRAFFIC_LOCK:_TRAFFIC["rejected"]+=1
                        _diag_event("proxy_capacity");_reject_busy(client);continue
                    with _TRAFFIC_LOCK:_TRAFFIC["accepted"]+=1
                    try:_STRICT_EGRESS.kickstart()   # v108: إقلاع سريع لكل اتصال جديد
                    except Exception:pass
                    try:
                        threading.Thread(target=_bounded_proxy_handle,args=(client,),
                                         name="proxy_client",daemon=True).start()
                    except Exception:
                        _PROXY_CONNECTION_SLOTS.release();raise
                except Exception:
                    time.sleep(0.5)
                    continue

        threading.Thread(target=_accept_loop, daemon=True).start()
        return True
    except Exception as e:
        print("[!] تعذّر تشغيل بروكسي المصادقة: %s" % e)
        return False

# ============================================================
# 7) التشغيل الآمن
# ============================================================
def diagnose_and_autofix():
    """يفحص السجل ويُصلح الأسباب الشائعة تلقائيًا قبل إعادة المحاولة."""
    log = (run("tail -n 80 %s 2>/dev/null" % KASM_LOG).stdout or "") + \
          (run("tail -n 40 /root/.vnc/*.log 2>/dev/null").stdout or "")
    fixed = False
    # -1) طبقة إقلاع قديمة فقدت Xvnc مع بقاء سجل dpkg والمشغّل Perl.
    if ('couldn\'t find "/usr/bin/Xvnc"' in log or
            'couldn\'t find "/usr/bin/vncpasswd"' in log or
            "could not find /usr/bin/Xvnc" in log or
            "could not find /usr/bin/vncpasswd" in log or _kasm_missing_runtime()):
        if _ensure_kasm_runtime():
            print("     [auto-fix] استُعيدت ملفات Xvnc/vncpasswd وتحقق التنفيذ قبل المحاولة التالية.")
            fixed = True
        else:
            print("     [auto-fix] تعذرت استعادة Xvnc محليًا؛ سيُستخدم مسار التثبيت الكامل.")
    # KasmVNC 1.5 restored from the package cache can use an Xvnc build that
    # does not expose optional VideoTime/VideoArea CLI parameters.  Never let
    # an optional video-tuning key prevent the desktop from starting.
    if ("Unrecognized option: -VideoTime" in log or
            "Unrecognized option: -VideoArea" in log):
        import re as _re
        for _cfg in ("/etc/kasmvnc/kasmvnc.yaml", "/root/.vnc/kasmvnc.yaml"):
            try:
                _txt=Path(_cfg).read_text(encoding="utf-8")
                _txt=_re.sub(r"(?m)^    enter_video_encoding_mode:\n      time_threshold:.*\n      area_threshold:.*\n", "", _txt)
                Path(_cfg).write_text(_txt,encoding="utf-8")
            except Exception:
                pass
        print("     [auto-fix] أزيلت خيارات VideoTime/VideoArea غير المدعومة؛ سيبدأ KasmVNC بإعداداته المتوافقة.")
        fixed = True
    # 0) اعتماد Perl مفقود (السبب المباشر لخروج kasmvncserver بالرمز 2)
    if ("Can't locate Switch.pm" in log or "BEGIN failed--compilation aborted" in log):
        if _ensure_kasm_perl_switch():
            print("     [auto-fix] ثُبّت libswitch-perl وأصبح Switch.pm متاحًا.")
            fixed = True
        else:
            print("     [auto-fix] فشل تثبيت libswitch-perl؛ راجع سجل apt المطبوع.")
    # 1) سؤال DE / فشل select-de
    if ("choose Desktop Environment" in log or "select-de" in log
            or "will be overwritten" in log):
        run("touch /root/.vnc/.de-was-selected")
        print("     [auto-fix] أُنشئ .de-was-selected لتخطّي سؤال DE.")
        fixed = True
    # 2) شهادة snakeoil مفقودة أو غير قابلة للقراءة
    if ("snakeoil" in log or "certificate file doesn't exist" in log
            or "certificate isn't readable" in log
            or "kasmvnc-cert" in log):
        run("sudo openssl req -x509 -nodes -newkey rsa:2048 -days 3650 "
            "-subj '/CN=localhost' "
            "-keyout /etc/ssl/private/ssl-cert-snakeoil.key "
            "-out /etc/ssl/certs/ssl-cert-snakeoil.pem > /dev/null 2>&1")
        run("sudo chmod 600 /etc/ssl/private/ssl-cert-snakeoil.key "
            "&& sudo chmod 644 /etc/ssl/certs/ssl-cert-snakeoil.pem 2>/dev/null")
        print("     [auto-fix] أُعيد توليد شهادة snakeoil وجُعلت قابلة للقراءة.")
        fixed = True
    # 3) قفل X متبقٍّ / جلسة :1 عالقة (السبب الجذري لعدم الاستقرار)
    if ("is taken because of /tmp/.X" in log or "SocketListen" in log
            or "already running as" in log
            or "Unrecognized option: --version" in log):
        _hard_cleanup_display()
        print("     [auto-fix] تنظيف قسري كامل لجلسة :1 (قفل + PID عالق).")
        fixed = True
    return fixed

def _wait_port(seconds, process=None):
    """انتظر المنفذ، وتوقف فورًا إذا خرج المشغّل بدل إضاعة 45 ثانية."""
    for _ in range(seconds):
        if port_listening(VNC_PORT):
            return True
        if process is not None and process.poll() is not None:
            print("     [!] ��رج مشغّل KasmVNC مبكرًا (exit=%s)." % process.returncode)
            return False
        time.sleep(1)
    return port_listening(VNC_PORT)

# ============================================================
# 7.5) صحّة سطح المكتب: كشف الشاشة السوداء + إصلاح متدرّج + watchdog
# ------------------------------------------------------------
# المشكلة: أحيانًا يظهر سطح المكتب أسود مع بقء واجهة KasmVNC، ثم يعود.
# السبب الغال��: سقوط أحد مكوّنات XFCE (خاصة xfwm4/xfdesktop) أو عم استجابة
# شاشة X مؤقتًا. الحل هنا كاشف خفيف + إصلاح *دريجي* بأقل تدخل، مع lock
# وcooldown ≥ دقيقتين، وسِجلّ صغير. لا نستخدم pkill عام، ولا نقتل Chrome/
# Xvfb/KasmVNC إلا كحلّ أخير للأخير فقط.
# ============================================================
DESKTOP_WATCHDOG = os.environ.get("DESKTOP_WATCHDOG", "1") == "1"
_DESK_LOG = os.path.join("/tmp", "desktop_health.log")
_DESK_LOCK = "/tmp/desktop_repair.lock"
_DESK_COOLDOWN = 120  # ثانية بين أي إصلاحَين (≥ دقيقتين)
_desk_last_fix = {}   # مكوّن -> آخر وقت أُصلح فيه

_DESK_PROCS = ["xfce4-session", "xfwm4", "xfdesktop", "xfce4-panel"]

def _desk_log(msg):
    try:
        line = "[%s] %s\n" % (time.strftime("%H:%M:%S"), msg)
        with open(_DESK_LOG, "a") as f:
            f.write(line)
    except Exception:
        pass

def _proc_alive(name):
    return run("pgrep -x %s >/dev/null 2>&1 && echo 1" % name).stdout.strip() == "1"

def _x_responsive():
    """هل تستجيب شاشة X؟ (نجاح أيٍّ من xset/xdpyinfo/xprop = حيّة)."""
    for cmd in ("xset -display %s q", "xdpyinfo -display %s",
                "xprop -display %s -root _NET_SUPPORTED"):
        if run((cmd + " >/dev/null 2>&1 && echo 1") % DISPLAY_NUM).stdout.strip() == "1":
            return True
    return False

def desktop_health():
    """يُعيد dict بحالة كل مكوّن + استجابة X + آخر أسطر السجل."""
    st = {
        "Xvfb_or_Xvnc": _proc_alive("Xvnc") or _proc_alive("Xvfb"),
        "kasmvnc_port": port_listening(VNC_PORT),
        "x_responsive": _x_responsive(),
    }
    for p in _DESK_PROCS:
        st[p] = _proc_alive(p)
    return st

def _run_de_component(name):
    """يشغّل مكوّن XFCE ناقصًا فقط (بيئة العرض الصحيحة)، بلا لمس ��لبقية."""
    env = ("DISPLAY=%s XAUTHORITY=/root/.Xauthority HOME=/root "
           "XDG_RUNTIME_DIR=/tmp " % DISPLAY_NUM)
    run("setsid bash -c '%s %s' >/dev/null 2>&1 &" % (env, name))

def _restart_xfce_session():
    """يعيد تشغيل جلسة XFCE فقط (لا ��مسّ Xvfb/KasmVNC/Chrome)."""
    run("pkill -x xfce4-session 2>/dev/null")
    time.sleep(1)
    run("setsid bash -c 'DISPLAY=%s XAUTHORITY=/root/.Xauthority HOME=/root "
        "XDG_RUNTIME_DIR=/tmp startxfce4' >/dev/null 2>&1 &" % DISPLAY_NUM)

def _cooldown_ok(key):
    now = time.time()
    if now - _desk_last_fix.get(key, 0) < _DESK_COOLDOWN:
        return False
    _desk_last_fix[key] = now
    return True

def desktop_repair(manual=False):
    """إصلاح متدرّج ب��قل تدخل. لا ينفّذ شيئًا إن كانت الجلسة سليمة."""
    if os.path.exists(_DESK_LOCK):
        return "قيد الإصلاح بالفعل — تجاهُل."
    open(_DESK_LOCK, "w").close()
    try:
        st = desktop_health()
        # الجلسة سليمة تمامًا؟ لا تفعل شيئًا.
        if (st["Xvfb_or_Xvnc"] and st["kasmvnc_port"] and st["x_responsive"]
                and all(st[p] for p in _DESK_PROCS)):
            return "سليم ✅ — لا إصلاح."
        acted = []
        # (1) شغّل عمليات XFCE الناقصة فقط
        missing = [p for p in _DESK_PROCS if not st[p]]
        if missing and st["x_responsive"] and _cooldown_ok("component"):
            for p in missing:
                _run_de_component(p)
                acted.append("start:" + p)
            time.sleep(3)
            st = desktop_health()
        # (2) أعد تشغيل جلسة XFCE فقط عند الحاجة
        if manual and st["x_responsive"] and not all(st[p] for p in _DESK_PROCS) \
                and _cooldown_ok("session"):
            _restart_xfce_session()
            acted.append("restart:xfce-session")
            time.sleep(5)
            st = desktop_health()
        # (3) أعد تشغيل KasmVNC فقط إن كان متوقفًا أو لا يصل إلى DISPLAY
        if (not st["kasmvnc_port"] or not st["Xvfb_or_Xvnc"]) \
                and _cooldown_ok("kasm"):
            run("pkill -x Xvnc 2>/dev/null; pkill -f kasmvnc 2>/dev/null")
            time.sleep(1)
            start_kasm()
            acted.append("restart:kasmvnc")
            _wait_port(30)
            st = desktop_health()
        # (4) حلّ أخير: إعاة تشغيل Xvfb/الخادم كليًّا
        if (not st["Xvfb_or_Xvnc"] or (manual and not st["x_responsive"])) \
                and _cooldown_ok("xvfb"):
            _hard_cleanup_display()
            start_kasm()
            acted.append("restart:xvfb(last-resort)")
            _wait_port(30)
        msg = "إصلاح: " + (", ".join(acted) if acted else "لا شيء (cooldown أو لا يلزم)")
        _desk_log(msg + (" [يدوي]" if manual else ""))
        return msg
    finally:
        try:
            os.remove(_DESK_LOCK)
        except Exception:
            pass


# ============================================================
# v45.4) المحرك الخبير ال��عاملي — تحقق، تراجع، وثقة متدرجة
# ============================================================
# نظام خبير حتمي محلي، وليس نموجًا لغويًا حرًا. لا ينفذ أوامر قادمة من
# الإنترنت، ولا يحذف ملفات Chrome/Drive، ولا يغيّر مخطط الحفظ المثبت.
_EXPERT_ENABLED = str(os.environ.get("EXPERT_SELF_HEALING", "1")).lower() not in ("0","false","off","no")
_EXPERT_LOCK = threading.RLock()
_EXPERT_ACTIONS = collections.deque(maxlen=80)
_EXPERT_GLOBAL_ACTIONS = collections.deque(maxlen=12)
_EXPERT_FAILURE_WINDOW = collections.deque(maxlen=12)
_EXPERT_STREAKS = collections.defaultdict(int)
_EXPERT_CONFIDENCE = collections.defaultdict(float)
_EXPERT_NEXT_ALLOWED = collections.defaultdict(float)
_EXPERT_FAILURES = collections.defaultdict(int)
_EXPERT_SUSPENDED_UNTIL = collections.defaultdict(float)
_EXPERT_LAST_NOTICE = collections.defaultdict(float)
_EXPERT_RESCUE_UNTIL = 0.0
_EXPERT_CANARY_CYCLES = 2
_EXPERT_STATE = {
    "enabled": _EXPERT_ENABLED, "mode": "startup_canary", "cycle": 0,
    "last_check": 0.0, "last_error": "", "health": "starting",
    "active_rule": "", "safe_actions": 0, "failed_actions": 0,
    "rollbacks": 0, "rescue_entries": 0, "guard": "transactional-non-destructive",
    "release_stage": "canary", "version": "v45.5"
}

def _expert_record(rule,result,detail="",before=None,after=None,confidence=None,txid=""):
    item={"time":int(time.time()),"rule":str(rule)[:64],"result":str(result)[:32],
          "detail":str(detail)[:240]}
    if isinstance(before,bool):item["before_ok"]=before
    if isinstance(after,bool):item["after_ok"]=after
    if isinstance(confidence,(int,float)):item["confidence"]=round(float(confidence),3)
    if txid:item["txid"]=str(txid)[:32]
    with _EXPERT_LOCK:_EXPERT_ACTIONS.append(item)
    try:_diag_event("expert:%s:%s"%(rule,result),detail)
    except Exception:pass

def _expert_enter_rescue(reason,seconds=900):
    global _EXPERT_RESCUE_UNTIL
    with _EXPERT_LOCK:
        _EXPERT_RESCUE_UNTIL=max(_EXPERT_RESCUE_UNTIL,time.monotonic()+max(300,int(seconds)))
        _EXPERT_STATE["mode"]="safe_rescue";_EXPERT_STATE["health"]="degraded"
        _EXPERT_STATE["rescue_entries"]+=1
    _expert_record("rescue","entered",str(reason)[:180])

def _expert_note_failure(rule):
    now=time.monotonic()
    with _EXPERT_LOCK:
        _EXPERT_FAILURE_WINDOW.append(now)
        while _EXPERT_FAILURE_WINDOW and now-_EXPERT_FAILURE_WINDOW[0]>600:
            _EXPERT_FAILURE_WINDOW.popleft()
        trip=len(_EXPERT_FAILURE_WINDOW)>=3
    if trip:_expert_enter_rescue("three repair failures in ten minutes")

def _expert_confidence(streak,base=.50,step=.16):
    return max(0.0,min(.99,float(base)+max(0,int(streak))*float(step)))

def _protection_checkpoint():
    paths=[os.path.join(d,"strict-adult-protection.json") for d in
           ("/etc/opt/chrome/policies/managed","/etc/chromium/policies/managed")]
    paths += ["/opt/strict-safe-search/manifest.json","/opt/strict-safe-search/safe-search.js"]
    paths += [os.path.join(d,"proton-vpn-extension.json") for d in
              ("/etc/opt/chrome/policies/managed","/etc/chromium/policies/managed")]
    out={}
    for path in paths:
        try:out[path]=(True,open(path,"rb").read())
        except FileNotFoundError:out[path]=(False,b"")
        except Exception:out[path]=(None,b"")
    return out

def _protection_rollback(checkpoint):
    if not isinstance(checkpoint,dict):return False
    ok=True
    for path,item in checkpoint.items():
        existed,data=item
        if existed is None:continue
        try:
            if existed:
                os.makedirs(os.path.dirname(path),exist_ok=True)
                tmp=path+".expert-rollback-%d"%os.getpid()
                with open(tmp,"wb") as f:f.write(data);f.flush();os.fsync(f.fileno())
                os.chmod(tmp,0o644);os.replace(tmp,path)
            elif os.path.exists(path):os.unlink(path)
        except Exception:ok=False
    return ok

def _expert_action(rule,action,verify,rollback=None,checkpoint=None,cooldown=300,
                   detail="",confidence=1.0,min_confidence=.90):
    """معاملة إصلاح واحدة: precheck→checkpoint→action→verify→rollback."""
    global _EXPERT_RESCUE_UNTIL
    now=time.monotonic();txid=("%x-%s"%(int(time.time()*1000),rule))[-32:]
    try:
        before=bool(verify())
    except Exception:
        before=False
    if before:
        _expert_record(rule,"no_op","healthy before action",True,True,confidence,txid)
        return True,"already_healthy"
    with _EXPERT_LOCK:
        if not _EXPERT_ENABLED:return False,"disabled"
        if _EXPERT_STATE.get("cycle",0)<=_EXPERT_CANARY_CYCLES:return False,"startup_canary"
        if now<_EXPERT_RESCUE_UNTIL:return False,"safe_rescue"
        if float(confidence)<float(min_confidence):return False,"low_confidence"
        if now<_EXPERT_SUSPENDED_UNTIL[rule]:return False,"rule_suspended"
        if now<_EXPERT_NEXT_ALLOWED[rule]:return False,"cooldown"
        while _EXPERT_GLOBAL_ACTIONS and now-_EXPERT_GLOBAL_ACTIONS[0]>900:_EXPERT_GLOBAL_ACTIONS.popleft()
        if len(_EXPERT_GLOBAL_ACTIONS)>=4:
            _EXPERT_RESCUE_UNTIL=max(_EXPERT_RESCUE_UNTIL,now+600)
            return False,"global_circuit"
        _EXPERT_NEXT_ALLOWED[rule]=now+max(60,int(cooldown))
        _EXPERT_GLOBAL_ACTIONS.append(now);_EXPERT_STATE["active_rule"]=rule
    cp=None
    try:
        if checkpoint is not None:cp=checkpoint()
        action();time.sleep(2)
        after=bool(verify())
        if after:
            with _EXPERT_LOCK:
                _EXPERT_FAILURES[rule]=0;_EXPERT_STATE["safe_actions"]+=1
            _expert_record(rule,"committed",detail,before,True,confidence,txid)
            return True,"committed"
        rolled=False
        if rollback is not None:
            try:rolled=bool(rollback(cp))
            except Exception:rolled=False
        with _EXPERT_LOCK:
            _EXPERT_FAILURES[rule]+=1;_EXPERT_STATE["failed_actions"]+=1
            if rolled:_EXPERT_STATE["rollbacks"]+=1
            if _EXPERT_FAILURES[rule]>=2:_EXPERT_SUSPENDED_UNTIL[rule]=time.monotonic()+600
        _expert_note_failure(rule)
        _expert_record(rule,"rolled_back" if rolled else "verify_failed",detail,before,False,confidence,txid)
        return False,"rolled_back" if rolled else "verify_failed"
    except Exception as exc:
        rolled=False
        if rollback is not None:
            try:rolled=bool(rollback(cp))
            except Exception:rolled=False
        with _EXPERT_LOCK:
            _EXPERT_FAILURES[rule]+=1;_EXPERT_STATE["failed_actions"]+=1
            if rolled:_EXPERT_STATE["rollbacks"]+=1
            if _EXPERT_FAILURES[rule]>=2:_EXPERT_SUSPENDED_UNTIL[rule]=time.monotonic()+600
            _EXPERT_STATE["last_error"]=(type(exc).__name__+": "+str(exc))[:240]
        _expert_note_failure(rule)
        _expert_record(rule,"exception_rollback" if rolled else "exception",type(exc).__name__,before,False,confidence,txid)
        return False,"exception"
    finally:
        with _EXPERT_LOCK:_EXPERT_STATE["active_rule"]=""

def _expert_snapshot():
    desk=desktop_health();prot=_protection_status_data()
    with _TRAFFIC_LOCK:active_connections=int(_TRAFFIC.get("connections",0))
    dead=[]
    try:
        with _MANAGED_LOCK:
            for name,info in _MANAGED.items():
                th=info.get("thread")
                if th is not None and not th.is_alive():dead.append(name)
    except Exception:pass
    try:work=_workspace_status_data()
    except Exception:work={}
    return {"desktop":desk,"protection":bool(prot.get("overall")),
            "proxy":bool(port_listening(PROXY_PORT)),
            "tunnel":bool(_cf_proc is not None and _cf_proc.poll() is None),
            "drive":bool(DRIVE_OK and os.path.isdir('/content/drive/MyDrive')),
            "connections":active_connections,"dead_managed":dead,"workspaces":work}

_EXTENSION_GUARD_STATE={"status":"waiting","last_check":0,"version":"","permission_change":False,"critical_added":[]}
_RESTORE_DRILL_STATE={"status":"not_run","last_check":0,"workspaces":{}}
_BLACK_SCREEN_STATE={"available":False,"black":False,"streak":0,"last_check":0,"repairs":0}
_SAVE_SCHEDULER_STATE={"pressure":False,"deferred":False,"reason":""}
_SAVE_PRESSURE_STARTED=0.0

def _extension_permission_guard():
    import hashlib as _h
    now=int(time.time());_EXTENSION_GUARD_STATE['last_check']=now
    try:
        m=json.load(open(os.path.join(_COLAB_REFRESH_DIR,'manifest.json'),encoding='utf-8'))
        def ss(v):return sorted(set(x for x in (v or []) if isinstance(x,str)))
        matches=[]
        for x in m.get('content_scripts',[]) or []:
            if isinstance(x,dict):matches+=ss(x.get('matches'))
        rec={'version':str(m.get('version',''))[:40],'permissions':ss(m.get('permissions')),
             'host_permissions':ss(m.get('host_permissions')),'content_matches':sorted(set(matches))}
        rec['permission_sha256']=_h.sha256(json.dumps({k:v for k,v in rec.items() if k!='version'},sort_keys=True,separators=(',',':')).encode()).hexdigest()
        exact=(rec['host_permissions']==['https://colab.research.google.com/*'] and
               rec['content_matches']==['https://colab.research.google.com/*'] and
               set(rec['permissions'])=={'alarms','storage','tabs'} and _verify_local_colab_refresh())
        if not exact:raise ValueError('unexpected-local-extension-scope')
        status='unchanged'
    except Exception:
        _EXTENSION_GUARD_STATE.update(status='manifest_unreadable_or_changed',permission_change=True,critical_added=[])
        return dict(_EXTENSION_GUARD_STATE)
    _EXTENSION_GUARD_STATE.update(status=status,version=rec['version'],permission_change=False,
                                  critical_added=[],permission_sha256=rec['permission_sha256'])
    return dict(_EXTENSION_GUARD_STATE)

def _read_only_restore_drill():
    now=int(time.time());result={}
    if not (DRIVE_OK and os.path.isdir('/content/drive/MyDrive')):out={'status':'drive_unavailable','last_check':now,'workspaces':{}}
    else:
        for n in _known_workspace_ids():
            c=[_inspect_recovery_slot(n,x,False) for x in ('slot-a','slot-b','slot-c','pre-upgrade','legacy')];c=[x for x in c if x.get('exists') and x.get('valid')]
            if not c:result[str(n)]={'status':'no_valid_candidate'};continue
            best=max(c,key=lambda x:int(x.get('generation') or 0));q=_inspect_recovery_slot(n,best['slot'],True)
            result[str(n)]={'status':'verified' if q.get('valid') else 'failed','slot':q.get('slot'),'generation':q.get('generation'),'files':q.get('files'),'verified_now':bool(q.get('verified_now'))}
        out={'status':'complete','last_check':now,'workspaces':result}
    _RESTORE_DRILL_STATE.clear();_RESTORE_DRILL_STATE.update(out);_expert_record('restore_drill','complete','read-only');return out

def _screen_luma_probe():
    """قياس سطوع/تنوّع الشاشة (8×8 رمادي) لاكتشاف الشاشة السوداء.

    v47: كان يعتمد على `import` وحده وهو غير مثبّت افتراضيًّا، فيرجع
    available=False دائمًا ⇒ الحارس معطّل بصمت. الآن يجرّب `import` ثم
    `xwd` كبديل. التكلفة صفر شبكة (كل شيء داخل الجهاز، صورة 8×8).
    """
    fmt='%s %s'%('%[fx:mean]','%[fx:standard_deviation]')
    if not shutil.which('convert'):
        return {'available':False,'black':False,'reason':'no_imagemagick'}
    srcs=[]
    if shutil.which('import'):
        srcs.append("DISPLAY=%s import -window root png:- 2>/dev/null"%DISPLAY_NUM)
    if shutil.which('xwd'):
        srcs.append("DISPLAY=%s xwd -root -silent 2>/dev/null"%DISPLAY_NUM)
    for src in srcs:
        cmd=("%s | convert - -resize 8x8\\! -colorspace Gray "
             "-format '%s' info: 2>/dev/null"%(src,fmt))
        try:
            p=(run(cmd,timeout=8).stdout or '').split()
            mean=float(p[0]);std=float(p[1])
            return {'available':True,'black':mean<.015 and std<.008,
                    'mean':round(mean,5),'stddev':round(std,5)}
        except Exception:
            continue
    return {'available':False,'black':False,'reason':'capture_failed'}

def _black_screen_guard():
    q=_screen_luma_probe();_BLACK_SCREEN_STATE.update(available=q.get('available',False),black=q.get('black',False),last_check=int(time.time()),last_mean=q.get('mean'),last_stddev=q.get('stddev'))
    _BLACK_SCREEN_STATE['streak']=(_BLACK_SCREEN_STATE['streak']+1) if q.get('black') else 0
    if q.get('available') and _BLACK_SCREEN_STATE['streak']>=4 and _x_responsive():
        def restart():_restart_xfce_session();time.sleep(5)
        ok,_=_expert_action('black_screen',restart,lambda:not _screen_luma_probe().get('black',True),cooldown=600,detail='XFCE-only restart after four black probes',confidence=.98,min_confidence=.95)
        if ok:_BLACK_SCREEN_STATE['streak']=0;_BLACK_SCREEN_STATE['repairs']+=1
    return dict(_BLACK_SCREEN_STATE)

def _smart_save_scheduler():
    global _PERFORMANCE_PAUSE_UNTIL,_SAVE_PRESSURE_STARTED
    mem=0
    try:
        for ln in open('/proc/meminfo'):
            if ln.startswith('MemAvailable:'):mem=int(ln.split()[1])//1024;break
    except Exception:pass
    try:cpu=min(100.,os.getloadavg()[0]/max(1,CPU_COUNT)*100.)
    except Exception:cpu=0.
    with _TRAFFIC_LOCK:conn=int(_TRAFFIC.get('connections',0))
    pressure=conn>0 and (cpu>=92 or (mem and mem<384));deferred=False;reason=''
    if pressure:
        if not _SAVE_PRESSURE_STARTED:_SAVE_PRESSURE_STARTED=time.monotonic()
        if time.monotonic()-_SAVE_PRESSURE_STARTED<600:_PERFORMANCE_PAUSE_UNTIL=max(_PERFORMANCE_PAUSE_UNTIL,time.time()+90);deferred=True;reason='cpu' if cpu>=92 else 'memory'
    else:_SAVE_PRESSURE_STARTED=0.
    _SAVE_SCHEDULER_STATE.update(pressure=pressure,deferred=deferred,reason=reason,cpu_pct=round(cpu,1),mem_available_mb=mem);return dict(_SAVE_SCHEDULER_STATE)

def _safe_diagnostic_data():
    ws=_workspace_status_data();safe={str(n):{k:v.get(k) for k in ('workspace','state','message','generation','age_seconds','updated_at') if k in v} for n,v in ws.items()}
    p=_protection_status_data()
    return {'ok':True,'version':'v45.29','generated_at':int(time.time()),'desktop':desktop_health(),'metrics':_runtime_metrics(),'workspaces':safe,'protection':{'overall':p.get('overall'),'policy_ok':p.get('policy_ok'),'extensions_policy_ok':p.get('extensions_policy_ok'),'colab_keep_alive_managed':p.get('colab_keep_alive_managed')},'extension_guard':dict(_EXTENSION_GUARD_STATE),'restore_drill':dict(_RESTORE_DRILL_STATE),'black_screen':dict(_BLACK_SCREEN_STATE),'save_scheduler':dict(_SAVE_SCHEDULER_STATE),'expert':_expert_public_status().get('expert',{})}

def _write_safe_diagnostic_file():
    try:
        path='/content/desktop-diagnostic-v44-9.json';tmp=path+'.tmp'
        with open(tmp,'w',encoding='utf-8') as f:json.dump(_safe_diagnostic_data(),f,ensure_ascii=False,separators=(',',':'));f.flush();os.fsync(f.fileno())
        os.chmod(tmp,0o600);os.replace(tmp,path);return True
    except Exception:return False

def _handle_expert_report(client):
    body=json.dumps(_safe_diagnostic_data(),ensure_ascii=False,separators=(',',':')).encode()
    _serve_local(client,body,ctype='application/json; charset=utf-8',extra_headers='Content-Disposition: attachment; filename="desktop-diagnostic-v44-9.json"\\r\\n')

def _expert_public_status():
    with _EXPERT_LOCK:
        state=dict(_EXPERT_STATE);state["actions"]=list(_EXPERT_ACTIONS)[-20:]
        state["streaks"]={k:int(v) for k,v in _EXPERT_STREAKS.items() if v}
        state["confidence"]={k:round(float(v),3) for k,v in _EXPERT_CONFIDENCE.items()}
        state["suspended_rules"]=[k for k,v in _EXPERT_SUSPENDED_UNTIL.items() if time.monotonic()<v]
        state["rescue_active"]=time.monotonic()<_EXPERT_RESCUE_UNTIL
        state["rescue_remaining_seconds"]=max(0,int(_EXPERT_RESCUE_UNTIL-time.monotonic()))
    state["extension_guard"]=dict(_EXTENSION_GUARD_STATE)
    state["restore_drill"]=dict(_RESTORE_DRILL_STATE)
    state["black_screen"]=dict(_BLACK_SCREEN_STATE)
    state["save_scheduler"]=dict(_SAVE_SCHEDULER_STATE)
    return {"ok":True,"expert":state}

def _handle_expert_status(client):
    body=json.dumps(_expert_public_status(),ensure_ascii=False,separators=(",",":")).encode("utf-8")
    _serve_local(client,body,ctype="application/json; charset=utf-8")

def _expert_notice(key,detail,every=900):
    now=time.monotonic()
    if now-_EXPERT_LAST_NOTICE[key]>=every:
        _EXPERT_LAST_NOTICE[key]=now;_expert_record(key,"observed",detail)

def _expert_save_health_only(workspaces):
    """فحص حفظ للقراءة فقط؛ يمنع أي إصلاح تلقائي لملفات المستخدم."""
    for n,ws in (workspaces or {}).items():
        state=str((ws or {}).get("state",""));age=(ws or {}).get("age_seconds")
        if state in ("error","corrupt","failed"):_expert_notice("workspace_"+str(n),"state="+state,300)
        elif isinstance(age,(int,float)) and age>900 and state not in ("not_started","idle"):
            _expert_notice("workspace_stale_"+str(n),"save status stale",600)

def expert_self_healing_loop():
    """تشخيص متكرر وإصلاح منخفض المخاطر فقط، مع وضع إنقاذ تلقائي."""
    time.sleep(20)
    while True:
        try:
            snap=_expert_snapshot()
            with _EXPERT_LOCK:
                _EXPERT_STATE["cycle"]+=1;cycle=_EXPERT_STATE["cycle"]
                _EXPERT_STATE["last_check"]=time.time()
                _EXPERT_STATE["release_stage"]="canary" if cycle<=_EXPERT_CANARY_CYCLES else "stable"
                _EXPERT_STATE["mode"]="startup_canary" if cycle<=_EXPERT_CANARY_CYCLES else "analyze"
            desk=snap["desktop"]
            desk_ok=bool(desk.get("Xvfb_or_Xvnc") and desk.get("kasmvnc_port") and
                         desk.get("x_responsive") and all(desk.get(p) for p in _DESK_PROCS))
            checks={"protection":snap["protection"],"desktop":desk_ok,"proxy":snap["proxy"]}
            for key,ok in checks.items():
                _EXPERT_STREAKS[key]=0 if ok else _EXPERT_STREAKS[key]+1
                _EXPERT_CONFIDENCE[key]=1.0 if ok else _expert_confidence(_EXPERT_STREAKS[key])
            if _EXPERT_STREAKS["protection"]>=3:
                _expert_action("protection",_repair_protection_files,
                    lambda:bool(_protection_status_data().get("overall")),
                    rollback=_protection_rollback,checkpoint=_protection_checkpoint,
                    cooldown=300,detail="verified policy restoration",
                    confidence=_EXPERT_CONFIDENCE["protection"],min_confidence=.90)
                _EXPERT_STREAKS["protection"]=0
            if _EXPERT_STREAKS["desktop"]>=3:
                _expert_action("desktop",lambda:desktop_repair(manual=False),
                    lambda:bool(desktop_health().get("Xvfb_or_Xvnc") and desktop_health().get("kasmvnc_port")),
                    cooldown=180,detail="minimal desktop service recovery",
                    confidence=_EXPERT_CONFIDENCE["desktop"],min_confidence=.90)
                _EXPERT_STREAKS["desktop"]=0
            if _EXPERT_STREAKS["proxy"]>=3:
                _expert_action("proxy",start_auth_proxy,lambda:bool(port_listening(PROXY_PORT)),
                    cooldown=180,detail="local proxy socket recovery",
                    confidence=_EXPERT_CONFIDENCE["proxy"],min_confidence=.90)
                _EXPERT_STREAKS["proxy"]=0
            if not snap["drive"]:_expert_notice("drive_unavailable","Drive unavailable; all data repair refused")
            if snap["dead_managed"]:_expert_notice("managed_thread",",".join(snap["dead_managed"]),300)
            _expert_save_health_only(snap.get("workspaces"))
            _smart_save_scheduler()
            if cycle==1 or cycle%20==0:
                _extension_permission_guard();_write_safe_diagnostic_file()
            if cycle>=6 and cycle%240==6 and snap.get("connections",0)==0 and snap.get("drive"):
                _read_only_restore_drill()
            if cycle%2==0:
                _black_screen_guard()
            all_ok=all(checks.values())
            with _EXPERT_LOCK:
                rescue=time.monotonic()<_EXPERT_RESCUE_UNTIL
                _EXPERT_STATE["health"]="healthy" if all_ok else ("degraded" if rescue else "recovering")
                _EXPERT_STATE["mode"]="safe_rescue" if rescue else ("observe" if cycle>_EXPERT_CANARY_CYCLES else "startup_canary")
                if all_ok:_EXPERT_STATE["last_error"]=""
        except Exception as exc:
            with _EXPERT_LOCK:
                _EXPERT_STATE["health"]="degraded";_EXPERT_STATE["mode"]="safe_wait"
                _EXPERT_STATE["last_error"]=(type(exc).__name__+": "+str(exc))[:240]
            _expert_record("engine","exception",type(exc).__name__)
        time.sleep(45)

def _desktop_watchdog_loop():
    # v46: كان أول سطرين (_desk_log و=0) خارج أي حماية؛ لو فشل _desk_log
    # (قرص ممتلئ/صلاحيات) لمات الـ watchdog كليًّا وفقد النظام إصلاحه الذاتي،
    # فيبقى سطح المكتب معط��بًا بلا أي محاولة تصحيح.
    try:
        _desk_log("watchdog مستقر بدأ (يتطلب 3 إخفاقات متتالية).")
    except Exception:
        pass
    failures = 0
    while True:
        try:
            time.sleep(60)
        except Exception:
            return
        try:
            st = desktop_health()
            bad = (not st["kasmvnc_port"]
                   or not st["Xvfb_or_Xvnc"]
                   or not all(st[p] for p in _DESK_PROCS))
            if bad:
                failures += 1
                _desk_log("فحص غير سليم %d/3: %s" %
                          (failures, {k: v for k, v in st.items() if not v}))
                if failures >= 3:
                    desktop_repair()
                    failures = 0
            else:
                failures = 0
        except Exception as e:
            _desk_log("watchdog خطأ: %s" % e)

_DESKTOP_ICONS_FIX_SH = r'''#!/bin/bash
# يعيد أيقونات وخلفية سطح المكتب إذا اختفت (سقوط xfdesktop أو تعطّل
# إعداد الأيقونات). آمن تمامًا: لا يقتل أي تطبيق ولا يمسّ النوافذ المفتوحة.
export DISPLAY="${DISPLAY:-__DISPLAY_NUM__}"
export XAUTHORITY="${XAUTHORITY:-/root/.Xauthority}"
export HOME=/root
export XDG_RUNTIME_DIR="${XDG_RUNTIME_DIR:-/tmp}"

mkdir -p /root/Desktop 2>/dev/null || true
chmod +x /root/Desktop/*.desktop 2>/dev/null || true
for f in /root/Desktop/*.desktop; do
  [ -e "$f" ] || continue
  gio set "$f" metadata::trusted true >/dev/null 2>&1 || true
done

if command -v xfconf-query >/dev/null 2>&1; then
  xfconf-query -c xfce4-desktop -p /desktop-icons/style -t int -s 2 --create >/dev/null 2>&1 || true
  xfconf-query -c xfce4-desktop -p /desktop-icons/show-tooltips -t bool -s false --create >/dev/null 2>&1 || true
  xfconf-query -c xfce4-desktop -p /desktop-icons/tooltip-size -t uint -s 0 --create >/dev/null 2>&1 || true
  xfconf-query -c xfce4-desktop -p /desktop-icons/file-icons/show-home -t bool -s true --create >/dev/null 2>&1 || true
  xfconf-query -c xfce4-desktop -p /desktop-icons/file-icons/show-trash -t bool -s true --create >/dev/null 2>&1 || true
fi

# تحقق قابل للرصد: تبقى الخاصية false حتى بعد استعادة إعدادات قديمة من Drive.
if command -v xfconf-query >/dev/null 2>&1; then
  TIP_STATE=$(xfconf-query -c xfce4-desktop -p /desktop-icons/show-tooltips 2>/dev/null || echo true)
  [ "$TIP_STATE" = "false" ] || \
    xfconf-query -c xfce4-desktop -p /desktop-icons/show-tooltips -t bool -s false --create >/dev/null 2>&1 || true
fi

if pgrep -x xfdesktop >/dev/null 2>&1; then
  xfdesktop --reload >/dev/null 2>&1 || true
  sleep 2
fi
if ! pgrep -x xfdesktop >/dev/null 2>&1; then
  setsid xfdesktop >> /root/.vnc/xfdesktop.log 2>&1 &
  sleep 3
fi

if pgrep -x xfdesktop >/dev/null 2>&1; then
  echo "[OK] أيقونات سطح المكتب تعمل ✅"
  exit 0
fi
echo "[!] تعذّر تشغيل xfdesktop — راجع /root/.vnc/xfdesktop.log"
exit 1
'''


def _write_desktop_cmds():
    """أوامر shell: desktop-health و desktop-repair (تستدعيا�� بايثون الحيّ)."""
    hp = ("#!/bin/bash\n"
          "echo '=== حالة سطح المكتب ==='\n"
          "for p in Xvnc Xvfb xfce4-session xfwm4 xfdesktop xfce4-panel; do\n"
          "  if pgrep -x \"$p\" >/dev/null 2>&1; then echo \"✅ $p\"; "
          "else echo \"❌ $p\"; fi\n"
          "done\n"
          "if xset -display %s q >/dev/null 2>&1; then echo '✅ شاشة X تستجيب'; "
          "else echo '❌ شاشة X لا تستجيب'; fi\n"
          "echo '--- آخر السجل ---'; tail -n 15 %s 2>/dev/null || "
          "echo '(لا سجل)'\n" % (DISPLAY_NUM, _DESK_LOG))
    with open("/usr/local/bin/desktop-health", "w") as f:
        f.write(hp)
    run("chmod +x /usr/local/bin/desktop-health")
    rp = ("#!/bin/bash\n"
          "# يستدعي منفذ الإصلاح داخل عملية بايثون الحيّة عبر HTTP محلي.\n"
          "curl -s -X POST http://127.0.0.1:%d/_desktop_repair 2>/dev/null "
          "|| echo 'تعذّر الاتصال بخادم البروكسي'\n"
          "echo; tail -n 8 %s 2>/dev/null\n" % (PROXY_PORT, _DESK_LOG))
    with open("/usr/local/bin/desktop-repair", "w") as f:
        f.write(rp)
    run("chmod +x /usr/local/bin/desktop-repair")
    # إصلاح اختفاء أيقونات سطح المكتب (xfdesktop) دون لمس النوافذ المفتوحة.
    di = _DESKTOP_ICONS_FIX_SH.replace("__DISPLAY_NUM__", str(DISPLAY_NUM))
    with open("/usr/local/bin/desktop-icons-fix", "w", encoding="utf-8") as f:
        f.write(di)
    run("chmod +x /usr/local/bin/desktop-icons-fix")

def safe_start():
    print("[6] تنظيف الجلسات السابقة...")
    for p in ["Xvnc", "kasmvnc", "xfce4-session", "pulseaudio", "cloudflared"]:
        run("pkill -9 -f %s" % p)
    run("vncserver -kill %s > /dev/null 2>&1" % DISPLAY_NUM)
    time.sleep(2)
    print("[7] تشغيل الصوت...");          start_audio()
    # محاولات متعددة مع إصلاح تلقائي بينها — يضمن عدم تكرار الفشل
    ok = False
    for attempt in range(1, 4):
        print("[8] تشغيل KasmVNC + XFCE... (محاولة %d/3)" % attempt)
        try:
            _kasm_process = start_kasm()
        except (FileNotFoundError, PermissionError, RuntimeError, OSError) as exc:
            # لا نُسقط السكربت بالكامل إذا كانت استعادة الحزمة ناقصة؛ مرحلة
            # التثبيت أعلاه ستعيد تنزيلها في التشغيل التالي بدل الخطأ المضلل.
            print("     [!] تعذّر تشغيل KasmVNC: %s" % exc)
            print("     [i] التثبيت غير مكتمل؛ لم يُعتبر صالحًا ولن يُتخطّى لاحقًا.")
            ok = False
            break
        print("     انتظار جاهزية الخادم (حتى 45 ثانية)...")
        ok = _wait_port(45, _kasm_process)
        if ok:
            break
        print("     [!] لم يبدأ الخادم — تشخيص تلقائي...")
        _brief = run("tail -n 25 %s 2>/dev/null" % KASM_LOG).stdout.strip()
        if _brief:
            print("----- تشخيص KasmVNC -----")
            print(_brief)
            print("----- نهاية التشخيص -----")
        did_fix = diagnose_and_autofix()
        if not did_fix and attempt >= 2:
            break  # لا فائدة من إعادة المحاولة بدون إصلاح
        run("pkill -9 -f Xvnc"); run("pkill -9 -f kasmvnc")
        run("vncserver -kill %s > /dev/null 2>&1" % DISPLAY_NUM)
        time.sleep(2)
    print("[OK] KasmVNC: %s | المنفذ %d"
          % ("يعمل ✅" if ok else "متوقف ❌", VNC_PORT))
    if not ok:
        print("\n--- آخر 50 سطر من السجل ---")
        print(run("tail -n 50 %s 2>/dev/null" % KASM_LOG).stdout or "(لا يوجد سجل)")
        print(run("tail -n 30 /root/.vnc/*.log 2>/dev/null").stdout or "")
        print("--- نهاية السجل ---\n")
    return ok

# كل ملفات الحزم والمشغلات والسياسات أصبحت مكتوبة؛ يمكن الآن التقاط لقطة
# متسقة فور اكتمال التطبيقات الخلفية، قبل بدء خدمات الجلسة المتغيرة.
_SYSTEM_CONFIGURATION_DONE.set()
