# إن كانت حزمة cloudflared محفوظة في Drive فانسخها بالتوازي الآن بدل انتظار مرحلة النفق.
def _v25_prefetch_cloudflared_cache():
    try:
        if os.path.isfile('/tmp/cloudflared') and os.path.getsize('/tmp/cloudflared')>5_000_000:return
        candidates=(os.path.join(PERSIST_DIR,'pkg-cache','cloudflared-linux-amd64'),
                    os.path.join(PERSIST_DIR,'package_store','cloudflared-linux-amd64'))
        src=next((x for x in candidates if os.path.isfile(x) and os.path.getsize(x)>5_000_000),None)
        if not src:return
        tmp='/tmp/cloudflared.v25-part';shutil.copy2(src,tmp);os.chmod(tmp,0o755)
        if run([tmp,'--version'],timeout=15).returncode!=0:os.unlink(tmp);return
        os.replace(tmp,'/tmp/cloudflared')
    except Exception as exc:_diag_event('cloudflared_cache_prefetch',exc)
threading.Thread(target=_v25_prefetch_cloudflared_cache,name='cloudflared-cache-prefetch',daemon=True).start()

# ============================================================
# *** v109 — خزنة بيانات الدخول المشفّرة (Credentials Vault) ***
# ============================================================
# تسجيلات الدخول في كل نوافذ «ملف العمل» (Cookies + Login Data +
# Web Data + التفضيلات) تُحفَظ دوريًّا في ملف واحد مُشفّر AES-256
# داخل درايف، وتُستعاد تلقائيًّا في الخلفية عند التشغيل. طبقة
# إضافية مستقلة تمامًا: لا تعديل على مسارات الحفظ القائمة، وأي
# فشل هنا لا يؤثّر في أي نظام آخر إطلاقًا.
import tarfile as _cred_tarfile
import urllib.parse as _cred_urlparse
import atexit as _cred_atexit
CRED_LOCAL_ROOT = "/root/.chrome-profiles-local"
CRED_VAULT_DIR = os.path.join(PERSIST_DIR, "chrome-profiles", ".cred-vault")
CRED_DB_NAMES = ('Cookies', 'Network/Cookies', 'Login Data',
                 'Login Data For Account', 'Web Data')
CRED_JSON_NAMES = ('Preferences', 'Secure Preferences')
_CRED_SYNC_SECONDS = 180


def _cred_tar_extract(tf, path):
    """استخراج آمن متوافق مع كل إصدارات بايثون — 3.12+/3.14 تشترط
    filter='data'، والأقدم لا يعرفه. أرشيفاتنا ذاتية الإنشاء وملفاتها
    عادية فقط فالمرشّح آمن."""
    try:
        tf.extractall(path, filter='data')
    except TypeError:
        tf.extractall(path)


def _cred_key_file():
    """ملف كلمة مرور التشفير: من البيئة CRED_VAULT_PASS إن وُجد، وإلا
    مفتاح عشوائي دائم في درايف (يُنشأ مرة واحدة) مع احتياط محلي."""
    envp = os.environ.get("CRED_VAULT_PASS", "").strip()
    local = "/root/.cred-vault.key"
    if envp:
        try:
            with open(local, "w") as f:
                f.write(envp + "\n")
            os.chmod(local, 0o600)
        except Exception:
            pass
        return local
    drive_key = os.path.join(CRED_VAULT_DIR, ".key")
    try:
        os.makedirs(CRED_VAULT_DIR, exist_ok=True)
        if not os.path.isfile(drive_key) or os.path.getsize(drive_key) < 32:
            with open(drive_key, "w") as f:
                f.write(secrets.token_hex(32) + "\n")
        os.chmod(drive_key, 0o600)
        return drive_key
    except Exception:
        pass
    try:
        if not os.path.isfile(local) or os.path.getsize(local) < 32:
            with open(local, "w") as f:
                f.write(secrets.token_hex(32) + "\n")
        os.chmod(local, 0o600)
        return local
    except Exception:
        return None


def _cred_sqlite_snapshot(src, dst):
    """نسخة متسقة من قاعدة SQLite (قراءة فقط) + فحص سلامة — نفس أسلوب
    اللقطات التعاملية المعتمدة في مسارات الحفظ القائمة."""
    os.makedirs(os.path.dirname(dst), exist_ok=True)
    fd, tmp = tempfile.mkstemp(prefix=".credsnap-", dir=os.path.dirname(dst))
    os.close(fd)
    try:
        uri = 'file:' + _cred_urlparse.quote(src, safe='/') + '?mode=ro'
        a = sqlite3.connect(uri, uri=True, timeout=8)
        b = sqlite3.connect(tmp, timeout=8)
        try:
            a.backup(b, pages=256, sleep=.02)
            b.commit()
            try:
                b.execute('PRAGMA wal_checkpoint(TRUNCATE)')
            except Exception:
                pass
            b.execute('PRAGMA journal_mode=DELETE')
            b.commit()
        finally:
            b.close(); a.close()
        for suffix in ('-wal', '-shm', '-journal'):
            try: os.unlink(tmp + suffix)
            except OSError: pass
        c = sqlite3.connect(tmp)
        q = c.execute('PRAGMA quick_check').fetchone()
        c.close()
        if not q or q[0] != 'ok':
            raise RuntimeError('quick_check')
        os.replace(tmp, dst)
    except Exception:
        try: os.unlink(tmp)
        except OSError: pass
        raise


def _cred_stage(profile_dir, staging):
    """يجمع ملفات بيانات الدخول من ملف كروم إلى دليل تجهيز محلي."""
    files = []
    subs = sorted(d for d in (os.listdir(profile_dir) if os.path.isdir(profile_dir) else [])
                  if d == 'Default' or (d.startswith('Profile ') and os.path.isdir(os.path.join(profile_dir, d))))
    if not subs:
        return files
    ls_src = os.path.join(profile_dir, 'Local State')
    if os.path.isfile(ls_src):
        shutil.copy2(ls_src, os.path.join(staging, 'Local State'))
        files.append('Local State')
    for sub in subs:
        for name in CRED_DB_NAMES:
            src = os.path.join(profile_dir, sub, name)
            if os.path.isfile(src):
                dst = os.path.join(staging, sub, name)
                _cred_sqlite_snapshot(src, dst)
                files.append(sub + '/' + name)
        for name in CRED_JSON_NAMES:
            src = os.path.join(profile_dir, sub, name)
            if os.path.isfile(src):
                dst = os.path.join(staging, sub, name)
                os.makedirs(os.path.dirname(dst), exist_ok=True)
                shutil.copy2(src, dst)
                json.load(open(dst, encoding='utf-8'))
                files.append(sub + '/' + name)
    return files


def _cred_extract(staging, profile_dir, vault_ts, restore):
    """يتحقق من بصمات manifest؛ وعند restore=True يزرع الملفات دون
    أن يكتب فوق ملف محلي أحدث من لقطة الخزنة أبدًا."""
    mpath = os.path.join(staging, 'manifest.json')
    data = json.load(open(mpath, encoding='utf-8'))
    written = 0
    for rel, want in (data.get('files') or {}).items():
        sdec = os.path.join(staging, rel)
        if not os.path.isfile(sdec):
            continue
        h = hashlib.sha256()
        with open(sdec, 'rb') as f:
            for chunk in iter(lambda: f.read(262144), b''):
                h.update(chunk)
        if h.hexdigest() != want:
            raise RuntimeError('hash:' + rel)
        if restore:
            dst = os.path.join(profile_dir, rel)
            if os.path.isfile(dst) and vault_ts and (os.path.getmtime(dst) - float(vault_ts)) > 2:
                continue  # الملف المحلي أحدث — لا نفقد تسجيل دخول أبدًا
            os.makedirs(os.path.dirname(dst), exist_ok=True)
            fd, tmpd = tempfile.mkstemp(prefix=".credout-", dir=os.path.dirname(dst))
            os.close(fd)
            shutil.copy2(sdec, tmpd)
            os.replace(tmpd, dst)
            written += 1
    return written


def _cred_vault(n):
    """خزنة v46 لبيانات دخول ملف العمل N (أجيال ZIP موثّقة بنشر ذري)."""
    return _DV.Vault(os.path.join(CRED_VAULT_DIR, "cred-vault-profile-%s" % n),
                     name="cred-%s" % n, keep=5)


def _cred_save_items(profile_dir):
    """عناصر الدخول المطلوب حفظها — نفس نطاق _cred_stage القديم تمامًا."""
    items = ['Local State']
    try:
        subs = sorted(d for d in os.listdir(profile_dir)
                      if (d == 'Default' or d.startswith('Profile '))
                      and os.path.isdir(os.path.join(profile_dir, d)))
    except OSError:
        subs = []
    for sub in subs:
        for name in CRED_DB_NAMES + CRED_JSON_NAMES:
            if os.path.isfile(os.path.join(profile_dir, sub, name)):
                items.append(sub + '/' + name)
    return items


def _cred_local_newer(profile_dir, vault_ts):
    """حارس «لا كتابة فوق الأحدث»: أي ملف دخول محلي أحدث من لقطة الخزنة
    يمنع الاستعادة (نفس دلالة فحص mtime في _cred_extract القديم)."""
    if not vault_ts:
        return False
    for rel in _cred_save_items(profile_dir):
        p = os.path.join(profile_dir, rel)
        try:
            if os.path.isfile(p) and os.path.getmtime(p) - float(vault_ts) > 2:
                return True
        except OSError:
            continue
    return False


def _cred_vault_save(n):
    """حفظ بيانات دخول ملف العمل N كجيل v46 موثّق — نفس العقد: bool."""
    profile_dir = os.path.join(CRED_LOCAL_ROOT, "profile-%s" % n)
    if not os.path.isdir(profile_dir):
        return False
    if not os.path.isfile(os.path.join(profile_dir, 'Local State')) \
            and not os.path.isdir(os.path.join(profile_dir, 'Default')):
        return False
    if not _DV_OK or _DV is None:
        return False
    v = _cred_vault(n)
    stage = tempfile.mkdtemp(prefix=".credstage-")
    try:
        items = _cred_save_items(profile_dir)
        if len(items) <= 1 and not os.path.isfile(
                os.path.join(profile_dir, 'Local State')):
            return False
        if v.snapshot(profile_dir, stage, items) == 0:
            return False
        owner = "cred-%s-%d" % (n, os.getpid())
        lock = _DV.VaultLock(v.dir, owner, ttl=180)
        if not lock.acquire():
            return False
        try:
            g = v.publish(stage, owner=owner)
        finally:
            lock.release()
        return bool(g)
    except Exception:
        return False
    finally:
        shutil.rmtree(stage, ignore_errors=True)


def _cred_vault_restore(n):
    """استعادة بيانات الدخول لملف العمل N: جيل v46 أولًا، ثم سلسلة
    .tar.enc القديمة (مع ترحيلها إلى v46). يُتخطّى وكروم يعمل، ولا
    يكتب فوق محتوى محلي أحدث من الخزنة. نفس العقد: bool."""
    profile_dir = os.path.join(CRED_LOCAL_ROOT, "profile-%s" % n)
    if os.path.exists(os.path.join(profile_dir, 'SingletonLock')):
        return False
    if _DV_OK and _DV is not None:
        v = _cred_vault(n)
        gens = v.list_generations()
        if gens:
            ts = gens[0][1].get('created_at', 0)
            if not _cred_local_newer(profile_dir, ts):
                g = v.restore(profile_dir)
                if g:
                    return True
    # المسار القديم: أجيال .tar.enc (الرئيسية ← السابقة ← الاحتياطية)
    key = _cred_key_file()
    if not key:
        return False
    final = os.path.join(CRED_VAULT_DIR, 'profile-%s.tar.enc' % n)
    for cand in (final, final + '.prev', final + '.backup'):
        if not os.path.isfile(cand):
            continue
        staging = tempfile.mkdtemp(prefix=".credrestore-")
        try:
            dec = subprocess.run(['openssl', 'enc', '-d', '-aes-256-cbc', '-pbkdf2', '-iter', '200000',
                                  '-in', cand, '-out', staging + '.tar.gz', '-pass', 'file:%s' % key],
                                 capture_output=True, timeout=300)
            if dec.returncode != 0 or not os.path.isfile(staging + '.tar.gz'):
                continue
            with _cred_tarfile.open(staging + '.tar.gz', 'r:gz') as tf:
                _cred_tar_extract(tf, staging)
            mpath = os.path.join(staging, 'manifest.json')
            if not os.path.isfile(mpath):
                continue
            try:
                ts = float(json.load(open(mpath, encoding='utf-8')).get('ts', 0))
            except Exception:
                ts = 0.0
            if _cred_extract(staging, profile_dir, ts, restore=True) > 0:
                _cred_vault_save(n)  # ترحيل فوري إلى v46
                return True
        except Exception:
            continue
        finally:
            shutil.rmtree(staging, ignore_errors=True)
            try: os.unlink(staging + '.tar.gz')
            except OSError: pass
    return False


def _cred_profile_nums():
    """أرقام كل ملفات العمل الموجودة محليًّا (كل النوافذ لا حصر بعدد)."""
    try:
        nums = []
        for d in os.listdir(CRED_LOCAL_ROOT):
            if d.startswith('profile-') and os.path.isdir(os.path.join(CRED_LOCAL_ROOT, d)):
                n = d[len('profile-'):]
                if _valid_workspace_id(n):
                    nums.append(n)
        return sorted(set(nums), key=int)
    except Exception:
        return []


def _cred_vault_nums():
    """أرقام الملفات التي لها خزنة في درايف (v46 أو .tar.enc قديم)."""
    nums = []
    try:
        for f in os.listdir(CRED_VAULT_DIR):
            if f.startswith('profile-') and f.endswith('.tar.enc'):
                n = f[len('profile-'):-len('.tar.enc')]
                if _valid_workspace_id(n):
                    nums.append(n)
            elif f.startswith('cred-vault-profile-'):
                n = f[len('cred-vault-profile-'):]
                if _valid_workspace_id(n):
                    nums.append(n)
    except Exception:
        pass
    return sorted(set(nums), key=int)


def _cred_vault_save_all():
    total = 0
    for n in _cred_profile_nums():
        try:
            if _cred_vault_save(n):
                total += 1
        except Exception:
            pass
    return total


def _cred_vault_restore_all():
    total = 0
    for n in _cred_vault_nums():
        try:
            if _cred_vault_restore(n):
                total += 1
        except Exception:
            pass
    return total


def _cred_vault_loop():
    while True:
        time.sleep(_CRED_SYNC_SECONDS)
        try:
            _cred_vault_save_all()
        except Exception:
            pass


def _cred_vault_start():
    """إقلاع الخزنة: استعادة في خيط خلفي، ثم حفظ دوري + حفظ ختامي."""
    # v116: كانت الاستعادة متزامنة عند الإقلاع وقراءة .enc عبر FUSE قد يبطئ
    # انطلاق سطح المكتب — الآن خيط خلفي مستقل لا يحجب شيئًا.
    def _boot_restore():
        try:
            restored = _cred_vault_restore_all()
            if restored:
                print('[🔐 خزنة الدخول] استُعيدت بيانات الدخول لـ %d ملف عمل من درايف ✅' % restored)
        except Exception:
            pass
    try:
        threading.Thread(target=_boot_restore, name="cred_boot_restore", daemon=True).start()
    except Exception:
        pass
    try:
        threading.Thread(target=_cred_vault_loop, name="cred_vault", daemon=True).start()
    except Exception:
        pass
    try:
        _cred_atexit.register(lambda: _cred_vault_save_all())
    except Exception:
        pass


try:
    _cred_vault_start()
    print('[🔐 خزنة الدخول] حفظ مشفّر AES-256 في درايف كل %d ث + استعادة تلقائية عند التشغيل ✅'
          % _CRED_SYNC_SECONDS)
except Exception:
    pass


# ============================================================
# *** v110 — خزنة دخول التطبيقات المشفّرة + مكنسة درايف الدقيقة ***
# ============================================================
# (1) بيانات دخول/إعدادات أنتيغرافيتي + IDE + كورسر + أندرويد ستوديو
#     تُحفَظ مشفّرة AES-256 في نفس خزنة درايف (v109) وتُستعاد عند
#     التشغيل — بلا كاش ولا ملفات تشغيل مؤقتة.
# (2) مكنسة درايف: أيتام ومؤقتات قديمة وملفات مُثبَت تلفها وأجيال
#     فوق السقف — داخل PERSIST_DIR فقط، وبلا لمس workspace أو أي
#     بيانات مهمة إطلاقًا (سجلّ كامل لكل حذف).
_APP_VAULT_APPS = (
    ('antigravity', '/root/.config/Google-Antigravity'),
    ('antigravity-ide', '/root/.config/Antigravity-IDE'),
    ('cursor', '/root/.config/Cursor'),
    ('android-studio', '/root/.android-studio-colab'),
)
_APP_EXCLUDE_DIRS = frozenset((
    'Cache', 'cache', 'Code Cache', 'GPUCache', 'ShaderCache', 'DawnCache',
    'GrShaderCache', 'Crashpad', 'BrowserMetrics', 'logs', 'blob_storage',
    'CacheStorage', 'ScriptCache', 'system', '.cache', 'CachedData',
    'CachedExtensions', 'CachedExtensionVSIXs', 'Service Worker', '__pycache__'))
_APP_PER_FILE_CAP = 8 * 1024 * 1024      # حدّ الملف الواحد
_APP_TOTAL_CAP = 96 * 1024 * 1024        # حدّ التطبيق الواحد — دخول+إعدادات فقط
_APP_SAVE_SECONDS = 300
_APP_LAST_SIG = {}
_V110_LOCK = threading.Lock()
_V110_PROJECT_CAP = 4 * 1024 ** 3        # يطابق MAX_TOTAL المشدود في خزنة المشاريع
_V110_PROJECT_MIN_KEEP = 5               # لا حذف يترك أقل من 5 أجيال أبدًا


def _app_stage(name, local_dir, staging):
    """يجمع بيانات الدخول/الإعدادات من شجرة إعدادات التطبيق — لا كاش،
    ولا ملفات تشغيل. ملفات leveldb (.log/.ldb) بيانات دخول فتُنسخ."""
    files = []
    total = 0
    sig_count = 0
    sig_size = 0
    sig_mtime = 0
    for base, dirs, names in os.walk(local_dir, topdown=True, followlinks=False):
        dirs[:] = sorted(d for d in dirs
                         if d not in _APP_EXCLUDE_DIRS
                         and not os.path.islink(os.path.join(base, d)))
        relbase = os.path.relpath(base, local_dir)
        for fn in sorted(names):
            if fn.startswith('Singleton') or fn.endswith(('.tmp', '-wal', '-shm', '.lock')):
                continue
            src = os.path.join(base, fn)
            try:
                st = os.lstat(src)
            except OSError:
                continue
            if os.path.islink(src) or not os.path.isfile(src):
                continue
            if st.st_size > _APP_PER_FILE_CAP:
                continue
            if total + st.st_size > _APP_TOTAL_CAP:
                continue
            rel = fn if relbase == '.' else relbase.replace(os.sep, '/') + '/' + fn
            dst = os.path.join(staging, rel)
            os.makedirs(os.path.dirname(dst), exist_ok=True)
            try:
                low = fn.lower()
                if low.endswith(('.vscdb', '.db')) or fn == 'Cookies':
                    _cred_sqlite_snapshot(src, dst)
                else:
                    shutil.copy2(src, dst)
            except Exception:
                continue
            files.append(rel)
            total += st.st_size
            sig_count += 1
            sig_size += st.st_size
            sig_mtime = max(sig_mtime, st.st_mtime_ns)
    return files, (sig_count, sig_size, sig_mtime)


def _vault_file_ok(path):
    """يتحقق من ملف خزنة مشفّر: فكّ + استخراج + بصمات manifest.
    عند غياب المفتاح نعيد True بحذر (لا حكم بالتلف بلا دليل)."""
    key = _cred_key_file()
    if not key:
        return True
    staging = tempfile.mkdtemp(prefix='.vaultcheck-')
    try:
        dec = subprocess.run(['openssl', 'enc', '-d', '-aes-256-cbc', '-pbkdf2', '-iter', '200000',
                              '-in', path, '-out', staging + '.tar.gz', '-pass', 'file:%s' % key],
                             capture_output=True, timeout=300)
        if dec.returncode != 0 or not os.path.isfile(staging + '.tar.gz'):
            return False
        with _cred_tarfile.open(staging + '.tar.gz', 'r:gz') as tf:
            _cred_tar_extract(tf, staging)
        if not os.path.isfile(os.path.join(staging, 'manifest.json')):
            return False
        _cred_extract(staging, '', 0, False)
        return True
    except Exception:
        return False
    finally:
        shutil.rmtree(staging, ignore_errors=True)
        try:
            os.unlink(staging + '.tar.gz')
        except OSError:
            pass


def _app_sig_quick(name, local_dir):
    """بصمة رخيصة (عدد/حجم/mtime) بنفس نطاق _app_stage — بلا نسخ."""
    sig_count = 0
    sig_size = 0
    sig_mtime = 0
    for base, dirs, names in os.walk(local_dir, topdown=True, followlinks=False):
        dirs[:] = [d for d in dirs if d not in _APP_EXCLUDE_DIRS
                   and not os.path.islink(os.path.join(base, d))]
        for fn in names:
            if fn.startswith('Singleton') or fn.endswith(('.tmp', '-wal', '-shm', '.lock')):
                continue
            src = os.path.join(base, fn)
            try:
                st = os.lstat(src)
            except OSError:
                continue
            if not os.path.isfile(src) or os.path.islink(src):
                continue
            sig_count += 1
            sig_size += st.st_size
            if st.st_mtime_ns > sig_mtime:
                sig_mtime = st.st_mtime_ns
    return (sig_count, sig_size, sig_mtime)


def _app_vault_save(name, local_dir, force=False):
    """حفظ بيانات دخول/إعدادات التطبيق كجيل v46 موثّق — نفس العقد: bool
    مع تفادي الكتابة بلا تغيّر (بصمة) وسقف 96MB للتطبيق."""
    if not os.path.isdir(local_dir):
        return False
    if not _DV_OK or _DV is None:
        return False
    try:
        sig = _app_sig_quick(name, local_dir)
        if not force and _APP_LAST_SIG.get(name) == sig:
            return False
    except Exception:
        sig = None
    v = _DV.Vault(os.path.join(CRED_VAULT_DIR, "app-vault-%s" % name),
                  name="app-%s" % name, keep=5)
    stage = tempfile.mkdtemp(prefix='.appstage-')
    try:
        excludes = sorted(_APP_EXCLUDE_DIRS) + ['*.tmp', '*.lock']
        if v.snapshot(local_dir, stage, ['.'], excludes=excludes) == 0:
            return False
        total = 0
        for _b, _d, _fs in os.walk(stage):
            for _fn in _fs:
                try:
                    total += os.path.getsize(os.path.join(_b, _fn))
                except OSError:
                    pass
        if total > _APP_TOTAL_CAP:
            return False  # دخول+إعدادات فقط — لا ننشر شجرة ضخمة أبدًا
        owner = "app-%s-%d" % (name, os.getpid())
        lock = _DV.VaultLock(v.dir, owner, ttl=180)
        if not lock.acquire():
            return False
        try:
            g = v.publish(stage, owner=owner)
        finally:
            lock.release()
        if g and sig is not None:
            _APP_LAST_SIG[name] = sig
        return bool(g)
    except Exception:
        return False
    finally:
        shutil.rmtree(stage, ignore_errors=True)


_APP_RUNNING_PATTERNS = {
    # أنماط ثابتة فقط؛ لا تُشتق من إدخال مستخدم أو مسار ملف.
    'antigravity': r'(^|/)(google-antigravity|antigravity)([[:space:]]|$)',
    'antigravity-ide': r'(^|/)(antigravity-ide|Antigravity-IDE)([[:space:]]|$)',
    'cursor': r'(^|/)(cursor|Cursor)([[:space:]]|$)|Cursor\.AppImage',
    'android-studio': r'(^|/)(studio\.sh|android-studio)([[:space:]]|$)|jetbrains',
}


def _app_running(name, _local_dir):
    """True عند احتمال تشغيل التطبيق؛ نؤجل الاستعادة بدل الكتابة فوقه."""
    pattern = _APP_RUNNING_PATTERNS.get(name)
    if not pattern:
        return False
    try:
        p = subprocess.run(['pgrep', '-af', pattern],
                           stdout=subprocess.PIPE,
                           stderr=subprocess.DEVNULL,
                           text=True, timeout=10)
        return p.returncode == 0 and bool(p.stdout.strip())
    except (OSError, subprocess.SubprocessError):
        # عند تعذّر الفحص لا تكتب فوق ملف تعريف تطبيق قد يكون مفتوحًا.
        return True


def _app_vault_restore(name, local_dir):
    """استعادة بيانات التطبيق: جيل v46 أولًا ثم سلسلة .tar.enc القديمة
    (مع ترحيل). لا كتابة فوق محلي أحدث، ويُتخطّى والتطبيق يعمل."""
    if _app_running(name, local_dir):
        return False
    if _DV_OK and _DV is not None:
        v = _DV.Vault(os.path.join(CRED_VAULT_DIR, "app-vault-%s" % name),
                      name="app-%s" % name, keep=5)
        gens = v.list_generations()
        if gens:
            ts = gens[0][1].get('created_at', 0)
            newer = False
            for _b, _d, _fs in os.walk(local_dir):
                for _fn in _fs:
                    try:
                        if os.path.getmtime(os.path.join(_b, _fn)) - float(ts) > 2:
                            newer = True
                            break
                    except OSError:
                        pass
                if newer:
                    break
            if not newer:
                g = v.restore(local_dir)
                if g:
                    try:
                        _APP_LAST_SIG[name] = _app_sig_quick(name, local_dir)
                    except Exception:
                        pass
                    return True
    key = _cred_key_file()
    if not key:
        return False
    final = os.path.join(CRED_VAULT_DIR, 'app-%s.tar.enc' % name)
    for cand in (final, final + '.prev', final + '.backup'):
        if not os.path.isfile(cand):
            continue
        staging = tempfile.mkdtemp(prefix='.apprestore-')
        try:
            dec = subprocess.run(['openssl', 'enc', '-d', '-aes-256-cbc', '-pbkdf2', '-iter', '200000',
                                  '-in', cand, '-out', staging + '.tar.gz', '-pass', 'file:%s' % key],
                                 capture_output=True, timeout=300)
            if dec.returncode != 0 or not os.path.isfile(staging + '.tar.gz'):
                continue
            with _cred_tarfile.open(staging + '.tar.gz', 'r:gz') as tf:
                _cred_tar_extract(tf, staging)
            mpath = os.path.join(staging, 'manifest.json')
            if not os.path.isfile(mpath):
                continue
            try:
                ts = float(json.load(open(mpath, encoding='utf-8')).get('ts', 0))
            except Exception:
                ts = 0.0
            os.makedirs(local_dir, exist_ok=True)
            if _cred_extract(staging, local_dir, ts, restore=True) > 0:
                _app_vault_save(name, local_dir, force=True)  # ترحيل إلى v46
                return True
        except Exception:
            continue
        finally:
            shutil.rmtree(staging, ignore_errors=True)
            try:
                os.unlink(staging + '.tar.gz')
            except OSError:
                pass
    return False


def _app_vault_save_all(force=False):
    total = 0
    for name, local_dir in _APP_VAULT_APPS:
        try:
            if _app_vault_save(name, local_dir, force=force):
                total += 1
        except Exception:
            pass
    return total


def _app_vault_restore_all():
    total = 0
    for name, local_dir in _APP_VAULT_APPS:
        try:
            if _app_vault_restore(name, local_dir):
                total += 1
        except Exception:
            pass
    return total


def _v110_tmp_name(s):
    """أنماط أسماء الملفات/المجلدات المؤقتة التي يصنعها السكربت حصرًا."""
    return ('.tmp-' in s
            or s.startswith(('.meta-', '.sqlite-', '.credsnap-', '.credout-',
                              '.next-', '.vaultcheck-', '.appstage-', '.apprestore-',
                              '.credstage-', '.credverify-', '.credrestore-', '.logrot-'))
            or s.endswith(('.partial', '.part'))
            or 'pending-critical' in s
            or '.fuse_hidden' in s or '.driveupload' in s)


def _drive_janitor():
    """مكنسة درايف الدقيقة — قواعد صارمة:
    • النطاق realpath(PERSIST_DIR) فقط؛ تخطّي workspace (بيانات مستخدم)
      وكل symlink؛ حذف ملفات فقط (لا rm -rf لمسارات ديناميكية).
    • أيتام/مؤقتات أقدم من 6 ساعات بأنماط صناعة السكربت حصرًا.
    • ملفات خزنة يُثبَت تلفها → حجر صحي (.corrupt-<ts>) بحدّ أقصى 2 لكل
      اسم — لا فقدان لأي ملف قد يكون سليمًا.
    • أجيال مشاريع فوق السقف: حذف الأقدم مع بقاء 5 على الأقل.
    • تدوير السجلات الكبيرة (>2MB) اقتطاعًا لا حذفًا.
    • كل حذف يُسجَّل في cleanup-log.tsv."""
    entries = []
    freed = 0
    if _SAFE_CLEAN_BUSY.get('copy'):
        return 0, 0  # نسخ حزم جارٍ — نؤجل بالكامل
    if not _V110_LOCK.acquire(blocking=False):
        return 0, 0
    try:
        try:
            root = os.path.realpath(PERSIST_DIR)
        except Exception:
            return 0, 0
        now = time.time()
        # (1) أيتام ومؤقتات قديمة بأنماط صناعة السكربت حصرًا
        for base, dirs, names in os.walk(root, topdown=True, followlinks=False):
            dirs[:] = [d for d in dirs if d != 'workspace'
                       and not os.path.islink(os.path.join(base, d))]
            for fn in names:
                p = os.path.join(base, fn)
                try:
                    if os.path.islink(p) or not os.path.isfile(p):
                        continue
                    st = os.lstat(p)
                    if now - st.st_mtime < 6 * 3600:
                        continue
                    if not (_v110_tmp_name(fn) or _v110_tmp_name(os.path.basename(base))):
                        continue
                    rel = os.path.relpath(p, root)
                    os.unlink(p)
                    freed += st.st_size
                    entries.append(('orphan-temp', rel, st.st_size))
                except Exception:
                    continue
        # (2) حجر صحي لملفات الخزنة المُثبَت تلفها + حدّ أقصى 2 لكل اسم
        try:
            for fn in os.listdir(CRED_VAULT_DIR):
                if fn == '.key' or '.corrupt-' in fn:
                    continue
                if not (fn.endswith('.tar.enc') or fn.endswith('.tar.enc.prev')):
                    continue
                p = os.path.join(CRED_VAULT_DIR, fn)
                try:
                    if not _vault_file_ok(p):
                        qp = p + '.corrupt-%d' % int(now)
                        os.replace(p, qp)
                        entries.append(('corrupt-vault-quarantine', os.path.basename(qp), 0))
                except Exception:
                    continue
            groups = {}
            for fn in sorted(os.listdir(CRED_VAULT_DIR)):
                if '.corrupt-' in fn:
                    groups.setdefault(fn.split('.corrupt-')[0], []).append(fn)
            for base_name, gfiles in groups.items():
                gfiles.sort(key=lambda f: os.lstat(os.path.join(CRED_VAULT_DIR, f)).st_mtime)
                while len(gfiles) > 2:
                    victim = gfiles.pop(0)
                    p = os.path.join(CRED_VAULT_DIR, victim)
                    try:
                        sz = os.lstat(p).st_size
                        os.unlink(p)
                        freed += sz
                        entries.append(('corrupt-vault-purge', victim, sz))
                    except Exception:
                        pass
        except Exception:
            pass
        # (3) أجيال المشاريع فوق السقف — الأقدم أولًا مع بقاء MIN_KEEP
        try:
            gen = os.path.join(_PROTECTED_PROJECTS_VAULT, 'generations')
            metas = []
            for fn in os.listdir(gen):
                if not fn.endswith('.json'):
                    continue
                try:
                    m = json.load(open(os.path.join(gen, fn), encoding='utf-8'))
                    if m.get('schema') == 1:
                        metas.append((float(m.get('created', 0)), fn, m))
                except Exception:
                    continue
            metas.sort(key=lambda x: x[0])
            total = sum(int(m.get('bytes', 0)) for _, _, m in metas)
            while total > _V110_PROJECT_CAP and len(metas) > _V110_PROJECT_MIN_KEEP:
                _, mfn, m = metas.pop(0)
                for victim in (os.path.join(gen, m.get('archive', '')), os.path.join(gen, mfn)):
                    try:
                        if os.path.isfile(victim) and not os.path.islink(victim):
                            sz = os.lstat(victim).st_size
                            os.unlink(victim)
                            freed += sz
                            entries.append(('project-gen-overcap', os.path.basename(victim), sz))
                    except Exception:
                        pass
                total -= int(m.get('bytes', 0))
            known = {m.get('archive') for _, _, m in metas}
            for fn in os.listdir(gen):
                if not fn.endswith('.zip') or fn in known:
                    continue
                p = os.path.join(gen, fn)
                try:
                    st = os.lstat(p)
                    if now - st.st_mtime > 24 * 3600 and not os.path.islink(p):
                        os.unlink(p)
                        freed += st.st_size
                        entries.append(('project-gen-orphan', fn, st.st_size))
                except Exception:
                    pass
        except Exception:
            pass
        # (4) تدوير السجلات الكبيرة (>2MB) — اقتطاع لا حذف
        for base, dirs, names in os.walk(root, topdown=True, followlinks=False):
            dirs[:] = [d for d in dirs if d != 'workspace'
                       and not os.path.islink(os.path.join(base, d))]
            for fn in names:
                if not (fn.endswith('.log') or fn == 'cleanup-log.tsv'):
                    continue
                p = os.path.join(base, fn)
                try:
                    if os.path.islink(p) or not os.path.isfile(p):
                        continue
                    sz = os.lstat(p).st_size
                    if sz <= 2 * 1024 * 1024:
                        continue
                    lines = open(p, encoding='utf-8', errors='ignore').readlines()[-2000:]
                    fd, tmp = tempfile.mkstemp(prefix='.logrot-', dir=base)
                    with os.fdopen(fd, 'w', encoding='utf-8') as f:
                        f.writelines(lines)
                    os.replace(tmp, p)
                    entries.append(('log-rotate', os.path.relpath(p, root), max(0, sz - os.path.getsize(p))))
                except Exception:
                    continue
    finally:
        _V110_LOCK.release()
    if entries:
        try:
            _append_cleanup_log(entries)
        except Exception:
            pass
        print('[🧹 مكنسة درايف] حرّرت %.1fMB عبر %d عنصرًا ✅' % (freed / 1048576.0, len(entries)))
    return freed, len(entries)


def _v110_loop():
    time.sleep(180)
    cycle = 0
    while True:
        try:
            _app_vault_save_all()
        except Exception:
            pass
        cycle += 1
        if cycle == 1 or cycle % 12 == 0:  # أول مرة ثم كل ساعة (12×300ث)
            try:
                _drive_janitor()
            except Exception:
                pass
        time.sleep(_APP_SAVE_SECONDS)


def _v110_start():
    """إقلاع v110: استعادة التطبيقات في خيط خلفي، ثم حفظ دوري + مكنسة
    درايف ساعية + حفظ ختامي. كل فشل معزول — لا أثر على غيره."""
    # v116: الاستعادة كانت متزامنة عند الإقلاع — الآن خيط خلفي لا يحجب
    # انطلاق سطح المكتب (قراءة .enc عبر FUSE قد يتلكأ).
    def _boot_restore():
        try:
            restored = _app_vault_restore_all()
            if restored:
                print('[🔐 خزنة التطبيقات] استُعيد دخول %d تطبيق من درايف ✅' % restored)
        except Exception:
            pass
    try:
        threading.Thread(target=_boot_restore, name="app_boot_restore", daemon=True).start()
    except Exception:
        pass
    try:
        threading.Thread(target=_v110_loop, name='v110_loop', daemon=True).start()
    except Exception:
        pass
    try:
        _cred_atexit.register(lambda: _app_vault_save_all(force=True))
    except Exception:
        pass


try:
    _v110_start()
    print('[🔐 خزنة التطبيقات] دخول أنتيغرافيتي/كورسر/أندرويد ستوديو مشفّر ✅ | [🧹 مكنسة درايف] ساعية ✅')
except Exception:
    pass


# ============================================================
# *** v111 — مكنسة مهملات Google Drive (سبب نفاد المساحة الحقيقي) ***
# ============================================================
# الحقيقة الدقيقة: الحذف عبر نقطة /content/drive لا يحرّر المساحة —
# الملفات تنتقل إلى «مهملات» حساب Google Drive وتبقى محسوبة ضمن
# الحصة حتى تُفرَّغ (30 يومًا أو يدويًّا). لذلك كان تنظيف المجلد لا
# يكفي. هذه الطبقة تفرّغ المهملات عبر Drive API بقواعد محافظة:
#   • لا تلمس إلا ملفات «مهملات» أصلًا — ملف حيّ واحد لا يُحذف أبدًا.
#   • مهملات عمره > 3 أيام (أي موضع) → حذف نهائي.
#   • مهملات باسم مؤقت من صناعة السكربت → حذف نهائي فوري.
#   • مهملات داخل مجلد المشروع (مسارات مُدارة بالكامل) → فوري.
import datetime as _v111_dt
_V111_STATE = {'built_at': 0.0, 'svc': None, 'folder_ids': set(), 'proj_root': None}
_V111_MIN_AGE_DAYS = 3
_V111_RUN_SECONDS = 24 * 3600


def _v111_service():
    """عميل Drive API مرة كل 30 دقيقة؛ None خارج Colab/بدون صلاحية."""
    now = time.time()
    if _V111_STATE['svc'] is not None and now - _V111_STATE['built_at'] < 1800:
        return _V111_STATE['svc']
    try:
        from google.colab import auth as _gca
        _gca.authenticate_user()
        import googleapiclient.discovery as _gd
        svc = _gd.build('drive', 'v3', cache_discovery=False)
        _V111_STATE['svc'] = svc
        _V111_STATE['built_at'] = now
        return svc
    except Exception:
        return None


def _v111_project_folders(svc):
    """معرّفات مجلد المشروع ومحتواه حتى عمق 3 — تُخزَّن للجلسة."""
    if _V111_STATE['folder_ids']:
        return _V111_STATE['folder_ids']
    ids = set()
    try:
        root_name = os.path.basename(PERSIST_DIR)
        q = ("name='%s' and mimeType='application/vnd.google-apps.folder' "
             "and trashed=false" % root_name.replace("'", "\\'"))
        r = svc.files().list(q=q, fields='files(id,name)', pageSize=10).execute()
        roots = r.get('files', [])
        if not roots:
            return ids
        frontier = [roots[0]['id']]
        ids.add(roots[0]['id'])
        _V111_STATE['proj_root'] = roots[0]['id']
        for _depth in range(3):
            nxt = []
            for fid in frontier:
                try:
                    rr = svc.files().list(
                        q=("'%s' in parents and mimeType='application/vnd.google-apps.folder' "
                           "and trashed=false" % fid),
                        fields='files(id)', pageSize=200).execute()
                    for f in rr.get('files', []):
                        if f['id'] not in ids:
                            ids.add(f['id'])
                            nxt.append(f['id'])
                except Exception:
                    continue
            frontier = nxt
            if not frontier:
                break
    except Exception:
        pass
    _V111_STATE['folder_ids'] = ids
    return ids


def _v111_trash_candidates(svc):
    """كل ملفات المهملات (العمر/الحجم/الآباء) — حدّ 10 صفحات للمرة."""
    out = []
    token = None
    for _ in range(10):
        try:
            kwargs = dict(q='trashed=true', spaces='drive', pageSize=1000,
                          fields='nextPageToken,files(id,name,size,trashedTime,parents)')
            if token:
                kwargs['pageToken'] = token
            r = svc.files().list(**kwargs).execute()
            out.extend(r.get('files', []))
            token = r.get('nextPageToken')
            if not token:
                break
        except Exception:
            break
    return out


def _v111_trash_age_days(f):
    try:
        ts = f.get('trashedTime') or ''
        dt = _v111_dt.datetime.strptime(ts[:19], '%Y-%m-%dT%H:%M:%S')
        return (time.time() - dt.replace(tzinfo=_v111_dt.timezone.utc).timestamp()) / 86400.0
    except Exception:
        return None


def _v111_should_purge(f, folder_ids):
    """قواعد الحذف النهائي الثلاث — كلها داخل المهملات فقط."""
    if _v110_tmp_name(f.get('name', '')):
        return True
    if any(p in folder_ids for p in (f.get('parents') or [])):
        return True
    age = _v111_trash_age_days(f)
    return age is not None and age >= _V111_MIN_AGE_DAYS


# *** v115 — مفرّغ مهملات درايف المعزول (لا فشل صامت بعد اليوم) ***
_V111_PURGE_PY = r'''#!/usr/bin/env python3
# -*- coding: utf-8 -*-
# v115 — مفرّغ مهملات Google Drive المعزول.
# عملية مستقلة بمهلة صارمة من الطرف المُشغّل: أي تعليق في المصادقة أو
# الشبكة لا يمسّ العملية الرئيسية. القواعد المحافظة (كما وثّقها v111):
#   • لا يُحذَف إلا ما هو في المهملات أصلًا — ملف حيّ لا يُقرَب أبدًا.
#   • مهملات أقدم من 3 أيام (أي موضع) → حذف نهائي.
#   • مهملات باسم مؤقت من صناعة السكربت → فوري.
#   • مهملات داخل مجلد المشروع → فوري.
import os, sys, time, json, datetime, subprocess as _sp
MIN_AGE_DAYS = 3
ROOT_NAME = os.environ.get('DRIVE_PROJECT_ROOT', '')


def tmp_name(s):
    return ('.tmp-' in s
            or s.startswith(('.meta-', '.sqlite-', '.credsnap-', '.credout-',
                              '.next-', '.vaultcheck-', '.appstage-', '.apprestore-',
                              '.credstage-', '.credverify-', '.credrestore-', '.logrot-'))
            or s.endswith(('.partial', '.part'))
            or 'pending-critical' in s
            or '.fuse_hidden' in s or '.driveupload' in s)


def build():
    try:
        import googleapiclient.discovery as gd
    except Exception:
        try:
            _sp.run([sys.executable, '-m', 'pip', 'install', '-q', '--no-input',
                     'google-api-python-client'], timeout=600,
                    stdout=_sp.DEVNULL, stderr=_sp.DEVNULL)
        except Exception:
            pass
        import googleapiclient.discovery as gd
    from google.colab import auth as gca
    gca.authenticate_user()
    return gd.build('drive', 'v3', cache_discovery=False)


def project_folders(svc):
    ids = set()
    if not ROOT_NAME:
        return ids
    try:
        q = ("name='%s' and mimeType='application/vnd.google-apps.folder' and trashed=false"
             % ROOT_NAME.replace("'", "\\'"))
        r = svc.files().list(q=q, fields='files(id,name)', pageSize=10).execute()
        roots = r.get('files', [])
        if not roots:
            return ids
        frontier = [roots[0]['id']]
        ids.add(roots[0]['id'])
        for _depth in range(3):
            nxt = []
            for fid in frontier:
                try:
                    rr = svc.files().list(
                        q=("'%s' in parents and mimeType='application/vnd.google-apps.folder' and trashed=false" % fid),
                        fields='files(id)', pageSize=200).execute()
                    for f in rr.get('files', []):
                        if f['id'] not in ids:
                            ids.add(f['id'])
                            nxt.append(f['id'])
                except Exception:
                    continue
            frontier = nxt
            if not frontier:
                break
    except Exception:
        pass
    return ids


def age_days(f):
    try:
        ts = f.get('trashedTime') or ''
        dt = datetime.datetime.strptime(ts[:19], '%Y-%m-%dT%H:%M:%S')
        return (time.time() - dt.replace(tzinfo=datetime.timezone.utc).timestamp()) / 86400.0
    except Exception:
        return None


def decide(f, folder_ids):
    if tmp_name(f.get('name', '')):
        return True
    if any(p in folder_ids for p in (f.get('parents') or [])):
        return True
    a = age_days(f)
    return a is not None and a >= MIN_AGE_DAYS


def main():
    try:
        svc = build()
    except Exception as e:
        print(json.dumps({'ok': False, 'stage': 'build', 'error': type(e).__name__}))
        return 2
    ids = project_folders(svc)
    purged = 0
    freed = 0
    kept = 0
    names = []
    token = None
    for _page in range(10):
        try:
            kwargs = dict(q='trashed=true', spaces='drive', pageSize=1000,
                          fields='nextPageToken,files(id,name,size,trashedTime,parents)')
            if token:
                kwargs['pageToken'] = token
            r = svc.files().list(**kwargs).execute()
        except Exception as e:
            print(json.dumps({'ok': False, 'stage': 'list', 'error': type(e).__name__}))
            return 3
        for f in r.get('files', []):
            if not decide(f, ids):
                kept += 1
                continue
            try:
                svc.files().delete(fileId=f['id']).execute()
                purged += 1
                try:
                    freed += int(f.get('size') or 0)
                except Exception:
                    pass
                names.append(f.get('name', f['id']))
            except Exception:
                kept += 1
        token = r.get('nextPageToken')
        if not token:
            break
    print(json.dumps({'ok': True, 'purged': purged, 'freed': freed,
                      'kept': kept, 'names': names[:200]}))
    return 0


if __name__ == '__main__':
    sys.exit(main())
'''
_V111_PURGER = '/usr/local/bin/drive-trash-purge'


def _v111_write_purger():
    try:
        cur = ''
        try:
            cur = open(_V111_PURGER, encoding='utf-8').read()
        except Exception:
            pass
        if cur != _V111_PURGE_PY:
            with open(_V111_PURGER, 'w', encoding='utf-8') as f:
                f.write(_V111_PURGE_PY)
            os.chmod(_V111_PURGER, 0o755)
        return True
    except Exception:
        return False


def _drive_trash_purge():
    """v115: إفراغ المهملات عبر عملية معزولة بمهلة 15 دقيقة — عميل Drive
    API يُثبَّت تلقائيًّا إن غاب، والمصادقة تجري خارج العملية الرئيسية
    (لا تعليق إطلاقًا)، وأي خطأ يُعلَن بدل ابتلاعه كما كان يحدث صامتًا."""
    if not _v111_write_purger():
        return 0, 0
    env = dict(os.environ)
    env['DRIVE_PROJECT_ROOT'] = os.path.basename(PERSIST_DIR)
    try:
        r = subprocess.run(['python3', _V111_PURGER], capture_output=True,
                           text=True, timeout=900, env=env)
    except Exception:
        return 0, 0
    lines = (r.stdout or '').strip().splitlines()
    if not lines:
        try:
            open('/tmp/drive-trash-purge.err', 'w').write((r.stderr or '')[-4000:])
        except Exception:
            pass
        print('[🧹 مهملات درايف] تعذّر الإفراغ هذه المرة — السبب في /tmp/drive-trash-purge.err')
        return 0, 0
    try:
        data = json.loads(lines[-1])
    except Exception:
        return 0, 0
    if not data.get('ok'):
        print('[🧹 مهملات درايف] تعذّر الوصول لدرايف (%s/%s) — يُعاد تلقائيًّا'
              % (data.get('stage', '?'), data.get('error', '?')))
        return 0, 0
    purged = int(data.get('purged', 0))
    freed = int(data.get('freed', 0))
    kept = int(data.get('kept', 0))
    if purged:
        try:
            _append_cleanup_log([('drive-trash-purge', n, 0)
                                 for n in (data.get('names') or [])[:200]])
        except Exception:
            pass
        print('[🧹 مهملات درايف] حُذف نهائيًّا %d مهملًا (≈%.1fMB محرَّرة) — أُبقي %d حديثًا ✅'
              % (purged, freed / 1048576.0, kept))
    return purged, freed


def _v111_loop():
    time.sleep(120)   # v115: أول إفراغ مبكر — المهملات المتراكمة لا تنتظر
    while True:
        try:
            _drive_trash_purge()
        except Exception:
            pass
        time.sleep(_V111_RUN_SECONDS)


def _v111_start():
    try:
        threading.Thread(target=_v111_loop, name='v111_trash_purge', daemon=True).start()
    except Exception:
        pass


try:
    _v111_start()
    print('[🧹 مهملات درايف] تفريغ آمن يومي — الملفات الحيّة لا تُمسّ إطلاقًا ✅')
except Exception:
    pass




