# ============================================================
# *** v113 — حارس ملاءمة النوافذ: لا قصّ ولا تشويه لأي نافذة ***
# ============================================================
# النوافذ الحوارية (كحوار أمان كلمات المرور) تُولَد أعرض من شاشة الجوال
# فيقصّ مدير النوافذ أطرافها وتضيع أزرارها، وsafe-fit-app-window يكبّر
# النافذة الرئيسية فقط لكل تطبيق ومرة واحدة. هذا الحارس يراقب كل نافذة
# ظاهرة كل 1.5ث: يصغّر ما يتجاوز منطقة العمل ويعيد ما خرج منها إلى
# الداخل — بلا تكبير قسري ولا لمس لأي نافذة داخل الحدود (لا تشويه
# إطلاقًا)، ولا يلمس سطح المكتب ولا اللوحات ولا النوافذ المكبَّرة.
_window_fit_watchdog = r'''#!/bin/bash
set -u
export DISPLAY="${DISPLAY:-:1}"
declare -A LAST_SIG=()
while true; do
  sleep 1.5
  WA=$(xprop -root _NET_WORKAREA 2>/dev/null | sed 's/.*= *//;s/,/ /g' | awk '{print $1,$2,$3,$4}')
  WAX=$(printf '%s' "$WA"|awk '{print $1}'); WAY=$(printf '%s' "$WA"|awk '{print $2}')
  WAW=$(printf '%s' "$WA"|awk '{print $3}'); WAH=$(printf '%s' "$WA"|awk '{print $4}')
  WAX=${WAX:-0}; WAY=${WAY:-0}; WAW=${WAW:-0}; WAH=${WAH:-0}
  [ "$WAW" -lt 100 ] 2>/dev/null && continue
  [ "$WAH" -lt 100 ] 2>/dev/null && continue
  for W in $(xdotool search --onlyvisible --name '' 2>/dev/null | awk '/^[0-9]+$/'); do
    T=$(xprop -id "$W" _NET_WM_WINDOW_TYPE 2>/dev/null)
    case "$T" in *DESKTOP*|*DOCK*) continue;; esac
    ST=$(xprop -id "$W" _NET_WM_STATE 2>/dev/null)
    # حتى النافذة المكبرة قد تصبح أكبر من منطقة العمل بعد دوران الهاتف أو
    # تغيّر DPI؛ لا نستثنيها من الفحص، لكن لا نغيّرها ما دامت داخل الحدود.
    G=$(xdotool getwindowgeometry --shell "$W" 2>/dev/null) || continue
    X=$(printf '%s\n' "$G"|awk -F= '$1=="X"{print $2}'); Y=$(printf '%s\n' "$G"|awk -F= '$1=="Y"{print $2}')
    WI=$(printf '%s\n' "$G"|awk -F= '$1=="WIDTH"{print $2}'); HE=$(printf '%s\n' "$G"|awk -F= '$1=="HEIGHT"{print $2}')
    [ -n "$X" ] && [ -n "$Y" ] && [ -n "$WI" ] && [ -n "$HE" ] || continue
    NX=$X; NY=$Y; NW=$WI; NH=$HE
    [ "$NW" -gt "$WAW" ] 2>/dev/null && NW=$WAW
    [ "$NH" -gt "$WAH" ] 2>/dev/null && NH=$WAH
    [ "$NX" -lt "$WAX" ] 2>/dev/null && NX=$WAX
    [ "$NY" -lt "$WAY" ] 2>/dev/null && NY=$WAY
    [ $((NX+NW)) -gt $((WAX+WAW)) ] && NX=$((WAX+WAW-NW))
    [ $((NY+NH)) -gt $((WAY+WAH)) ] && NY=$((WAY+WAH-NH))
    [ "$NX" -lt "$WAX" ] 2>/dev/null && NX=$WAX
    [ "$NY" -lt "$WAY" ] 2>/dev/null && NY=$WAY
    SIG="$NX,$NY,$NW,$NH"; CUR="$X,$Y,$WI,$HE"
    [ "$SIG" = "$CUR" ] && { LAST_SIG[$W]="$SIG"; continue; }
    [ "${LAST_SIG[$W]:-}" = "$SIG" ] && continue
    wmctrl -ir "$W" -b remove,maximized_vert,maximized_horz 2>/dev/null || true
    if [ "$NW" != "$WI" ] || [ "$NH" != "$HE" ]; then
      xdotool windowsize "$W" "$NW" "$NH" 2>/dev/null || true
    fi
    if [ "$NX" != "$X" ] || [ "$NY" != "$Y" ]; then
      xdotool windowmove "$W" "$NX" "$NY" 2>/dev/null || true
    fi
    LAST_SIG[$W]="$SIG"
  done
done
'''
if kasm_ok:
    try:
        with open('/usr/local/bin/window-fit-watchdog', 'w', encoding='utf-8') as _wf:
            _wf.write(_window_fit_watchdog)
        os.chmod('/usr/local/bin/window-fit-watchdog', 0o755)
        run("pkill -f window-fit-watchdog 2>/dev/null; setsid env DISPLAY=%s /usr/local/bin/window-fit-watchdog >/tmp/window-fit-watchdog.log 2>&1 < /dev/null &" % DISPLAY_NUM, timeout=10)
        print('[🪟 ملاءمة النوافذ] كل نافذة وحوار داخل الشاشة تلقائيًّا — بلا قصّ ولا تشويه ✅')
    except Exception as _wfe:
        print('[i] ملاءمة النوافذ: %s' % _wfe)

# ============================================================
# ============================================================
# *** v123 — قائمة التطبيقات الأصلية الكاملة (بلا سلاسل إطلاق) ***
# ============================================================
# إعادة بناء جذرية بعد أن لم تظهر القائمة أبدًا: زر اللوحة لم يعد مشغّلًا
# لسكربت وسيط (ملف .desktop ← Exec ← باش ← zenity — سلسلة تنكسر بصمت)،
# بل أصبح إضافة applicationsmenu الأصلية في اللوحة نفسها (نظام garcon
# الرسمي — نفس قائمة زر XFCE الأزرق التي تعمل): القائمة تنبثق من اللوحة
# مباشرة وداخل عمليتها، بلا سكربتات ولا zenity ولا ناقل جلسة ولا أقفال.
