def _v123_register_app(desktop_id, name, exec_cmd, icon, categories,
                       app_dir='/usr/share/applications'):
    """يسجّل التطبيق بفئته في ملف .desktop — يضيف Categories لملف موجود بنفس
    الأمر دون لمسه، وينشئ ملفًا جديدًا للغائب، ولا يكرر ولا يكتب عند التطابق."""
    try:
        cand = []
        try:
            cand = [f for f in os.listdir(app_dir) if f.endswith('.desktop')]
        except Exception:
            return None
        for fn in cand:
            p = os.path.join(app_dir, fn)
            try:
                body = open(p, encoding='utf-8', errors='ignore').read()
            except Exception:
                continue
            if 'Exec=' not in body or exec_cmd.split()[0] not in body:
                continue
            if 'Categories=' in body:
                return p
            lines = body.rstrip('\n').split('\n')
            out = []
            for ln in lines:
                out.append(ln)
                if ln.startswith('Name='):
                    out.append('Categories=%s' % categories)
            tmp = p + '.v123tmp'
            with open(tmp, 'w', encoding='utf-8') as f:
                f.write('\n'.join(out) + '\n')
            os.replace(tmp, p)
            return p
        path = os.path.join(app_dir, desktop_id)
        body = ('[Desktop Entry]\nType=Application\nName=%s\nExec=%s\nIcon=%s\n'
                'Categories=%s\nTerminal=false\nStartupNotify=false\n'
                % (name, exec_cmd, icon, categories))
        cur = None
        try:
            cur = open(path, encoding='utf-8', errors='ignore').read()
        except Exception:
            cur = None
        if cur == body:
            return path
        tmp = path + '.v123tmp'
        with open(tmp, 'w', encoding='utf-8') as f:
            f.write(body)
        os.chmod(tmp, 0o644)
        os.replace(tmp, path)
        return path
    except Exception:
        return None


