# *** v121 — حارس ثبات سكربتات الواجهة بعد الاستعادة الخلفية ***
# ============================================================
# السبب الجذري لعودة «زر الكرة لا يُظهر شيئًا» بعد v117: اللقطة الكاملة على
# Drive بُنيت من نسخة أقدم وتحمل /usr/local/bin قديمة، والاستعادة الخلفية
# (_background_full_snapshot_restore) تفكّها فوق الجذر بـ --unlink-first
# فتطمس phone-app-menu وappmenu-apps (وأدوات v113-v120) بالنسخ القديمة بعد
# ثوانٍ من كتابتها — فيعود الزر للقائمة المكسورة كل إقلاع. الحل: بعد اكتمال
# الاستعادة الخلفية (_DEF_FULL_DONE) نعيد كتابة سكربتاتنا الحرجة من ثوابت
# الذاكرة (الأحدث دائمًا) بشكل ذرّي — لا يبقى أثر للنسخة القديمة.
def _v121_rewrite_user_scripts(reason="", bin_dir="/usr/local/bin"):
    try:
        writes = [
            ('phone-app-menu', globals().get('_PHONE_APP_MENU_SH')),
            ('appmenu-apps', globals().get('_APPMENU_APPS_PY')),
            ('window-fit-watchdog', globals().get('_window_fit_watchdog')),
            ('drive-trash-purge', globals().get('_V111_PURGE_PY')),
            ('xfce-session-command', globals().get('_XFCE_SESSION_COMMAND')),
            ('genspark-window', globals().get('_WORKSPACE100_FINAL_MENU_SH')),
            # V14: اللقطة المؤجلة تدهس كل /usr/local/bin — أعد تثبيت جميع
            #      مشغّلات التطبيقات لا 6 فقط (سبب «البرنامج غير موجود»).
            ('chrome-root', globals().get('chrome_wrapper')),
            ('chrome-profile', globals().get('chrome_profile_sh')),
            ('cursor-colab', globals().get('_cursor_wrapper')),
            ('android-studio-colab', globals().get('_android_wrapper')),
            ('antigravity-ide-colab', globals().get('_ag_ide_wrapper')),
            ('antigravity-hub-colab', globals().get('_ag_wrapper')),
            ('qwen-app', globals().get('qwen_app_sh')),
            ('deepseek-app', globals().get('deepseek_sh')),
            ('gs-agent-ui', globals().get('gs_agent_ui_sh')),
        ]
        changed = 0
        for fname, data in writes:
            if not data:
                continue
            path = os.path.join(bin_dir, fname)
            try:
                try:
                    cur = open(path, encoding='utf-8', errors='ignore').read()
                except Exception:
                    cur = None
                if cur == data:
                    continue
                tmp = path + '.v121tmp'
                with open(tmp, 'w', encoding='utf-8') as f:
                    f.write(data)
                os.chmod(tmp, 0o755)
                os.replace(tmp, path)
                changed += 1
            except Exception:
                continue
        if reason:
            print('[🧷 ثبات] ثُبّتت سكربتات الواجهة الأحدث بعد %s (%d ملفًا) ✅'
                  % (reason, changed))
        return changed
    except Exception:
        return 0


def _v121_post_restore_watch():
    """ينتظر اكتمال الاستعادة الخلفية ثم يعيد تثبيت سكربتاتنا — بلا أثر
    إن لم تحدث استعادة أصلًا (إقلاع بارد أو تثبيت كامل من الشبكة)."""
    try:
        _deadline = time.time() + 1800
        _ev = None
        while time.time() < _deadline:
            _ev = globals().get('_DEF_FULL_DONE')
            if _ev is not None:
                break
            time.sleep(3)
        if _ev is None:
            return
        _ev.wait(timeout=max(1.0, _deadline - time.time()))
        if not _ev.is_set():
            return
        if not globals().get('_DEFERRED_FULL_RESTORE'):
            return
        time.sleep(2)
        _v121_rewrite_user_scripts('استعادة اللقطة الخلفية')
    except Exception:
        pass


try:
    threading.Thread(target=_v121_post_restore_watch,
                     name='v121-post-restore-rewrite', daemon=True).start()
except Exception:
    pass

