# ============================================================
# 8.9) مشرف الخيوط الذاتي (يضمن بقاء كل الحرّاس حيّين 24 ساعة)
# ============================================================
# الخيوط daemon قد تموت بصمت إثر اتثناء غير متوقّع. هذا المشرف يسجّل كل
# خيط أساسي بالاسم، ثم يفحصها دوريًّا ويعيد إحياء أي خيط سقط — فلا تتوقّف
# أي وظيفة بقاء (مراقبة/نفق/ذاكرة/heartbeat/حفظ) مهما طالت المدة.
_MANAGED=(_V26_PREVIOUS_MANAGED if isinstance(_V26_PREVIOUS_MANAGED,dict) else {})
_MANAGED_LOCK=(_V26_PREVIOUS_MANAGED_LOCK if _V26_PREVIOUS_MANAGED_LOCK is not None else threading.RLock())

def _spawn(name,fn):
    """Start one managed daemon; duplicate live instances are refused."""
    with _MANAGED_LOCK:
        old=_MANAGED.get(name)
        if old and old.get("thread") and old["thread"].is_alive():return old["thread"]
        t=threading.Thread(target=fn,name=name,daemon=True)
        _MANAGED[name]={"fn":fn,"thread":t,"restarts":collections.deque(maxlen=12),"next":0.0}
        t.start();return t

def thread_supervisor():
    """Bounded restart policy: max five restarts/5min, then five-minute cooldown."""
    while True:
        time.sleep(60);now=time.monotonic()
        with _MANAGED_LOCK:items=list(_MANAGED.items())
        for name,info in items:
            try:
                th=info.get("thread")
                if th is not None and th.is_alive():continue
                if now<float(info.get("next",0)):continue
                hist=info.setdefault("restarts",collections.deque(maxlen=12))
                while hist and now-hist[0]>300:hist.popleft()
                if len(hist)>=5:
                    info["next"]=now+300;_diag_event("thread_circuit_"+name);continue
                hist.append(now);info["next"]=now+min(60,2**max(0,len(hist)-1))
                nt=threading.Thread(target=info["fn"],name=name,daemon=True)
                info["thread"]=nt;nt.start();_diag_event("thread_restart_"+name)
            except Exception as exc:_diag_event("thread_supervisor",exc,"error")


