def _link_card_update(html_text):
    """Update one persistent Colab output card; fallback to a new output block."""
    global _LINK_DISPLAY_HANDLE
    try:
        from IPython.display import display as _d, HTML as _h
        if _LINK_DISPLAY_HANDLE is not None:
            _LINK_DISPLAY_HANDLE.update(_h(html_text))
        else:
            _LINK_DISPLAY_HANDLE = _d(_h(html_text), display_id=True)
        return True
    except Exception:
        return False


