def _wait_http_ready(port, seconds=45):
    """لا نعلن رابط Cloudflare قبل أن يصبح خادم KasmVNC والبروكسي قابلين للاتصال فعلاً."""
    deadline = time.time() + seconds
    while time.time() < deadline:
        if port_listening(port):
            try:
                r = run("curl -fsS --max-time 3 -o /dev/null http://127.0.0.1:%d/_health" % port,
                        timeout=6)
                if getattr(r, "returncode", 1) == 0:
                    return True
            except Exception:
                pass
        time.sleep(1)
    return False


def _public_url_ok(url, tries=6, gap=3):
    """يتحقّق أن الرابط العام يستجيب فعلًا عبر حافة Cloudflare.

    سبب «الرابط الأزرق لا يفتح حتى أعيد التشغيل»: كان يُنشر بمجرّد أن
    cloudflared يطبعه، والفحص محلي فقط (127.0.0.1). لو لم تسجّل حافة
    Cloudflare المسار (أو ماتت الحافة لاحقًا) يبقى الرابط ميتًا رغم أن
    العملية حيّة. هنا نختبر الرابط من الخارج قبل نشره وبعده دوريًا.
    """
    if not url:
        return False
    probe = url.rstrip("/") + "/_health"
    for _attempt in range(max(1, int(tries))):
        try:
            r = run("curl -sS --max-time 8 -o /dev/null -w '%%{http_code}' '%s'" % probe,
                    timeout=14)
            code = (getattr(r, "stdout", "") or "").strip()[-3:]
            if code.isdigit() and 200 <= int(code) < 500:
                return True
        except Exception:
            pass
        time.sleep(gap)
    return False


def _cloudflared_binary_ready(path):
    """يتحقق من أن التنزيل مكتمل وقابل للتشغيل؛ يمنع تشغيل ملف HTML/جزئي."""
    try:
        if os.path.getsize(path) < 10_000_000:
            return False
        return getattr(run("'%s' --version >/dev/null 2>&1" % path, timeout=12),
                       "returncode", 1) == 0
    except Exception:
        return False


def cloudflare_loop():
    """يشغّل نفق Cloudflare ويُبقيه حيًّا 24 ساعة — يقاوم انقطاع الإنترنت.

    • لو سقط النفق (انقطاع نت/خطأ) يُعاد تشغيله فورًا مع backoff لطيف.
    • نقتل أي بقايا cloudflared عالقة قبل كل محاولة (لا تتراكم عمليات ميتة).
    • نتتبّع _cf_last_ok (آ��ر نبضة من stderr) كي يكتشف حارس الصحة الجمود
      ويعيد التشغيل حتى لو لم تخرج العملية لكنها توقّفت عن ال��مل.
    """
    global public_url, _cf_proc, _cf_last_ok, _cf_restart_count
    bin_path = "/tmp/cloudflared"
    # v86: نسخة مخبأة في Drive — بدل تنزيل 17MB من GitHub في كل إقلاع بارد
    #     (وفشل GitHub كان يؤخر ظهور الرابط دقائق). الاستعادة من Drive أسرع
    #     بمراحل، والتنزيل من GitHub صار خطة احتياط تُحدِّث الكاش عند نجاحه.
    _cf_cache = os.path.join(PERSIST_DIR, "pkg-cache", "cloudflared-linux-amd64") \
        if globals().get("PERSIST_DIR") else ""
    if not _cloudflared_binary_ready(bin_path) and _cf_cache \
            and os.path.isfile(_cf_cache):
        try:
            shutil.copyfile(_cf_cache, bin_path)
            os.chmod(bin_path, 0o755)
            if not _cloudflared_binary_ready(bin_path):
                run("rm -f '%s'" % bin_path)
        except Exception:
            run("rm -f '%s'" % bin_path)
    # تنزيل ذري مع تحقق؛ لا نبدأ نفقًا بملف ناقص بعد قطع جلسة Colab.
    if not _cloudflared_binary_ready(bin_path):
        run("rm -f /tmp/cloudflared /tmp/cloudflared.new")
        r = run("curl -fL --retry 4 --connect-timeout 20 --max-time 300 "
                "https://github.com/cloudflare/cloudflared/releases/latest/download/"
                "cloudflared-linux-amd64 -o /tmp/cloudflared.new", timeout=330)
        run("chmod +x /tmp/cloudflared.new 2>/dev/null")
        if getattr(r, "returncode", 1) == 0 and _cloudflared_binary_ready("/tmp/cloudflared.new"):
            os.replace("/tmp/cloudflared.new", bin_path)
            try:
                if _cf_cache:
                    os.makedirs(os.path.dirname(_cf_cache), exist_ok=True)
                    shutil.copyfile(bin_path, _cf_cache)
            except Exception:
                pass
        else:
            print("[نفق] تعذّر تجهيز cloudflared؛ ستُعاد المحاولة تلقائيًا.")
            time.sleep(8)
            return

    # ========================================================
    # المسار (أ): نفق مُسمّى بتوكن → رابط ثابت لا يتغيّر أبدًا 24/7
    # ========================================================
    if CF_TUNNEL_TOKEN:
        print("[نفق] وضع النفق الثابت (مُسمّى) مُفعّل — الرابط لن يتغيّر ✅")
        print("      افتح رابطك الثابت المرتبط بالنفق في لوحة Cloudflare.")
        while True:
            try:
                run("pkill -9 -f 'cloudflared tunnel' 2>/dev/null")
                time.sleep(1)
                cf = subprocess.Popen(
                    [bin_path, "tunnel", "--no-autoupdate",
                     # >>> أقصى سرعة يدعمها النفق: auto = QUIC أولًا (أسرع
                     #     وأقل تأخيرًا من http2، خاصة على شبكات الجوال)،
                     #     ولو UDP محجوب يرجع http2 تلقائيًّا — بلا مخاطرة. <<<
                     "--protocol", "http2",
                     "--edge-ip-version", "auto",
                     "--retries", "300",   # v112: صمود أطول — التسجيل الثابت لا يضيع عبر الانقطاعات
                     "--grace-period", "30s",
                     "run", "--token", CF_TUNNEL_TOKEN],
                    stdout=subprocess.DEVNULL, stderr=subprocess.PIPE,
                    text=True, preexec_fn=os.setpgrp, stdin=subprocess.DEVNULL)
                _cf_proc = cf
                _cf_last_ok = time.time()
                for line in cf.stderr:
                    _cf_last_ok = time.time()
                cf.wait()
                _cf_restart_count += 1
                print("[نفق] النفق الثابت انقطع — إعادة تشغيل #%d "
                      "(الرابط نفسه يعود)..." % _cf_restart_count)
            except Exception:
                pass
            time.sleep(4)
        return

    # ========================================================
    # المسار (ب): Pinggy  رابط ثابت (يحتاج اشتراك Pinggy Pro لتثبيت الـ
    # subdomain؛ المجاني يعطي رابطًا عشوائيًا). نقطة النهاية: pro.pinggy.io
    # ========================================================
    if PINGGY_TOKEN:
        print("[نفق] وضع Pinggy مُفعّل (التوكن: %s...) — "
              "الرابط ثابت مع اشتراك Pro." % PINGGY_TOKEN[:6])
        # نضمن توفّر عميل ssh
        if run("which ssh").stdout.strip() == "":
            run("apt-get install -y openssh-client > /dev/null 2>&1")
        while True:
            tunnel_port = PROXY_PORT
            try:
                run("pkill -9 -f 'ssh.*pinggy' 2>/dev/null")
                time.sleep(1)
                # نفق HTTP عبر SSH إلى Pinggy: التوكن يحدّد الـ subdomain الثابت
                # StrictHostKeyChecking=no: تشغيل آلي بلا سؤال تفاعلي.
                ssh_cmd = [
                    "ssh", "-p", "443",
                    "-o", "StrictHostKeyChecking=no",
                    "-o", "ServerAliveInterval=30",
                    "-o", "ServerAliveCountMax=3",
                    "-o", "ExitOnForwardFailure=yes",
                    "-R", "0:localhost:%d" % tunnel_port,
                    "%s@pro.pinggy.io" % PINGGY_TOKEN,
                ]
                cf = subprocess.Popen(
                    ssh_cmd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                    text=True, preexec_fn=os.setpgrp, stdin=subprocess.DEVNULL)
                _cf_proc = cf
                _cf_last_ok = time.time()
                for line in cf.stdout:
                    _cf_last_ok = time.time()
                    m = re.search(
                        r"https://[a-zA-Z0-9.-]+\.(pinggy\.link|pinggy\.io|a\.free\.pinggy\.link)",
                        line)
                    if m and m.group(0) != public_url:
                        public_url = m.group(0)
                        _print_phone_url(tunnel_port)
                cf.wait()
                _cf_restart_count += 1
                print("[نفق] Pinggy انقطع — إعادة تشغيل #%d (الرابط نفسه يعود)..."
                      % _cf_restart_count)
            except Exception:
                pass
            time.sleep(4)
        return

    # ========================================================
    # المسار (ج): الفق السريع (بلا حساب) — رابط عشوائي لكن ثابت طوال الجلسة
    # (بعد الإصلاح: لا يُدوَّر إلا لو انقطع الإنترنت فعلًا فسقطت العملية)
    # ========================================================
    while True:
        # لا ننشئ الرابط قبل جاهزية المنفذ: يمنع trycloudflare من إعلان رابط
        # يجيب 502/invalid في أول ثواني قلاع Colab.
        tunnel_port = PROXY_PORT
        if not _wait_http_ready(tunnel_port, seconds=60):
            print("[نفق] بانتظار خادم سطح المكتب قبل إنشاء الرابط...")
            time.sleep(3)
            continue
        try:
            # نظّف أي عملية cloudflared قديمة عالقة (تتراكم بع انقطاعات النت)
            run("pkill -9 -f 'cloudflared tunnel' 2>/dev/null")
            time.sleep(1)
            # إعدادات تقاوم الانقطاعات: مهلات أطول + إبقاء الاتصال حيًّا
            cf = subprocess.Popen(
                [bin_path, "tunnel", "--no-autoupdate",
                 # >>> أقصى سرعة يدعمها النفق: auto = QUIC أولًا (أسرع وأقل
                 #     تأخيرًا من http2 خاصة على شبكات الجوال)، ولو UDP
                 #     محجوب في Colab يرجع http2 تلقائيًّا — بلا مخاطرة. <<<
                 "--protocol", "http2",
                 "--edge-ip-version", "auto",
                 "--url", "http://localhost:%d" % tunnel_port,
                 "--retries", "300",   # v112: صمود أطول — الرابط يبقى نفسه عبر الانقطاعات
                 "--grace-period", "30s"],
                stdout=subprocess.DEVNULL, stderr=subprocess.PIPE, text=True,
                preexec_fn=os.setpgrp, stdin=subprocess.DEVNULL)
            _cf_proc = cf
            _cf_last_ok = time.time()
            for line in cf.stderr:
                # أي سطر من stderr = النفق حيّ وينبض (يُستخدم لكشف الجمود)
                _cf_last_ok = time.time()
                m = re.search(r"https://[a-zA-Z0-9-]+\.trycloudflare\.com", line)
                if m and m.group(0) != public_url:
                    candidate = m.group(0)
                    # Cloudflare يحتاج لحظات لتسجيل المسار عند أول اتصال؛ لا
                    # ننشر الرابط إلا بعد نجاح فحص حقيقي من خارج الجلسة،
                    # فيمنع نهائيًا ظهور رابط أزرق ميت يحتاج إعادة تشغيل.
                    time.sleep(2)
                    if (cf.poll() is None
                            and _wait_http_ready(tunnel_port, seconds=10)
                            and _public_url_ok(candidate)):
                        public_url = candidate
                        _print_phone_url(tunnel_port)
                    elif cf.poll() is None:
                        print("[نفق] الرابط الجديد لم يستجب عبر Cloudflare — "
                              "يُنشأ نفق بديل تلقائيًا (لا تعيد تشغيل الخلية)...",
                              flush=True)
                        public_url = ""
                        try:
                            cf.kill()
                        except Exception:
                            pass
                        break
            cf.wait()
            _cf_restart_count += 1
            print("[نفق] انقطع الاتصال (نت/خطأ) — إعادة تشغيل تلقائية #%d..."
                  % _cf_restart_count)
        except Exception:
            pass
        # backoff لطيف: لا نُغرق المعالج لو تكرّر الفشل سريعًا (مثلاً نت مقطوع)
        time.sleep(4)


def tunnel_health_loop():
    """حارس صحة النفق — نسخة مُصحّحة (لا تدوّر الرابط بلا داعٍ).

    *** إصلاح جوهري لعدم ا��تقرار الرابط ***
    المشكلة القديمة: كان يعتبر النفق «جامدًا» لمجرد غياب نبضات stderr، لكن
    غياب الن��ضات سببه أن KasmVNC (الخلفية) ميّت — لا عيب في النفق نفسه.
    فكان يقتل النفق كل ~200ث → رابط جديد كل مرة (يعيق العمل).

    الحل: لا ��دوّر النفق ��لا إذا سقطت عملية cloudflared فعليًا (poll != None).
    ما دامت العملية ��يّة، الرابط ثابت مهما توقّفت الخلفية — والووتشدوغ
    مسؤول عن إعادة تشغيل KasmVNC، لا النفق. هكذا يبقى الرابط ثابتًا طوال
    عمر الجلسة (لا يتغيّر إلا لو انقطع الإنترنت فعلًا وسقطت العملية).
    """
    global public_url
    fails = 0
    last_rotate = 0.0
    while True:
        time.sleep(30)   # v112: كشف أسرع لموت الحافة
        try:
            if CF_TUNNEL_TOKEN or PINGGY_TOKEN or _cf_proc is None:
                continue
            # ماتت العملية فعليًا — cloudflare_loop يتكفّل بإعادة التشغيل ولا نتدخّل.
            if _cf_proc.poll() is not None:
                fails = 0
                continue
            if not public_url:
                continue
            # لا نلوم النفق إذا كانت الخدمة المحلية نفسها متوقّفة (ذلك شأن الووتشدوغ).
            if not _wait_http_ready(PROXY_PORT, seconds=5):
                fails = 0
                continue
            if _public_url_ok(public_url, tries=2, gap=2):
                fails = 0
                continue
            fails += 1
            # ثلاث إخفاقات متتالية (~2.5 دقيقة) = الحافة ميتة رغم حياة العملية.
            # ندوّر نفقًا جديدًا مرة كل 5 دقائق كحد أقصى حتى لا يتغير الرابط بلا داعٍ.
            if fails >= 3 and (time.time() - last_rotate) > 180:  # v112: استشفاء أسرع من موت الحافة
                last_rotate = time.time()
                fails = 0
                print("[نفق] الرابط توقّف عن الاستجابة رغم أن سطح المكتب يعمل — "
                      "يُنشأ رابط جديد تلقائيًا (لا حاجة لإعادة تشغيل السكربت)...",
                      flush=True)
                public_url = ""
                try:
                    _cf_proc.kill()
                except Exception:
                    pass
                run("pkill -9 -f 'cloudflared tunnel' 2>/dev/null")
        except Exception:
            pass


_v26_external_cf_reuse=False
try:
    _v26_cf_live=(run("pgrep -af '[/]tmp/cloudflared tunnel' | grep -F -- '--url http://localhost:%d' >/dev/null 2>&1"%PROXY_PORT,timeout=8).returncode==0)
    if public_url and _v26_cf_live and port_listening(PROXY_PORT):
        _v26_external_cf_reuse=True
except Exception:pass
if _v26_external_cf_reuse and not _MANAGED.get("cloudflare_loop"):
    print('[⚡ V27] أُعيد استخدام نفق Cloudflare الحي؛ لا انتظار 330ث ولا تدوير للرابط ✅',flush=True)
else:
    _spawn("cloudflare_loop", cloudflare_loop)
    _spawn("tunnel_health_loop", tunnel_health_loop)


def _session_guardian_loop():
    """v112 — حارس الجلسة: كروم الأصلي (نبض Colab) لا يموت بصمت أبدًا.
    إن مات أُعيد إطلاقه تلقائيًّا فيستعيد التبويبات (ومعه إضافة الإبقاء)،
    وإلا توقّف النبض فتُعاد جدولة الجلسة فيظهر خطأ 1033. محدود بـ3
    إطلاقات/10 دقائق، ولا يعمل قبل أول رصد حي (لا يتدخّل في الإقلاع)."""
    seen_alive = False
    relaunches = []
    while True:
        time.sleep(90)
        try:
            alive = (run("pgrep -f 'user-data-dir=/root/.config/google-chrome' >/dev/null 2>&1").returncode == 0)
            if alive:
                seen_alive = True
                continue
            if not seen_alive:
                continue
            now = time.time()
            relaunches[:] = [t for t in relaunches if now - t < 600]
            if len(relaunches) >= 3:
                continue
            if not (_proc_alive("Xvnc") or _proc_alive("Xvfb")):
                continue  # العرض ميت — ووتشدوغ سطح المكتب مسؤول عنه أولًا
            relaunches.append(now)
            print("[🛡️ حارس الجلسة] كروم الأصلي متوقف — إعادة إطلاق لاستعادة نبض Colab #%d" % len(relaunches), flush=True)
            run("setsid env DISPLAY=%s /usr/local/bin/chrome-root >/tmp/chrome-guardian.log 2>&1 < /dev/null &"
                % globals().get("DISPLAY_NUM", ":1"), timeout=15)
        except Exception:
            pass


# A guardian can intentionally relaunch Chrome after the user closes it.
# Keep it opt-in to avoid surprise windows and preserve a single-browser desktop.
CHROME_SESSION_GUARDIAN = os.environ.get("CHROME_SESSION_GUARDIAN", "0").strip().lower() in ("1", "true", "yes", "on")
if CHROME_SESSION_GUARDIAN:
    _spawn("session_guardian_loop", _session_guardian_loop)
else:
    print("[i] حارس إعادة فتح Chrome معطّل افتراضيًا لمنع النوافذ المتكررة.", flush=True)

# Keep this cell's main output attached until the first quick-tunnel URL exists.
# This avoids Colab mobile dropping display() calls emitted only by a background thread.
def _render_first_link_on_main_thread(timeout=330):
    if CF_TUNNEL_TOKEN or PINGGY_TOKEN:
        return
    deadline=time.time()+timeout;last_note=-1
    while time.time()<deadline:
        if public_url:
            _print_phone_url(PROXY_PORT, force=True)
            return
        left=max(0,int(deadline-time.time()))
        note=left//15
        if note!=last_note:
            last_note=note
            _link_card_update(
              '<div style="padding:14px;border:3px solid #f9ab00;border-radius:12px;'
              'background:#fef7e0;text-align:center;direction:rtl;font-family:sans-serif">'
              '<b>⏳ جارٍ تجهيز الرابط الأزرق...</b><br><span style="font-size:12px">'
              'الخادم جاهز، وننتظر Cloudflare. لا تغلق الخلية (%d ثانية كحد أقصى).</span></div>'%left)
        time.sleep(.5)
    _link_card_update(
      '<div style="padding:14px;border:3px solid #d93025;border-radius:12px;background:#fce8e6;'
      'text-align:center;direction:rtl;font-family:sans-serif"><b>تعذر إنشاء الرابط مؤقتًا.</b><br>'
      '<span style="font-size:12px">سيستمر النظام في المحاولة تلقائيًا؛ افحص اتصال Colab ثم أعد تشغيل الخلية إذا استمر ذلك.</span></div>')
    print('[نفق] لم يصل رابط Cloudflare خلال المهلة؛ ��ستمر المحاولة في الخلفية.',flush=True)

_render_first_link_on_main_thread()

# ============================================================
# v77) تشغيل التجهيز التلقائي فور طهور الرابط + متابعة آخر مشروع
# ============================================================
def _net_lockdown_boot():
    """يقفل كل حركة شبكة خلفية فوراً بعد طهور الرابط (يسبق التجهيز)."""
    try:
        if not _NET_SAVER_READY:
            return
        _env = dict(os.environ, DISPLAY=DISPLAY_NUM, HOME="/root")
        try:
            subprocess.run(["/usr/local/bin/net-lockdown", "all"], env=_env, timeout=420,
                           stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        except Exception as _exc:
            _diag_event("net_lockdown_run", _exc, "warning")
        try:
            subprocess.run(["/usr/local/bin/net-usage", "reset"], env=_env, timeout=60,
                           stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        except Exception:
            pass
        _prof = "saver"
        try:
            _prof = open("/root/.config/colab-desktop/net-profile").read().strip() or "saver"
        except Exception:
            pass
        if _prof != "full":
            print("[📉 توفير] أُوقفت التحديثات والتقارير والجلب الخلفي؛ "
                  "والتنزيلات الكبيرة مؤجلة حتى تطلبها من أيقونة تنزيل حزم التطوير ✅", flush=True)
        else:
            print("[📉 توفير] أُوقفت الاتصالات الخلفية (ملف الشبكة: كامل) ✅", flush=True)
        _diag_event("net_lockdown_done")
    except Exception as exc:
        _diag_event("net_lockdown_boot_failed", exc, "warning")


def _app_provision_boot():
    """يجهز التطبيقات ويستعيد المشاريع في الخلفية بمجرد طهور الرابط."""
    try:
        if not _APP_PROVISION_READY:
            return
        try:
            _xfce_session_live(True)
        except Exception:
            pass
        _diag_event("app_provision_start")
        _env = dict(os.environ, DISPLAY=DISPLAY_NUM, HOME="/root",
                    DEBIAN_FRONTEND="noninteractive")
        # مرّتان: الأولى فورًا (إعدادات + مشاريع + حزم أساس)، والثانية بعد اكتمال
        # تثبيت التطبيقات الكبيرة (لأن sdkmanager يحتاج JDK المرفق مع Android Studio).
        _saver = True
        try:
            _saver = (open("/root/.config/colab-desktop/net-profile").read().strip()
                      != "full")
        except Exception:
            pass
        for _phase in ((1,) if _saver else (1, 2)):
            if _phase == 2:
                try:
                    _APP_INSTALL_DONE.wait(3000)
                except Exception:
                    pass
                time.sleep(20)
            try:
                subprocess.run(["/usr/local/bin/app-provision"], env=_env, timeout=5400,
                               stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            except Exception as _exc:
                _diag_event("app_provision_run", _exc, "warning")
            if _phase == 1:
                print("[⚙️ تجهيز] إعدادات المحررات والمشاريع جاهزة؛ نواصل تنزيل حزم "
                      "Android/Gradle في الخلفية...", flush=True)
        if os.path.exists("/root/.config/colab-desktop/.apps-provisioned"):
            print("[OK] كل التطبيقات مُهيأة: الحزم مُنزّلة والإعدادات مضبوطة "
                  "والمشاريع مستعادة ✅", flush=True)
        else:
            print("[i] اكتمل معطم التجهيز؛ الخطوات المتبق��ة ستُكمل تلقائيًا "
                  "(التفاصيل في /tmp/app-provision.log) ✅", flush=True)
        _diag_event("app_provision_done")
        try:
            _persist_now("app-provision")
        except Exception:
            pass
    except Exception as exc:
        _diag_event("app_provision_boot_failed", exc, "warning")


def _last_project_tracker_loop():
    """يُحدّث ملف آخر مشروع كل دقائق لتعمل زر "متابعة آخر مشروع" دون أخطاء."""
