# v80) أدوات الجاهزية والتشخيص والتخطيط والخزنة ووضع القراءة
# ------------------------------------------------------------
# كلها سكربتات مستقلة: لا تلمس مسارات الإقلاع، ولا تنزّل شيئًا من الإنترنت،
# ولا تقتل أي عملية ��املة. تُكتب مرة واحدة عند ��لإقلاع مع أيقونات عربية.
# ============================================================
_V80_STATUS_SH = r'''#!/bin/bash
# ============================================================
# colab-status (v80) — شارة جاهزية موحّدة لكل عمليات الخلفية.
# لا تقتل شيئًا ولا تُعدّل شيئًا: قراءة فقط + ت��رير عربي مخ��صر.
#   colab-status            طباعة نصّية في الطرفية
#   colab-status --gui      نافذة zenity قابلة للتحديث
#   colab-status --file     كتابة /root/workspace/boot-status.txt فقط
# ============================================================
set -u
CFG=/root/.config/colab-desktop
PERSIST="${PERSIST_DIR:-/content/drive/MyDrive/colab_desktop_v43}"
OUT=/root/workspace/boot-status.txt

ok(){ printf '\xe2\x9c\x85 %s\n' "$1"; }
wait_(){ printf '\xe2\x8f\xb3 %s\n' "$1"; }
bad(){ printf '\xe2\x9a\xa0\xef\xb8\x8f %s\n' "$1"; }

has_proc(){ pgrep -f "$1" >/dev/null 2>&1; }

rate_line(){
  # معدل الاستهلاك الحالي (تقديري) من /proc/net/dev — قراءتان بفارق ثانية
  local a b d
  a=$(awk 'NR>2{r+=$2;t+=$10}END{print r+t}' /proc/net/dev 2>/dev/null || echo 0)
  sleep 1
  b=$(awk 'NR>2{r+=$2;t+=$10}END{print r+t}' /proc/net/dev 2>/dev/null || echo 0)
  d=$(( (b - a) / 1024 ))
  [ "$d" -lt 0 ] && d=0
  printf '%s' "$d"
}

report(){
  echo "== حالة الجاهزية — $(date '+%Y-%m-%d %H:%M:%S') =="
  echo
  echo "— سطح المكتب والرابط —"
  if [ -s /tmp/desktop_link.txt ]; then
    _safe_link="$(head -n1 /tmp/desktop_link.txt)"; _safe_link="${_safe_link%%\?*}"; ok "الرابط جاهز (الرمز مخفي): $_safe_link"
  else
    wait_ "الرابط لم يُنشَر بعد"
  fi
  if has_proc 'Xvfb|kasmvnc|Xkasm'; then ok "خادم العرض يعمل"; else bad "خادم العرض غير مكتشف"; fi
  if has_proc 'xfce4-session'; then ok "جلسة XFCE تعمل"; else bad "جلسة XFCE غير مكتشفة"; fi
  if has_proc 'cloudflared'; then ok "النفق يعمل"; else bad "النفق غير مكتشف"; fi
  echo
  echo "— الحفظ في Drive —"
  if [ -d "$PERSIST" ]; then
    ok "مجلد الحفظ متاح: $PERSIST"
    if [ -f "$PERSIST/.snapshot/mark.json" ] || ls "$PERSIST"/.snapshot/*.zst >/dev/null 2>&1; then
      ok "لقطة النظام موجودة"
    else
      wait_ "لقطة النظام لم تُبنَ بعد"
    fi
    if [ -d "$PERSIST/boot-core" ]; then ok "طبقة الإقلاع السريع جاهزة"; else wait_ "طبقة الإقلاع السريع قيد التحضير"; fi
  else
    bad "مجلد Drive غير مُركَّب — الحفظ متوقف"
  fi
  echo
  echo "— التطبيقات والحزم —"
  if [ -f "$CFG/.apps-provisioned" ]; then ok "تهيئة التطبيقات كاملة"
  elif [ -f "$CFG/.apps-provisioned-lite" ] || [ -f "$CFG/apps-provisioned-lite" ]; then ok "تهيئة التطبيقات (وضع مقتصد)"
  else wait_ "تهيئة التطبيقات تعمل في الخلفية"; fi
  if [ -f /root/Android/Sdk/.colab-warmup-done ]; then ok "ملفات Android SDK جاهزة"; else wait_ "تحميل ملفات Android SDK"; fi
  if [ -f "$CFG/last-project" ]; then ok "آخر مشروع: $(head -c 120 "$CFG/last-project")"; else wait_ "لا مشروع مسجَّل بعد"; fi
  echo
  echo "— النوافذ المعزولة (العمل) —"
  local slots=0
  [ -d /root/genspark-profiles ] && slots=$(ls -1 /root/genspark-profiles 2>/dev/null | wc -l)
  [ "$slots" = "0" ] && [ -d "$PERSIST/genspark-slots" ] && slots=$(ls -1 "$PERSIST/genspark-slots" 2>/dev/null | wc -l)
  if [ "$slots" -gt 0 ]; then ok "عدد الجلسات المحفوظة: $slots"; else wait_ "لا جلسات محفوظة بعد"; fi
  if has_proc 'genspark-window'; then ok "نوافذ العمل مفتوحة الآن"; else wait_ "لا نافذة عمل مفتوحة"; fi
  echo
  echo "— الشبكة والاستهلاك —"
  if [ -f "$CFG/net-profile" ]; then ok "وضع البيانات: $(cat "$CFG/net-profile")"; else wait_ "وضع البيانات غير محدَّد"; fi
  echo "   📶 المعدل الآن: $(rate_line) KB/s"
  if has_proc 'colab-keep-alive|colab-keepalive-guard'; then ok "مانع الخمول يعمل"; else wait_ "مانع الخمول غير مكتشف"; fi
  echo
  echo "سجلات مفيدة: /tmp/app-provision.log /tmp/net-lockdown.log /tmp/flathub-install.log"
}

main(){
  local mode="${1:-}"
  local txt
  txt=$(report)
  mkdir -p /root/Desktop 2>/dev/null || true
  printf '%s\n' "$txt" > "$OUT" 2>/dev/null || true
  case "$mode" in
    --file) : ;;
    --gui)
      while :; do
        txt=$(report)
        printf '%s\n' "$txt" > "$OUT" 2>/dev/null || true
        printf '%s\n' "$txt" > /tmp/.colab-status.txt
        if zenity --text-info --title="حالة الجاهزية" --filename=/tmp/.colab-status.txt \
             --width=640 --height=560 --ok-label="تحديث" --cancel-label="إغلاق" 2>/dev/null; then
          continue
        fi
        break
      done
      ;;
    *) printf '%s\n' "$txt" ;;
  esac
}
main "${1:-}"
'''
_V80_DOCTOR_SH = r'''#!/bin/bash
# ============================================================
# colab-doctor (v80) — تشخيص شامل + إصلاح آمن بضغطة واحدة.
# مبدأ الأمان: لا يقتل النفق ولا العرض ولا أي تطبيق مفتوح،
# ولا يُنزّل أي شيء من الإنترنت. إصلاحاته محلية وقابلة للتراجع.
# ============================================================
set -u
CFG=/root/.config/colab-desktop
PERSIST="${PERSIST_DIR:-/content/drive/MyDrive/colab_desktop_v43}"
LOG=/tmp/colab-doctor.log
REPORT=/tmp/.colab-doctor.txt
FIX="${1:-}"
: > "$REPORT"
exec 3>>"$LOG"

say(){ printf '%s\n' "$1" >>"$REPORT"; printf '%s\n' "$1" >&3; }
okk(){ say "✅ $1"; }
wrn(){ say "⚠️ $1"; }
fixed(){ say "🔧 $1"; }
has(){ command -v "$1" >/dev/null 2>&1; }
proc(){ pgrep -f "$1" >/dev/null 2>&1; }
PROBLEMS=0
note_problem(){ PROBLEMS=$((PROBLEMS+1)); }

say "== تقرير التشخيص ا��شامل — $(date '+%Y-%m-%d %H:%M:%S') =="
say ""

# ---------------------------------------------------------- 1) النفق/الرابط
say "1) الرابط والنفق"
URL=""
[ -s /tmp/desktop_link.txt ] && URL=$(head -n1 /tmp/desktop_link.txt)
if [ -n "$URL" ]; then
  okk "الرابط المنشور: $URL"
  if has curl; then
    CODE=$(curl -m 12 -s -o /dev/null -w '%{http_code}' "$URL" 2>/dev/null || echo 000)
    if [ "$CODE" = "200" ] || [ "$CODE" = "401" ] || [ "$CODE" = "302" ]; then
      okk "النفق يردّ (HTTP $CODE)"
    else
      wrn "النفق لا يردّ (HTTP $CODE) — حارس النفق التلقائي سيُعيد بناءه خلال دقيقة"
      note_problem
    fi
  fi
else
  wrn "لا يوجد رابط منشور بعد"
  note_problem
fi
if proc 'cloudflared'; then okk "عملية cloudflared تعمل"; else wrn "cloudflared غير مكتشف"; note_problem; fi
say ""

# ------------------------------------------------------------- 2) خادم العرض
say "2) خادم العرض والجلسة"
if proc 'Xvfb|kasmvnc|Xkasm|websockify'; then okk "خادم العرض يعمل"; else wrn "خادم العرض غير مكتشف"; note_problem; fi
if proc 'xfce4-session'; then okk "جلسة XFCE تعمل"; else wrn "جلسة XFCE غير مكتشفة"; note_problem; fi
if [ -n "${DISPLAY:-}" ] && has xdotool; then
  G=$(DISPLAY="${DISPLAY:-:1}" xdotool getdisplaygeometry 2>/dev/null || true)
  if [ -n "$G" ]; then okk "دقة الشاشة: $G"; else wrn "تعذر قراءة دقة الشاشة"; note_problem; fi
fi
ICONS=$(ls -1 /root/Desktop/*.desktop 2>/dev/null | wc -l)
if [ "$ICONS" -ge 3 ]; then okk "أيقونات سطح المكتب: $ICONS"; else wrn "أيقونات سطح المكتب قليلة ($ICONS)"; note_problem; fi
say ""

# ----------------------------------------------------------- 3) الحفظ في Drive
say "3) الحفظ في Drive"
if [ -d "$PERSIST" ]; then
  okk "مجلد الحفظ متاح"
  T="$PERSIST/.doctor-write-test"
  if ( echo ok > "$T" ) 2>/dev/null && [ -s "$T" ]; then
    okk "الكتابة على Drive تعمل"
    rm -f "$T" 2>/dev/null || true
  else
    wrn "الكتابة على Drive فاشلة — أعد تركيب Drive من خلية Colab"
    note_problem
  fi
  FREE=$(df -Pm "$PERSIST" 2>/dev/null | awk 'NR==2{print $4}')
  [ -n "${FREE:-}" ] && say "   المساحة الحرة في Drive: ${FREE}MB"
else
  wrn "مجلد Drive غير موجود — لا يوجد حفط دائم الآن"
  note_problem
fi
say ""

# ------------------------------------------------- 4) النوافذ المعزولة والخزنة
say "4) النوافذ المعزولة ومخزن الدخول"
if [ -x /usr/local/bin/vault-verify ]; then
  if /usr/local/bin/vault-verify check >>"$LOG" 2>&1; then
    okk "مخزن بيانات الدخول سليم (بصمات متطابقة)"
  else
    wrn "بعض أرشيفات الجلسات بلا بصمة أو ناقصة — راجع $LOG"
    note_problem
  fi
fi
if [ -x /usr/local/bin/genspark-window ]; then okk "مُشغّل نوافذ العمل موجود"; else wrn "مُشغّل نوافذ العمل مفقود"; note_problem; fi
say ""

# --------------------------------------------------------------- 5) التطبيقات
say "5) التطبيقات والحزم"
for b in /usr/local/bin/chrome-root /usr/local/bin/android-studio-colab /usr/local/bin/cursor-colab; do
  if [ -x "$b" ]; then okk "موجود: $(basename "$b")"; else wrn "مفقود: $(basename "$b")"; note_problem; fi
done
if dpkg -l 2>/dev/null | tail -n +6 | cut -c1-2 | grep -qv '^ii'; then
  wrn "توجد حزم ناقصة التهيئة في dpkg"
  note_problem
else
  okk "حالة الحزم متّسقة"
fi
say ""

# ------------------------------------------------------ الإصلاحات الآمنة
if [ "$FIX" = "--fix" ] || [ "$FIX" = "fix" ]; then
  say "== إصلاحات آمنة =="
  mkdir -p /root/Desktop /root/Projects "$CFG" 2>/dev/null || true
  chmod 755 /root/Desktop/*.desktop 2>/dev/null || true
  fixed "ضبط أذونات أيقونات سطح المكتب"
  if has update-desktop-database; then update-desktop-database /usr/share/applications >/dev/null 2>&1 || true; fi
  [ -x /usr/local/bin/refresh-app-menu ] && /usr/local/bin/refresh-app-menu >>"$LOG" 2>&1 || true
  fixed "تحديث قائمة التطبيقات"
  if [ -x /usr/local/bin/window-fitter ]; then
    pkill -USR1 -f 'window-fitter' 2>/dev/null || true
    fixed "إعادة محاذاة النوافذ داخل حدود الشاشة"
  fi
  if has xfdesktop && [ -n "${DISPLAY:-}" ]; then
    DISPLAY="${DISPLAY:-:1}" xfdesktop --reload >>"$LOG" 2>&1 || true
    fixed "إعادة تحميل سطح المكتب (الأيقونات)"
  fi
  if [ -x /usr/local/bin/net-lockdown ] && [ -f "$CFG/net-profile" ]; then
    /usr/local/bin/net-lockdown apply >>"$LOG" 2>&1 || true
    fixed "إعادة ت��بيق وضع توفير البيانات"
  fi
  if [ -x /usr/local/bin/vault-verify ]; then
    /usr/local/bin/vault-verify mirror >>"$LOG" 2>&1 || true
    fixed "تحديث النسخة المرايا لمخزن الدخول + بصماته"
  fi
  if [ -x /usr/local/bin/colab-keepalive-guard ]; then
    ( setsid /usr/local/bin/colab-keepalive-guard >>"$LOG" 2>&1 & ) 2>/dev/null || true
    fixed "إنعاش حارس مانع الخمول"
  fi
  say ""
fi

if [ "$PROBLEMS" = "0" ]; then
  say "النتيجة: لا توجد مشاكل مكتشفة ✅"
else
  say "النتيجة: $PROBLEMS ملاحزة/مشكلة — التفاصيل أعلاه والسجل: $LOG"
fi

if [ "${DISPLAY:-}" != "" ] && command -v zenity >/dev/null 2>&1 && [ "$FIX" != "--quiet" ]; then
  if zenity --text-info --title="التشخيص الشامل" --filename="$REPORT" --width=680 --height=580 \
       --ok-label="إصلاح آمن الآن" --cancel-label="إغلاق" 2>/dev/null; then
    if [ "$FIX" != "--fix" ] && [ "$FIX" != "fix" ]; then
      exec "$0" --fix
    fi
  fi
else
  cat "$REPORT"
fi
exit 0
'''
_V80_WINLAYOUT_SH = r'''#!/bin/bash
# ============================================================
# window-layout (v80) — حفظ تخطيط النوافذ واستعادته.
#   window-layout save      يحفظ النوافذ المفتوحة ومواقعها وأحجامها
#   window-layout restore   يُعيد تشغيل التطبيقات ويُعيد مواضعها
#   window-layout menu      قائمة zenity (حفظ / استعادة / عرض)
# يُحترم حدود الشاشة دائمًا (لا نوافذ خارج الإطار) ويعمل مع window-fitter.
# ============================================================
set -u
export DISPLAY="${DISPLAY:-:1}"
CFG=/root/.config/colab-desktop
LAYOUT="$CFG/window-layout.txt"
LOG=/tmp/window-layout.log
mkdir -p "$CFG" 2>/dev/null || true
has(){ command -v "$1" >/dev/null 2>&1; }
log(){ printf '%s %s\n' "$(date '+%H:%M:%S')" "$1" >>"$LOG"; }
gui(){ [ -n "${DISPLAY:-}" ] && has zenity; }
# v83: لا نافذة تلقائ��ة أبدًا — الحفظ التلقائي يكتب في السجل فقط (WL_QUIET=1)،
# وأي رسالة يدوية تُغلق نفسها بعد 15 ثانية (--timeout).
quiet(){ [ "${WL_QUIET:-0}" = "1" ] || [ "${COLAB_QUIET:-0}" = "1" ]; }
msg(){ local m; m=$(printf '%b' "$1"); log "MSG: $(printf '%s' "$m" | tr "\n" " ")";
  if quiet; then return 0; fi;
  if gui; then zenity --info --width=440 --timeout=15 --title="تخطيط النوافذ" \
    --text="$m" >/dev/null 2>&1 || true; else printf '%s\n' "$m"; fi; }

has wmctrl || { msg "أداة wmctrl غير متوفرة."; exit 0; }
has xdotool || { msg "أداة xdotool غير متوفرة."; exit 0; }

# خريطة الصنف -> أمر التش��يل (لا نشغّل أي شيء غير معروف)
launcher_for(){
  case "$1" in
    *jetbrains-studio*|*android-studio*) echo "/usr/local/bin/android-studio-colab" ;;
    *ursor*) echo "/usr/local/bin/cursor-colab" ;;
    *ntigravity*) echo "/usr/local/bin/antigravity-colab" ;;
    *hunar*|*Thunar*) echo "thunar /root/Projects" ;;
    *erminal*|*xfce4-terminal*) echo "xfce4-terminal" ;;
    *google-chrome*|*Google-chrome*) echo "/usr/local/bin/chrome-root" ;;
    *) echo "" ;;
  esac
}

do_save(){
  : > "$LAYOUT.tmp"
  local line wid desk x y w h cls cmd
  wmctrl -lG -x 2>/dev/null | while read -r wid desk x y w h cls rest; do
    case "$cls" in
      *desktop*|*xfdesktop*|*xfce4-panel*) continue ;;
    esac
    cmd=$(launcher_for "$cls")
    [ -z "$cmd" ] && continue
    printf '%s|%s|%s|%s|%s|%s\n' "$cls" "$x" "$y" "$w" "$h" "$cmd" >> "$LAYOUT.tmp"
  done
  if [ -s "$LAYOUT.tmp" ]; then
    sort -u -o "$LAYOUT" "$LAYOUT.tmp"
    rm -f "$LAYOUT.tmp"
    log "saved $(wc -l < "$LAYOUT") windows"
    msg "حفظنا تخطيط $(wc -l < "$LAYOUT") نافذة.\nستُستعاد بزر «استعادة تخطيط النوافذ» أو تلقائيًا بعد الإقلاع."
  else
    rm -f "$LAYOUT.tmp"
    msg "لا توجد نوافذ معروفة مفتوحة لحفطها."
  fi
}

find_window(){
  local cls="$1" key w
  key=$(printf '%s' "$cls" | cut -d. -f1)
  w=$(xdotool search --onlyvisible --class "$key" 2>/dev/null | tail -n1 || true)
  [ -z "$w" ] && w=$(xdotool search --onlyvisible --classname "$key" 2>/dev/null | tail -n1 || true)
  printf '%s' "$w"
}

place(){
  local w="$1" x="$2" y="$3" ww="$4" hh="$5" geo sw sh
  geo=$(xdotool getdisplaygeometry 2>/dev/null || echo "800 1280")
  sw=${geo%% *}; sh=${geo##* }
  [ "$ww" -gt "$sw" ] && ww=$sw
  [ "$hh" -gt "$sh" ] && hh=$sh
  [ "$x" -lt 0 ] && x=0
  [ "$y" -lt 0 ] && y=0
  [ $((x + ww)) -gt "$sw" ] && x=$((sw - ww))
  [ $((y + hh)) -gt "$sh" ] && y=$((sh - hh))
  [ "$x" -lt 0 ] && x=0
  [ "$y" -lt 0 ] && y=0
  wmctrl -ir "$w" -b remove,maximized_vert,maximized_horz 2>/dev/null || true
  sleep .2
  xdotool windowmove "$w" "$x" "$y" 2>/dev/null || true
  xdotool windowsize "$w" "$ww" "$hh" 2>/dev/null || true
}

do_restore(){
  [ -s "$LAYOUT" ] || { msg "لا يوجد تخطيط محفوط بعد."; exit 0; }
  local cls x y w h cmd wid n=0
  while IFS='|' read -r cls x y w h cmd; do
    [ -z "${cls:-}" ] && continue
    wid=$(find_window "$cls")
    if [ -z "$wid" ]; then
      log "launch $cmd"
      ( setsid sh -c "$cmd" >>"$LOG" 2>&1 & ) 2>/dev/null || true
      local t=0
      while [ "$t" -lt 45 ]; do
        sleep 2; t=$((t+2))
        wid=$(find_window "$cls")
        [ -n "$wid" ] && break
      done
    fi
    if [ -n "$wid" ]; then
      place "$wid" "$x" "$y" "$w" "$h"
      n=$((n+1))
    fi
  done < "$LAYOUT"
  [ -x /usr/local/bin/window-fitter ] && pkill -USR1 -f window-fitter 2>/dev/null || true
  log "restored $n windows"
  msg "استعدنا $n نافذة داخل حدود الشاشة."
}

case "${1:-menu}" in
  save) do_save ;;
  restore) do_restore ;;
  restore-quiet) do_restore >/dev/null 2>&1 ;;
  show) if gui; then zenity --text-info --title="التخطيط المحفوط" --filename="$LAYOUT" --width=560 --height=400 2>/dev/null; else cat "$LAYOUT" 2>/dev/null; fi ;;
  menu)
    if gui; then
      CH=$(zenity --list --title="تخطيط النوافذ" --width=440 --height=300 \
           --column="الإجراء" "حفط التخطيط الحالي" "استعادة التخطيط" "عرض المحفوط" 2>/dev/null) || exit 0
      case "$CH" in
        "حفط التخطيط الحالي") do_save ;;
        "استعادة التخطيط") do_restore ;;
        "عرض المحفوط") exec "$0" show ;;
      esac
    else
      echo "usage: window-layout {save|restore|show}"
    fi ;;
  *) echo "usage: window-layout {save|restore|show|menu}" ;;
esac
exit 0
'''
_V80_VAULT_SH = r'''#!/bin/bash
# ============================================================
# vault-verify (v80) — حماية مزدوجة لبيانات دخول نوافذ العمل.
#   vault-verify mirror   ينسخ أرشيفات الجلسات إلى نسخة احتياطية ثانية + بصمة
#   vault-verify check    يتحقق من سلامة كل أرشيف قبل الاعتماد عليه
#   vault-verify heal     يستبدل أي أرشيف تالف بال��سخة السليمة من المرايا
# لا يحذف شيئًا أبدًا ولا يكتب فوق أرشيف سليم.
# ============================================================
set -u
PERSIST="${PERSIST_DIR:-/content/drive/MyDrive/colab_desktop_v43}"
VAULT="$PERSIST/genspark-slots"
MIRROR="$PERSIST/genspark-slots-mirror"
LOG=/tmp/vault-verify.log
MODE="${1:-check}"
has(){ command -v "$1" >/dev/null 2>&1; }
log(){ printf '%s %s\n' "$(date '+%H:%M:%S')" "$1" >>"$LOG"; }

[ -d "$PERSIST" ] || { log "drive not mounted"; exit 0; }
mkdir -p "$VAULT" "$MIRROR" 2>/dev/null || true

sha_of(){ sha256sum "$1" 2>/dev/null | awk '{print $1}'; }

do_mirror(){
  local f base s cur rc=0
  for f in "$VAULT"/*; do
    [ -f "$f" ] || continue
    case "$f" in *.sha256) continue ;; esac
    base=$(basename "$f")
    s=$(sha_of "$f")
    [ -z "$s" ] && { rc=1; continue; }
    # بصمة بجانب الأصل (تكتب أولًا إلى ملف مؤقت ثم تُنقل = لا بصمة ناقصة)
    printf '%s  %s\n' "$s" "$base" > "$VAULT/.$base.sha256.tmp" 2>/dev/null || rc=1
    mv -f "$VAULT/.$base.sha256.tmp" "$VAULT/$base.sha256" 2>/dev/null || rc=1
    cur=""
    [ -f "$MIRROR/$base.sha256" ] && cur=$(awk '{print $1}' "$MIRROR/$base.sha256" 2>/dev/null)
    if [ "$cur" != "$s" ]; then
      if cp -f "$f" "$MIRROR/.$base.part" 2>/dev/null; then
        if [ "$(sha_of "$MIRROR/.$base.part")" = "$s" ]; then
          mv -f "$MIRROR/.$base.part" "$MIRROR/$base" 2>/dev/null || rc=1
          printf '%s  %s\n' "$s" "$base" > "$MIRROR/$base.sha256" 2>/dev/null || rc=1
          log "mirrored $base"
        else
          rm -f "$MIRROR/.$base.part" 2>/dev/null || true
          log "mirror checksum mismatch $base (kept old copy)"
          rc=1
        fi
      else
        rm -f "$MIRROR/.$base.part" 2>/dev/null || true
        rc=1
      fi
    fi
  done
  return $rc
}

do_check(){
  local f base want got rc=0 n=0 bad=0
  for f in "$VAULT"/*; do
    [ -f "$f" ] || continue
    case "$f" in *.sha256) continue ;; esac
    base=$(basename "$f")
    n=$((n+1))
    if [ ! -f "$VAULT/$base.sha256" ]; then
      log "no checksum for $base"
      rc=1
      continue
    fi
    want=$(awk '{print $1}' "$VAULT/$base.sha256" 2>/dev/null)
    got=$(sha_of "$f")
    if [ "$want" != "$got" ]; then
      log "CORRUPT $base"
      bad=$((bad+1))
      rc=1
    fi
  done
  log "checked $n archives, $bad corrupt"
  return $rc
}

do_heal(){
  local f base want got healed=0
  for f in "$VAULT"/*; do
    [ -f "$f" ] || continue
    case "$f" in *.sha256) continue ;; esac
    base=$(basename "$f")
    [ -f "$VAULT/$base.sha256" ] || continue
    want=$(awk '{print $1}' "$VAULT/$base.sha256" 2>/dev/null)
    got=$(sha_of "$f")
    [ "$want" = "$got" ] && continue
    if [ -f "$MIRROR/$base" ] && [ "$(sha_of "$MIRROR/$base")" = "$want" ]; then
      cp -f "$MIRROR/$base" "$VAULT/.$base.heal" 2>/dev/null || continue
      mv -f "$VAULT/.$base.heal" "$f" 2>/dev/null || continue
      healed=$((healed+1))
      log "healed $base from mirror"
    else
      log "cannot heal $base (no good mirror)"
    fi
  done
  log "healed $healed archives"
  return 0
}

case "$MODE" in
  mirror) do_mirror ;;
  check) do_check ;;
  heal) do_heal ;;
  all) do_check || do_heal; do_mirror ;;
  *) echo "usage: vault-verify {mirror|check|heal|all}"; exit 2 ;;
esac
exit $?
'''
_V80_READING_SH = r'''#!/bin/bash
# ============================================================
# reading-code-mode (v80) — وضع «قراءة كود» بضغطة واحدة ورجوع فوري.
#   reading-code-mode on    دقة واسعة + خط أكبر + محرر مريح
#   reading-code-mode off   رجوع للإعدادات المحفوطة
#   reading-code-mode       تبديل تلقائي
# لا يُغير أي إعداد من دون حفط القيمة القديمة أولًا (تراجع مضمون).
# ============================================================
set -u
export DISPLAY="${DISPLAY:-:1}"
CFG=/root/.config/colab-desktop
STATE="$CFG/reading-code-state"
SAVED="$CFG/reading-code-saved"
LOG=/tmp/reading-code.log
mkdir -p "$CFG" 2>/dev/null || true
has(){ command -v "$1" >/dev/null 2>&1; }
log(){ printf '%s %s\n' "$(date '+%H:%M:%S')" "$1" >>"$LOG"; }
note(){ local m; m=$(printf '%b' "$1"); if [ -n "${DISPLAY:-}" ] && has notify-send; then notify-send "وضع قراءة الكود" "$m" 2>/dev/null || true; fi; printf '%s\n' "$m"; }

dpi_get(){ has xfconf-query && xfconf-query -c xsettings -p /Xft/DPI 2>/dev/null || echo ""; }
dpi_set(){ has xfconf-query && xfconf-query -c xsettings -p /Xft/DPI -s "$1" 2>/dev/null || true; }

turn_on(){
  local cur
  cur=$(dpi_get)
  [ -n "$cur" ] && printf 'dpi=%s\n' "$cur" > "$SAVED"
  # خط أكبر قليلًا للقراءة دون تكبير مبالغ يقلّل الأسطر المرئية
  dpi_set 118
  if [ -x /usr/local/bin/coding-mode ]; then
    /usr/local/bin/coding-mode >>"$LOG" 2>&1 || true
  fi
  if [ -x /usr/local/bin/window-fitter ]; then
    pkill -USR1 -f window-fitter 2>/dev/null || true
  fi
  echo on > "$STATE"
  log "reading mode on"
  note "تم تفعيل وضع قراءة الكود:\nدقة واسعة + خط أكبر + محاذاة نوافذ داخل الشاشة."
}

turn_off(){
  local d=""
  [ -f "$SAVED" ] && d=$(sed -n 's/^dpi=//p' "$SAVED" | head -n1)
  [ -n "$d" ] && dpi_set "$d"
  if [ -x /usr/local/bin/screen-adapt ] && [ -f "$CFG/screen-geometry" ]; then
    set -- $(tr 'x' ' ' < "$CFG/screen-geometry" | head -n1)
    if [ -n "${1:-}" ] && [ -n "${2:-}" ]; then
      /usr/local/bin/screen-adapt "$1" "$2" >>"$LOG" 2>&1 || true
    fi
  fi
  if [ -x /usr/local/bin/window-fitter ]; then
    pkill -USR1 -f window-fitter 2>/dev/null || true
  fi
  echo off > "$STATE"
  log "reading mode off"
  note "رجعنا للإعدادات المعتادة."
}

case "${1:-toggle}" in
  on) turn_on ;;
  off) turn_off ;;
  toggle)
    if [ "$(cat "$STATE" 2>/dev/null || echo off)" = "on" ]; then turn_off; else turn_on; fi ;;
  *) echo "usage: reading-code-mode {on|off|toggle}" ;;
esac
exit 0
'''
_FIT_NOW_SH = r'''#!/bin/bash
# fit-now (v86) - إرجاع كل النوافذ داخل الشاشة فورًا وتوسيطها
export DISPLAY="${DISPLAY:-:1}"
command -v xdotool >/dev/null 2>&1 || exit 0
command -v wmctrl  >/dev/null 2>&1 || exit 0
WA=$(xprop -root _NET_WORKAREA 2>/dev/null | sed 's/.*= *//; s/,/ /g')
WX=$(printf '%s' "$WA" | awk '{print $1+0}')
WY=$(printf '%s' "$WA" | awk '{print $2+0}')
WW=$(printf '%s' "$WA" | awk '{print $3+0}')
WH=$(printf '%s' "$WA" | awk '{print $4+0}')
if [ "${WW:-0}" -le 0 ] 2>/dev/null; then
  G=$(xdotool getdisplaygeometry 2>/dev/null)
  WX=0; WY=0
  WW=$(printf '%s' "$G" | awk '{print $1+0}')
  WH=$(printf '%s' "$G" | awk '{print $2+0}')
fi
[ "${WW:-0}" -gt 0 ] 2>/dev/null || exit 0
n=0
while read -r WID _REST; do
  case "$WID" in 0x*) ;; *) continue;; esac
  TYPE=$(xprop -id "$WID" _NET_WM_WINDOW_TYPE 2>/dev/null)
  printf '%s' "$TYPE" | grep -q 'DOCK\|DESKTOP\|MENU\|TOOLTIP\|NOTIFICATION' && continue
  wmctrl -i -r "$WID" -b remove,maximized_vert,maximized_horz 2>/dev/null || true
  sleep 0.05
  G=$(xdotool getwindowgeometry --shell "$WID" 2>/dev/null) || continue
  X=$(printf '%s\n' "$G" | awk -F= '$1=="X"{print $2}')
  Y=$(printf '%s\n' "$G" | awk -F= '$1=="Y"{print $2}')
  W=$(printf '%s\n' "$G" | awk -F= '$1=="WIDTH"{print $2}')
  H=$(printf '%s\n' "$G" | awk -F= '$1=="HEIGHT"{print $2}')
  case "$X$Y$W$H" in ''|*[!0-9-]*) continue;; esac
  MW=$((WW - 16)); MH=$((WH - 24))
  NW="$W"; NH="$H"
  [ "$W" -gt "$MW" ] 2>/dev/null && NW="$MW"
  [ "$H" -gt "$MH" ] 2>/dev/null && NH="$MH"
  NX=$((WX + (WW - NW) / 2)); NY=$((WY + (WH - NH) / 2))
  [ "$NX" -lt "$WX" ] && NX="$WX"
  [ "$NY" -lt "$WY" ] && NY="$WY"
  xdotool windowsize "$WID" "$NW" "$NH" 2>/dev/null || true
  xdotool windowmove "$WID" "$NX" "$NY" 2>/dev/null || true
  sleep 0.15
  G2=$(xdotool getwindowgeometry --shell "$WID" 2>/dev/null) || continue
  W2=$(printf '%s\n' "$G2" | awk -F= '$1=="WIDTH"{print $2}')
  H2=$(printf '%s\n' "$G2" | awk -F= '$1=="HEIGHT"{print $2}')
  case "$W2$H2" in ''|*[!0-9-]*) continue;; esac
  if [ "$W2" -gt "$MW" ] 2>/dev/null || [ "$H2" -gt "$MH" ] 2>/dev/null; then
    wmctrl -i -r "$WID" -e "0,$NX,$NY,$NW,$NH" 2>/dev/null || true
    sleep 0.15
    G2=$(xdotool getwindowgeometry --shell "$WID" 2>/dev/null) || continue
    W2=$(printf '%s\n' "$G2" | awk -F= '$1=="WIDTH"{print $2}')
    case "$W2" in ''|*[!0-9-]*) continue;; esac
    if [ "$W2" -gt "$MW" ] 2>/dev/null; then
      wmctrl -i -r "$WID" -b remove,maximized_vert,maximized_horz 2>/dev/null || true
      wmctrl -i -r "$WID" -e "0,$NX,$NY,$NW,$NH" 2>/dev/null || true
    fi
  fi
  n=$((n+1))
done < <(wmctrl -l 2>/dev/null)
exit 0

'''


