# ------------------------------------------------------------
# أي تعديل مستقبلي يحذف أحد هذه الشروط سيطبع تحذيرًا واضحًا عند الإقلاع،
# لأنّ حذف أيّ منها أعاد مشكلة «زر الحذف لا يعمل + الكتابة بطيئة» مرتين من قبل.
# ============================================================
_KB_INVARIANTS = (
    ("var _KB_PAD=new Array(25).join('_');",
     "حشو الحقل المخفي (شرط عمل زر الحذف)"),
    ("_ensureKbPad(inp,true);",
     "إعادة الحشو بعد كل تفريغ"),
    ("case 'deleteContentBackward':",
     "تحويل حدّ الحذف إلى مفتاح Backspace حقيقي"),
    ("inp.addEventListener('keydown',function(e){",
     "المسار الاحتياطي للحذف"),
    ("if(b>4096)return 14;return 28;",
     "دفعة الإرسال السريعة"),
    ("if(_rfbBufferedAmount(rfb)>98304)",
     "حماية الازدحام (منع سقوط الأحرف)"),
    ("function kbSelfTest(){",
     "زر فحص الكيبورد"),
)
_KB_FORBIDDEN = (("try{inp.value=" + chr(39) * 2 + ";}catch(_e){}shadow="
                  + chr(39) * 2 + ";"),)


def _kb_invariants_check():
    """يتأكد أن إصلاح الكيبورد موجود في هذه النسخة قبل نشر الرابط."""
    try:
        with open(__file__, encoding="utf-8", errors="replace") as f:
            body = f.read()
    except Exception:
        return True
    missing = [d for t, d in _KB_INVARIANTS if t not in body]
    present_bad = [t for t in _KB_FORBIDDEN if t in body]
    if not missing and not present_bad:
        print("[✅] فحص الكيبورد: زر الحذف والكتابة السريعة محميان بكل الشروط ✅")
        return True
    if missing:
        print("[⚠️] تحذير الكيبورد: نقص %d شرطًا (%s) — زر الحذف أو السرعة قد يتأذّران."
              % (len(missing), "، ".join(missing)))
    if present_bad:
        print("[⚠️] تحذير الكيبورد: أُعيد تفريغ الحقل المخفي — وهو سبب تعطّل زر الحذف.")
    try:
        _diag_event("kb_invariants_missing")
    except Exception:
        pass
    return False


def _text_health_check():
    """فحص سلامة النصوص: يحذّر (ولا يوقف شيئًا) إن وُجد حرف تالف في نص مرئي."""
    try:
        with open(__file__, encoding="utf-8", errors="replace") as f:
            bad = 0
            for line in f:
                if "\ufffd" in line and not line.lstrip().startswith("#"):
                    bad += 1
            if bad:
                print("[i] فحص النصوص: %d سطرًا يحتاج مراجعة (لا تأثير على العمل)." % bad)
            else:
                print("[✅] فحص النصوص: كل النصوص المرئية سليمة.")
    except Exception:
        pass


