# v71) تشغيل Keep Alive مع ظهور الرابط + تحميل ملف��ت Android Studio
# ============================================================
_ANDROID_SDK_WARMUP_SH = r"""#!/bin/bash
# تجهيز ملفات Android الأساسية (SDK) في الخلفية دون تعطيل أي شيء.
set -u
SDK=/root/Android/Sdk
LOG=/tmp/android-sdk-warmup.log
MARK="$SDK/.colab-warmup-done"
exec >>"$LOG" 2>&1
echo "== $(date '+%H:%M:%S') بدء تجهيز ملفات Android SDK =="
if [ -f "$MARK" ]; then echo "جاهز مسبقًا"; exit 0; fi
mkdir -p "$SDK" /root/Projects/AndroidStudio /root/.android 2>/dev/null
JDK=""
for c in /opt/android-studio/jbr /opt/android-studio/jre /usr/lib/jvm/java-17-openjdk-amd64 /usr/lib/jvm/default-java; do
  [ -x "$c/bin/java" ] && JDK="$c" && break
done
if [ -z "$JDK" ]; then echo "لم تكتمل بيئة Java بعد — نعيد المحاولة لاحقًا"; exit 3; fi
export JAVA_HOME="$JDK" PATH="$JDK/bin:$PATH" ANDROID_HOME="$SDK" ANDROID_SDK_ROOT="$SDK"
CLT="$SDK/cmdline-tools/latest"
if [ ! -x "$CLT/bin/sdkmanager" ]; then
  URL=https://dl.google.com/android/repository/commandlinetools-linux-11076708_latest.zip
  ZIP=/tmp/android-clt.zip
  rm -f "$ZIP"
  curl -fL --retry 4 --retry-delay 4 --connect-timeout 25 -o "$ZIP" "$URL" || { echo "تعذر تنزيل cmdline-tools"; exit 4; }
  rm -rf /tmp/android-clt-x; mkdir -p /tmp/android-clt-x
  if command -v unzip >/dev/null 2>&1; then unzip -q "$ZIP" -d /tmp/android-clt-x
  else python3 -c "import zipfile,sys;zipfile.ZipFile(sys.argv[1]).extractall(sys.argv[2])" "$ZIP" /tmp/android-clt-x; fi
  [ -d /tmp/android-clt-x/cmdline-tools ] || { echo "أرشيف cmdline-tools غير متوقع"; exit 5; }
  mkdir -p "$SDK/cmdline-tools"; rm -rf "$CLT"
  mv /tmp/android-clt-x/cmdline-tools "$CLT" || { echo "تعذر تركيب cmdline-tools"; exit 6; }
  chmod -R +x "$CLT/bin" 2>/dev/null || true
  rm -f "$ZIP"; rm -rf /tmp/android-clt-x
fi
yes 2>/dev/null | "$CLT/bin/sdkmanager" --sdk_root="$SDK" --licenses >/dev/null 2>&1 || true
OK=1
for p in "platform-tools" "platforms;android-34" "build-tools;34.0.0"; do
  echo "-- تنزيل $p"
  "$CLT/bin/sdkmanager" --sdk_root="$SDK" --install "$p" >/dev/null 2>&1 || { echo "تعذر $p — نكمل"; OK=0; }
done
[ "$OK" = "1" ] && touch "$MARK"
echo "== انتهى تجهيز Android SDK (ok=$OK) =="
exit 0
"""
try:
    with open("/tmp/android-sdk-warmup", "w", encoding="utf-8") as _f:
        _f.write(_ANDROID_SDK_WARMUP_SH)
    run("sudo cp /tmp/android-sdk-warmup /usr/local/bin/android-sdk-warmup && "
        "sudo chmod +x /usr/local/bin/android-sdk-warmup")
except Exception as _exc:
    _diag_event("android_sdk_warmup_install", _exc, "warning")

def _android_files_warmup_boot():
    """ينزّل ملفات Android Studio/SDK مع التشغيل في خيط خلفي تمامًا.

    لا يمسّ مسار الإقلاع ولا الرابط: ينتظر انتهاء تثبيت التطبيقات
    الكبيرة (لأن sdkmanager يحتاج JDK المرفق مع Android Studio) ثم يعمل مرة
    واحدة، وأي فشل يُسجّل فقط ولا يوقف شيئًا.
    """
    try:
        try:
            _APP_INSTALL_DONE.wait(2700)
        except Exception:
            pass
        _deadline = time.time() + 900
        while time.time() < _deadline:
            if any(os.path.exists(p) for p in ("/opt/android-studio/jbr/bin/java",
                                               "/opt/android-studio/jre/bin/java")):
                break
            time.sleep(10)
        for _try in (1, 2):
            try:
                _rc = subprocess.run(["/usr/local/bin/android-sdk-warmup"], timeout=3300).returncode
                if _rc != 0:
                    _diag_event("android_sdk_warmup_exit_%d" % _rc, None, "warning")
            except Exception as _exc:
                _diag_event("android_sdk_warmup_run", _exc, "warning")
                return
            if os.path.exists("/root/Android/Sdk/.colab-warmup-done"):
                print("[OK] ملفات Android Studio والـSDK جاهزة (تمّ تنزيلها مع التشغيل) ✅", flush=True)
                return
            if _try == 1:
                time.sleep(90)
        print("[i] تجهيز ملفات Android لم يكتمل بعد — السجل: /tmp/android-sdk-warmup.log ✅", flush=True)
    except Exception as _outer:
        _diag_event("android_files_warmup", _outer, "warning")


# ------------------------------------------------------------
# حارس Keep Alive على مستوى النظام (طبقة ثانية مستقلة عن الإضافة)
#
# لماذا نحتاجه؟ لأن أحداث الجافاسكربت غير موثوقة (isTrusted=false)،
# فإن أردنا أقوى منع للخمول فلا بدّ من إدخال حقيقي عبر XTEST.
# ال��مان: لا نرسل أي إدخال إلا إن كانت نافذة Colab هي النشطة فعلًا،
# والمفتاح المُرسل محايد (Shift وحده) فلا يكتب ولا يُنفّذ أي خلية،
# ولا نلمس الماوس إلا بإزاحة بكسل واحد ثم نرجعه فورًا.
# وإن لم تكن نافذة Colab هي النشطة فالحارس يسكت تمامًا فلا يقاطع عملك.
# ------------------------------------------------------------
_KEEPALIVE_GUARD_SH = r'''#!/bin/bash
# حارس منع خمول Colab — طبقة نظام خفيفة جدًا.
export DISPLAY="${DISPLAY:-:1}"
export HOME=/root
export XAUTHORITY=/root/.Xauthority
LOG=/tmp/colab-keepalive-guard.log
COLAB_URL="https://colab.research.google.com/"
PERIOD="${1:-150}"
case "$PERIOD" in ''|*[!0-9]*) PERIOD=150;; esac
[ "$PERIOD" -lt 60 ] && PERIOD=60
[ "$PERIOD" -gt 600 ] && PERIOD=600
LAST_RELAUNCH=0
log(){ printf '%s %s\n' "$(date +%H:%M:%S)" "$1" >> "$LOG" 2>/dev/null; }
# منع أكثر من نسخة واحدة
exec 9>/tmp/.colab-keepalive-guard.lock 2>/dev/null || true
if command -v flock >/dev/null 2>&1; then flock -n 9 || { log "guard already running"; exit 0; }; fi
log "guard started period=${PERIOD}s"
has_colab_window(){ xdotool search --name "Colab" 2>/dev/null | head -1; }
active_is_colab(){
  local id name
  id=$(xdotool getactivewindow 2>/dev/null) || return 1
  [ -n "$id" ] || return 1
  name=$(xdotool getwindowname "$id" 2>/dev/null)
  case "$name" in *Colab*|*colab*) return 0;; *) return 1;; esac
}
while true; do
  sleep "$PERIOD"
  if ! command -v xdotool >/dev/null 2>&1; then log "xdotool missing"; continue; fi
  WIN=$(has_colab_window)
  if [ -z "$WIN" ]; then
    # v86: لا إعادة فتح تلقائية نهائيًّا — نافذة Colab تُفتَح مرة واحدة عند الإقلاع فقط.
    log "colab window missing -> skip (auto-relaunch disabled)"
    continue
  fi
  if active_is_colab; then
    # إدخال حقيقي محايد تمامًا عبر XTEST
    xdotool key --clearmodifiers shift >/dev/null 2>&1
    xdotool mousemove_relative --sync -- 1 0 >/dev/null 2>&1
    xdotool mousemove_relative --sync -- -1 0 >/dev/null 2>&1
    log "trusted pulse sent"
  else
    log "skip (colab not focused)"
  fi
done
'''


def _write_keepalive_guard():
    """يكتب حارس النشاط إلى /usr/local/bin ويجعله قابلًا للتنفيذ."""
    try:
        Path("/tmp/colab-keepalive-guard").write_text(_KEEPALIVE_GUARD_SH, encoding="utf-8")
        run("sudo cp /tmp/colab-keepalive-guard /usr/local/bin/colab-keepalive-guard && "
            "sudo chmod +x /usr/local/bin/colab-keepalive-guard")
        return os.access("/usr/local/bin/colab-keepalive-guard", os.X_OK)
    except Exception as _exc:
        _diag_event("keepalive_guard_write", _exc, "warning")
        return False


def _power_terminal_tools_boot():
    """يثبت طقم أدوات لينكس الكامل خلفياً ثم يشغل الفحص الشامل مرة واحدة."""
    try:
        if not _POWER_TERMINAL_READY:
            return
        time.sleep(45)
        os.makedirs(os.path.dirname(_TERM_TOOLS_MARK), exist_ok=True)
        if not os.path.exists(_TERM_TOOLS_MARK):
            _env = dict(os.environ, DEBIAN_FRONTEND="noninteractive")
            try:
                subprocess.run(["apt-get", "update", "-qq"], env=_env,
                               timeout=600, stdout=subprocess.DEVNULL,
                               stderr=subprocess.DEVNULL)
            except Exception:
                pass
            _pkgs = list(_TERM_TOOL_PACKAGES)
            try:
                _np = open("/root/.config/colab-desktop/net-profile").read().strip()
            except Exception:
                _np = "saver"
            if _np != "full" and os.environ.get("TERM_TOOLS_FULL", "0") != "1":
                # v78: في وضع توفير الباقة نكتفي بأدوات صغيرة جداً وأساسية
                _pkgs = ["zip", "unzip", "tmux", "htop", "jq", "tree", "lsof", "less",
                         "file", "bash-completion"]
            _missing = []
            for _pkg in _pkgs:
                try:
                    _r = subprocess.run(["dpkg-query", "-W", "-f=${Status}", _pkg],
                                        capture_output=True, text=True, timeout=30)
                    if "install ok installed" in (_r.stdout or ""):
                        continue
                except Exception:
                    pass
                _missing.append(_pkg)
            _ok_all = True
            if _missing and _np != "full" and os.environ.get("TERM_TOOLS_FULL", "0") != "1":
                _diag_event("term_tools_saver_subset")
            if _missing:
                _cmd = ["apt-get", "install", "-y", "--no-install-recommends",
                        "-o", "DPkg::Lock::Timeout=600"] + _missing
                try:
                    _r = subprocess.run(_cmd, env=_env, timeout=2400,
                                        stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
                    _ok_all = (_r.returncode == 0)
                except Exception:
                    _ok_all = False
                if not _ok_all:
                    # تراجع أمن: تثبيت كل حزمة على حدة حتى لا تفشل الدفعة كلها
                    for _pkg in _missing:
                        try:
                            subprocess.run(["apt-get", "install", "-y",
                                            "--no-install-recommends",
                                            "-o", "DPkg::Lock::Timeout=600", _pkg],
                                           env=_env, timeout=420,
                                           stdout=subprocess.DEVNULL,
                                           stderr=subprocess.DEVNULL)
                        except Exception:
                            pass
            try:
                with open(_TERM_TOOLS_MARK, "w") as _f:
                    _f.write(time.strftime("%Y-%m-%d %H:%M:%S"))
            except Exception:
                pass
            _diag_event("term_tools_installed")
            try:
                _persist_now("terminal-tools")
            except Exception:
                pass
        # فحص ذاتي شامل (لا يغير شيئاً في النطام) وتقرير على سطح المكتب
        try:
            _env2 = dict(os.environ, DISPLAY=DISPLAY_NUM,
                         REPORT="/root/Desktop/terminal-test-report.txt")
            with open("/tmp/linux-power-test.log", "a") as _lf:
                subprocess.run(["/usr/local/bin/linux-power-test"], env=_env2,
                               timeout=900, stdout=_lf, stderr=_lf)
            _diag_event("term_selftest_done")
        except Exception as exc:
            _diag_event("term_selftest_failed", exc, "warning")
    except Exception as exc:
        _diag_event("term_tools_boot_failed", exc, "warning")


def _download_installer_watch_boot():
    """يشغّل مراقب التنزيلات بعد جاهزية جلسة سطح المك��ب.

    وظيفته: ��تى اكتمل تنزيل برنامج من المتصفح يسألك مباشرة هل تريد
    تثبيته، ولا يفعل شيئًا إلا بموافقتك. لا يلمس الملفات القديمة إطلاقًا.
    """
    try:
        if not _LINUX_APP_INSTALLER_READY:
            return
        if not os.access("/usr/local/bin/download-install-watch", os.X_OK):
            return
        _deadline = time.time() + 480
        while time.time() < _deadline:
            try:
                if _xfce_session_live(True):
                    break
            except Exception:
                pass
            time.sleep(5)
        else:
            return
        time.sleep(10)
        subprocess.run(
            "setsid /usr/local/bin/download-install-watch "
            ">>/tmp/download-install-watch.log 2>&1 &",
            shell=True, timeout=30,
            env=dict(os.environ, DISPLAY=DISPLAY_NUM, HOME="/root",
                     XAUTHORITY="/root/.Xauthority"))
        _diag_event("download_watch_start", None, "info")
    except Exception as _exc:
        _diag_event("download_watch_boot", _exc, "warning")


def _colab_keepalive_autostart():
    """يُشغّل Chrome الأصلي على تبويب Colab مرة واحدة بعد جاهزية الرابط.

    وبذلك تبدأ إضافة Keep Alive عملها فورًا دون تدخّل منك. ولأن الإضافة
    مُحمّلة في chrome-root فقط، فلن تمسّ أي ملف من ملفات نوافذ «العمل».
    """
    try:
        if not _KEEPALIVE_READY:
            return
        _live = False
        _deadline = time.time() + 480
        while time.time() < _deadline:
            try:
                if _xfce_session_live(True):
                    _live = True
                    break
            except Exception:
                pass
            time.sleep(4)
        if not _live:
            print("[i] تأجل تشغيل Keep Alive: لم تجهز جلسة سطح المكتب — افتح Chrome يدويًا وستعمل تلقائيًا ✅", flush=True)
            return
        time.sleep(8)
        if not os.path.isfile("/usr/local/bin/chrome-root"):
            return
        try:
            subprocess.run(
                "setsid /usr/local/bin/chrome-root https://colab.research.google.com/ "
                ">/tmp/colab-keepalive-launch.log 2>&1 &",
                shell=True, timeout=45,
                env=dict(os.environ, DISPLAY=DISPLAY_NUM, HOME="/root",
                         XAUTHORITY="/root/.Xauthority"))
            print("[OK] شغّلنا Chrome الأصلي على تبويب Colab — إضافة Keep Alive تعمل الآن ✅", flush=True)
        except Exception as _exc:
            _diag_event("keepalive_launch", _exc, "warning")
        # طبقة ثانية: حارس نشاط حقيقي على مستوى النظام (نبض فقط — لا يعيد فت�� النافذة إن أُغلقت)
        try:
            if _write_keepalive_guard():
                subprocess.run(
                    "setsid /usr/local/bin/colab-keepalive-guard 150 "
                    ">>/tmp/colab-keepalive-guard.log 2>&1 &",
                    shell=True, timeout=30,
                    env=dict(os.environ, DISPLAY=DISPLAY_NUM, HOME="/root",
                             XAUTHORITY="/root/.Xauthority"))
                print("[OK] حارس منع الخمول يعمل أيضًا (طبقة ثانية مستقلة) ✅", flush=True)
        except Exception as _gexc:
            _diag_event("keepalive_guard_start", _gexc, "warning")
    except Exception as _outer:
        _diag_event("keepalive_autostart", _outer, "warning")

try:
    if not STABILITY_FIRST:
        threading.Thread(target=_colab_keepalive_autostart, name="keepalive-autostart", daemon=True).start()
        threading.Thread(target=_download_installer_watch_boot, name="download-install-watch", daemon=True).start()
        print("[طرفية] الطرفية القياسية جاهزة؛ تجهيز الأدوات والفحص الشامل يدويان لتجنب حمل الإقلاع ✅")
        threading.Thread(target=_android_files_warmup_boot, name="android-files-warmup", daemon=True).start()
    else:
        print("[صيانة] لم تُفتح نافذة Colab ثانية ولم تبدأ مراقبات Downloads/Android تلقائيًا ✅")
except Exception as _exc:
    _diag_event("v71_boot_threads", _exc, "warning")

