# ============================================================
# v70) تأقلم دقيق مع دوران الهاتف (عمودي/أفقي) بلا أشرطة سوداء
# ============================================================
# السبب الجذري للمشكلة: دقة سطح المكتب كانت ثابتة (800×1280) والغلاف
# يلائمها داخل الشاشة بالتصغير؛ ومتى اختلفت نسبة العرض إلى الارتفاع
# عن نسبة الهاتف (وهي تختلف دائمًا: 20:9 عموديًا و 9:20 أفقيًا) تظهر
# أشرطة سوداء ويصغر سطح المكتب. الحل الجذري: دقة حقيقية ديناميكية
# تُطابق نسبة شاشة الهاتف تمامًا عند كل دوران، ثم إعادة ملاءمة كل
# النوافذ داخل مساحة العمل الجديدة (فلا يُقطع أي طرف).
# المساحة الكلية (عدد البكسلات) تبقى شبه ثابتة فلا يزيد الاستهلاك.
screen_adapt_sh = r"""#!/bin/bash
export DISPLAY="${DISPLAY:-:1}" HOME=/root XAUTHORITY=/root/.Xauthority
W="$1"; H="$2"
case "${W}${H}" in ''|*[!0-9]*) echo "bad-args"; exit 2;; esac
[ "$W" -ge 480 ] && [ "$H" -ge 480 ] || { echo "too-small"; exit 2; }
[ "$W" -le 2560 ] && [ "$H" -le 2560 ] || { echo "too-big"; exit 2; }

STATE_DIR=/root/.config/colab-desktop
mkdir -p "$STATE_DIR" 2>/dev/null

out_name(){ xrandr 2>/dev/null | awk '/ connected/{print $1;exit}'; }
cur_geo(){ xdotool getdisplaygeometry 2>/dev/null | tr ' ' 'x'; }

O="$(out_name)"
CUR="$(cur_geo)"
[ "$CUR" = "${W}x${H}" ] && { echo "same ${W}x${H}"; exit 0; }

OK=""
# (1) نمط موجود مسبقًا
if [ -n "$O" ] && xrandr --output "$O" --mode "${W}x${H}" >/dev/null 2>&1; then OK=1; fi
# (2) إنشاء نمط جديد بـ cvt (المسار المعتمد مع Xvnc/KasmVNC)
if [ -z "$OK" ] && [ -n "$O" ] && command -v cvt >/dev/null 2>&1; then
  ML=$(cvt "$W" "$H" 60 2>/dev/null | grep Modeline | sed 's/^ *Modeline *//')
  if [ -n "$ML" ]; then
    NAME=$(echo "$ML" | awk '{print $1}' | tr -d '\"')
    REST=$(echo "$ML" | cut -d' ' -f2-)
    xrandr --newmode "$NAME" $REST >/dev/null 2>&1
    xrandr --addmode "$O" "$NAME" >/dev/null 2>&1
    xrandr --output "$O" --mode "$NAME" >/dev/null 2>&1 && OK=1
  fi
fi
# (3) احتياطي: قائمة الأنماط الجاهزة
if [ -z "$OK" ]; then xrandr -s "${W}x${H}" >/dev/null 2>&1 && OK=1; fi
# (4) احتياطي أخير: تغيير حجم الإطار مباشرة
if [ -z "$OK" ]; then xrandr --fb "${W}x${H}" >/dev/null 2>&1 && OK=1; fi

NEW="$(cur_geo)"
if [ "$NEW" != "${W}x${H}" ]; then
  echo "failed cur=$NEW want=${W}x${H}"
  exit 4
fi
echo "${W}x${H}" > "$STATE_DIR/screen-geometry" 2>/dev/null

# ---- إعادة ملاءمة كل النوافذ داخل مساحة العمل الجديدة ----
# أولًا ننتطر لحظة حتى يحدّث xfwm4/الشريط مساحة العمل (_NET_WORKAREA).
sleep 1
read_workarea(){
  xprop -root _NET_WORKAREA 2>/dev/null | sed 's/.*= *//' | tr -d ' ' | cut -d, -f1-4
}
WA="$(read_workarea)"
WAX=$(echo "$WA" | cut -d, -f1); WAY=$(echo "$WA" | cut -d, -f2)
WAW=$(echo "$WA" | cut -d, -f3); WAH=$(echo "$WA" | cut -d, -f4)
case "${WAX}${WAY}${WAW}${WAH}" in ''|*[!0-9]*) WAX=0; WAY=0; WAW="$W"; WAH="$H";; esac
[ "$WAW" -gt 0 ] 2>/dev/null || WAW="$W"
[ "$WAH" -gt 0 ] 2>/dev/null || WAH="$H"

SKIP='xfdesktop|xfce4-panel|Desktop|xfwm4'
if command -v wmctrl >/dev/null 2>&1; then
  wmctrl -l -x 2>/dev/null | while read -r WID DESK CLS REST; do
    echo "$CLS" | grep -Eiq "$SKIP" && continue
    TYPE=$(xprop -id "$WID" _NET_WM_WINDOW_TYPE 2>/dev/null || true)
    STATE=$(xprop -id "$WID" _NET_WM_STATE 2>/dev/null || true)
    TRANS=$(xprop -id "$WID" WM_TRANSIENT_FOR 2>/dev/null || true)
    # لا تستثن الحوارات أو النوافذ التابعة: هي أكثر ما يتجاوز حد الهاتف.
    # تُعامل كأي نافذة مرئية، مع إزالة حالة التكبير فقط عند الحاجة إلى التقليم.
    wmctrl -i -r "$WID" -b remove,maximized_vert,maximized_horz 2>/dev/null
    FW=$((WAW>16 ? WAW-12 : WAW)); FH=$((WAH>20 ? WAH-12 : WAH))
    FX=$((WAX+6)); FY=$((WAY+6))
    xdotool windowsize "$WID" "$FW" "$FH" 2>/dev/null
    xdotool windowmove "$WID" "$FX" "$FY" 2>/dev/null
  done
fi

# تنبيه حارس الملاءمة ليراجع الحدود فورًا (يعمل دوريًا أصلاً)
pkill -USR1 -f window-fitter 2>/dev/null
# إعادة ترتيب أيقونات سطح المكتب على القياس الجديد (بلا إعادة تشغيل الجلسة)
xdotool search --onlyvisible --class xfdesktop 2>/dev/null | head -1 >/dev/null 2>&1
echo "ok ${W}x${H} workarea=${WAW}x${WAH}"
exit 0
"""
with open("/tmp/screen-adapt", "w") as f:
    f.write(screen_adapt_sh)
run("sudo cp /tmp/screen-adapt /usr/local/bin/screen-adapt && "
    "sudo chmod +x /usr/local/bin/screen-adapt")
print("[OK] التأقلم مع دوران الهاتف: سطح المكتب يملأ الشاشة عموديًا وأفقيًا ✅")

# ============================================================
# v69) code-server: محرّر VS Code في المتصفح برابط مستقل
# ============================================================
# لماذا: الكتابة داخل VNC تمرّ عبر صورة؛ أمّا code-server فهو نصّ HTML
# حقيقي → كيبورد الهاتف والتحديد والتكبير تعمل طبيعيًا، والاستهلاك أقل
# بكثير من بثّ الشاشة. يعمل على نفس ملفات /root/Projects المحمية على Drive.
# كل شيء يجري في خيط خلفي بعد نشر رابط سطح المكتب، فلا يؤخّر الإقلاع أبدًا.
CODE_PORT = find_free_port(8890)
CODE_PASSWORD = hashlib.sha256(
    (REMOTE_ACCESS_TOKEN + "code-server").encode("utf-8")).hexdigest()[:14]
CODE_LINK_FILE = "/tmp/code_link.txt"
code_public_url = ""


def _code_server_installed():
    return os.path.exists("/usr/bin/code-server") or os.path.exists(
        "/usr/local/bin/code-server")


def _code_server_install():
    if _code_server_installed():
        return True
    run("curl -fsSL https://code-server.dev/install.sh -o /tmp/cs-install.sh",
        timeout=180)
    if not os.path.exists("/tmp/cs-install.sh"):
        return False
    run("bash /tmp/cs-install.sh >/tmp/code-server-install.log 2>&1", timeout=900)
    return _code_server_installed()


def _code_server_config():
    cfg = "/root/.config/code-server/config.yaml"
    os.makedirs(os.path.dirname(cfg), exist_ok=True)
    with open(cfg, "w") as f:
        f.write("bind-addr: 127.0.0.1:%d\nauth: password\npassword: %s\n"
                "cert: false\ndisable-telemetry: true\n"
                "disable-update-check: true\n" % (CODE_PORT, CODE_PASSWORD))
    os.makedirs("/root/Projects", exist_ok=True)


def _code_server_running():
    try:
        with socket.create_connection(("127.0.0.1", CODE_PORT), timeout=2):
            return True
    except Exception:
        return False


def _code_server_start():
    if _code_server_running():
        return True
    run("setsid nohup /usr/bin/code-server --disable-workspace-trust "
        "/root/Projects >/tmp/code-server.log 2>&1 < /dev/null &")
    for _ in range(40):
        if _code_server_running():
            return True
        time.sleep(1.5)
    return False


def _code_tunnel_once():
    """يفتح نفق Cloudflare مستقلًا لـ code-server ويعيد الرابط."""
    global code_public_url
    log = "/tmp/cloudflared-code.log"
    run("rm -f %s" % log)
    if not os.path.exists("/tmp/cloudflared"):
        return ""
    proc = subprocess.Popen(
        ["/tmp/cloudflared", "tunnel", "--no-autoupdate", "--protocol", "http2",
         "--retries", "5", "--logfile", log,
         "--url", "http://127.0.0.1:%d" % CODE_PORT],
        stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
        preexec_fn=os.setsid)
    url = ""
    for _ in range(80):
        time.sleep(2)
        try:
            txt = open(log, "r", errors="ignore").read()
        except Exception:
            txt = ""
        m = re.search(r"https://[a-z0-9-]+\.trycloudflare\.com", txt)
        if m:
            url = m.group(0)
            break
        if proc.poll() is not None:
            break
    if url:
        code_public_url = url
        try:
            with open(CODE_LINK_FILE, "w") as f:
                f.write(url + "\n")
        except Exception:
            pass
    return url


def code_server_loop():
    """تجهيز وتشغيل وإصلاح ذاتي دائم لمحرر المتصفح."""
    try:
        if not _code_server_install():
            print("[i] تعذّر تجهيز محرر المتصفح — سطح المكتب يعمل طبيعيًا.", flush=True)
            return
        _code_server_config()
        if not _code_server_start():
            print("[i] محرر المتصفح لم يبدأ بعد — تُعاد المحاولة تلقائيًا.", flush=True)
        for _ in range(6):
            if os.path.exists("/tmp/cloudflared"):
                break
            time.sleep(10)
        url = _code_tunnel_once()
        if url:
            print("", flush=True)
            print("[💻 محرر الكود في المتصفح] الرابط: %s" % url, flush=True)
            print("    كلمة المرور: %s" % CODE_PASSWORD, flush=True)
            print("    يفتح مجلد /root/Projects نفسه المحمي على Drive — كيبورد الهاتف يعمل فيه طبيعيًا ✅", flush=True)
        while True:
            time.sleep(45)
            if not _code_server_running():
                _code_server_start()
            if not code_public_url or not os.path.exists(CODE_LINK_FILE):
                continue
            r = run("pgrep -f 'cloudflared tunnel .*%d' >/dev/null" % CODE_PORT)
            if getattr(r, "returncode", 1) != 0:
                _code_tunnel_once()
    except Exception as exc:
        _diag_event("code_server_loop", exc)


