START_TIME = time.time()

def watchdog():
    """مراقب الخدمات: يعيد تشغيل أي خدمة تسقط (صوت/فيديو/بروكسي)."""
    last = {"audio": 0.0, "kasm": 0.0}
    GRACE = 30
    while True:
        try:
            now = time.time()
            # 1) الصوت
            if now - last["audio"] > GRACE and not proc_running("pulseaudio"):
                start_audio(); last["audio"] = time.time()
            # 2) خادم الفيديو KasmVNC
            if now - last["kasm"] > GRACE and \
               not (proc_running("Xvnc") and port_listening(VNC_PORT)):
                print("[watchdog] إعادة تشغيل خادم سطح المكتب...")
                start_kasm(); last["kasm"] = time.time(); time.sleep(12)
            # 3) بروكسي المصادقة (ضروري للـ WebSocket على الهاتف)
            if port_listening(VNC_PORT) and not port_listening(PROXY_PORT):
                start_auth_proxy()
        except Exception:
            pass
        time.sleep(60)

