def memory_guard():
    """حارس الذاكرة: يمنع تجمّد الجلسة عند امتلاء ا��رام (يحرّر الكاش)."""
    while True:
        try:
            avail = 0
            with open("/proc/meminfo") as mf:
                for ln in mf:
                    if ln.startswith("MemAvailable:"):
                        avail = int(ln.split()[1]) // 1024  # ميجابايت
                        break
            # عتبة أعلى للمتانة طويلة المدى (24 ساعة): نحرّر الكاش مبكرًا
            # قبل أن يقترب النظام من التجمّد، فلا تتوقّف الجلسة أبدًا.
            if 0 < avail < 600:
                run("sync; echo 1 | sudo tee /proc/sys/vm/drop_caches "
                    "> /dev/null 2>&1")
                print("[memory_guard] تحرير الكاش (المتاح %d ميجا)." % avail)
        except Exception:
            pass
        time.sleep(120)

_spawn("memory_guard", memory_guard)


def interaction_priority_guard():
    strikes={}
    critical=('Xvnc','xfwm4','xfce4-session','python','python3','cloudflared','pulseaudio')
    while True:
        try:
            run("renice -n -5 -p $(pgrep -o Xvnc) >/dev/null 2>&1 || true", timeout=3)
            txt=run("ps -eo pid=,comm=,pcpu=,ni= --sort=-pcpu | head -n 8", timeout=4).stdout or ''
            seen=set()
            for ln in txt.splitlines():
                parts=ln.split()
                if len(parts)<4: continue
                pid=int(parts[0]); comm=parts[1]; cpu=float(parts[2]); nice=int(parts[3]); seen.add(pid)
                if comm in critical or cpu<90.0: strikes.pop(pid,None); continue
                strikes[pid]=strikes.get(pid,0)+1
                if strikes[pid]>=3 and nice<7:
                    try: os.setpriority(os.PRIO_PROCESS,pid,7)
                    except Exception: pass
            for pid in list(strikes):
                if pid not in seen: strikes.pop(pid,None)
        except Exception:
            pass
        time.sleep(120)

_spawn("interaction_priority_guard", interaction_priority_guard)

def keep_alive():
    """heartbeat: نشاط دوري داخل سطح المكتب ي��نع خمول/تعتيم الجلسة (كل 30ث).

    مهم جدًّا للبقاء 24 ساعة حتى مع إغلاق المتصفح: ن��لّد نشاط إدخال صامتًا
    (مفتاح + تحريك ��ؤشر بسيط) فيبقى X server والجلسة نشطين ولا يدخلان وضع
    الخمول، ويبقى ناتج الخلية متجدّدًا فلا يوقف Colab الـ kernel.
    """
    n = 0
    while True:
        try:
            # نبضة غير تدخلية: لا ترسل مفاتيح أو حركة ماوس إلى سطح المكتب.
            # إرسال إدخال اصطناعي قد يُفسّر داخل النوافذ النشطة ويؤدي إلى
            # فقدان التركيز أو تنفيذ اختصارات غير مقصودة.
            run("DISPLAY=%s xset q >/dev/null 2>&1" % DISPLAY_NUM)
            n += 1
            if n % 10 == 0:
                hrs = (time.time() - START_TIME) / 3600.0
                print("[♥ نشط] الجلسة تعمل منذ %.1f ساعة — كل شيء يعمل." % hrs)
        except Exception:
            pass
        time.sleep(120)

_spawn("keep_alive", keep_alive)

