# ---------------------------------------------------------------------------
# ⚡ v46 — نظام حفظ ذكي: كشف تغيّر + حفظ أوّلي فور + إيقاع تكيّفي
# ---------------------------------------------------------------------------
# المشكلة سابقًا:
#   1) ملفات تعريف بيئات التطوير الثلاثة تُحفظ كل 60ث دائمًا حتى بلا أي تغيير،
#      وكل عملية قد تصل إلى 320ث على Drive ال��طيء ⇒ الحلة تتراكم وتُثقل النظام
#      وتُبطئ الجلسة كلها (وأحيانًا يتعارض حفظان فيفشل أحدهما).
#   2) أول حفظ لا يحدث إلا بعد 60 ثانية ⇒ لو انقطعت الجلسة في أول دقيقة
#      (شائع جدًّا في Colab) تُفقد كل بيانات تلك الدقيقة.
# الحل: بصمة رخيصة (عدد الملفات + أحدث mtime + مجموع الأحجام) تُخبرنا هل تغيّر
#   شيء فعلًا. بلا تغيير ⇒ نتخطّى النسخ الثقيل تممًا. مع فحص إجباري كل 15 دقيق
#   كشبكة أمان، وحفظ أوّلي بعد 20ث فقط من بدء الحلقة.
_DEV_PROFILE_SAVE_TARGETS = (
    ("antigravity-ide", "/root/.config/Antigravity-IDE",
     "/usr/local/bin/antigravity-ide-profile save "
     ">/tmp/antigravity-ide-periodic-save.log 2>&1 || true", 260),
    ("cursor", "/root/.config/Cursor",
     "/usr/local/bin/dev-app-profile cursor save "
     ">/tmp/cursor-periodic-save.log 2>&1 || true", 320),
    ("android-studio", "/root/.config/Google",
     "/usr/local/bin/dev-app-profile android-studio save "
     ">/tmp/android-studio-periodic-save.log 2>&1 || true", 320),
)
_DEV_PROFILE_FINGERPRINTS = {}
_DEV_PROFILE_FORCE_EVERY = 900          # فحص إجباري كل 15 دقيقة (شبكة أمان)
_DEV_PROFILE_LAST_FORCED = {}
_SAVE_SKIP_STATS = {"skipped": 0, "saved": 0}
# استثناءات الكاش: لا معنى لأن يُبطل الكاش المتغيّر باستمرار كشفَ التغيير
_FP_SKIP_DIRS = {
    "Cache", "CachedData", "Code Cache", "GPUCache", "ShaderCache", "DawnCache",
    "Crashpad", "logs", "CachedExtensionVSIXs", "blob_storage", "GrShaderCache",
    "Service Worker", "IndexedDB", "Local Storage", "Session Storage", "tmp",
}


def _dir_change_fingerprint(root, max_entries=20000):
    """بصمة رخيصة جدًّا لمجلد: (عدد الملفات، أحدث mtime، مجموع الأحجام).

    لا تقرأ محتوى أي ملف (لا SHA) ⇒ أسرع بمئات المرّات من مقارنة فعلية،
    وكافية تمامًا لتقرير «هل يوجد تغيير يستحق الحفظ؟».
    """
    count = 0
    newest = 0.0
    total = 0
    try:
        for dirpath, dirnames, filenames in os.walk(root, topdown=True):
            dirnames[:] = [d for d in dirnames if d not in _FP_SKIP_DIRS]
            for fn in filenames:
                if fn.endswith((".log", ".tmp", "-wal", "-shm", ".lock")):
                    continue
                try:
                    st = os.stat(os.path.join(dirpath, fn))
                except OSError:
                    continue
                count += 1
                total += st.st_size
                if st.st_mtime > newest:
                    newest = st.st_mtime
                if count >= max_entries:
                    return (count, int(newest), total, True)
    except Exception as exc:
        _diag_event("dir_fingerprint", exc)
        return None
    return (count, int(newest), total, False)


def _dev_profile_needs_save(key, path):
    """True إن تغيّر المجلد فعلًا أو حان الفحص الإجباري، بلا تعديل الحالة."""
    if not os.path.isdir(path):
        return False
    fp = _dir_change_fingerprint(path)
    if fp is None:
        return True
    forced = (time.monotonic() - _DEV_PROFILE_LAST_FORCED.get(key, 0.0)
              >= _DEV_PROFILE_FORCE_EVERY)
    return forced or _DEV_PROFILE_FINGERPRINTS.get(key) != fp


def _save_dev_profiles_if_changed():
    """يحفظ الملفات المتغيّرة، ولا يعتمد البصمة إلا بعد نجاح حقيقي للأمر."""
    for key, path, cmd, tmo in _DEV_PROFILE_SAVE_TARGETS:
        try:
            if not _dev_profile_needs_save(key, path):
                _SAVE_SKIP_STATS["skipped"] += 1
                continue
            before_fp = _dir_change_fingerprint(path)
            # أوامر القائمة القديمة تنتهي بـ `|| true`؛ أزله كي يصل رمز الفشل.
            effective_cmd = re.sub(r"\s*\|\|\s*true\s*$", "", cmd)
            result = run(effective_cmd, timeout=tmo)
            if getattr(result, "returncode", 1) != 0:
                _diag_event("dev_profile_save_failed_" + key,
                            RuntimeError("save command failed"), "warning")
                continue
            _DEV_PROFILE_FINGERPRINTS[key] = (
                _dir_change_fingerprint(path) or before_fp)
            _DEV_PROFILE_LAST_FORCED[key] = time.monotonic()
            _SAVE_SKIP_STATS["saved"] += 1
        except Exception as exc:
            _diag_event("dev_profile_save_" + key, exc)


def persist_sync_loop():
    """مزامنة ذكية: /root ⇄ Drive + ملفات بيئات التطوير عند تغيّرها فقط.

    v46: حفظ أوّلي بعد 20ث (كان 60ث) لحماية بيانات أول دقيقة، ثم كل 60ث
    مع تخطّي النسخ الثقيل غير الضروري.
    """
    first = True
    while True:
        try:
            time.sleep(20 if first else 600)
        except Exception:
            return
        try:
            if time.time() < _PERFORMANCE_PAUSE_UNTIL:
                continue
            _persist_now("حفظ أوّلي مبكر (حماية بيانات أول دقيقة) ✅" if first else "")
            _save_dev_profiles_if_changed()
            if first:
                first = False
        except Exception as exc:
            _diag_event("persist_sync_loop", exc)


