# WORKSPACE_100_WINDOWGEOMETRY_V6
# إصلاح هندسة مساحات العمل: يكتب مساعدًا محدودًا ويعدّل مشغّل النوافذ النهائي فقط.
from pathlib import Path as _Workspace100Path
import os as _workspace100_os

_WORKSPACE_100_FIT_SH = '#!/bin/bash\n# يصحح موضع وحجم نوافذ Chrome التابعة لمساحات العمل فقط؛ لا يقتل Chrome ولا يقرأ بياناته.\nset -u\nexport DISPLAY="${DISPLAY:-:1}" XAUTHORITY="${XAUTHORITY:-/root/.Xauthority}"\nworkarea() {\n  local raw geo sw sh\n  raw=$(xprop -root _NET_WORKAREA 2>/dev/null | sed \'s/.*= *//;s/,/ /g\' | awk \'{print $1,$2,$3,$4}\')\n  set -- $raw; X=${1:-0}; Y=${2:-0}; W=${3:-0}; H=${4:-0}\n  geo=$(xdotool getdisplaygeometry 2>/dev/null || true); sw=${geo%% *}; sh=${geo##* }\n  case "$X$Y$W$H" in \'\'|*[!0-9]*) X=0; Y=0; W=${sw:-840}; H=${sh:-1494};; esac\n  [ "$W" -gt 160 ] 2>/dev/null || W=${sw:-840}; [ "$H" -gt 160 ] 2>/dev/null || H=${sh:-1494}\n  SX=$((X + 16)); SY=$((Y + 10)); SW=$((W - 32)); SH=$((H - 28))\n  [ "$SW" -gt 300 ] 2>/dev/null || { SX=$X; SW=$W; }\n  [ "$SH" -gt 300 ] 2>/dev/null || { SY=$Y; SH=$H; }\n}\nbelongs_to_workspace() {\n  local wid="$1" pid cmd\n  pid=$(xprop -id "$wid" _NET_WM_PID 2>/dev/null | awk -F\'= \' \'NF>1{gsub(/ /,"",$2); print $2; exit}\')\n  [ -n "$pid" ] && [ -r "/proc/$pid/cmdline" ] || return 1\n  cmd=$(tr \'\\000\' \' \' < "/proc/$pid/cmdline" 2>/dev/null || true)\n  printf \'%s\' "$cmd" | grep -qE -- \'--user-data-dir=/root/\\.config/google-chrome-work|--user-data-dir=/root/\\.chrome-profiles-local/profile-[0-9]+\'\n}\nfit_one() {\n  local wid="$1" geo x y w h nx ny nw nh hex\n  geo=$(xdotool getwindowgeometry --shell "$wid" 2>/dev/null) || return 0\n  x=$(printf \'%s\\n\' "$geo" | awk -F= \'$1=="X"{print $2}\')\n  y=$(printf \'%s\\n\' "$geo" | awk -F= \'$1=="Y"{print $2}\')\n  w=$(printf \'%s\\n\' "$geo" | awk -F= \'$1=="WIDTH"{print $2}\')\n  h=$(printf \'%s\\n\' "$geo" | awk -F= \'$1=="HEIGHT"{print $2}\')\n  case "$x,$y,$w,$h" in *[!0-9,-]*|,,,*|\'\') return 0;; esac\n  nx=$x; ny=$y; nw=$w; nh=$h\n  [ "$nw" -gt "$SW" ] 2>/dev/null && nw=$SW; [ "$nh" -gt "$SH" ] 2>/dev/null && nh=$SH\n  [ "$nx" -lt "$SX" ] 2>/dev/null && nx=$SX; [ "$ny" -lt "$SY" ] 2>/dev/null && ny=$SY\n  [ $((nx + nw)) -gt $((SX + SW)) ] && nx=$((SX + SW - nw))\n  [ $((ny + nh)) -gt $((SY + SH)) ] && ny=$((SY + SH - nh))\n  [ "$nx,$ny,$nw,$nh" = "$x,$y,$w,$h" ] && return 0\n  hex=$(printf \'0x%x\' "$wid")\n  wmctrl -i -r "$hex" -b remove,maximized_vert,maximized_horz 2>/dev/null || true\n  wmctrl -i -r "$hex" -e "0,$nx,$ny,$nw,$nh" 2>/dev/null || true\n}\nworkarea\nfor wid in $(xdotool search --onlyvisible --name \'\' 2>/dev/null | awk \'/^[0-9]+$/\' | sort -u); do\n  belongs_to_workspace "$wid" && fit_one "$wid"\ndone\n'
_WORKSPACE_100_LAUNCH_HELPER = 'safe_work_geometry() {\n  local geo wa\n  geo=$(xdotool getdisplaygeometry 2>/dev/null || echo "840 1494")\n  sw=$(echo "$geo" | awk \'{print $1}\'); sh=$(echo "$geo" | awk \'{print $2}\')\n  wa=$(xprop -root _NET_WORKAREA 2>/dev/null | sed \'s/.*= //\' | tr -d \',\')\n  wx=$(echo "$wa" | awk \'{print $1}\'); wy=$(echo "$wa" | awk \'{print $2}\')\n  ww=$(echo "$wa" | awk \'{print $3}\'); wh=$(echo "$wa" | awk \'{print $4}\')\n  case "$wx$wy$ww$wh" in \'\'|*[!0-9]*) wx=0; wy=0; ww=${sw:-840}; wh=${sh:-1494};; esac\n  [ "$ww" -gt "$sw" ] 2>/dev/null && ww="$sw"; [ "$wh" -gt "$sh" ] 2>/dev/null && wh="$sh"\n  # --window-size يحدد المحتوى لا إطار X11؛ الهامش يمنع القص في الاتجاهين.\n  [ "$ww" -gt 180 ] 2>/dev/null && { wx=$((wx + 24)); ww=$((ww - 48)); }\n  [ "$wh" -gt 180 ] 2>/dev/null && { wy=$((wy + 16)); wh=$((wh - 54)); }\n  # V29: حجم التطبيق مستقل عن XFCE؛ لا تصغّر Chrome لمجرد أن السطح 720px.\n  scale=1.25\n}\nlaunch_window() {\n  local kind="$1" url="$2" args=()\n  safe_work_geometry\n  if [ "$kind" = "app" ]; then args=(--app="$url"); else args=(--new-window "$url"); fi\n  setsid "$(chrome_bin)" --no-sandbox --disable-dev-shm-usage --password-store=basic \\\n    --no-first-run --no-default-browser-check --class=colab-work --start-maximized \\\n    --user-data-dir="$PROFILE" --window-position="$wx,$wy" --window-size="$ww,$wh" \\\n    --force-device-scale-factor="$scale" --high-dpi-support=1 "${args[@]}" >/dev/null 2>&1 &\n  # تصحيحان قصيران بعد ظهور Chrome لاحتمال إعادة تطبيق أبعاد محفوظة في الملف الشخصي.\n  ( sleep 1; /usr/local/bin/fit-work-windows >/tmp/fit-work-windows.log 2>&1 || true; \\\n    sleep 2; /usr/local/bin/fit-work-windows >/tmp/fit-work-windows.log 2>&1 || true ) &\n}\n'

def _workspace100_atomic(path, body, mode=0o755):
    target = _Workspace100Path(path)
    temporary = _Workspace100Path(path + '.workspace100-geometry-tmp')
    temporary.write_text(body, encoding='utf-8')
    _workspace100_os.chmod(temporary, mode)
    _workspace100_os.replace(temporary, target)

try:
    _workspace100_atomic('/usr/local/bin/fit-work-windows', _WORKSPACE_100_FIT_SH)
    _window_script = _Workspace100Path('/usr/local/bin/genspark-window')
    _window_text = _window_script.read_text(encoding='utf-8')
    _open_anchor = 'open_window() {\n'
    if _window_text.count(_open_anchor) != 1:
        raise RuntimeError('genspark work launcher anchor missing or ambiguous')
    _window_text = _window_text.replace(_open_anchor, _WORKSPACE_100_LAUNCH_HELPER + '\n' + _open_anchor, 1)
    _old_app = 'setsid "$(chrome_bin)" --user-data-dir="$PROFILE" --app="$url" >/dev/null 2>&1 &'
    _old_window = 'setsid "$(chrome_bin)" --user-data-dir="$PROFILE" --new-window "$url" >/dev/null 2>&1 &'
    if _window_text.count(_old_app) != 1 or _window_text.count(_old_window) != 1:
        raise RuntimeError('genspark work launch command anchor missing or ambiguous')
    _window_text = _window_text.replace(_old_app, 'launch_window app "$url"', 1)
    _window_text = _window_text.replace(_old_window, 'launch_window full "$url"', 1)
    _workspace100_atomic('/usr/local/bin/genspark-window', _window_text)
    _launcher = '[Desktop Entry]\nVersion=1.0\nType=Application\nName=إصلاح نوافذ العمل\nComment=إرجاع نوافذ العمل فقط إلى داخل الشاشة\nExec=/usr/local/bin/fit-work-windows\nIcon=preferences-desktop-windows\nTerminal=false\nCategories=Utility;\n'
    _workspace100_atomic('/root/Desktop/إصلاح نوافذ العمل.desktop', _launcher, 0o755)
    _workspace100_os.system("setsid bash -c 'sleep 7; /usr/local/bin/fit-work-windows >/tmp/fit-work-windows.log 2>&1 || true' >/dev/null 2>&1 &")
    print('[OK] أبعاد مساحات العمل 1–100 آمنة ومصحح النوافذ الحالي مفعّل ✅')
except Exception as _workspace100_exc:
    print('[!] لم يكتمل إصلاح أبعاد مساحات العمل: %s' % _workspace100_exc)

# WORKSPACE_100_GENSPARK_LOGIN_V7
# فتح كل مساحة في ملف تعريفها الخاص على رابط الدخول المعطى، بلا إدخال حساب أو تجاوز تحقق.
from pathlib import Path as _WorkspaceLoginPath
import os as _workspacelogin_os

_WORKSPACE_GENSPARK_LOGIN_URL = 'https://login.genspark.ai/'

def _workspace_login_atomic(path, body, mode=0o755):
    target = _WorkspaceLoginPath(path)
    temporary = _WorkspaceLoginPath(path + '.workspace-login-tmp')
    temporary.write_text(body, encoding='utf-8')
    _workspacelogin_os.chmod(temporary, mode)
    _workspacelogin_os.replace(temporary, target)

try:
    _profile_script = _WorkspaceLoginPath('/usr/local/bin/chrome-profile')
    _profile_text = _profile_script.read_text(encoding='utf-8')
    _profile_anchor = 'LOCAL_DIR="$LOCAL_ROOT/profile-$N"'
    if _profile_text.count(_profile_anchor) != 1:
        raise RuntimeError('isolated chrome-profile anchor missing or ambiguous')
    _profile_insert = 'WORKSPACE_GSPARK_LOGIN_URL=' + repr(_WORKSPACE_GENSPARK_LOGIN_URL) + '\n' + 'if [ "$SYNC_ONLY" = "0" ] && [ "$#" -eq 1 ]; then set -- "$N" "$WORKSPACE_GSPARK_LOGIN_URL"; fi\n' + _profile_anchor
    _profile_text = _profile_text.replace(_profile_anchor, _profile_insert, 1)
    _workspace_login_atomic('/usr/local/bin/chrome-profile', _profile_text)
    _menu_script = _WorkspaceLoginPath('/usr/local/bin/genspark-window')
    _menu_text = _menu_script.read_text(encoding='utf-8')
    _open_start = _menu_text.find('cmd_open() {')
    _url_start = _menu_text.find('cmd_url() {', _open_start)
    if _open_start < 0 or _url_start < 0:
        raise RuntimeError('workspace menu command section missing')
    _open_section = _menu_text[_open_start:_url_start]
    if _open_section.count('open_window "$url"') != 1:
        raise RuntimeError('workspace menu launch anchor missing or ambiguous')
    _isolated_launch = 'slot=$((10#$n))\n  exec /usr/local/bin/chrome-profile "$slot" ' + repr(_WORKSPACE_GENSPARK_LOGIN_URL)
    _open_section = _open_section.replace('open_window "$url"', _isolated_launch, 1)
    _menu_text = _menu_text[:_open_start] + _open_section + _menu_text[_url_start:]
    _workspace_login_atomic('/usr/local/bin/genspark-window', _menu_text)
    print('[OK] المساحات 1–100 تفتح رابط Genspark في ملفات تعريف مستقلة ✅')
except Exception as _workspace_login_exc:
    print('[!] لم يكتمل ربط مساحات العمل برابط Genspark: %s' % _workspace_login_exc)

