# WORKSPACE_100_FINAL_LAUNCHER_V9
# هذه الطبقة تعمل بعد كل التهيئة وتُعاد بعد الاستعادة الخلفية عبر v121.
from pathlib import Path as _WorkspaceFinalPath
import os as _workspacefinal_os

_WORKSPACE100_FINAL_MENU_SH = '#!/bin/bash\n# مشغّل العمل النهائي: لا يطلب رابطًا ولا يشارك ملف تعريف بين أي رقمين.\nset -u\nexport DISPLAY="${DISPLAY:-:1}" XAUTHORITY="${XAUTHORITY:-/root/.Xauthority}"\nLOGIN_URL=\'https://login.genspark.ai/\'\nvalid_slot() { case "${1:-}" in 1|[2-9]|[1-9][0-9]|100) return 0;; *) return 1;; esac; }\nfit_later() {\n  ( sleep 1; /usr/local/bin/fit-work-windows >/tmp/fit-work-windows.log 2>&1 || true\n    sleep 2; /usr/local/bin/fit-work-windows >/tmp/fit-work-windows.log 2>&1 || true ) &\n}\nopen_slot() {\n  local n="$1"\n  valid_slot "$n" || { echo \'رقم المساحة يجب أن يكون من 1 إلى 100.\' >&2; return 2; }\n  # chrome-profile يعيد vault-profile-N إلى profile-N قبل إطلاق Chrome ثم يحفظه دوريًا ونهائيًا.\n  setsid /usr/local/bin/chrome-profile "$n" "$LOGIN_URL" >/tmp/workspace-$n-launch.log 2>&1 &\n  fit_later\n}\nchoose_slot() {\n  local n items=() i\n  for i in $(seq 1 100); do items+=("$(printf \'مساحة العمل %03d\' "$i")"); done\n  if command -v zenity >/dev/null 2>&1; then\n    n=$(zenity --list --title=\'العمل — مساحات معزولة\' \\\n      --text=\'اختر مساحة. لكل رقم جلسة Genspark وبيانات Drive مستقلة.\' \\\n      --width=440 --height=620 --column=\'مساحة العمل\' "${items[@]}" 2>/dev/null | grep -oE \'[0-9]{3}\' | head -n1 || true)\n  else\n    printf \'رقم المساحة (1-100): \' >&2; read -r n || return 1\n  fi\n  [ -n "${n:-}" ] || return 0\n  n=$((10#$n)); open_slot "$n"\n}\ncase "${1:-menu}" in\n  menu|choose) choose_slot;;\n  open) open_slot "${2:-}";;\n  1|[2-9]|[1-9][0-9]|100) open_slot "$1";;\n  *) echo \'الاستخدام: genspark-window [menu|open <1-100>|<1-100>]\' >&2; exit 2;;\nesac\n'

def _workspacefinal_atomic(path, body, mode=0o755):
    target = _WorkspaceFinalPath(path)
    temporary = _WorkspaceFinalPath(path + '.workspace-final-tmp')
    temporary.write_text(body, encoding='utf-8')
    _workspacefinal_os.chmod(temporary, mode)
    _workspacefinal_os.replace(temporary, target)

try:
    _workspacefinal_atomic('/usr/local/bin/genspark-window', _WORKSPACE100_FINAL_MENU_SH)
    _work_desktop = '[Desktop Entry]\nVersion=1.0\nType=Application\nName=العمل — مساحات Genspark معزولة\nComment=100 مساحة مستقلة؛ بلا إدخال رابط يدوي\nExec=/usr/local/bin/genspark-window menu\nIcon=internet-web-browser\nTerminal=false\nCategories=Network;\n'
    for _work_entry in ('/root/Desktop/مساحات العمل المعزولة.desktop', '/usr/share/applications/colab-work.desktop'):
        _workspacefinal_atomic(_work_entry, _work_desktop, 0o755)
    print('[OK] مشغّل المساحات النهائي 1–100 ثبت بعد التهيئة والاستعادة؛ لا يوجد مربع رابط يدوي ✅')
except Exception as _workspacefinal_exc:
    print('[!] لم يكتمل تثبيت مشغّل المساحات النهائي: %s' % _workspacefinal_exc)

# GENSPARK_SLOTS_ONLY_V10
# فصل نهائي: chrome-profile لمساحات Chrome الأصلية؛ genspark-slots-engine للفتحات 001–100 فقط.
from pathlib import Path as _GSSlotsPath
import os as _gsslots_os
import re as _gsslots_re

_GENSPARK_SLOTS_ONLY_LOGIN = 'https://login.genspark.ai/'
_GENSPARK_SLOTS_FIT_SH = '#!/bin/bash\n# يحتوى نوافذ GenSpark slot-N فقط داخل مساحة الهاتف؛ لا يلمس Chrome 1–3.\nset -u\nexport DISPLAY="${DISPLAY:-:1}" XAUTHORITY="${XAUTHORITY:-/root/.Xauthority}"\nraw=$(xprop -root _NET_WORKAREA 2>/dev/null | sed \'s/.*= *//;s/,/ /g\' | awk \'{print $1,$2,$3,$4}\')\nset -- $raw; X=${1:-0}; Y=${2:-0}; W=${3:-840}; H=${4:-1494}\ncase "$X$Y$W$H" in \'\'|*[!0-9]*) X=0; Y=0; W=840; H=1494;; esac\nSX=$((X + 18)); SY=$((Y + 10)); SW=$((W - 36)); SH=$((H - 30))\n[ "$SW" -gt 300 ] 2>/dev/null || { SX=$X; SW=$W; }; [ "$SH" -gt 300 ] 2>/dev/null || { SY=$Y; SH=$H; }\nfor wid in $(xdotool search --onlyvisible --name \'\' 2>/dev/null | awk \'/^[0-9]+$/\' | sort -u); do\n  cls=$(xprop -id "$wid" WM_CLASS 2>/dev/null || true)\n  printf \'%s\' "$cls" | grep -qE \'genspark-[0-9]{3}\' || continue\n  geo=$(xdotool getwindowgeometry --shell "$wid" 2>/dev/null || true)\n  x=$(printf \'%s\\n\' "$geo" | awk -F= \'$1=="X"{print $2}\'); y=$(printf \'%s\\n\' "$geo" | awk -F= \'$1=="Y"{print $2}\')\n  w=$(printf \'%s\\n\' "$geo" | awk -F= \'$1=="WIDTH"{print $2}\'); h=$(printf \'%s\\n\' "$geo" | awk -F= \'$1=="HEIGHT"{print $2}\')\n  case "$x,$y,$w,$h" in *[!0-9,-]*|,,,*|\'\') continue;; esac\n  nx=$x; ny=$y; nw=$w; nh=$h\n  [ "$nw" -gt "$SW" ] 2>/dev/null && nw=$SW; [ "$nh" -gt "$SH" ] 2>/dev/null && nh=$SH\n  [ "$nx" -lt "$SX" ] 2>/dev/null && nx=$SX; [ "$ny" -lt "$SY" ] 2>/dev/null && ny=$SY\n  [ $((nx+nw)) -gt $((SX+SW)) ] && nx=$((SX+SW-nw)); [ $((ny+nh)) -gt $((SY+SH)) ] && ny=$((SY+SH-nh))\n  [ "$nx,$ny,$nw,$nh" = "$x,$y,$w,$h" ] && continue\n  hex=$(printf \'0x%x\' "$wid"); wmctrl -i -r "$hex" -b remove,maximized_vert,maximized_horz 2>/dev/null || true\n  wmctrl -i -r "$hex" -e "0,$nx,$ny,$nw,$nh" 2>/dev/null || true\ndone\n'
_GENSPARK_SLOTS_WRAPPER_SH = '#!/bin/bash\n# بوابة نوافذ GenSpark 001–100 فقط.\nexec /usr/local/bin/genspark-slots-engine "$@"\n'

def _gsslots_atomic(path, body, mode=0o755):
    target = _GSSlotsPath(path)
    temporary = _GSSlotsPath(path + '.gsslots-only-tmp')
    temporary.write_text(body, encoding='utf-8')
