# -*- coding: utf-8 -*-
# مقطع الـ FINALIZER الخاص بـ V15 — يُحقن داخل نص FINALIZER في build_derived.py.
# يحوي: مساعد اللوحة الخالد (بلا D-Bus = بلا حوار)، أداة تثبيت أندرويد المرئية،
# وتحديث قوائم الخطوات وسلسلة إعادة الفرض.

# ---- (V15-أ) مساعد إعادة تشغيل اللوحة الخالد --------------------------------
# الجذر الوحيد لحوار «فشلت إعادة تشغيل اللوحة / Could not connect» هو أمر
# xfce4-panel -r عبر D-Bus. نحذف هذا المسار نهائيًّا: المساعد يقتل العملية
# ثم يشغّلها من جديد — لا حوار يمكن أن يظهر مهما كانت حالة الناقل.
_FX_PANEL_RESTART_SH = r"""#!/bin/bash
set -u
# V18: اقتل النسخ المتراكبة، ثم دع xfce4-session يعيد نسخة واحدة فقط.
pkill -x xfce4-panel >/dev/null 2>&1 || true
for _i in $(seq 1 16); do
  sleep 0.5
  _n=$(pgrep -xc xfce4-panel 2>/dev/null || true)
  [ "${_n:-0}" -eq 1 ] 2>/dev/null && exit 0
  [ "${_n:-0}" -gt 1 ] 2>/dev/null && pkill -x xfce4-panel >/dev/null 2>&1 || true
done
# لا مشرف جلسة يعيد اللوحة: ابدأ نسخة واحدة كحل أخير.
setsid xfce4-panel >/dev/null 2>&1 &
exit 0
"""


def _fx_install_panel_restart():
    """يكتب gs-panel-restart أحادي النسخة ويحيّد أي استدعاء -r متبقٍّ."""
    p = "/usr/local/bin/gs-panel-restart"
    cur = _fx_read(p)
    if cur != _FX_PANEL_RESTART_SH:
        _fx_atomic(p, _FX_PANEL_RESTART_SH)
    # حيّد أي موقع -r مكشوف في قائمة الهاتف إن أعادت الاستعادة النسخة القديمة.
    menu = _fx_read("/usr/local/bin/phone-app-menu")
    if menu is not None and "gs-panel-restart" not in menu:
        exposed = "xfce4-panel -r >/tmp/panel-repair.log 2>&1 || true"
        if exposed in menu:
            _fx_atomic("/usr/local/bin/phone-app-menu",
                       menu.replace(exposed,
                                    "/usr/local/bin/gs-panel-restart"
                                    " >/tmp/panel-repair.log 2>&1 || true"))
            return "installed+menu-fixed"
    return "installed"


# ---- (V15-ب) أداة تثبيت Android Studio المرئية ------------------------------
# الجذر: STABILITY_FIRST يمنع التثبيت نهائيًّا فيغيب /opt/android-studio
# ويخرج المغلّف exit 4 بصمت تام. هذه الأداة تثبّت عند أول نقرة بنافذة تقدّم.
_FX_ANDROID_INSTALL_SH = r"""#!/bin/bash
set -u
LOG=/tmp/android-studio-install.log
URL="https://dl.google.com/dl/android/studio/ide-zips/2026.1.3.8/android-studio-quail3-patch1-linux.tar.gz"
SHA256="5bd5ee5d6e747b13f82fba3241380bd358cc2f4a847815c8e860757df13dc35f"
TMP=/tmp/android-studio-install.tar.gz
STAGE=/tmp/android-studio-extract
exec 9>/tmp/android-studio-install.lock
flock -n 9 || { echo "تثبيت Android Studio يعمل بالفعل."; exit 0; }
exec >"$LOG" 2>&1
echo "[V16] بدء تثبيت Android Studio"
rm -f "$TMP" 2>/dev/null || true
if command -v zenity >/dev/null 2>&1; then
  ( wget -O "$TMP" "$URL" 2>&1 | stdbuf -o0 awk -F% 'NF>1{gsub(/[^0-9]/,"",$2);print $2}' | zenity --progress --auto-close --pulsate=false --title="Android Studio" --text="يُنزَّل Android Studio..." 2>/dev/null ) || wget -O "$TMP" "$URL" || exit 1
else
  wget -O "$TMP" "$URL" || exit 1
fi
printf '%s  %s\n' "$SHA256" "$TMP" | sha256sum -c - || { echo "SHA-256 mismatch"; rm -f "$TMP"; exit 1; }
rm -rf "$STAGE" 2>/dev/null || true
mkdir -p "$STAGE" || exit 1
tar -xzf "$TMP" -C "$STAGE" || { rm -rf "$STAGE"; exit 1; }
SRC=$(find "$STAGE" -maxdepth 3 -type f \( -name studio -o -name studio.sh \) -print -quit 2>/dev/null)
[ -n "$SRC" ] || { rm -rf "$STAGE"; exit 1; }
APP_ROOT=$(dirname "$(dirname "$SRC")")
[ -x "$APP_ROOT/jbr/bin/java" ] && [ -f "$APP_ROOT/bin/idea.properties" ] || { rm -rf "$STAGE"; exit 1; }
rm -rf /opt/android-studio.old 2>/dev/null || true
[ -d /opt/android-studio ] && mv /opt/android-studio /opt/android-studio.old || true
mkdir -p /opt
if ! mv "$APP_ROOT" /opt/android-studio; then
  rm -rf /opt/android-studio 2>/dev/null || true
  [ -d /opt/android-studio.old ] && mv /opt/android-studio.old /opt/android-studio || true
  rm -rf "$STAGE" "$TMP" 2>/dev/null || true
  exit 1
fi
chmod +x /opt/android-studio/bin/studio /opt/android-studio/bin/studio.sh /opt/android-studio/jbr/bin/java 2>/dev/null || true
rm -rf /opt/android-studio.old "$STAGE" "$TMP" 2>/dev/null || true
echo "[V16] اكتمل تثبيت Android Studio"
"""


