def _fx_sanitize_desktop_labels():
    """أصلح تلف Unicode في ملفاتنا وأزل emoji غير المدعوم من أسماء الأيقونات."""
    roots=("/usr/share/applications","/root/.local/share/applications","/root/Desktop")
    fixes={"بقي��":"بقية","��زم":"حزم","المستخد��":"المستخدم",
           "بالعرب��ة":"بالعربية","النطام":"النظام"}
    changed=0
    for root in roots:
        try: entries=list(_FxPath(root).glob("*.desktop"))
        except Exception: continue
        for path in entries:
            if not (path.name.startswith(("colab-","chrome-","google-antigravity","genspark","android")) or root.endswith("Desktop")):
                continue
            text=_fx_read(str(path))
            if text is None: continue
            original=text
            for bad,good in fixes.items(): text=text.replace(bad,good)
            rows=[]
            for line in text.splitlines(True):
                if line.startswith(("Name=","Name[ar]=")):
                    line="".join(ch for ch in line if ch!="�" and ord(ch)<=0xFFFF)
                rows.append(line)
            text="".join(rows)
            if text!=original:
                _fx_atomic(str(path),text,0o755 if root.endswith("Desktop") else 0o644);changed+=1
    return "desktop-labels=%d"%changed




# ---- (V18) احتواء نهائي للنوافذ — يشمل النوافذ ذات العنوان الفارغ ----------
_FX_WINDOW_FIT_V18 = r"""#!/bin/bash
set -u
export DISPLAY="${DISPLAY:-:1}" XAUTHORITY="${XAUTHORITY:-/root/.Xauthority}"
MODE="${1:---active}"
exec 9>/tmp/colab-window-fit-v18.lock
flock -n 9 || exit 0
read_area(){
  local raw geo
  geo=$(xdotool getdisplaygeometry 2>/dev/null || echo '880 1565')
  SW=${geo%% *}; SH=${geo##* }
  raw=$(xprop -root _NET_WORKAREA 2>/dev/null | sed 's/.*= *//;s/,/ /g' | awk '{print $1,$2,$3,$4}')
  set -- $raw; AX=${1:-0}; AY=${2:-0}; AW=${3:-$SW}; AH=${4:-$SH}
  case "$AX$AY$AW$AH" in ''|*[!0-9]*) AX=0; AY=0; AW=$SW; AH=$SH;; esac
  [ $((AX+AW)) -gt "$SW" ] 2>/dev/null && AW=$((SW-AX))
  [ $((AY+AH)) -gt "$SH" ] 2>/dev/null && AH=$((SH-AY))
  PX=10; PT=8; PB=12
  SX=$((AX+PX)); SY=$((AY+PT)); FW=$((AW-PX*2)); FH=$((AH-PT-PB))
  [ "$FW" -gt 240 ] || { SX=$AX; FW=$AW; }
  [ "$FH" -gt 240 ] || { SY=$AY; FH=$AH; }
}
values(){
  local g="$1"
  X=$(printf '%s\n' "$g"|awk -F= '$1=="X"{print $2}')
  Y=$(printf '%s\n' "$g"|awk -F= '$1=="Y"{print $2}')
  W=$(printf '%s\n' "$g"|awk -F= '$1=="WIDTH"{print $2}')
  H=$(printf '%s\n' "$g"|awk -F= '$1=="HEIGHT"{print $2}')
  case "$X,$Y,$W,$H" in *[!0-9,-]*|,,,*|'') return 1;; esac
}
outside(){ [ "$X" -lt "$SX" ] || [ "$Y" -lt "$SY" ] || [ $((X+W)) -gt $((SX+FW)) ] || [ $((Y+H)) -gt $((SY+FH)) ]; }
fit(){
  local id="$1" typ trans g nx ny nw nh hex after
  typ=$(xprop -id "$id" _NET_WM_WINDOW_TYPE 2>/dev/null || true)
  case "$typ" in *DESKTOP*|*DOCK*|*SPLASH*) return 0;; esac
  state=$(xprop -id "$id" _NET_WM_STATE 2>/dev/null || true)
  # النافذة المكبرة داخل workarea سليمة حتى لو كانت حدود الإطار سالبة بضعة بكسلات.
  # لمسها دوريًا كان السبب المباشر للاهتزاز بين maximize وmanual geometry.
  echo "$state" | grep -Eq 'MAXIMIZED|FULLSCREEN|HIDDEN|SHADED' && return 0
  hex=$(printf '0x%x' "$id")
  trans=$(xprop -id "$id" WM_TRANSIENT_FOR 2>/dev/null || true)
  # تجربة الهاتف: كل نافذة تطبيق عادية تملأ workarea؛ الحوارات تبقى بحجمها وتُحتوى فقط.
  if [ "${MOBILE_MAXIMIZE_APPS:-1}" = "1" ] && echo "$typ" | grep -q '_NORMAL' && ! echo "$trans" | grep -q 'window id #'; then
    wmctrl -i -r "$hex" -b add,maximized_vert,maximized_horz 2>/dev/null || true
    return 0
  fi
  g=$(xdotool getwindowgeometry --shell "$id" 2>/dev/null) || return 0
  values "$g" || return 0
  outside || return 0
  nx=$X; ny=$Y; nw=$W; nh=$H
  [ "$nw" -gt "$FW" ] && nw=$FW; [ "$nh" -gt "$FH" ] && nh=$FH
  [ "$nx" -lt "$SX" ] && nx=$SX; [ "$ny" -lt "$SY" ] && ny=$SY
  [ $((nx+nw)) -gt $((SX+FW)) ] && nx=$((SX+FW-nw))
  [ $((ny+nh)) -gt $((SY+FH)) ] && ny=$((SY+FH-nh))
  hex=$(printf '0x%x' "$id")
  wmctrl -i -r "$hex" -b remove,maximized_vert,maximized_horz 2>/dev/null || true
  wmctrl -i -r "$hex" -e "0,$nx,$ny,$nw,$nh" 2>/dev/null || true
  sleep 0.12
  after=$(xdotool getwindowgeometry --shell "$id" 2>/dev/null || true)
  if values "$after" && outside; then
    xdotool windowsize "$id" "$nw" "$nh" 2>/dev/null || true
    xdotool windowmove "$id" "$nx" "$ny" 2>/dev/null || true
    sleep 0.12
    after=$(xdotool getwindowgeometry --shell "$id" 2>/dev/null || true)
    # بعض التطبيقات ترفض موضع/حجم X11 اليدوي؛ التكبير داخل workarea هو الضمان.
    if values "$after" && outside; then
      wmctrl -i -r "$hex" -b add,maximized_vert,maximized_horz 2>/dev/null || true
    fi
  fi
}
read_area
case "$MODE" in
 --active) id=$(xdotool getactivewindow 2>/dev/null || true); [ -n "$id" ] && fit "$id";;
 --all)
   ids=$(xprop -root _NET_CLIENT_LIST_STACKING 2>/dev/null | grep -oE '0x[0-9a-fA-F]+' | sort -u)
   [ -n "$ids" ] || ids=$(xdotool search --onlyvisible --name '' 2>/dev/null | sort -u)
   for id in $ids; do fit "$id"; done;;
 *) exit 2;;
esac
"""
_FX_WINDOW_WATCH_V18 = r"""#!/bin/bash
set -u
export DISPLAY="${DISPLAY:-:1}" XAUTHORITY="${XAUTHORITY:-/root/.Xauthority}"
last=""; full=0
trap '/usr/local/bin/window-fit-now --all >/tmp/window-fit-watchdog.log 2>&1 || true' USR1
/usr/local/bin/window-fit-now --all >/tmp/window-fit-watchdog.log 2>&1 || true
while true; do
  cur=$(xdotool getactivewindow 2>/dev/null || true)
  if [ -n "$cur" ] && [ "$cur" != "$last" ]; then last="$cur"; /usr/local/bin/window-fit-now --active >/tmp/window-fit-watchdog.log 2>&1 || true; fi
  now=$(date +%s); if [ $((now-full)) -ge 300 ]; then /usr/local/bin/window-fit-now --all >/tmp/window-fit-watchdog.log 2>&1 || true; full=$now; fi
  sleep 2
done
"""


def _fx_install_window_fit_v18():
    _fx_atomic('/usr/local/bin/window-fit-now',_FX_WINDOW_FIT_V18)
    _fx_atomic('/usr/local/bin/window-fit-watchdog',_FX_WINDOW_WATCH_V18)
    _fx_atomic('/usr/local/bin/window-fitter','#!/bin/bash\n# V28: disabled; window-fit-watchdog is the sole geometry owner.\nexit 0\n')
    try: subprocess.run(['pkill','-f','/usr/local/bin/window-fitter'],stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,timeout=5)
    except Exception: pass
    env=dict(_fx_os.environ,DISPLAY=_fx_os.environ.get('DISPLAY',':1'),
             XAUTHORITY=_fx_os.environ.get('XAUTHORITY','/root/.Xauthority'))
    try: subprocess.run(['pkill','-f','/usr/local/bin/window-fit-watchdog'],stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,timeout=5)
    except Exception: pass
    try: subprocess.Popen(['/usr/local/bin/window-fit-watchdog'],env=env,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,start_new_session=True)
    except Exception: pass
    try: subprocess.run(['/usr/local/bin/window-fit-now','--all'],env=env,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,timeout=20)
    except Exception: pass
    return 'window-fit-v18-installed'

def _fx_apply_mobile_scale():
    """يفرض 150% فقط إذا بقيت الجلسة على ملف 132DPI/48px الصغير."""
    try:
        current_dpi=int((_xfce_get_live('xsettings','/Xft/DPI') or '0').strip())
    except Exception:
        current_dpi=0
    try:
        current_icon=int((_xfce_get_live('xfce4-desktop','/desktop-icons/icon-size') or '0').strip())
    except Exception:
        current_icon=0
    # Electron: صغّر canvas الداخلي إلى 0.8/0.85 للملاءمة، ثم كبّر محتوى المحرر دلاليًا.
    try:
        _atomic_json_update('/root/.config/Cursor/User/settings.json',{'window.zoomLevel':4})
        _atomic_json_update('/root/.config/Antigravity-IDE/User/settings.json',{'window.zoomLevel':4})
    except Exception:
        pass
    if 150<=current_dpi<=168 and 76<=current_icon<=88:
        return "system-scale-natural(dpi=%d,icon=%d,appZoom=4)"%(current_dpi,current_icon)
    last=""
    for attempt in range(1,4):
        try:
            _apply_ui_scale(150,True)
            time.sleep(1.5)
            dpi=int((_xfce_get_live('xsettings','/Xft/DPI') or '0').strip())
            icon=int((_xfce_get_live('xfce4-desktop','/desktop-icons/icon-size') or '0').strip())
            panel=int((_xfce_get_live('xfce4-panel','/panels/panel-1/size') or '0').strip())
            if 150<=dpi<=168 and 76<=icon<=88 and 58<=panel<=66:
                return "mobile-scale-applied(dpi=%d,icon=%d,panel=%d)"%(dpi,icon,panel)
            last="readback=%d/%d/%d"%(dpi,icon,panel)
        except Exception as exc:
            last=type(exc).__name__
        time.sleep(attempt*2)
    return "mobile-scale-ERR("+last+")"



def _fx_patch_chrome_workspace_guard_v19():
    """أعد الحارس غير المشروط بعد أي v121/rootfs rewrite لملف chrome-profile."""
    path='/usr/local/bin/chrome-profile'
    text=_fx_read(path)
    if text is None:
        return 'chrome-profile-missing'
    if 'V19: افحص العملية/النافذة دائمًا' in text:
        return 'chrome-guard-v19-ok'
    old=globals().get('_WORKSPACE_GUARD_OLD')
    new=globals().get('_WORKSPACE_GUARD_NEW')
    if isinstance(old,str) and isinstance(new,str) and old in text:
        _fx_atomic(path,text.replace(old,new,1))
        return 'chrome-guard-v19-installed'
    return 'chrome-guard-anchor-missing'



def _fx_compact_diagnostics_v20():
    """احذف ضجيج command_exit التاريخي واحتفظ بآخر 250 حدث metadata فقط."""
    path='/root/workspace/error-log.txt'
    try:
        rows=[]
        if os.path.isfile(path):
            for line in open(path,encoding='utf-8',errors='ignore'):
                try:
                    item=json.loads(line)
                    if str(item.get('component','')).startswith('command_exit_'):continue
                    rows.append(json.dumps(item,ensure_ascii=False,separators=(',',':'))+'\n')
                except Exception:continue
        rows=rows[-250:]
        os.makedirs(os.path.dirname(path),exist_ok=True)
        fd,tmp=tempfile.mkstemp(prefix='.diag-v20-',dir=os.path.dirname(path))
        with os.fdopen(fd,'w',encoding='utf-8') as f:f.writelines(rows);f.flush();os.fsync(f.fileno())
        os.replace(tmp,path);os.chmod(path,0o600)
        return 'diagnostics=%d'%len(rows)
    except Exception as exc:
        return 'diagnostics-ERR('+type(exc).__name__+')'


def _v20_persistence_integrity_loop():
    cycle=0
    while True:
        time.sleep(900);cycle+=1
        try:
            if not DRIVE_OK or time.time()<globals().get('_PERFORMANCE_PAUSE_UNTIL',0):continue
            p=run(['/usr/local/bin/protected-project-vault','verify'],timeout=300)
            if getattr(p,'returncode',1)!=0:_diag_event('projects_integrity_verify_failed',RuntimeError('rc=%s'%getattr(p,'returncode','?')),'error')
            # الفحص الكامل لكل الخزائن مرة كل ساعة فقط حتى لا نثقل Drive FUSE.
            if cycle%4==0 and os.path.isfile('/usr/local/bin/vault-verify'):
                v=run(['/usr/local/bin/vault-verify','all'],timeout=1200)
                if getattr(v,'returncode',1)!=0:_diag_event('vault_integrity_verify_failed',RuntimeError('rc=%s'%getattr(v,'returncode','?')),'error')
        except Exception as exc:_diag_event('persistence_integrity_loop',exc,'error')


def _fx_start_persistence_integrity_v20():
    try:_spawn('persistence_integrity_v20',_v20_persistence_integrity_loop)
    except Exception as exc:return 'integrity-ERR('+type(exc).__name__+')'
    return 'integrity-monitor-started'


# ---- (V21) Android Studio القياسي بلا STUDIO_PROPERTIES غير versioned --------
_FX_ANDROID_WRAPPER_V22 = r"""#!/bin/bash
set -u
[ -f /tmp/.android-studio_profile_ready ] || { zenity --error --title="Android Studio" --text="لم تكتمل استعادة إعدادات Android Studio بعد." 2>/dev/null || true; exit 5; }
BIN=""
for c in /opt/android-studio/bin/studio /opt/android-studio/bin/studio.sh; do [ -x "$c" ] && { BIN="$c"; break; }; done
[ -n "$BIN" ] || { zenity --error --title="Android Studio" --text="حزمة Android Studio غير موجودة." 2>/dev/null || true; exit 4; }
export HOME=/root DISPLAY="${DISPLAY:-:1}" XAUTHORITY=/root/.Xauthority
export LANG=C.UTF-8 LANGUAGE=en GTK_IM_MODULE=ibus QT_IM_MODULE=ibus XMODIFIERS=@im=ibus
export ANDROID_HOME=/root/Android/Sdk ANDROID_SDK_ROOT=/root/Android/Sdk LIBGL_ALWAYS_SOFTWARE=1
unset STUDIO_PROPERTIES
mkdir -p /root/Projects/AndroidStudio /root/.config/Google /root/.cache/Google /tmp/android-studio-logs
wid=$(wmctrl -lx 2>/dev/null | awk 'BEGIN{IGNORECASE=1} /Android Studio|jetbrains-studio/ && $0 !~ /Start Failed/{print $1;exit}')
if [ -n "$wid" ]; then wmctrl -ia "$wid" 2>/dev/null || true; /usr/local/bin/window-fit-now --active >/dev/null 2>&1 || true; exit 0; fi
pids=$(pgrep -f '/opt/android-studio/.*/studio|/opt/android-studio/jbr/.*java' 2>/dev/null || true)
if [ -n "$pids" ]; then kill -TERM $pids 2>/dev/null || true; sleep 3; for p in $pids; do kill -0 "$p" 2>/dev/null && kill -KILL "$p" 2>/dev/null || true; done; fi
find /root/.cache/Google /root/.config/Google -maxdepth 4 -type f \( -name '*.lock' -o -name '.lock' \) -delete 2>/dev/null || true
exec 9>/tmp/android-studio-v22-launch.lock
flock -n 9 || { notify-send "Android Studio" "التطبيق قيد الفتح بالفعل." 2>/dev/null || true; exit 0; }
launch_once(){
  "$BIN" -Duser.language=en -Duser.country=US -Dsun.java2d.uiScale=1.50 \
    -Dsun.java2d.uiScale.enabled=true -Dide.ui.scale=1.50 -Dide.ui.animation=false \
    -Didea.default.project.directory=/root/Projects/AndroidStudio "$@" \
    >/tmp/android-studio-launch.log 2>&1 & PID=$!
  ( sleep 1; /usr/local/bin/window-fit-now --all >/tmp/android-studio-fit.log 2>&1 || true
    sleep 2; /usr/local/bin/window-fit-now --all >>/tmp/android-studio-fit.log 2>&1 || true
    sleep 5; /usr/local/bin/window-fit-now --all >>/tmp/android-studio-fit.log 2>&1 || true ) &
  wait "$PID"; return $?
}
RC=0;launch_once "$@" || RC=$?
if [ "$RC" -ne 0 ] && grep -Eqi 'Start Failed|PluginException|NoSuchElementException|component store|DirectoryLock' /tmp/android-studio-launch.log; then
  stamp=$(date +%Y%m%d-%H%M%S)
  # احتفظ بالإعداد الفاشل backup ولا تنشره إلى Drive؛ ثم أعد محاولة نظيفة مرة واحدة.
  for d in /root/.config/Google/AndroidStudio* /root/.cache/Google/AndroidStudio*; do
    [ -e "$d" ] || continue; mv "$d" "$d.failed-$stamp" 2>/dev/null || true
  done
  notify-send "Android Studio" "أُصلحت حالة بدء تالفة؛ إعادة محاولة نظيفة الآن." 2>/dev/null || true
  RC=0;launch_once "$@" || RC=$?
fi
# لا تحفظ config فاشلاً؛ النجاح/الإغلاق الطبيعي فقط يُنشئ جيل Drive جديدًا.
if [ "$RC" -eq 0 ]; then /usr/local/bin/dev-app-profile android-studio save >/tmp/android-studio-profile-save.log 2>&1 || true; fi
exit "$RC"
"""


def _fx_install_android_wrapper_v22():
    globals()['_android_wrapper']=_FX_ANDROID_WRAPPER_V22
    _fx_atomic('/usr/local/bin/android-studio-colab',_FX_ANDROID_WRAPPER_V22)
